{
  "name": "Nexus Hub",
  "description": "A cross-platform chat application merging Telegram's group flexibility with Discord's voice channels and dashboard-style topic management.",
  "requestFramePermissions": [
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum GroupType {
  STANDARD = 'STANDARD',
  TOPICS = 'TOPICS'
}

export interface Topic {
  id: string;
  name: string;
  description: string;
  icon: string;
}

export interface Message {
  id: string;
  sender: string;
  text: string;
  timestamp: Date;
  avatar: string;
}

export interface Group {
  id: string;
  name: string;
  type: GroupType;
  topics: Topic[];
  lastMessage?: string;
  icon: string;
  activeVoiceChannel?: boolean;
}

export interface VoiceParticipant {
  id: string;
  name: string;
  avatar: string;
  isSpeaking: boolean;
}

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatArea from './components/ChatArea';
import DashboardArea from './components/DashboardArea';
import VoiceChannel from './components/VoiceChannel';
import { Group, GroupType } from './types';

const INITIAL_GROUPS: Group[] = [
  {
    id: '1',
    name: 'Dev Community',
    type: GroupType.STANDARD,
    topics: [],
    lastMessage: 'Let\'s fix the bug in production!',
    icon: '💻'
  },
  {
    id: '2',
    name: 'Product Nexus',
    type: GroupType.TOPICS,
    topics: [
      { id: 't1', name: 'Roadmap', description: 'Future plans and vision', icon: '🗺️' },
      { id: 't2', name: 'Feedback', description: 'User input and surveys', icon: '💬' },
      { id: 't3', name: 'Design', description: 'UI/UX mockups', icon: '🎨' }
    ],
    icon: '🚀'
  },
  {
    id: '3',
    name: 'Game Lounge',
    type: GroupType.TOPICS,
    topics: [
      { id: 't4', name: 'General', description: 'Chill out zone', icon: '🎮' },
      { id: 't5', name: 'Lobby', description: 'Voice lounge', icon: '🔊' }
    ],
    icon: '🕹️',
    activeVoiceChannel: true
  }
];

const App: React.FC = () => {
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string>('1');
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [isVoiceOpen, setIsVoiceOpen] = useState(false);

  const activeGroup = groups.find(g => g.id === activeGroupId) || groups[0];

  const handleCreateGroup = (name: string, type: GroupType) => {
    const newGroup: Group = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      topics: type === GroupType.TOPICS ? [
        { id: 'd1', name: 'General', description: 'Welcome to the group!', icon: '👋' }
      ] : [],
      icon: '📁'
    };
    setGroups([...groups, newGroup]);
    setActiveGroupId(newGroup.id);
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-200">
      {/* Sidebar Navigation */}
      <Sidebar 
        groups={groups} 
        activeGroupId={activeGroupId} 
        onSelectGroup={(id) => {
          setActiveGroupId(id);
          setActiveTopicId(null);
        }}
        onCreateGroup={handleCreateGroup}
      />

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col relative overflow-hidden">
        {activeGroup.type === GroupType.STANDARD ? (
          <ChatArea group={activeGroup} />
        ) : (
          <DashboardArea 
            group={activeGroup} 
            activeTopicId={activeTopicId}
            onSelectTopic={setActiveTopicId}
            onOpenVoice={() => setIsVoiceOpen(true)}
          />
        )}

        {/* Floating Voice Layer */}
        {isVoiceOpen && (
          <div className="absolute inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-4">
            <VoiceChannel onClose={() => setIsVoiceOpen(false)} groupName={activeGroup.name} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Group, GroupType } from '../types';

interface SidebarProps {
  groups: Group[];
  activeGroupId: string;
  onSelectGroup: (id: string) => void;
  onCreateGroup: (name: string, type: GroupType) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ groups, activeGroupId, onSelectGroup, onCreateGroup }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newName, setNewName] = useState('');
  const [newType, setNewType] = useState<GroupType>(GroupType.STANDARD);

  return (
    <aside className="w-20 md:w-64 bg-slate-900 border-r border-slate-800 flex flex-col h-full shrink-0">
      <div className="p-4 border-b border-slate-800 flex items-center justify-between">
        <h1 className="hidden md:block font-bold text-lg text-white">Nexus Hub</h1>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-indigo-600 hover:bg-indigo-500 text-white p-2 rounded-lg transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
            <path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" />
          </svg>
        </button>
      </div>

      <div className="flex-1 overflow-y-auto py-4 space-y-2">
        {groups.map((group) => (
          <button
            key={group.id}
            onClick={() => onSelectGroup(group.id)}
            className={`w-full flex items-center p-3 transition-all ${
              activeGroupId === group.id 
                ? 'bg-indigo-600/20 text-indigo-400 border-l-4 border-indigo-500' 
                : 'hover:bg-slate-800 text-slate-400'
            }`}
          >
            <span className="text-2xl md:mr-3">{group.icon}</span>
            <div className="hidden md:block text-left truncate">
              <div className="font-medium text-slate-100">{group.name}</div>
              <div className="text-xs text-slate-500 truncate">{group.lastMessage || 'No messages'}</div>
            </div>
            {group.activeVoiceChannel && (
              <div className="ml-auto hidden md:block">
                <span className="flex h-2 w-2 rounded-full bg-green-500 animate-pulse"></span>
              </div>
            )}
          </button>
        ))}
      </div>

      {/* Creation Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-2xl shadow-2xl p-6">
            <h2 className="text-xl font-bold mb-4 text-white">Create New Group</h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Name</label>
                <input 
                  type="text" 
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-lg p-3 outline-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Enter group name..."
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setNewType(GroupType.STANDARD)}
                  className={`p-4 rounded-xl border-2 transition-all text-center ${
                    newType === GroupType.STANDARD ? 'border-indigo-500 bg-indigo-500/10' : 'border-slate-800'
                  }`}
                >
                  <div className="text-2xl mb-1">💬</div>
                  <div className="font-semibold text-sm">Standard</div>
                  <div className="text-[10px] text-slate-500">Telegram style chat</div>
                </button>
                <button 
                  onClick={() => setNewType(GroupType.TOPICS)}
                  className={`p-4 rounded-xl border-2 transition-all text-center ${
                    newType === GroupType.TOPICS ? 'border-indigo-500 bg-indigo-500/10' : 'border-slate-800'
                  }`}
                >
                  <div className="text-2xl mb-1">📋</div>
                  <div className="font-semibold text-sm">Topics</div>
                  <div className="text-[10px] text-slate-500">Discord style dashboard</div>
                </button>
              </div>
              <div className="flex gap-3 pt-4">
                <button 
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 px-4 py-2 bg-slate-800 hover:bg-slate-700 rounded-lg transition-colors"
                >
                  Cancel
                </button>
                <button 
                  onClick={() => {
                    if (newName) {
                      onCreateGroup(newName, newType);
                      setIsModalOpen(false);
                      setNewName('');
                    }
                  }}
                  className="flex-1 px-4 py-2 bg-indigo-600 hover:bg-indigo-500 rounded-lg transition-colors"
                >
                  Create
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </aside>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import { Group, Message } from '../types';

interface ChatAreaProps {
  group: Group;
}

const ChatArea: React.FC<ChatAreaProps> = ({ group }) => {
  const [messages, setMessages] = useState<Message[]>([
    { id: '1', sender: 'Alice', text: 'Hey everyone, how is it going?', timestamp: new Date(), avatar: 'https://picsum.photos/40/40?1' },
    { id: '2', sender: 'Bob', text: 'Working on the new API integration!', timestamp: new Date(), avatar: 'https://picsum.photos/40/40?2' }
  ]);
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      sender: 'You',
      text: input,
      timestamp: new Date(),
      avatar: 'https://picsum.photos/40/40?3'
    };
    setMessages([...messages, newMessage]);
    setInput('');
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50">
      <header className="p-4 border-b border-slate-800 bg-slate-900/80 backdrop-blur-md flex items-center">
        <div className="text-2xl mr-3">{group.icon}</div>
        <div>
          <h2 className="font-bold text-slate-100">{group.name}</h2>
          <p className="text-xs text-slate-500">12 members online</p>
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((m) => (
          <div key={m.id} className={`flex items-end gap-3 ${m.sender === 'You' ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-8 h-8 rounded-full border border-slate-700" alt="avatar" />
            <div className={`max-w-[70%] rounded-2xl p-3 shadow-lg ${
              m.sender === 'You' 
                ? 'bg-indigo-600 text-white rounded-br-none' 
                : 'bg-slate-800 text-slate-200 rounded-bl-none'
            }`}>
              {m.sender !== 'You' && <div className="text-[10px] font-bold text-indigo-400 mb-1">{m.sender}</div>}
              <p className="text-sm leading-relaxed">{m.text}</p>
              <div className="text-[10px] text-right mt-1 opacity-60">
                {m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="p-4 bg-slate-900/80 border-t border-slate-800">
        <div className="max-w-4xl mx-auto flex items-center gap-3">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type a message..."
            className="flex-1 bg-slate-800 border border-slate-700 rounded-full px-5 py-3 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
          />
          <button 
            onClick={handleSend}
            className="bg-indigo-600 hover:bg-indigo-500 text-white p-3 rounded-full shadow-lg transition-transform active:scale-95"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatArea;

import React from 'react';
import { Group, Topic } from '../types';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ group, activeTopicId, onSelectTopic, onOpenVoice }) => {
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  return (
    <div className="flex h-full">
      {/* Topics Sidebar */}
      <div className="w-64 bg-slate-900/80 border-r border-slate-800 hidden md:flex flex-col">
        <div className="p-4 font-bold uppercase tracking-wider text-xs text-slate-500">Topics</div>
        <div className="flex-1 overflow-y-auto px-2 space-y-1">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-2 rounded-lg flex items-center gap-3 transition-colors ${
                activeTopicId === topic.id ? 'bg-slate-800 text-indigo-400' : 'text-slate-400 hover:bg-slate-800/50 hover:text-slate-200'
              }`}
            >
              <span className="text-xl">{topic.icon}</span>
              <span className="font-medium">{topic.name}</span>
            </button>
          ))}

          <div className="mt-8 p-4 font-bold uppercase tracking-wider text-xs text-slate-500">Voice Channels</div>
          <button
            onClick={onOpenVoice}
            className="w-full text-left p-2 rounded-lg flex items-center gap-3 text-slate-400 hover:bg-slate-800/50 group"
          >
            <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center group-hover:bg-indigo-600 transition-colors">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z" clipRule="evenodd" />
              </svg>
            </div>
            <span className="font-medium group-hover:text-slate-200">Main Lounge</span>
          </button>
        </div>
      </div>

      {/* Main Viewport */}
      <div className="flex-1 flex flex-col bg-slate-950 overflow-y-auto">
        {!activeTopic ? (
          <div className="p-8">
            <h1 className="text-3xl font-bold text-white mb-2">{group.name} Dashboard</h1>
            <p className="text-slate-400 mb-8">Select a topic to start collaborating.</p>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {group.topics.map((topic) => (
                <div 
                  key={topic.id}
                  onClick={() => onSelectTopic(topic.id)}
                  className="bg-slate-900 border border-slate-800 p-6 rounded-2xl hover:border-indigo-500/50 hover:bg-slate-800/40 transition-all cursor-pointer group"
                >
                  <div className="text-4xl mb-4 group-hover:scale-110 transition-transform origin-left">{topic.icon}</div>
                  <h3 className="text-xl font-bold text-white mb-2">{topic.name}</h3>
                  <p className="text-slate-500 text-sm line-clamp-2">{topic.description}</p>
                  <div className="mt-4 flex items-center text-xs text-indigo-400 font-bold tracking-widest uppercase opacity-0 group-hover:opacity-100 transition-opacity">
                    Join Thread →
                  </div>
                </div>
              ))}

              <div 
                onClick={onOpenVoice}
                className="bg-gradient-to-br from-indigo-900/40 to-slate-900 border border-indigo-500/30 p-6 rounded-2xl hover:border-indigo-500 transition-all cursor-pointer group relative overflow-hidden"
              >
                <div className="absolute top-0 right-0 p-3">
                  <span className="flex h-2 w-2 rounded-full bg-indigo-500 animate-ping"></span>
                </div>
                <div className="text-4xl mb-4">🔊</div>
                <h3 className="text-xl font-bold text-white mb-2">Voice Lounge</h3>
                <p className="text-slate-400 text-sm">Hop in and chat with team members in real-time.</p>
                <button className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded-lg text-sm font-semibold hover:bg-indigo-500 transition-colors">
                  Join Room
                </button>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex flex-col h-full">
            <header className="p-4 border-b border-slate-800 flex items-center justify-between sticky top-0 bg-slate-950/80 backdrop-blur-md z-10">
              <div className="flex items-center gap-3">
                <button onClick={() => onSelectTopic('')} className="md:hidden text-slate-400">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                  </svg>
                </button>
                <div className="text-xl">{activeTopic.icon}</div>
                <h2 className="font-bold text-white">{activeTopic.name}</h2>
              </div>
            </header>
            <div className="flex-1 p-8 text-center text-slate-500">
              <div className="max-w-md mx-auto py-20">
                <div className="text-6xl mb-4 opacity-20">🕳️</div>
                <h3 className="text-xl font-medium text-slate-400">Welcome to #{activeTopic.name}</h3>
                <p className="mt-2">{activeTopic.description}</p>
                <div className="mt-8 border-t border-slate-800 pt-8">
                  <p className="text-sm">This is the beginning of the topic history.</p>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DashboardArea;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { VoiceParticipant } from '../types';

interface VoiceChannelProps {
  onClose: () => void;
  groupName: string;
}

const VoiceChannel: React.FC<VoiceChannelProps> = ({ onClose, groupName }) => {
  const [isMuted, setIsMuted] = useState(false);
  const [participants, setParticipants] = useState<VoiceParticipant[]>([
    { id: '1', name: 'You', avatar: 'https://picsum.photos/80/80?u=1', isSpeaking: false },
    { id: 'ai', name: 'Nexus AI', avatar: 'https://picsum.photos/80/80?u=ai', isSpeaking: false },
    { id: '2', name: 'Sara', avatar: 'https://picsum.photos/80/80?u=2', isSpeaking: false },
    { id: '3', name: 'Marcus', avatar: 'https://picsum.photos/80/80?u=3', isSpeaking: false },
  ]);
  const [isConnecting, setIsConnecting] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Gemini Live refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<any>(null);

  useEffect(() => {
    // Initializing Gemini Live Session
    const startSession = async () => {
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

        // Setup Audio Contexts
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
        outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

        const sessionPromise = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-12-2025',
          callbacks: {
            onopen: () => {
              setIsConnecting(false);
              // Stream user microphone
              const source = audioContextRef.current!.createMediaStreamSource(stream);
              const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

              scriptProcessor.onaudioprocess = (e) => {
                if (isMuted) return;
                const inputData = e.inputBuffer.getChannelData(0);
                const pcmBlob = createBlob(inputData);
                sessionPromise.then((session) => {
                  session.sendRealtimeInput({ media: pcmBlob });
                });
              };

              source.connect(scriptProcessor);
              scriptProcessor.connect(audioContextRef.current!.destination);
            },
            onmessage: async (message: LiveServerMessage) => {
              const audioBase64 = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
              if (audioBase64) {
                setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: true } : p));

                const ctx = outputAudioContextRef.current!;
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);

                const audioBuffer = await decodeAudioData(
                  decode(audioBase64),
                  ctx,
                  24000,
                  1
                );

                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(ctx.destination);
                source.addEventListener('ended', () => {
                  sourcesRef.current.delete(source);
                  setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: false } : p));
                });

                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
              }

              if (message.serverContent?.interrupted) {
                sourcesRef.current.forEach(s => s.stop());
                sourcesRef.current.clear();
                nextStartTimeRef.current = 0;
              }
            },
            onerror: (e) => {
              console.error("Gemini Live Error:", e);
              setError("Connection lost. Retrying...");
            },
            onclose: () => {
              console.log("Gemini Live Closed");
            }
          },
          config: {
            responseModalities: [Modality.AUDIO],
            systemInstruction: `You are the Moderator of a voice channel in a group called ${groupName}. Keep conversations light, helpful, and community-focused.`
          }
        });

        sessionPromiseRef.current = sessionPromise;

      } catch (err) {
        console.error("Failed to start voice session:", err);
        setError("Microphone access is required.");
        setIsConnecting(false);
      }
    };

    startSession();

    return () => {
      audioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      sessionPromiseRef.current?.then((s: any) => s.close());
    };
  }, [groupName]);

  // Utility functions for audio
  function decode(base64: string) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number) {
    const dataInt16 = new Int16Array(data.buffer);
    const buffer = ctx.createBuffer(channels, dataInt16.length / channels, sampleRate);
    for (let c = 0; c < channels; c++) {
      const channelData = buffer.getChannelData(c);
      for (let i = 0; i < channelData.length; i++) {
        channelData[i] = dataInt16[i * channels + c] / 32768.0;
      }
    }
    return buffer;
  }

  function createBlob(data: Float32Array) {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
    return {
      data: btoa(String.fromCharCode(...new Uint8Array(int16.buffer))),
      mimeType: 'audio/pcm;rate=16000'
    };
  }

  return (
    <div className="w-full max-w-4xl bg-slate-900 border border-slate-800 rounded-3xl shadow-2xl flex flex-col overflow-hidden max-h-[90vh]">
