          messages: [...g.messages, newMessage],
          lastMessage: text
        };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? {
            ...t,
            messages: [...t.messages, newMessage]
          } : t)
