                  <div className="font-black text-xs text-white uppercase tracking-tight">Standard</div>
                </button>
                <button 
                  onClick={() => setNewType(GroupType.TOPICS)}
                  className={`p-6 rounded-[2rem] border-2 transition-all text-center ${
