                       <div>
                          <h4 className="text-xl font-bold text-white mb-1">Knowledge Sync</h4>
                          <p className="text-sm text-slate-400">All materials uploaded here are synchronized across student devices for offline access.</p>
                       </div>
                       <div className="flex items-center gap-2">
                          <span className="text-[10px] font-black text-indigo-400 uppercase tracking-tighter">SDG 4 COMPLIANT</span>
                          <div className="w-10 h-10 rounded-full bg-indigo-600/20 flex items-center justify-center text-indigo-400 font-bold">4</div>
