const App: React.FC = () => {
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string>('edu-1');
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [isVoiceOpen, setIsVoiceOpen] = useState(false);

  const activeGroup = groups.find(g => g.id === activeGroupId) || groups[0];

  const handleCreateGroup = (name: string, type: GroupType, avatar: string) => {
    const newGroup: Group = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      topics: type === GroupType.TOPICS ? [
        { id: 'd1', name: 'Intro', description: 'Welcome to the workspace!', icon: '✨', messages: [], resources: [] }
      ] : [],
      messages: [],
      avatar
    };
    setGroups([...groups, newGroup]);
    setActiveGroupId(newGroup.id);
  };

  const handleUploadResource = (topicId: string, resourceData: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => {
    const newResource: Resource = {
      ...resourceData,
      id: `res-${Date.now()}`,
      uploadedBy: 'You',
      date: new Date()
    };

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return {
        ...g,
        topics: g.topics.map(t => {
          if (t.id !== topicId) return t;
          return {
            ...t,
            resources: [newResource, ...t.resources]
          };
        })
      };
    }));
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    const newMessage: Message = {
      id: Date.now().toString(),
      sender: 'You',
      text,
      timestamp: new Date(),
      avatar: 'https://picsum.photos/40/40?u=me',
      attachment
    };

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;

      if (g.type === GroupType.STANDARD) {
        return {
          ...g,
          messages: [...g.messages, newMessage],
          lastMessage: text
        };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => {
            if (t.id !== topicIdOrNull) return t;

            // If it's a file, also add it to persistent resources
            const newResources = attachment ? [
              {
                id: `res-${Date.now()}`,
                name: attachment.name,
                type: attachment.type,
                size: attachment.size,
                uploadedBy: 'You',
                date: new Date()
              },
              ...t.resources
            ] : t.resources;

            return {
              ...t,
              messages: [...t.messages, newMessage],
              resources: newResources
            };
          })
        };
      }
    }));
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-200">
      <Sidebar 
        groups={groups} 
        activeGroupId={activeGroupId} 
        onSelectGroup={(id) => {
          setActiveGroupId(id);
          setActiveTopicId(null);
        }}
        onCreateGroup={handleCreateGroup}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden">
        {activeGroup.type === GroupType.STANDARD ? (
          <ChatArea 
            groupName={activeGroup.name} 
            messages={activeGroup.messages}
            onSendMessage={(text, att) => handleSendMessage(null, text, att)}
          />
        ) : (
          <DashboardArea 
            group={activeGroup} 
            activeTopicId={activeTopicId}
            onSelectTopic={setActiveTopicId}
            onOpenVoice={() => setIsVoiceOpen(true)}
            onSendMessage={handleSendMessage}
            onUploadResource={handleUploadResource}
          />
        )}

        {isVoiceOpen && (
          <div className="absolute inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-4">
            <VoiceChannel 
              onClose={() => setIsVoiceOpen(false)} 
              groupName={activeTopicId ? activeGroup.topics.find(t => t.id === activeTopicId)?.name || activeGroup.name : activeGroup.name} 
            />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { VoiceParticipant } from '../types';

interface MeetingSessionProps {
  onClose: () => void;
  groupName: string;
  mode: 'voice' | 'video';
}

const MeetingSession: React.FC<MeetingSessionProps> = ({ onClose, groupName, mode }) => {
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(mode === 'voice');
  const [participants, setParticipants] = useState<VoiceParticipant[]>([
    { id: '1', name: 'You (Lecturer)', avatar: 'https://picsum.photos/80/80?u=1', isSpeaking: false },
    { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', isSpeaking: false },
    { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', isSpeaking: false },
    { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', isSpeaking: false },
  ]);
  const [isConnecting, setIsConnecting] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<any>(null);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    const startSession = async () => {
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
        outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

        const constraints = { 
          audio: true, 
          video: mode === 'video' ? { width: 640, height: 480 } : false 
        };
        const stream = await navigator.mediaDevices.getUserMedia(constraints);

        if (mode === 'video' && videoRef.current) {
          videoRef.current.srcObject = stream;
        }

        const sessionPromise = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-12-2025',
          callbacks: {
            onopen: () => {
              setIsConnecting(false);
              // Audio Stream
              const source = audioContextRef.current!.createMediaStreamSource(stream);
              const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
              scriptProcessor.onaudioprocess = (e) => {
                if (isMuted) return;
                const inputData = e.inputBuffer.getChannelData(0);
                const pcmBlob = createBlob(inputData);
                sessionPromise.then((session) => {
                  session.sendRealtimeInput({ media: pcmBlob });
                });
              };
              source.connect(scriptProcessor);
              scriptProcessor.connect(audioContextRef.current!.destination);

              // Video Stream (Image Frames)
              if (mode === 'video') {
                const FRAME_RATE = 2; // Low frame rate for Gemini vision
                frameIntervalRef.current = window.setInterval(() => {
                  if (isVideoOff || !videoRef.current || !canvasRef.current) return;
                  const canvas = canvasRef.current;
                  const video = videoRef.current;
                  const ctx = canvas.getContext('2d');
                  if (!ctx) return;

                  canvas.width = video.videoWidth;
                  canvas.height = video.videoHeight;
                  ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

                  const base64Data = canvas.toDataURL('image/jpeg', 0.5).split(',')[1];
                  sessionPromise.then((session) => {
                    session.sendRealtimeInput({
                      media: { data: base64Data, mimeType: 'image/jpeg' }
                    });
                  });
                }, 1000 / FRAME_RATE);
              }
            },
            onmessage: async (message: LiveServerMessage) => {
              const audioBase64 = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
              if (audioBase64) {
                setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: true } : p));
                const ctx = outputAudioContextRef.current!;
                nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
                const audioBuffer = await decodeAudioData(decode(audioBase64), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(ctx.destination);
                source.addEventListener('ended', () => {
                  sourcesRef.current.delete(source);
                  setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: false } : p));
                });
                source.start(nextStartTimeRef.current);
                nextStartTimeRef.current += audioBuffer.duration;
                sourcesRef.current.add(source);
              }
              if (message.serverContent?.interrupted) {
                sourcesRef.current.forEach(s => s.stop());
                sourcesRef.current.clear();
                nextStartTimeRef.current = 0;
              }
            },
            onerror: (e) => {
              console.error("Gemini Live Error:", e);
              setError("Network link unstable.");
            },
            onclose: () => console.log("Meeting Closed")
          },
          config: {
            responseModalities: [Modality.AUDIO],
            systemInstruction: `You are an expert Educational Facilitator for a ${mode} session on "${groupName}". 
            ${mode === 'video' ? 'You can see the student through their camera. Observe their reactions and any visual material they show.' : ''}
            Your goal is to ensure Quality Education (SDG 4). Be interactive, answer questions intelligently, and guide the discussion.`
          }
        });
        sessionPromiseRef.current = sessionPromise;
      } catch (err) {
        console.error("Failed to start session:", err);
        setError("Microphone and Camera permissions are required.");
        setIsConnecting(false);
      }
    };
    startSession();
    return () => {
      if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
      audioContextRef.current?.close();
      outputAudioContextRef.current?.close();
      sessionPromiseRef.current?.then((s: any) => s.close());
    };
  }, [groupName, mode]);

  function decode(base64: string) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number) {
    const dataInt16 = new Int16Array(data.buffer);
    const buffer = ctx.createBuffer(channels, dataInt16.length / channels, sampleRate);
    for (let c = 0; c < channels; c++) {
      const channelData = buffer.getChannelData(c);
      for (let i = 0; i < channelData.length; i++) {
        channelData[i] = dataInt16[i * channels + c] / 32768.0;
      }
    }
    return buffer;
  }

  function createBlob(data: Float32Array) {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
    return {
      data: btoa(String.fromCharCode(...new Uint8Array(int16.buffer))),
      mimeType: 'audio/pcm;rate=16000'
    };
  }

  return (
    <div className="w-full max-w-6xl bg-slate-900 border border-slate-800 rounded-[3rem] shadow-[0_32px_120px_-20px_rgba(0,0,0,0.9)] flex flex-col overflow-hidden max-h-[95vh]">
      <header className="p-6 border-b border-slate-800 flex items-center justify-between bg-slate-950/60 backdrop-blur-md">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-600/20 rounded-2xl text-indigo-400">
            {mode === 'video' ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 00-2 2z" /></svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
            )}
          </div>
          <div>
            <h2 className="text-xl font-black text-white tracking-tight leading-none mb-1 uppercase italic">{mode} Collaborative Session</h2>
            <p className="text-slate-500 text-[10px] font-bold tracking-widest uppercase">{groupName} • SDG 4 Quality Ed</p>
          </div>
        </div>
        <button onClick={onClose} className="p-3 hover:bg-red-600/20 hover:text-red-500 rounded-2xl transition-all text-slate-500 border border-slate-800">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
        </button>
      </header>

      <div className="flex-1 p-8 overflow-y-auto bg-slate-950">
        {isConnecting ? (
          <div className="flex flex-col items-center justify-center py-20">
            <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6"></div>
            <p className="text-indigo-400 font-bold uppercase tracking-widest text-xs animate-pulse">Syncing Nexus Media Core...</p>
          </div>
        ) : error ? (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="text-6xl mb-6">🚫</div>
            <p className="text-slate-200 font-black text-xl mb-2">{error}</p>
            <button onClick={onClose} className="mt-8 px-10 py-4 bg-slate-800 text-white font-bold rounded-2xl hover:bg-slate-700 transition-all">Exit Session</button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 h-full">
