            <div className="col-span-1 md:col-span-2 lg:col-span-2 aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden border border-slate-800 shadow-2xl relative group">
              {mode === 'video' && !isVideoOff ? (
