              <div className="absolute bottom-6 left-6 px-4 py-2 bg-slate-900/80 backdrop-blur-md rounded-xl text-white font-bold text-xs flex items-center gap-2 border border-white/10">
                <span className="w-2 h-2 rounded-full bg-green-500"></span> You (Lecturer)
