        <div className="p-4 bg-slate-900 border-t border-slate-800">
           <div className="flex items-center gap-3 bg-slate-800/50 p-2.5 rounded-xl border border-slate-700/50">
              <div className="w-8 h-8 rounded-lg bg-indigo-500 flex items-center justify-center text-xs font-bold text-white shadow-lg">JD</div>
              <div className="flex-1 min-w-0">
                <div className="text-xs font-bold text-white truncate">John Doe</div>
                <div className="text-[10px] text-green-500 flex items-center gap-1">
                   <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span> Online
                </div>
              </div>
           </div>
        </div>
      </div>

      {/* Main Viewport */}
      <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden">
        {!activeTopic ? (
          <div className="p-10 h-full overflow-y-auto">
            <header className="mb-12 flex flex-col md:flex-row md:items-end justify-between gap-6 bg-indigo-600/5 p-8 rounded-[3rem] border border-indigo-500/10">
              <div className="flex items-start gap-6">
                <div className="relative group/avatar">
                  <img src={group.avatar} className="w-24 h-24 rounded-3xl shadow-2xl border-4 border-slate-950 object-cover" alt="" />
                  <button 
                    onClick={() => {
                      setEditName(group.name);
                      setEditCategory(group.category || 'Community');
                      setEditAvatar(group.avatar);
                      setIsSettingsModalOpen(true);
                    }}
                    className="absolute -bottom-2 -right-2 bg-slate-900 border border-slate-700 p-2 rounded-xl text-indigo-400 hover:text-white hover:bg-indigo-600 shadow-xl transition-all"
                    title="Customize Hub"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  </button>
                </div>
