                  </div>
                  <p className="text-slate-400 max-w-xl text-lg leading-relaxed">Centralized resource repository and collaborative hub for quality academic exchange.</p>
                </div>
              </div>
            </header>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
              {group.topics.map((topic) => (
                <div 
                  key={topic.id}
