                             <div className="flex-1 min-w-0">
                                <h5 className="font-bold text-slate-100 truncate">{res.name}</h5>
                                <div className="flex items-center gap-3 mt-1">
                                   <span className="text-[10px] text-slate-500 font-bold uppercase">{res.size}</span>
                                   <span className="w-1 h-1 rounded-full bg-slate-700"></span>
                                   <span className="text-[10px] text-slate-500 font-bold uppercase">By {res.uploadedBy}</span>
