                             </button>
                          </div>
                        ))}
                      </div>
                    )}
                 </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Hub Settings / Customization Modal */}
      {isSettingsModalOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-lg rounded-[3rem] shadow-[0_32px_120px_-20px_rgba(0,0,0,0.8)] p-10">
            <h2 className="text-3xl font-black mb-8 text-white text-center italic uppercase tracking-tighter">Customize Hub</h2>
            <div className="space-y-8">
