                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Update Identity Image</label>
                <div className="flex gap-4">
                  {AVATAR_PRESETS.map((url) => (
                    <button
                      key={url}
                      onClick={() => setEditAvatar(url)}
                      className={`relative w-16 h-16 rounded-[1.5rem] overflow-hidden border-4 transition-all transform hover:scale-110 ${
                        editAvatar === url ? 'border-indigo-600 shadow-2xl scale-110' : 'border-slate-800 opacity-50 hover:opacity-100'
                      }`}
                    >
                      <img src={url} className="w-full h-full object-cover" alt="" />
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black mb-2 text-slate-500 uppercase tracking-[0.2em]">Workspace Name</label>
                <input 
                  type="text" 
                  value={editName}
                  onChange={(e) => setEditName(e.target.value)}
                  className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 outline-none focus:ring-4 focus:ring-indigo-600/20 text-white font-bold placeholder:text-slate-600"
                />
              </div>

              <div>
                <label className="block text-[10px] font-black mb-4 text-slate-500 uppercase tracking-[0.2em]">Industry Category</label>
                <div className="grid grid-cols-3 gap-3">
                   {CATEGORIES.map(cat => (
                     <button
                        key={cat}
                        onClick={() => setEditCategory(cat)}
                        className={`py-3 px-2 rounded-xl border font-bold text-[10px] uppercase tracking-widest transition-all ${editCategory === cat ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500'}`}
                     >
                        {cat}
                     </button>
                   ))}
                </div>
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => setIsSettingsModalOpen(false)}
                  className="flex-1 px-8 py-4 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-2xl transition-all font-bold uppercase text-[10px] tracking-widest"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleUpdateGroupSubmit}
                  className="flex-1 px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl transition-all font-black uppercase text-[10px] tracking-widest shadow-2xl shadow-indigo-600/40"
                >
                  Sync Hub
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Topic Creation Modal */}
      {isTopicModalOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-[3rem] shadow-[0_32px_120px_-20px_rgba(0,0,0,0.8)] p-10">
            <h2 className="text-3xl font-black mb-8 text-white text-center italic uppercase tracking-tighter">Add Learning Module</h2>
            <div className="space-y-6">
              <div>
                <label className="block text-[10px] font-black mb-2 text-slate-500 uppercase tracking-[0.2em]">Module Icon</label>
                <div className="flex gap-2">
                  {['📚', '📐', '📊', '🎯', '🧪', '🧬', '🎨'].map(emoji => (
                    <button 
                      key={emoji}
                      onClick={() => setNewTopicIcon(emoji)}
                      className={`text-2xl p-3 rounded-xl border transition-all ${newTopicIcon === emoji ? 'border-indigo-600 bg-indigo-600/10' : 'border-slate-800 bg-slate-800/50'}`}
                    >
                      {emoji}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black mb-2 text-slate-500 uppercase tracking-[0.2em]">Module Title</label>
                <input 
                  type="text" 
                  value={newTopicName}
                  onChange={(e) => setNewTopicName(e.target.value)}
