                >
                  Create Module
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DashboardArea;

import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onCreateTopic: (name: string, icon: string, description: string) => void;
  onUpdateGroup: (id: string, updates: Partial<Group>) => void;
}

const AVATAR_PRESETS = [
  'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=100&h=100&fit=crop',
  'https://images.unsplash.com/photo-1552664730-d307ca884978?w=100&h=100&fit=crop',
  'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=100&h=100&fit=crop',
  'https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?w=100&h=100&fit=crop',
];

const CATEGORIES: ('Education' | 'Corporate' | 'Community')[] = ['Education', 'Corporate', 'Community'];

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onUploadResource,
  onCreateTopic,
  onUpdateGroup
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources'>('discussion');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);

  // Topic creation states
  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicIcon, setNewTopicIcon] = useState('📚');
  const [newTopicDesc, setNewTopicDesc] = useState('');

  // Settings/Customization states
  const [editName, setEditName] = useState(group.name);
  const [editCategory, setEditCategory] = useState(group.category || 'Community');
  const [editAvatar, setEditAvatar] = useState(group.avatar);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const handleOpenSettings = () => {
    setEditName(group.name);
    setEditCategory(group.category || 'Community');
    setEditAvatar(group.avatar);
    setIsSettingsModalOpen(true);
  };

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel') || type.includes('spreadsheet')) return '📊';
    if (type.includes('word') || type.includes('text')) return '📄';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopicId) {
      onUploadResource(activeTopicId, {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`,
      });
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleCreateTopicSubmit = () => {
    if (newTopicName.trim()) {
      onCreateTopic(newTopicName, newTopicIcon, newTopicDesc);
      setNewTopicName('');
      setNewTopicIcon('📚');
      setNewTopicDesc('');
      setIsTopicModalOpen(false);
    }
  };

  const handleUpdateGroupSubmit = () => {
    onUpdateGroup(group.id, {
      name: editName,
      category: editCategory,
      avatar: editAvatar
    });
    setIsSettingsModalOpen(false);
  };

  return (
    <div className="flex h-full relative">
      {/* Topics Sidebar */}
      <div className="w-64 bg-slate-900 border-r border-slate-800 hidden md:flex flex-col shrink-0 shadow-xl">
        <div className="p-5 flex items-center justify-between border-b border-slate-800/50">
          <div className="font-bold uppercase tracking-widest text-[10px] text-indigo-400">Hub Navigation</div>
          <button 
            onClick={handleOpenSettings}
            className="text-slate-500 hover:text-indigo-400 transition-colors p-1.5 hover:bg-slate-800 rounded-lg"
            title="Workspace Settings"
