                      className={`text-2xl p-3 rounded-xl border transition-all ${newTopicIcon === emoji ? 'border-indigo-600 bg-indigo-600/10' : 'border-slate-800 bg-slate-800/50'}`}
                    >
                      {emoji}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black mb-2 text-slate-500 uppercase tracking-[0.2em]">Module Title</label>
                <input 
                  type="text" 
                  value={newTopicName}
                  onChange={(e) => setNewTopicName(e.target.value)}
