                />
              </div>

              <div>
                <label className="block text-[10px] font-black mb-2 text-slate-500 uppercase tracking-[0.2em]">Curriculum Summary</label>
                <textarea 
                  value={newTopicDesc}
                  onChange={(e) => setNewTopicDesc(e.target.value)}
                  rows={3}
                  className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 outline-none focus:ring-4 focus:ring-indigo-600/20 text-white font-medium placeholder:text-slate-600 resize-none text-sm"
                  placeholder="Describe the scope of this module..."
                />
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  onClick={() => setIsTopicModalOpen(false)}
                  className="flex-1 px-8 py-4 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-2xl transition-all font-bold uppercase text-[10px] tracking-widest"
                >
                  Dismiss
                </button>
                <button 
                  onClick={handleCreateTopicSubmit}
                  className="flex-1 px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl transition-all font-black uppercase text-[10px] tracking-widest shadow-2xl shadow-indigo-600/40"
                >
                  Create Module
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

