const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onUploadResource,
  onCreateTopic,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources'>('discussion');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);

  // Topic creation states
  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicIcon, setNewTopicIcon] = useState('📚');
  const [newTopicDesc, setNewTopicDesc] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel') || type.includes('spreadsheet')) return '📊';
    if (type.includes('word') || type.includes('text')) return '📄';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopicId) {
      onUploadResource(activeTopicId, {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`,
      });
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleCreateTopicSubmit = () => {
    if (newTopicName.trim()) {
      onCreateTopic(newTopicName, newTopicIcon, newTopicDesc);
      setNewTopicName('');
      setNewTopicIcon('📚');
      setNewTopicDesc('');
      setIsTopicModalOpen(false);
    }
  };

