  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const activeGroup = groups.find(g => g.id === activeGroupId) || groups[0];

  const handleCreateGroup = (name: string, type: GroupType, avatar: string) => {
    const newGroup: Group = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      topics: type === GroupType.TOPICS ? [
        { id: 'd1', name: 'Intro', description: 'Welcome to the workspace!', icon: '✨', messages: [], resources: [] }
      ] : [],
      messages: [],
      avatar,
      category: 'Community'
    };
    setGroups([...groups, newGroup]);
    setActiveGroupId(newGroup.id);
    setActiveTopicId(null);
    setIsSidebarOpen(false);
  };

  const handleCreateTopic = (name: string, icon: string, description: string) => {
    const newTopic: Topic = {
      id: `topic-${Date.now()}`,
      name,
      icon,
      description,
      messages: [],
      resources: []
    };

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return {
        ...g,
        topics: [...g.topics, newTopic]
      };
    }));
    setActiveTopicId(newTopic.id);
  };

  const handleUploadResource = (topicId: string, resourceData: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => {
    const newResource: Resource = {
      ...resourceData,
      id: `res-${Date.now()}`,
      uploadedBy: 'You',
      date: new Date()
    };

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return {
        ...g,
        topics: g.topics.map(t => {
          if (t.id !== topicId) return t;
          return {
            ...t,
            resources: [newResource, ...t.resources]
          };
        })
      };
    }));
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    const newMessage: Message = {
      id: Date.now().toString(),
      sender: 'You',
      text,
      timestamp: new Date(),
      avatar: 'https://picsum.photos/40/40?u=me',
      attachment
    };

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;

      if (g.type === GroupType.STANDARD) {
        return {
          ...g,
          messages: [...g.messages, newMessage],
          lastMessage: text
        };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => {
            if (t.id !== topicIdOrNull) return t;

            const newResources = attachment ? [
              {
                id: `res-${Date.now()}`,
                name: attachment.name,
                type: attachment.type,
                size: attachment.size,
                uploadedBy: 'You',
                date: new Date()
              },
              ...t.resources
            ] : t.resources;

            return {
              ...t,
              messages: [...t.messages, newMessage],
              resources: newResources
            };
          })
        };
      }
    }));
  };

  const handleSelectGroup = (id: string) => {
    setActiveGroupId(id);
    setActiveTopicId(null);
    // Note: Drawer remains open if it's a topic group to allow further nesting selection
  };

  const handleSelectTopic = (id: string | null) => {
    setActiveTopicId(id);
    setIsSidebarOpen(false); // Close drawer after nested topic is selected
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-200 relative">
      <Sidebar 
        groups={groups} 
        activeGroupId={activeGroupId} 
        activeTopicId={activeTopicId}
        onSelectGroup={handleSelectGroup}
        onSelectTopic={handleSelectTopic}
        onCreateGroup={handleCreateGroup}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className="flex-1 flex flex-col relative overflow-hidden h-full">
        {activeGroup.type === GroupType.STANDARD ? (
          <ChatArea 
            groupName={activeGroup.name} 
            messages={activeGroup.messages}
            onSendMessage={(text, att) => handleSendMessage(null, text, att)}
            onToggleMenu={() => setIsSidebarOpen(true)}
          />
        ) : (
          <DashboardArea 
            group={activeGroup} 
            activeTopicId={activeTopicId}
            onSelectTopic={handleSelectTopic}
            onOpenVoice={setSessionMode}
            onSendMessage={handleSendMessage}
            onUploadResource={handleUploadResource}
            onCreateTopic={handleCreateTopic}
            onToggleMenu={() => setIsSidebarOpen(true)}
          />
        )}

        {sessionMode && (
          <div className="absolute inset-0 z-50 bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-2 sm:p-4">
            <MeetingSession 
              mode={sessionMode}
              onClose={() => setSessionMode(null)} 
              groupName={activeTopicId ? activeGroup.topics.find(t => t.id === activeTopicId)?.name || activeGroup.name : activeGroup.name} 
            />
          </div>
        )}
      </main>
    </div>
  );
};

