import React, { useState, useRef, useEffect } from 'react';
import { Group, Message, Attachment } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  onSendMessage: (text: string, attachment?: Attachment) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
}

const ChatArea: React.FC<ChatAreaProps> = ({ groupName, messages, onSendMessage, headerContent, onToggleMenu }) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared a file: ${file.name}`, attachment);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50">
      <header className="p-4 border-b border-slate-800 bg-slate-900/80 backdrop-blur-md flex items-center justify-between z-10">
        <div className="flex items-center min-w-0">
          <button 
            onClick={onToggleMenu}
            className="p-2 mr-3 bg-slate-800 rounded-xl md:hidden text-slate-400 hover:text-white transition-all active:scale-90"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
          </button>
          <div className="text-lg font-bold text-white truncate">#{groupName}</div>
          <div className="hidden sm:flex ml-4 text-[10px] text-slate-500 items-center gap-2">
            <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
            Sync Active
          </div>
        </div>
        {headerContent}
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6">
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-30">
            <div className="text-5xl mb-4">💬</div>
            <p className="text-xs font-black uppercase tracking-[0.3em]">Beginning of thread</p>
          </div>
        )}
        {messages.map((m) => (
          <div key={m.id} className={`flex items-start gap-3 ${m.sender === 'You' ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-9 h-9 rounded-xl border border-slate-700 shadow-sm shrink-0" alt="" />
            <div className={`flex flex-col gap-1 max-w-[85%] ${m.sender === 'You' ? 'items-end' : ''}`}>
              <div className="flex items-center gap-2 px-1">
                <span className="text-[10px] font-bold text-indigo-400">{m.sender}</span>
                <span className="text-[9px] text-slate-600">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
              </div>
              <div className={`rounded-2xl p-4 shadow-lg border ${
                m.sender === 'You' 
                  ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                  : 'bg-slate-800 border-slate-700 text-slate-200 rounded-tl-none'
              }`}>
                {m.attachment && (
                  <div className="mb-3 p-3 bg-slate-950/40 rounded-xl flex items-center gap-3 border border-white/5">
                    <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400">
                       <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-xs font-bold truncate">{m.attachment.name}</div>
                      <div className="text-[9px] opacity-60 font-medium uppercase">{m.attachment.size}</div>
                    </div>
                  </div>
                )}
                <p className="text-sm leading-relaxed whitespace-pre-wrap">{m.text}</p>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="p-4 bg-slate-900/80 border-t border-slate-800">
        <div className="max-w-4xl mx-auto flex items-end gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="p-3 bg-slate-800 text-slate-400 hover:text-white rounded-xl transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
          <div className="flex-1 relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Your message..."
              className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-5 py-3 pr-14 outline-none focus:ring-2 focus:ring-indigo-500 transition-all resize-none max-h-40 min-h-[48px]"
              rows={1}
            />
            <button 
              onClick={handleSend}
              className="absolute right-2 bottom-2 bg-indigo-600 text-white p-2 rounded-xl disabled:opacity-50"
              disabled={!input.trim()}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

