import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onCreateTopic: (name: string, icon: string, description: string) => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onUploadResource,
  onCreateTopic,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources'>('discussion');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);

  // Topic creation states
  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicIcon, setNewTopicIcon] = useState('📚');
  const [newTopicDesc, setNewTopicDesc] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel') || type.includes('spreadsheet')) return '📊';
    if (type.includes('word') || type.includes('text')) return '📄';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopicId) {
      onUploadResource(activeTopicId, {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`,
      });
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleCreateTopicSubmit = () => {
    if (newTopicName.trim()) {
      onCreateTopic(newTopicName, newTopicIcon, newTopicDesc);
      setNewTopicName('');
      setNewTopicIcon('📚');
      setNewTopicDesc('');
      setIsTopicModalOpen(false);
    }
  };

  return (
    <div className="flex h-full relative">
      {/* Desktop-only Topics Sidebar (Internal Hub Navigation) */}
      <div className="w-64 bg-slate-900 border-r border-slate-800 hidden lg:flex flex-col shrink-0 shadow-xl">
        <div className="p-5 flex items-center justify-between border-b border-slate-800/50">
          <div className="font-bold uppercase tracking-widest text-[10px] text-indigo-400">Hub Navigation</div>
        </div>

        <div className="flex-1 overflow-y-auto px-3 py-4 space-y-1">
          <div className="px-3 mb-2 flex items-center justify-between">
            <span className="font-bold text-[10px] uppercase text-slate-500 tracking-wider">Learning Modules</span>
            <button 
              onClick={() => setIsTopicModalOpen(true)}
              className="p-1 hover:bg-indigo-600/10 hover:text-indigo-400 text-slate-600 rounded-md transition-all"
              title="Add Module"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            </button>
          </div>
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-3 rounded-xl flex items-center gap-3 transition-all ${
                activeTopicId === topic.id 
                  ? 'bg-indigo-600/10 text-indigo-400 font-bold border border-indigo-500/30 shadow-lg shadow-indigo-500/5' 
                  : 'text-slate-400 hover:bg-slate-800/80 hover:text-slate-100'
              }`}
            >
              <span className="text-xl leading-none">{topic.icon}</span>
              <span className="truncate flex-1 text-sm">{topic.name}</span>
              {topic.activeCall && (
                <span className="flex h-2 w-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)] animate-pulse"></span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Main Viewport */}
      <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden">
        {!activeTopic ? (
          <div className="flex flex-col h-full">
            {/* Simple Mobile Header when no topic is selected */}
            <header className="p-4 border-b border-slate-800 bg-slate-900/50 flex items-center justify-between md:hidden">
              <div className="flex items-center gap-3 min-w-0">
                <button onClick={onToggleMenu} className="p-2 bg-slate-800 rounded-xl text-slate-400">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
                </button>
                <img src={group.avatar} className="w-8 h-8 rounded-lg object-cover" alt="" />
                <h1 className="font-black text-white truncate text-sm">{group.name}</h1>
              </div>
              <button onClick={() => setIsTopicModalOpen(true)} className="p-2 bg-indigo-600 text-white rounded-xl">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
              </button>
            </header>

            <div className="flex-1 flex flex-col items-center justify-center p-6 text-center">
              {/* Grid hidden on Mobile to save time/space */}
              <div className="hidden md:block w-full max-w-5xl">
                <header className="mb-12 bg-indigo-600/5 p-8 rounded-[3rem] border border-indigo-500/10 text-left">
                  <div className="flex items-center gap-6">
                    <img src={group.avatar} className="w-24 h-24 rounded-3xl shadow-2xl border-4 border-slate-950 object-cover" alt="" />
                    <div>
                      <h1 className="text-5xl font-black text-white tracking-tighter mb-2">{group.name}</h1>
                      <p className="text-slate-400 max-w-xl">Select a module from the nested list to start collaborating.</p>
                    </div>
                  </div>
                </header>

                <div className="grid grid-cols-2 lg:grid-cols-3 gap-6">
                  {group.topics.map((topic) => (
                    <div 
                      key={topic.id}
                      onClick={() => onSelectTopic(topic.id)}
                      className="bg-slate-900/40 border border-slate-800 p-6 rounded-[2.5rem] hover:border-indigo-500 hover:bg-indigo-900/10 transition-all cursor-pointer group"
                    >
                      <div className="text-4xl mb-4 group-hover:scale-110 transition-transform origin-left">{topic.icon}</div>
                      <h3 className="text-xl font-extrabold text-white mb-2">{topic.name}</h3>
                      <div className="text-[10px] font-black uppercase tracking-widest text-indigo-400">Enter Topic →</div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Mobile Placeholder (Lighter) */}
              <div className="md:hidden">
                <div className="text-6xl mb-6 opacity-20">📂</div>
                <h2 className="text-2xl font-black text-white mb-2 italic">Select a Topic</h2>
                <p className="text-slate-500 text-sm max-w-[240px] mb-8">Tap the menu icon or use the nested list in the sidebar to view discussions and resources.</p>
                <button 
                  onClick={onToggleMenu}
                  className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-2xl shadow-indigo-600/30"
                >
                  Open Hub Navigation
                </button>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex flex-col h-full">
            <div className="bg-slate-900 border-b border-slate-800 p-3 sm:p-4 flex flex-col sm:flex-row items-center justify-between gap-4">
               <div className="flex items-center gap-3 sm:gap-4 min-w-0 w-full sm:w-auto">
                  <button 
                    onClick={onToggleMenu}
                    className="p-2 sm:p-2.5 bg-slate-800 rounded-xl md:hidden text-slate-400"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 sm:h-6 sm:w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
                  </button>
                  <div className="text-2xl sm:text-3xl shrink-0">{activeTopic.icon}</div>
                  <div className="min-w-0">
                    <h2 className="text-lg sm:text-xl font-black text-white leading-none mb-1 truncate">{activeTopic.name}</h2>
                    <p className="text-[9px] sm:text-[10px] text-slate-500 font-medium uppercase tracking-widest truncate">{group.name}</p>
                  </div>
               </div>

               <div className="flex items-center gap-1 bg-slate-950 p-1 rounded-2xl border border-slate-800 shadow-inner w-full sm:w-auto justify-center">
                  <button 
                    onClick={() => setViewMode('discussion')}
                    className={`flex-1 sm:flex-none px-4 sm:px-5 py-2 rounded-xl text-[10px] sm:text-xs font-bold transition-all ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
                  >
                    Chat
                  </button>
                  <button 
                    onClick={() => setViewMode('resources')}
                    className={`flex-1 sm:flex-none px-4 sm:px-5 py-2 rounded-xl text-[10px] sm:text-xs font-bold transition-all ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
                  >
                    Library ({activeTopic.resources.length})
                  </button>
               </div>

               <div className="flex items-center gap-2">
                 <button onClick={() => onOpenVoice('voice')} className="p-2 sm:p-2.5 bg-indigo-600/10 text-indigo-400 rounded-xl" title="Voice Channel">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z" clipRule="evenodd" /></svg>
                 </button>
                 <button onClick={() => onOpenVoice('video')} className="p-2 sm:p-2.5 bg-indigo-600/10 text-indigo-400 rounded-xl" title="Video Session">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M2 6a2 2 0 012-2h6a2 2 0 012 2v8a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14.553 7.106A1 1 0 0014 8v4a1 1 0 00.553.894l2 1A1 1 0 0018 13V7a1 1 0 00-1.447-.894l-2 1z" /></svg>
                 </button>
               </div>
            </div>

            {viewMode === 'discussion' ? (
              <ChatArea 
                groupName={activeTopic.name}
                messages={activeTopic.messages}
                onSendMessage={(text, attachment) => onSendMessage(activeTopic.id, text, attachment)}
                headerContent={null}
                onToggleMenu={onToggleMenu}
              />
            ) : (
              <div className="flex-1 overflow-y-auto p-4 sm:p-10 bg-slate-950">
                 <div className="max-w-5xl mx-auto">
                    <div className="flex items-center justify-between mb-8">
                       <h3 className="text-xl sm:text-2xl font-black text-white">Library</h3>
                       <button 
                          onClick={() => fileInputRef.current?.click()}
                          className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl font-bold text-xs shadow-lg flex items-center gap-2"
                        >
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                          Upload
                       </button>
                       <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileChange} accept=".pdf" />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                      {activeTopic.resources.map(res => (
                        <div key={res.id} className="bg-slate-900 border border-slate-800 p-4 rounded-2xl flex items-center gap-4">
                           <div className="w-12 h-12 bg-slate-800 rounded-xl flex items-center justify-center text-2xl">{getFileIcon(res.type)}</div>
                           <div className="flex-1 min-w-0">
                              <h5 className="font-bold text-slate-100 truncate text-sm">{res.name}</h5>
                              <span className="text-[10px] text-slate-500 font-bold uppercase">{res.size}</span>
                           </div>
                        </div>
                      ))}
                    </div>
                 </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Topic Creation Modal */}
      {isTopicModalOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-[2.5rem] p-8 shadow-2xl">
            <h2 className="text-2xl font-black mb-6 text-white text-center italic uppercase">Add Module</h2>
            <div className="space-y-6">
              <input 
                type="text" 
                value={newTopicName}
                onChange={(e) => setNewTopicName(e.target.value)}
                className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 text-white font-bold"
                placeholder="Module Title"
              />
              <textarea 
                value={newTopicDesc}
                onChange={(e) => setNewTopicDesc(e.target.value)}
                rows={2}
                className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 text-white resize-none"
                placeholder="Summary"
              />
              <div className="flex gap-4">
                <button onClick={() => setIsTopicModalOpen(false)} className="flex-1 px-8 py-3 bg-slate-800 text-slate-400 rounded-2xl font-bold uppercase text-[10px]">Cancel</button>
                <button onClick={handleCreateTopicSubmit} className="flex-1 px-8 py-3 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px]">Create</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

