  onToggleMenu?: () => void;
}

const ChatArea: React.FC<ChatAreaProps> = ({ groupName, messages, members, onSendMessage, onAddMember, headerContent, onToggleMenu }) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);

  const [newMemberName, setNewMemberName] = useState('');
  const [newMemberRole, setNewMemberRole] = useState<GroupMember['role']>('Member');

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
  };

  const handleInviteSubmit = () => {
    if (newMemberName.trim()) {
      onAddMember(newMemberName, newMemberRole);
      setNewMemberName('');
      setIsInviteModalOpen(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared a file: ${file.name}`, attachment);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900/50 relative">
      <header className="p-4 border-b border-slate-800 bg-slate-900/80 backdrop-blur-md flex items-center justify-between z-10">
        <div className="flex items-center min-w-0">
          <button 
            onClick={onToggleMenu}
            className="p-2 mr-3 bg-slate-800 rounded-xl md:hidden text-slate-400 hover:text-white transition-all active:scale-90"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
          </button>
          <div className="text-lg font-bold text-white truncate">#{groupName}</div>
        </div>

        <div className="flex items-center gap-2">
          {headerContent}
          <button 
            onClick={() => setShowMembers(!showMembers)}
            className={`p-2 rounded-xl transition-all ${showMembers ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'bg-slate-800 text-slate-400 hover:text-slate-100'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-6">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center opacity-30">
              <div className="text-5xl mb-4">💬</div>
              <p className="text-xs font-black uppercase tracking-[0.3em]">Beginning of thread</p>
            </div>
          )}
          {messages.map((m) => (
            <div key={m.id} className={`flex items-start gap-3 ${m.sender === 'You' ? 'flex-row-reverse' : ''}`}>
              <img src={m.avatar} className="w-9 h-9 rounded-xl border border-slate-700 shadow-sm shrink-0" alt="" />
              <div className={`flex flex-col gap-1 max-w-[85%] ${m.sender === 'You' ? 'items-end' : ''}`}>
                <div className="flex items-center gap-2 px-1">
                  <span className="text-[10px] font-bold text-indigo-400">{m.sender}</span>
                  <span className="text-[9px] text-slate-600">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                </div>
                <div className={`rounded-2xl p-4 shadow-lg border ${
                  m.sender === 'You' 
                    ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                    : 'bg-slate-800 border-slate-700 text-slate-200 rounded-tl-none'
                }`}>
                  {m.attachment && (
                    <div className="mb-3 p-3 bg-slate-950/40 rounded-xl flex items-center gap-3 border border-white/5">
                      <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400">
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="text-xs font-bold truncate">{m.attachment.name}</div>
                        <div className="text-[9px] opacity-60 font-medium uppercase">{m.attachment.size}</div>
                      </div>
                    </div>
                  )}
                  <p className="text-sm leading-relaxed whitespace-pre-wrap">{m.text}</p>
                </div>
              </div>
            </div>
          ))}
        </div>

        {showMembers && (
          <div className="absolute inset-y-0 right-0 w-64 bg-slate-900 border-l border-slate-800 z-20 shadow-2xl flex flex-col slide-in-right">
             <div className="p-5 border-b border-slate-800 flex items-center justify-between">
                <span className="text-[10px] font-black uppercase text-indigo-400 tracking-widest">Active Members</span>
                <button onClick={() => setIsInviteModalOpen(true)} className="p-1.5 bg-indigo-600 text-white rounded-lg shadow-lg hover:bg-indigo-500 transition-colors">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-4">
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[8px] font-black text-slate-600 uppercase mb-3 ml-2">{status} — {filtered.length}</div>
                      <div className="space-y-1">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-3 p-2 rounded-xl hover:bg-slate-800/50 transition-all cursor-pointer">
                            <img src={member.avatar} className="w-8 h-8 rounded-lg object-cover" alt="" />
                            <div className="min-w-0">
                               <div className="text-xs font-bold text-slate-200 truncate">{member.name}</div>
                               <div className="text-[8px] text-slate-500 uppercase">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-900/80 border-t border-slate-800">
        <div className="max-w-4xl mx-auto flex items-end gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-800 text-slate-400 hover:text-white rounded-xl transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
          <div className="flex-1 relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Your message..."
              className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-5 py-3 pr-14 outline-none focus:ring-2 focus:ring-indigo-500 transition-all resize-none max-h-40 min-h-[48px]"
              rows={1}
            />
            <button onClick={handleSend} className="absolute right-2 bottom-2 bg-indigo-600 text-white p-2 rounded-xl disabled:opacity-50" disabled={!input.trim()}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </div>
      </div>

      {isInviteModalOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-[2.5rem] p-8 shadow-2xl">
            <h2 className="text-2xl font-black mb-6 text-white text-center italic uppercase tracking-tighter">Invite Nexus Link</h2>
            <div className="space-y-6">
              <div>
                 <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Display Name</label>
                 <input type="text" value={newMemberName} onChange={(e) => setNewMemberName(e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 text-white font-bold" placeholder="Identity Signature" />
              </div>
              <div>
                 <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Permissions</label>
                 <select value={newMemberRole} onChange={(e) => setNewMemberRole(e.target.value as any)} className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 text-white font-bold appearance-none">
                    <option value="Member">Member</option>
                    <option value="Admin">Admin</option>
                    <option value="Owner">Owner</option>
                    <option value="AI Assistant">AI Assistant</option>
                 </select>
              </div>
              <div className="flex gap-4">
                <button onClick={() => setIsInviteModalOpen(false)} className="flex-1 px-8 py-4 bg-slate-800 text-slate-400 rounded-2xl font-bold uppercase text-[10px]">Cancel</button>
                <button onClick={handleInviteSubmit} className="flex-1 px-8 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] shadow-xl">Confirm</button>
              </div>
            </div>
          </div>
        </div>
      )}

      <style>{`
        .slide-in-right { animation: slideInRight 0.2s ease-out; }
        @keyframes slideInRight {
          from { transform: translateX(100%); }
          to { transform: translateX(0); }
        }
      `}</style>
    </div>
  );
};

export default ChatArea;

import React, { useState } from 'react';
import { Group, GroupType } from '../types';

interface SidebarProps {
