      {isModalOpen && (
        <div className="fixed inset-0 z-[100] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-[2.5rem] shadow-2xl p-8">
            <h2 className="text-2xl font-black mb-8 text-white text-center italic uppercase tracking-tighter">Initialize Hub</h2>
            <div className="space-y-6">
              <div>
                <label className="block text-[10px] font-black mb-2 text-slate-500 uppercase tracking-widest text-center">Identity Signature</label>
                <div className="flex gap-4 justify-center">
                  {AVATAR_PRESETS.map((url) => (
                    <button
                      key={url}
                      onClick={() => setSelectedAvatar(url)}
                      className={`w-12 h-12 rounded-xl border-2 transition-all ${selectedAvatar === url ? 'border-indigo-600 scale-110 shadow-lg' : 'border-slate-800 opacity-50'}`}
                    >
                      <img src={url} className="w-full h-full object-cover rounded-lg" alt="" />
                    </button>
                  ))}
                </div>
              </div>
              <input 
                type="text" 
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
                className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 text-white font-bold"
