              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => setNewType(GroupType.STANDARD)}
                  className={`p-4 rounded-2xl border-2 transition-all text-center ${newType === GroupType.STANDARD ? 'border-indigo-600 bg-indigo-600/10' : 'border-slate-800'}`}
                >
                  <div className="text-2xl mb-1">💬</div>
                  <div className="font-black text-[10px] text-white uppercase">Standard</div>
                </button>
                <button 
                  onClick={() => setNewType(GroupType.TOPICS)}
                  className={`p-4 rounded-2xl border-2 transition-all text-center ${newType === GroupType.TOPICS ? 'border-indigo-600 bg-indigo-600/10' : 'border-slate-800'}`}
                >
                  <div className="text-2xl mb-1">🎓</div>
                  <div className="font-black text-[10px] text-white uppercase">Structured</div>
                </button>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsModalOpen(false)} className="flex-1 py-4 bg-slate-800 text-slate-400 rounded-2xl font-bold uppercase text-[10px] tracking-widest">Cancel</button>
                <button onClick={() => { if (newName) { onCreateGroup(newName, newType, selectedAvatar); setIsModalOpen(false); setNewName(''); } }} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl">Create</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </aside>
  );
};

