        name: 'Q4 Roadmap', 
        description: 'Resource management and project milestones.', 
        icon: '🎯',
        messages: [],
        resources: [
          { id: 'r2', name: 'Budget_Draft.xlsx', type: 'application/vnd.ms-excel', size: '1.1 MB', uploadedBy: 'Jane Doe', date: new Date() }
        ]
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=100&h=100&fit=crop'
  }
];

const App: React.FC = () => {
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    if (!isMobile && activeGroupId === null) {
      setActiveGroupId('edu-1');
    }
    return () => window.removeEventListener('resize', handleResize);
  }, [isMobile, activeGroupId]);

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  const handleCreateGroup = (name: string, type: GroupType, avatar: string) => {
    const newGroup: Group = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      topics: type === GroupType.TOPICS ? [
        { id: 'd1', name: 'Intro', description: 'Welcome!', icon: '✨', messages: [], resources: [] }
      ] : [],
      messages: [],
      members: [{ id: '1', name: 'You', avatar: 'https://picsum.photos/80/80?u=1', role: 'Owner', status: 'online' }],
      avatar,
      category: 'Community'
    };
    setGroups([...groups, newGroup]);
    setActiveGroupId(newGroup.id);
    setActiveTopicId(null);
  };

  const handleAddMember = (groupId: string, name: string, role: GroupMember['role']) => {
    const newMember: GroupMember = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      role,
      avatar: `https://picsum.photos/80/80?u=${Math.random()}`,
      status: 'online'
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== groupId) return g;
      return { ...g, members: [...g.members, newMember] };
    }));
  };

  const handleUploadResource = (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => {
    const newResource: Resource = {
      ...resource,
      id: Date.now().toString(),
      uploadedBy: 'You',
      date: new Date()
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return {
        ...g,
        topics: g.topics.map(t => {
          if (t.id !== topicId) return t;
          return { ...t, resources: [...t.resources, newResource] };
        })
      };
    }));
  };

  const handleCreateTopic = (name: string, icon: string, description: string) => {
    const newTopic: Topic = {
      id: `topic-${Date.now()}`,
      name,
      icon,
      description,
      messages: [],
      resources: []
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return { ...g, topics: [...g.topics, newTopic] };
    }));
    setActiveTopicId(newTopic.id);
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    const newMessage: Message = {
      id: Date.now().toString(),
      sender: 'You',
      text,
      timestamp: new Date(),
      avatar: 'https://picsum.photos/40/40?u=1',
      attachment
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => {
            if (t.id !== topicIdOrNull) return t;
            return { ...t, messages: [...t.messages, newMessage] };
          })
        };
      }
    }));
  };

  const handleSelectGroup = (id: string) => {
    setActiveGroupId(id);
    setActiveTopicId(null);
  };

  const handleSelectTopic = (id: string | null) => {
    setActiveTopicId(id);
  };

  const handleBack = () => {
    if (activeTopicId) {
      setActiveTopicId(null);
    } else {
      setActiveGroupId(null);
    }
  };

  const showContent = isMobile ? (activeGroup?.type === GroupType.STANDARD || (activeGroup?.type === GroupType.TOPICS && activeTopicId !== null)) : true;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-200 relative">
      {(!showContent || !isMobile) && (
        <Sidebar 
          groups={groups} 
          activeGroupId={activeGroupId || ''} 
          activeTopicId={activeTopicId}
          onSelectGroup={handleSelectGroup}
          onSelectTopic={handleSelectTopic}
          onCreateGroup={handleCreateGroup}
          onJoinVoice={setSessionMode}
          isOpen={true}
          onClose={() => {}}
        />
      )}

      {(showContent || !isMobile) && activeGroup && (
        <main className={`flex-1 flex flex-col relative overflow-hidden h-full ${isMobile ? 'fixed inset-0 z-50 bg-slate-950' : ''}`}>
          {activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              onSendMessage={(text, att) => handleSendMessage(null, text, att)}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onToggleMenu={handleBack}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              activeTopicId={activeTopicId}
              onSelectTopic={handleSelectTopic}
              onOpenVoice={setSessionMode}
              onSendMessage={handleSendMessage}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onUploadResource={handleUploadResource}
              onCreateTopic={handleCreateTopic}
              onToggleMenu={handleBack}
            />
          )}

          {sessionMode && (
            <div className="absolute inset-0 z-[60] bg-slate-950/90 backdrop-blur-md flex items-center justify-center p-2 sm:p-4">
              <MeetingSession 
                mode={sessionMode}
                onClose={() => setSessionMode(null)} 
                groupName={activeTopicId ? activeGroup.topics.find(t => t.id === activeTopicId)?.name || activeGroup.name : activeGroup.name} 
              />
            </div>
          )}
        </main>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onCreateTopic: (name: string, icon: string, description: string) => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onAddMember,
  onUploadResource,
  onCreateTopic,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [isAddMemberModalOpen, setIsAddMemberModalOpen] = useState(false);

  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicIcon, setNewTopicIcon] = useState('📚');

  const [newMemberName, setNewMemberName] = useState('');
  const [newMemberRole, setNewMemberRole] = useState<GroupMember['role']>('Member');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel') || type.includes('spreadsheet') || type.includes('csv')) return '📊';
    if (type.includes('word') || type.includes('text') || type.includes('document')) return '📄';
    if (type.includes('image')) return '🖼️';
    if (type.includes('presentation') || type.includes('powerpoint')) return '📽️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      // Reset input
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-red-500/10 text-red-500 border-red-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-800 text-slate-400 border-slate-700';
    }
  };

  const handleCreateTopicSubmit = () => {
    if (newTopicName.trim()) {
      onCreateTopic(newTopicName, newTopicIcon, '');
      setIsTopicModalOpen(false);
    }
  };

  const handleAddMemberSubmit = () => {
    if (newMemberName.trim()) {
      onAddMember(newMemberName, newMemberRole);
      setNewMemberName('');
      setIsAddMemberModalOpen(false);
    }
  };

  return (
    <div className="flex h-full relative">
      <div className="w-64 bg-slate-900 border-r border-slate-800 hidden lg:flex flex-col shrink-0 shadow-xl">
        <div className="p-5 border-b border-slate-800/50">
          <div className="font-bold uppercase tracking-widest text-[10px] text-indigo-400">Hub Navigation</div>
        </div>
        <div className="flex-1 overflow-y-auto px-3 py-4 space-y-1">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-3 rounded-xl flex items-center gap-3 transition-all ${
                activeTopicId === topic.id ? 'bg-indigo-600/10 text-indigo-400 font-bold border border-indigo-500/30 shadow-lg' : 'text-slate-400 hover:bg-slate-800/80 hover:text-slate-100'
              }`}
            >
              <span className="text-xl">{topic.icon}</span>
              <span className="truncate flex-1 text-sm">{topic.name}</span>
            </button>
          ))}
          <button 
            onClick={() => setIsTopicModalOpen(true)}
            className="w-full text-left p-3 rounded-xl flex items-center gap-3 text-slate-500 hover:bg-slate-800/80 hover:text-slate-300 border border-dashed border-slate-700 mt-4"
          >
            <span className="text-xl">➕</span>
            <span className="truncate flex-1 text-[10px] font-black uppercase tracking-widest">Add Module</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col bg-slate-950 overflow-hidden">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-6 text-center">
             <div className="text-6xl mb-6 opacity-20">📂</div>
             <h2 className="text-2xl font-black text-white mb-2 italic">Select a Topic</h2>
             <button onClick={onToggleMenu} className="px-10 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-2xl">Open Hub Navigation</button>
