                  <button onClick={() => setViewMode('resources')} className={`px-4 py-2 rounded-xl text-[10px] font-bold transition-all ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>Library</button>
                  <button onClick={() => setViewMode('members')} className={`px-4 py-2 rounded-xl text-[10px] font-bold transition-all ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}>Members</button>
               </div>

               <div className="flex items-center gap-2">
                 <button onClick={() => onOpenVoice('voice')} className="p-2 bg-indigo-600/10 text-indigo-400 rounded-xl"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M7 4a3 3 0 016 0v4a3 3 0 11-6 0V4zm4 10.93A7.001 7.001 0 0017 8a1 1 0 10-2 0A5 5 0 015 8a1 1 0 00-2 0 7.001 7.001 0 006 6.93V17H6a1 1 0 100 2h8a1 1 0 100-2h-3v-2.07z" clipRule="evenodd" /></svg></button>
                 <button onClick={() => onOpenVoice('video')} className="p-2 bg-indigo-600/10 text-indigo-400 rounded-xl"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M2 6a2 2 0 012-2h6a2 2 0 012 2v8a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14.553 7.106A1 1 0 0014 8v4a1 1 0 00.553.894l2 1A1 1 0 0018 13V7a1 1 0 00-1.447-.894l-2 1z" /></svg></button>
               </div>
            </div>

            <div className="flex-1 overflow-hidden relative">
              {viewMode === 'discussion' && (
                <ChatArea groupName={activeTopic.name} messages={activeTopic.messages} members={group.members} onSendMessage={(text, attachment) => onSendMessage(activeTopic.id, text, attachment)} onAddMember={onAddMember} onToggleMenu={onToggleMenu} />
