                 <input type="text" value={newMemberName} onChange={(e) => setNewMemberName(e.target.value)} className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 text-white font-bold" placeholder="Full Name or Handle" />
              </div>
              <div>
                 <label className="block text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Access Role</label>
                 <select value={newMemberRole} onChange={(e) => setNewMemberRole(e.target.value as any)} className="w-full bg-slate-800 border border-slate-700 rounded-2xl p-4 text-white font-bold appearance-none">
                    <option value="Member">Member</option>
                    <option value="Admin">Admin</option>
                    <option value="Owner">Owner</option>
                    <option value="AI Assistant">AI Assistant</option>
                 </select>
