export default DashboardArea;

import React, { useState, useRef, useEffect } from 'react';
import { Group, Message, Attachment, GroupMember } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  onSendMessage: (text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
}

const ChatArea: React.FC<ChatAreaProps> = ({ groupName, messages, members, onSendMessage, onAddMember, headerContent, onToggleMenu }) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);

  const [newMemberName, setNewMemberName] = useState('');
  const [newMemberRole, setNewMemberRole] = useState<GroupMember['role']>('Member');

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
  };

  const handleInviteSubmit = () => {
    if (newMemberName.trim()) {
      onAddMember(newMemberName, newMemberRole);
      setNewMemberName('');
      setIsInviteModalOpen(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared a file: ${file.name}`, attachment);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 relative overflow-hidden">
      <header className="px-6 py-5 border-b border-slate-900 bg-slate-950/80 backdrop-blur-xl flex items-center justify-between z-10">
        <div className="flex items-center min-w-0">
          <button 
            onClick={onToggleMenu}
            className="p-3 mr-4 bg-slate-900 rounded-2xl md:hidden text-slate-400 hover:text-white transition-all border border-slate-800"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
            </svg>
          </button>
          <div className="text-lg font-extrabold text-white truncate tracking-tight uppercase italic flex items-center gap-3">
             <span className="text-indigo-500 opacity-60">#</span> {groupName}
          </div>
        </div>

        <div className="flex items-center gap-4">
          {headerContent}
          <button 
            onClick={() => setShowMembers(!showMembers)}
            className={`p-3 rounded-2xl border transition-all duration-300 ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-xl shadow-indigo-600/20' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-slate-300'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center p-12 opacity-20">
              <div className="w-20 h-20 bg-slate-900 rounded-[2rem] flex items-center justify-center text-4xl mb-6 border border-slate-800">💬</div>
              <p className="text-[11px] font-bold uppercase tracking-[0.4em] text-white">Encrypted Feed Established</p>
              <p className="text-xs font-medium text-slate-500 mt-2">Messages are synchronized across the Nexus hub network.</p>
            </div>
          )}
          {messages.map((m) => {
            const isMe = m.sender === 'You';
            return (
              <div key={m.id} className={`flex items-start gap-4 ${isMe ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                <img src={m.avatar} className="w-10 h-10 rounded-2xl border-2 border-slate-900 shadow-xl shrink-0 object-cover" alt="" />
                <div className={`flex flex-col gap-2 max-w-[80%] md:max-w-[70%] ${isMe ? 'items-end' : ''}`}>
                  <div className="flex items-center gap-3 px-1">
                    <span className="text-[11px] font-extrabold text-indigo-400 uppercase tracking-tight italic">{m.sender}</span>
                    <span className="text-[10px] text-slate-600 font-bold">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                  <div className={`rounded-[1.8rem] p-5 shadow-2xl border transition-all ${
                    isMe 
                      ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
