                    {m.attachment && (
                      <div className="mb-4 p-4 bg-black/30 rounded-2xl flex items-center gap-4 border border-white/5 backdrop-blur-md">
                        <div className="p-3 bg-indigo-500/20 rounded-xl text-indigo-400">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="text-sm font-bold truncate tracking-tight">{m.attachment.name}</div>
                          <div className="text-[10px] opacity-60 font-black uppercase tracking-widest mt-1">{m.attachment.size}</div>
                        </div>
                      </div>
                    )}
                    <p className="text-[15px] leading-relaxed whitespace-pre-wrap font-medium">{m.text}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {showMembers && (
          <div className="absolute inset-y-0 right-0 w-80 bg-slate-950 border-l border-slate-900 z-20 shadow-[0_0_100px_rgba(0,0,0,0.8)] flex flex-col animate-in slide-in-from-right duration-300">
             <div className="p-6 border-b border-slate-900 flex items-center justify-between">
