                            </div>
                            <div className="min-w-0">
                               <div className="text-sm font-bold text-white truncate tracking-tight">{member.name}</div>
                               <div className="text-[9px] text-slate-500 font-extrabold uppercase tracking-widest mt-1">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      <div className="p-6 bg-slate-950/80 backdrop-blur-xl border-t border-slate-900">
        <div className="max-w-4xl mx-auto flex items-end gap-4">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="p-4 bg-slate-900 text-slate-500 hover:text-indigo-400 hover:bg-indigo-600/10 rounded-2xl border border-slate-800 transition-all active:scale-95 shadow-xl">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </button>
          <div className="flex-1 relative group">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              className="w-full bg-slate-900 border border-slate-800 rounded-3xl px-6 py-4 pr-16 outline-none focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all resize-none max-h-48 min-h-[56px] text-slate-200 font-medium placeholder:text-slate-600 shadow-inner"
              rows={1}
            />
            <button 
              onClick={handleSend} 
              className="absolute right-3 bottom-3 bg-indigo-600 hover:bg-indigo-500 text-white p-3 rounded-2xl disabled:opacity-20 transition-all shadow-xl active:scale-95 group-hover:scale-105" 
              disabled={!input.trim()}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </div>
      </div>

      {isInviteModalOpen && (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-xl flex items-center justify-center p-6">
          <div className="bg-slate-950 border border-slate-900 w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95 duration-300">
            <h2 className="text-2xl font-extrabold mb-8 text-white text-center italic uppercase tracking-tight">Signal Hub Member</h2>
            <div className="space-y-8">
              <div>
                 <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-3 px-2">Display Identification</label>
                 <input type="text" value={newMemberName} onChange={(e) => setNewMemberName(e.target.value)} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 text-white font-bold outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Identity Signature" />
              </div>
              <div>
                 <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-3 px-2">Permissions Registry</label>
                 <select value={newMemberRole} onChange={(e) => setNewMemberRole(e.target.value as any)} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 text-white font-bold appearance-none outline-none focus:ring-2 focus:ring-indigo-500">
                    <option value="Member">Regular Contributor</option>
                    <option value="Admin">Security Overseer</option>
                    <option value="Owner">Root Administrator</option>
                    <option value="AI Assistant">Synthetic Agent</option>
                 </select>
              </div>
              <div className="flex gap-4 pt-4">
                <button onClick={() => setIsInviteModalOpen(false)} className="flex-1 py-5 bg-slate-900 text-slate-500 rounded-3xl font-bold uppercase text-[11px] tracking-widest">Abort</button>
                <button onClick={handleInviteSubmit} className="flex-1 py-5 bg-indigo-600 text-white rounded-3xl font-extrabold uppercase text-[11px] tracking-widest shadow-xl transition-all active:scale-95">Link Member</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

