import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onCreateTopic: (name: string, icon: string, description: string) => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onAddMember,
  onUploadResource,
  onCreateTopic,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [isAddMemberModalOpen, setIsAddMemberModalOpen] = useState(false);

  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicIcon, setNewTopicIcon] = useState('📚');

  const [newMemberName, setNewMemberName] = useState('');
  const [newMemberRole, setNewMemberRole] = useState<GroupMember['role']>('Member');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel') || type.includes('spreadsheet') || type.includes('csv')) return '📊';
    if (type.includes('word') || type.includes('text') || type.includes('document')) return '📄';
    if (type.includes('image')) return '🖼️';
    if (type.includes('presentation') || type.includes('powerpoint')) return '📽️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  // Submission handler for topic creation modal
  const handleCreateTopicSubmit = () => {
    if (newTopicName.trim()) {
      onCreateTopic(newTopicName, newTopicIcon, 'System generated module content.');
      setNewTopicName('');
      setIsTopicModalOpen(false);
    }
  };

  // Submission handler for adding members modal
  const handleAddMemberSubmit = () => {
    if (newMemberName.trim()) {
      onAddMember(newMemberName, newMemberRole);
      setNewMemberName('');
      setIsAddMemberModalOpen(false);
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-500 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-slate-950 relative overflow-hidden">
      {/* Second Sidebar - Hidden on mobile, shown on desktop for quick switching */}
      <div className="w-72 bg-slate-950 border-r border-slate-900 hidden xl:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-6 border-b border-slate-900">
          <div className="font-extrabold uppercase tracking-[0.2em] text-[10px] text-slate-500">Node Explorer</div>
        </div>
        <div className="px-4 py-6 space-y-2">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-4 rounded-2xl flex items-center gap-4 transition-all duration-200 ${
                activeTopicId === topic.id ? 'bg-indigo-600/10 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:bg-slate-900/50 hover:text-slate-300'
              }`}
            >
              <span className="text-xl">{topic.icon}</span>
              <span className="truncate flex-1 font-bold text-sm tracking-tight">{topic.name}</span>
            </button>
          ))}
          <button 
            onClick={() => setIsTopicModalOpen(true)}
            className="w-full text-left p-4 rounded-2xl flex items-center gap-4 text-slate-600 hover:bg-slate-900/50 hover:text-slate-400 border border-dashed border-slate-800 mt-6 group transition-all"
          >
            <span className="text-xl group-hover:scale-110 transition-transform">➕</span>
            <span className="truncate flex-1 text-[11px] font-bold uppercase tracking-widest">Add Module</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-8 text-center animate-in fade-in duration-700">
             <div className="w-24 h-24 bg-slate-900 rounded-[2.5rem] flex items-center justify-center text-4xl mb-8 shadow-2xl border border-slate-800">📡</div>
             <h2 className="text-3xl font-extrabold text-white mb-4 italic tracking-tight">System Idle</h2>
             <p className="text-slate-500 max-w-xs mb-10 text-sm font-medium leading-relaxed">Select a knowledge module from the sidebar to begin your workspace session.</p>
             <button onClick={onToggleMenu} className="px-12 py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-3xl font-extrabold uppercase text-[11px] tracking-widest shadow-2xl transition-all active:scale-95 lg:hidden">Browse Hubs</button>
          </div>
        ) : (
          <div className="flex flex-col h-full animate-in fade-in slide-in-from-bottom-2 duration-500">
            {/* Context Header */}
            <div className="bg-slate-950/80 backdrop-blur-xl border-b border-slate-900 p-4 sm:p-6 flex flex-col md:flex-row items-center justify-between gap-6 z-10">
               <div className="flex items-center gap-4 w-full md:w-auto">
                  <button onClick={onToggleMenu} className="p-3 bg-slate-900 rounded-2xl lg:hidden text-slate-400 hover:text-white border border-slate-800 transition-all">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
                  </button>
                  <div className="p-4 bg-slate-900 rounded-2xl border border-slate-800 text-3xl shadow-xl">{activeTopic.icon}</div>
                  <div className="min-w-0">
                    <h2 className="text-xl font-extrabold text-white leading-tight mb-1 truncate tracking-tight uppercase italic">{activeTopic.name}</h2>
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">{group.name}</span>
                      <span className="w-1 h-1 bg-slate-700 rounded-full"></span>
                      <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{activeTopic.resources.length} Nodes</span>
                    </div>
                  </div>
               </div>

               {/* View Switcher Tabs */}
               <div className="flex items-center gap-1 bg-slate-900/50 p-1.5 rounded-[1.8rem] border border-slate-900 w-full md:w-auto">
                  <button onClick={() => setViewMode('discussion')} className={`flex-1 md:flex-none px-6 py-3 rounded-2xl text-[11px] font-bold tracking-widest uppercase transition-all duration-300 ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-slate-300'}`}>Chat</button>
                  <button onClick={() => setViewMode('resources')} className={`flex-1 md:flex-none px-6 py-3 rounded-2xl text-[11px] font-bold tracking-widest uppercase transition-all duration-300 ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-slate-300'}`}>Library</button>
                  <button onClick={() => setViewMode('members')} className={`flex-1 md:flex-none px-6 py-3 rounded-2xl text-[11px] font-bold tracking-widest uppercase transition-all duration-300 ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-slate-300'}`}>Team</button>
               </div>

               {/* Live Actions */}
               <div className="flex items-center gap-3 w-full md:w-auto">
                 <button 
                  onClick={() => onOpenVoice('voice')} 
                  className="flex-1 md:flex-none flex items-center justify-center gap-3 px-6 py-4 bg-slate-900 text-indigo-400 rounded-2xl font-bold text-[11px] uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all border border-slate-800 active:scale-95"
                 >
                   <span className="text-lg">🔊</span>
                   <span>Join Voice</span>
                 </button>
                 <button 
                  onClick={() => onOpenVoice('video')} 
                  className="flex-1 md:flex-none flex items-center justify-center gap-3 px-6 py-4 bg-indigo-600 text-white rounded-2xl font-bold text-[11px] uppercase tracking-widest hover:bg-indigo-500 transition-all shadow-[0_10px_30px_rgba(79,70,229,0.3)] border border-indigo-400 active:scale-95"
                 >
                   <span className="text-lg">🎥</span>
                   <span>Join Video</span>
                 </button>
               </div>
            </div>

            <div className="flex-1 overflow-hidden">
              {viewMode === 'discussion' && (
                <ChatArea groupName={activeTopic.name} messages={activeTopic.messages} members={group.members} onSendMessage={(text, attachment) => onSendMessage(activeTopic.id, text, attachment)} onAddMember={onAddMember} onToggleMenu={onToggleMenu} />
              )}
              {viewMode === 'resources' && (
                <div className="h-full overflow-y-auto p-6 sm:p-12 bg-slate-950 custom-scrollbar">
                   <div className="max-w-6xl mx-auto space-y-12">
                     <div className="flex flex-col sm:flex-row items-center justify-between gap-6 border-b border-slate-900 pb-8">
                        <div>
                          <h3 className="text-2xl font-extrabold text-white italic tracking-tight uppercase mb-1">Knowledge Archive</h3>
                          <p className="text-[11px] font-bold text-slate-500 uppercase tracking-widest">Secure cloud module repository</p>
                        </div>
                        <p className="px-5 py-2 bg-slate-900 rounded-full text-[10px] font-bold text-indigo-400 uppercase tracking-widest border border-slate-800">{activeTopic.resources.length} Nodes Active</p>
                     </div>

                     <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" />
                        <button 
                          onClick={() => fileInputRef.current?.click()}
                          className="group relative bg-indigo-600/5 border-2 border-dashed border-indigo-500/20 rounded-[2.5rem] p-10 flex flex-col items-center justify-center gap-6 transition-all hover:bg-indigo-600/10 hover:border-indigo-500/50 shadow-2xl hover:shadow-indigo-500/10"
                        >
                           <div className="w-20 h-20 bg-indigo-600 text-white rounded-[1.8rem] flex items-center justify-center shadow-2xl group-hover:scale-110 transition-transform duration-500">
                              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                           </div>
                           <div className="text-center">
                              <div className="text-base font-extrabold text-white uppercase tracking-tight italic">Inject Node</div>
                              <div className="text-[10px] text-slate-500 font-bold uppercase mt-2 tracking-widest">Uplink: PDF, DOCX, XLSX</div>
                           </div>
                        </button>

                        {activeTopic.resources.map(res => (
                          <div key={res.id} className="bg-slate-900/50 border border-slate-900 p-8 rounded-[2.5rem] flex flex-col gap-6 hover:border-slate-800 hover:bg-slate-900 transition-all duration-300 shadow-2xl group relative">
                             <div className="flex items-center gap-6">
                               <div className="w-16 h-16 bg-slate-950 rounded-2xl flex items-center justify-center text-4xl shadow-inner border border-slate-800/50">{getFileIcon(res.type)}</div>
                               <div className="flex-1 min-w-0">
                                  <h5 className="font-bold text-white truncate text-base tracking-tight leading-tight mb-1">{res.name}</h5>
                                  <div className="flex items-center gap-3">
                                    <span className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{res.size}</span>
                                    <span className="text-[10px] text-indigo-500/60 font-black uppercase tracking-widest">{res.type.split('/')[1]?.toUpperCase() || 'DAT'}</span>
                                  </div>
                               </div>
                             </div>
                             <div className="pt-6 border-t border-slate-800/50 flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                  <div className="w-7 h-7 rounded-lg bg-indigo-600/20 flex items-center justify-center text-[10px] font-extrabold text-indigo-400">Y</div>
                                  <span className="text-[11px] text-slate-500 font-semibold tracking-tight">By {res.uploadedBy}</span>
                                </div>
                                <button className="px-5 py-2 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all">Retrieve</button>
                             </div>
                          </div>
                        ))}
                      </div>
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-6 sm:p-12 custom-scrollbar">
                   <div className="max-w-5xl mx-auto space-y-12">
                     <div className="flex items-center justify-between border-b border-slate-900 pb-8">
                       <div>
                         <h3 className="text-2xl font-extrabold text-white italic uppercase tracking-tight">Node Access List</h3>
                         <p className="text-[11px] font-bold text-slate-500 uppercase tracking-widest">Active participant directory</p>
                       </div>
                       <button onClick={() => setIsAddMemberModalOpen(true)} className="flex items-center gap-3 px-8 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[1.8rem] font-bold uppercase text-[11px] tracking-widest shadow-2xl transition-all active:scale-95">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" /></svg>
                          Invite Participant
                       </button>
                     </div>
                     <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                        {group.members.map(member => (
                          <div key={member.id} className="bg-slate-900/50 border border-slate-900 p-6 rounded-[2rem] flex items-center gap-5 hover:bg-slate-900 transition-all duration-300">
                             <div className="relative">
                               <img src={member.avatar} className="w-16 h-16 rounded-2xl object-cover border-2 border-slate-800 shadow-xl" alt="" />
                               <div className={`absolute -bottom-1 -right-1 w-5 h-5 rounded-full border-4 border-slate-950 shadow-xl ${member.status === 'online' ? 'bg-emerald-500 pulse-indicator' : 'bg-slate-600'}`}></div>
                             </div>
                             <div className="flex-1 min-w-0">
                               <div className="font-bold text-white text-base truncate tracking-tight uppercase italic leading-none mb-2">{member.name}</div>
                               <div className={`inline-flex px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border ${getRoleColor(member.role)}`}>
                                 {member.role}
                               </div>
                             </div>
                          </div>
                        ))}
                     </div>
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Modals Refined */}
      {isTopicModalOpen && (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-xl flex items-center justify-center p-6">
          <div className="bg-slate-950 border border-slate-900 w-full max-w-md rounded-[3rem] p-10 shadow-2xl animate-in zoom-in-95 duration-300">
