              </div>
              <div>
                 <label className="block text-[11px] font-bold text-slate-500 uppercase tracking-widest mb-3 px-2">Access Permissions</label>
                 <select value={newMemberRole} onChange={(e) => setNewMemberRole(e.target.value as any)} className="w-full bg-slate-900 border border-slate-800 rounded-2xl p-6 text-white font-bold appearance-none outline-none focus:ring-2 focus:ring-indigo-500">
                    <option value="Member">Regular Member</option>
                    <option value="Admin">System Admin</option>
                    <option value="Owner">Root Owner</option>
