import ChatArea from './components/ChatArea';
import DashboardArea from './components/DashboardArea';
import MeetingSession from './components/MeetingSession';
import { Group, GroupType, Message, Attachment, Resource, Topic, GroupMember } from './types';

const MOCK_MEMBERS: GroupMember[] = [
  { id: '1', name: 'You (Lecturer)', avatar: 'https://picsum.photos/80/80?u=1', role: 'Owner', status: 'online' },
  { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', role: 'AI Assistant', status: 'online' },
  { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', role: 'Admin', status: 'online' },
  { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', role: 'Member', status: 'offline' },
  { id: '4', name: 'Elena Rodriguez', avatar: 'https://picsum.photos/80/80?u=4', role: 'Member', status: 'online' },
];

const INITIAL_GROUPS: Group[] = [
  {
    id: 'edu-1',
    name: 'Advanced Mathematics',
    type: GroupType.TOPICS,
    category: 'Education',
    members: MOCK_MEMBERS,
    topics: [
      { 
        id: 't1', 
        name: 'Calculus III', 
        description: 'Multivariable calculus resources and lecture notes.', 
        icon: '📐',
        messages: [],
        resources: [
          { id: 'r1', name: 'Lecture_Notes_Week1.pdf', type: 'application/pdf', size: '2.4 MB', uploadedBy: 'Prof. Smith', date: new Date() }
        ]
      },
      { 
        id: 't2', 
        name: 'Linear Algebra', 
        description: 'Matrices, vectors, and linear transformations.', 
        icon: '📊',
        messages: [],
        resources: []
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=100&h=100&fit=crop'
  },
  {
    id: 'corp-1',
    name: 'Strategic Planning',
    type: GroupType.TOPICS,
    category: 'Corporate',
    members: MOCK_MEMBERS.slice(0, 3),
    topics: [
      { 
        id: 't3', 
        name: 'Q4 Roadmap', 
        description: 'Resource management and project milestones.', 
        icon: '🎯',
        messages: [],
        resources: [
          { id: 'r2', name: 'Budget_Draft.xlsx', type: 'application/vnd.ms-excel', size: '1.1 MB', uploadedBy: 'Jane Doe', date: new Date() }
        ]
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=100&h=100&fit=crop'
  }
];

const App: React.FC = () => {
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);

  // Meeting states
  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [sessionGroupName, setSessionGroupName] = useState<string | null>(null);
  const [isSessionMinimized, setIsSessionMinimized] = useState(false);

  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    if (!isMobile && activeGroupId === null) {
      setActiveGroupId('edu-1');
    }
    return () => window.removeEventListener('resize', handleResize);
  }, [isMobile, activeGroupId]);

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  const handleOpenVoice = (mode: 'voice' | 'video') => {
    const groupName = activeTopicId 
      ? activeGroup?.topics.find(t => t.id === activeTopicId)?.name || activeGroup?.name
      : activeGroup?.name;

    setSessionGroupName(groupName || 'Nexus Session');
    setSessionMode(mode);
    setIsSessionMinimized(false);
  };

  const handleCreateGroup = (name: string, type: GroupType, avatar: string) => {
    const newGroup: Group = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      type,
      topics: type === GroupType.TOPICS ? [
        { id: 'd1', name: 'Intro', description: 'Welcome!', icon: '✨', messages: [], resources: [] }
      ] : [],
      messages: [],
      members: [{ id: '1', name: 'You', avatar: 'https://picsum.photos/80/80?u=1', role: 'Owner', status: 'online' }],
      avatar,
      category: 'Community'
    };
    setGroups([...groups, newGroup]);
    setActiveGroupId(newGroup.id);
    setActiveTopicId(null);
  };

  const handleAddMember = (groupId: string, name: string, role: GroupMember['role']) => {
    const newMember: GroupMember = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      role,
      avatar: `https://picsum.photos/80/80?u=${Math.random()}`,
      status: 'online'
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== groupId) return g;
      return { ...g, members: [...g.members, newMember] };
    }));
  };

  const handleUploadResource = (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => {
    const newResource: Resource = {
      ...resource,
      id: Date.now().toString(),
      uploadedBy: 'You',
      date: new Date()
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return {
        ...g,
        topics: g.topics.map(t => {
          if (t.id !== topicId) return t;
          return { ...t, resources: [...t.resources, newResource] };
        })
      };
    }));
  };

  const handleCreateTopic = (name: string, icon: string, description: string) => {
    const newTopic: Topic = {
      id: `topic-${Date.now()}`,
      name,
      icon,
      description,
      messages: [],
      resources: []
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return { ...g, topics: [...g.topics, newTopic] };
    }));
    setActiveTopicId(newTopic.id);
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    const newMessage: Message = {
      id: Date.now().toString(),
      sender: 'You',
      text,
      timestamp: new Date(),
      avatar: 'https://picsum.photos/40/40?u=1',
      attachment
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => {
            if (t.id !== topicIdOrNull) return t;
            return { ...t, messages: [...t.messages, newMessage] };
          })
        };
      }
    }));
  };

  const handleSelectGroup = (id: string) => {
    setActiveGroupId(id);
    setActiveTopicId(null);
  };

  const handleSelectTopic = (id: string | null) => {
    setActiveTopicId(id);
  };

  const handleBack = () => {
    if (activeTopicId) {
      setActiveTopicId(null);
    } else {
      setActiveGroupId(null);
    }
  };

  const showContent = isMobile ? (activeGroup?.type === GroupType.STANDARD || (activeGroup?.type === GroupType.TOPICS && activeTopicId !== null)) : true;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-slate-950 text-slate-200 relative">
      {(!showContent || !isMobile) && (
        <Sidebar 
          groups={groups} 
          activeGroupId={activeGroupId || ''} 
          activeTopicId={activeTopicId}
          onSelectGroup={handleSelectGroup}
          onSelectTopic={handleSelectTopic}
          onCreateGroup={handleCreateGroup}
          onJoinVoice={handleOpenVoice}
          isOpen={true}
          onClose={() => {}}
        />
      )}

      {(showContent || !isMobile) && activeGroup && (
        <main className={`flex-1 flex flex-col relative overflow-hidden h-full ${isMobile ? 'fixed inset-0 z-50 bg-slate-950' : ''}`}>
          {activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              onSendMessage={(text, att) => handleSendMessage(null, text, att)}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onToggleMenu={handleBack}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              activeTopicId={activeTopicId}
              onSelectTopic={handleSelectTopic}
              onOpenVoice={handleOpenVoice}
              onSendMessage={handleSendMessage}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onUploadResource={handleUploadResource}
              onCreateTopic={handleCreateTopic}
              onToggleMenu={handleBack}
            />
          )}
        </main>
      )}

      {/* Persistent Session UI */}
      {sessionMode && (
        <div className={`fixed z-[100] transition-all duration-500 ease-in-out ${
          isSessionMinimized 
            ? 'bottom-6 right-6 w-80 h-auto' 
            : 'inset-0 flex items-center justify-center p-2 sm:p-4 bg-slate-950/60 backdrop-blur-md'
        }`}>
          <MeetingSession 
            mode={sessionMode}
            isMinimized={isSessionMinimized}
            onMinimize={() => setIsSessionMinimized(!isSessionMinimized)}
            onClose={() => {
              setSessionMode(null);
              setSessionGroupName(null);
            }} 
            groupName={sessionGroupName || 'Session'} 
          />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { VoiceParticipant } from '../types';

interface MeetingSessionProps {
  onClose: () => void;
  onMinimize?: () => void;
  isMinimized?: boolean;
  groupName: string;
  mode: 'voice' | 'video';
}

const MeetingSession: React.FC<MeetingSessionProps> = ({ onClose, onMinimize, isMinimized = false, groupName, mode }) => {
  const [hasJoined, setHasJoined] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(mode === 'voice');
  const [participants, setParticipants] = useState<VoiceParticipant[]>([
    { id: '1', name: 'You (Lecturer)', avatar: 'https://picsum.photos/80/80?u=1', isSpeaking: false },
    { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', isSpeaking: false },
    { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', isSpeaking: false },
    { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', isSpeaking: false },
  ]);
  const [isConnecting, setIsConnecting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<any>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const localStreamRef = useRef<MediaStream | null>(null);

  // Initial local preview setup
  useEffect(() => {
    const setupPreview = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: true, 
          video: mode === 'video' ? { width: 640, height: 480 } : false 
        });
        localStreamRef.current = stream;
        if (mode === 'video' && lobbyVideoRef.current) {
          lobbyVideoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Preview failed:", err);
        setError("Microphone and Camera permissions are required.");
      }
    };
    setupPreview();
    return () => {
      localStreamRef.current?.getTracks().forEach(track => track.stop());
    };
  }, [mode]);

  const joinSession = async () => {
    if (!localStreamRef.current) return;
    setIsConnecting(true);
    setHasJoined(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = localStreamRef.current;

      setTimeout(() => {
        if (mode === 'video' && videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      }, 100);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsConnecting(false);
            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              if (isMuted) return;
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);

            if (mode === 'video') {
              const FRAME_RATE = 2;
              frameIntervalRef.current = window.setInterval(() => {
                if (isVideoOff || !videoRef.current || !canvasRef.current) return;
                const canvas = canvasRef.current;
                const video = videoRef.current;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;

                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

                const base64Data = canvas.toDataURL('image/jpeg', 0.5).split(',')[1];
                sessionPromise.then((session) => {
                  session.sendRealtimeInput({
                    media: { data: base64Data, mimeType: 'image/jpeg' }
                  });
                });
              }, 1000 / FRAME_RATE);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioBase64 = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioBase64) {
              setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: true } : p));
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(audioBase64), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: false } : p));
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }
            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => {
            console.error("Gemini Live Error:", e);
            setError("Network link unstable.");
          },
          onclose: () => console.log("Meeting Closed")
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: `You are an expert Educational Facilitator for a ${mode} session on "${groupName}". 
          Your goal is to ensure Quality Education (SDG 4). Be interactive, answer questions intelligently, and guide the discussion.`
        }
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      console.error("Failed to start session:", err);
      setError("Microphone and Camera permissions are required.");
      setIsConnecting(false);
    }
  };

  function decode(base64: string) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return bytes;
  }

  async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, channels: number) {
    const dataInt16 = new Int16Array(data.buffer);
    const buffer = ctx.createBuffer(channels, dataInt16.length / channels, sampleRate);
    for (let c = 0; c < channels; c++) {
      const channelData = buffer.getChannelData(c);
      for (let i = 0; i < channelData.length; i++) {
        channelData[i] = dataInt16[i * channels + c] / 32768.0;
      }
    }
    return buffer;
  }

  function createBlob(data: Float32Array) {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
    return {
      data: btoa(String.fromCharCode(...new Uint8Array(int16.buffer))),
      mimeType: 'audio/pcm;rate=16000'
    };
  }

  // MINIMIZED VIEW
  if (isMinimized && hasJoined) {
    return (
      <div className="bg-slate-900/90 backdrop-blur-xl border border-indigo-500/30 rounded-[2rem] p-4 shadow-2xl animate-in slide-in-from-bottom duration-300 flex flex-col gap-3">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 min-w-0">
             <div className="w-8 h-8 rounded-lg bg-indigo-600 flex items-center justify-center text-xs shadow-lg">
                {mode === 'video' ? '📹' : '🔊'}
             </div>
             <div className="min-w-0">
                <div className="text-[10px] font-black text-white uppercase truncate tracking-tight">{groupName}</div>
                <div className="text-[8px] text-indigo-400 font-bold uppercase tracking-widest leading-none">Live Session</div>
             </div>
          </div>
          <button onClick={onMinimize} className="p-2 bg-slate-800 rounded-lg text-slate-400 hover:text-white transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
          </button>
        </div>

        <div className="flex gap-2 items-center justify-center p-2 bg-slate-950/50 rounded-xl border border-white/5">
           <button onClick={() => setIsMuted(!isMuted)} className={`p-2 rounded-lg ${isMuted ? 'bg-red-500' : 'bg-slate-800'}`}>
              <span className="text-xs">{isMuted ? '🔇' : '🎤'}</span>
           </button>
           {mode === 'video' && (
             <button onClick={() => setIsVideoOff(!isVideoOff)} className={`p-2 rounded-lg ${isVideoOff ? 'bg-red-500' : 'bg-slate-800'}`}>
                <span className="text-xs">{isVideoOff ? '🚫' : '📹'}</span>
             </button>
           )}
           <button onClick={onClose} className="p-2 bg-red-600 rounded-lg">
              <span className="text-xs">🚪</span>
           </button>
        </div>

        <div className="flex -space-x-2 justify-center">
           {participants.map((p, i) => (
             <img key={p.id} src={p.avatar} className={`w-6 h-6 rounded-full border-2 border-slate-900 ${p.isSpeaking ? 'ring-2 ring-indigo-500 z-10' : ''}`} alt="" style={{zIndex: 5-i}} />
           ))}
        </div>
      </div>
    );
  }

  // Lobby Component
  if (!hasJoined) {
    return (
      <div className="w-full max-w-4xl bg-slate-900 border border-slate-800 rounded-[3rem] shadow-[0_32px_120px_-20px_rgba(0,0,0,0.9)] flex flex-col overflow-hidden max-h-[90vh] animate-in fade-in zoom-in duration-300">
        <div className="flex-1 flex flex-col items-center justify-center p-6 sm:p-12">
          <div className="text-center mb-10">
            <h2 className="text-3xl sm:text-4xl font-black text-white italic uppercase tracking-tighter mb-2">Nexus Lobby</h2>
            <p className="text-indigo-400 text-[10px] font-black tracking-[0.3em] uppercase opacity-80">Link Node: {groupName}</p>
          </div>

          <div className="w-full max-w-2xl aspect-video bg-slate-950 rounded-[2rem] sm:rounded-[2.5rem] overflow-hidden border-2 border-slate-800 shadow-2xl relative group">
            {mode === 'video' && !isVideoOff ? (
              <video ref={lobbyVideoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
            ) : (
              <div className="w-full h-full flex flex-col items-center justify-center bg-gradient-to-br from-indigo-900/20 to-slate-900">
                <div className="w-16 h-16 sm:w-24 sm:h-24 rounded-2xl sm:rounded-3xl bg-slate-800 border border-slate-700 flex items-center justify-center text-3xl sm:text-4xl mb-4 shadow-2xl">👤</div>
                <span className="text-slate-500 font-bold uppercase tracking-widest text-[8px] sm:text-[10px]">Camera is Standby</span>
              </div>
            )}

            <div className="absolute top-4 sm:top-6 right-4 sm:right-6 px-3 sm:px-4 py-1.5 sm:py-2 bg-slate-900/90 backdrop-blur-md rounded-xl text-white font-black text-[8px] sm:text-[9px] uppercase tracking-widest border border-white/5 flex items-center gap-2">
              <span className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-indigo-500 shadow-[0_0_10px_rgba(99,102,241,0.5)]"></span> Equipment Check
            </div>

            <div className="absolute bottom-4 sm:bottom-6 inset-x-0 flex justify-center gap-3 sm:gap-4 px-6 opacity-0 group-hover:opacity-100 transition-all transform translate-y-2 group-hover:translate-y-0">
               <button onClick={() => setIsMuted(!isMuted)} className={`p-4 sm:p-5 rounded-2xl sm:rounded-[1.5rem] backdrop-blur-md border-2 transition-all shadow-2xl ${isMuted ? 'bg-red-500/80 border-red-500 text-white' : 'bg-slate-900/80 border-indigo-500/50 text-indigo-400 hover:bg-indigo-600 hover:text-white'}`}>
                 <span className="text-lg sm:text-xl">{isMuted ? '🔇' : '🎤'}</span>
               </button>
               {mode === 'video' && (
                 <button onClick={() => setIsVideoOff(!isVideoOff)} className={`p-4 sm:p-5 rounded-2xl sm:rounded-[1.5rem] backdrop-blur-md border-2 transition-all shadow-2xl ${isVideoOff ? 'bg-red-500/80 border-red-500 text-white' : 'bg-slate-900/80 border-indigo-500/50 text-indigo-400 hover:bg-indigo-600 hover:text-white'}`}>
                   <span className="text-lg sm:text-xl">{isVideoOff ? '🚫' : '📹'}</span>
                 </button>
               )}
            </div>
          </div>

          <div className="mt-8 sm:mt-12 flex flex-col items-center gap-4 sm:gap-6 w-full max-w-sm">
             <div className="flex flex-col items-center gap-1.5 sm:gap-2">
                <span className="text-[9px] sm:text-[10px] font-bold text-slate-500 uppercase tracking-widest">Ready to initialize?</span>
                <div className="flex items-center gap-2 text-indigo-400">
                   <span className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-green-500 animate-pulse shadow-[0_0_10px_rgba(34,197,94,0.5)]"></span>
                   <span className="text-[9px] sm:text-[10px] font-black uppercase tracking-[0.2em]">Uplink Sync Confirmed</span>
                </div>
             </div>

             <button 
                onClick={joinSession}
                className="group relative w-full py-5 sm:py-6 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[1.5rem] sm:rounded-[1.8rem] font-black uppercase text-xs sm:text-sm tracking-[0.3em] shadow-[0_20px_60px_-15px_rgba(79,70,229,0.5)] transition-all active:scale-95 overflow-hidden"
             >
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
                Join Session Now
             </button>

             <button onClick={onClose} className="text-slate-500 hover:text-white text-[9px] sm:text-[10px] font-black uppercase tracking-widest transition-colors border-b border-transparent hover:border-slate-500 pb-1">Cancel Connection</button>
          </div>
        </div>
      </div>
