                <div className="text-[10px] font-black text-white uppercase truncate">{groupName}</div>
                <div className="text-[8px] text-indigo-400 font-bold uppercase tracking-widest leading-none">Min-Mode Active</div>
             </div>
          </div>
          <button onClick={onMinimize} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
          </button>
        </div>
        <div className="flex gap-2 items-center justify-center">
           <button onClick={() => setIsMuted(!isMuted)} className={`p-2.5 rounded-xl ${isMuted ? 'bg-red-600' : 'bg-slate-800'} text-white`}>{isMuted ? '🔇' : '🎤'}</button>
           <button onClick={onClose} className="p-2.5 bg-red-600 rounded-xl text-white">🚪</button>
        </div>
      </div>
    );
  }

  if (!hasJoined) {
    return (
      <div className="w-full max-w-4xl bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300 mx-auto max-h-[95vh]">
        <div className="p-8 sm:p-12 flex flex-col items-center justify-center">
          <h2 className="text-3xl font-black text-white italic uppercase mb-2">Nexus Lobby</h2>
          <p className="text-indigo-400 text-[10px] font-bold tracking-[0.3em] uppercase mb-8">{groupName}</p>

          <div className="w-full max-w-xl aspect-video bg-slate-950 rounded-[2rem] overflow-hidden border border-slate-800 relative group shadow-2xl">
            {mode === 'video' && !isVideoOff ? (
              <video ref={lobbyVideoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
            ) : (
              <div className="w-full h-full flex flex-col items-center justify-center bg-slate-900">
                <div className="text-5xl mb-4">👤</div>
                <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Camera Standby</span>
              </div>
            )}
            <div className="absolute bottom-6 inset-x-0 flex justify-center gap-4 px-6 opacity-0 group-hover:opacity-100 transition-all">
               <button onClick={() => setIsMuted(!isMuted)} className={`p-4 rounded-2xl border-2 ${isMuted ? 'bg-red-500 border-red-400' : 'bg-slate-900 border-indigo-500/50'} text-white`}>{isMuted ? '🔇' : '🎤'}</button>
            </div>
          </div>

          <div className="mt-10 w-full max-w-xs space-y-6">
             <button onClick={joinSession} className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[1.5rem] font-black uppercase text-xs tracking-[0.2em] shadow-2xl transition-all">Connect Now</button>
             <button onClick={onClose} className="w-full text-slate-500 hover:text-white text-[10px] font-black uppercase tracking-widest">Abort Uplink</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="w-full max-w-6xl bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden max-h-[95vh] animate-in zoom-in-95 duration-300">
      <header className="p-5 sm:p-6 bg-slate-950/60 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-4">
           <div className="p-3 bg-indigo-600/20 rounded-2xl text-indigo-400">
             {mode === 'video' ? '📹' : '🔊'}
           </div>
           <div>
             <h2 className="text-lg font-black text-white italic uppercase tracking-tight leading-none mb-1">{groupName} Session</h2>
             <p className="text-slate-500 text-[9px] font-bold tracking-widest uppercase">Live Link Active</p>
           </div>
        </div>
        <button onClick={onMinimize} className="p-2 hover:bg-slate-800 rounded-xl transition-all text-slate-400">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
        </button>
      </header>

      <div className="flex-1 p-4 sm:p-8 overflow-y-auto bg-slate-950 custom-scrollbar">
        {isConnecting ? (
          <div className="h-full flex flex-col items-center justify-center">
            <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6"></div>
            <p className="text-indigo-400 font-bold uppercase tracking-widest text-[10px]">Syncing Core...</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="md:col-span-2 aspect-video bg-slate-900 rounded-[2rem] overflow-hidden border border-slate-800 shadow-2xl relative">
              {mode === 'video' && !isVideoOff ? (
                <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
              ) : (
                <div className="w-full h-full flex items-center justify-center">
                   <img src={participants[0].avatar} className="w-24 h-24 rounded-[2rem] border-4 border-indigo-500 shadow-2xl" alt="" />
                </div>
              )}
            </div>
            <div className="flex flex-col gap-4 overflow-y-auto max-h-full">
               {participants.map(p => (
                 <div key={p.id} className={`p-4 rounded-[1.5rem] border transition-all ${p.isSpeaking ? 'bg-indigo-600/10 border-indigo-500 shadow-lg' : 'bg-slate-900 border-slate-800'} flex items-center gap-4`}>
                    <img src={p.avatar} className={`w-12 h-12 rounded-xl border-2 ${p.isSpeaking ? 'border-indigo-400' : 'border-slate-800'}`} alt="" />
                    <div className="min-w-0">
                       <div className="text-xs font-black text-white truncate uppercase">{p.name}</div>
                       <div className="text-[9px] text-slate-500 font-bold uppercase mt-1">{p.isSpeaking ? 'Speaking...' : 'Standby'}</div>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}
      </div>

      <footer className="p-6 sm:p-8 bg-slate-950/80 border-t border-slate-800 flex justify-center gap-6">
        <button onClick={() => setIsMuted(!isMuted)} className={`p-5 rounded-2xl transition-all ${isMuted ? 'bg-red-600 text-white shadow-xl' : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700'}`}>{isMuted ? '🔇' : '🎤'}</button>
        <button onClick={onClose} className="px-12 py-4 bg-red-600 hover:bg-red-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-2xl">End Link</button>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default MeetingSession;

{
  "name": "Nexus Hub",
  "description": "Adaptive cross-platform hub for standard chat and collaborative live sessions with AI facilitation.",
  "requestFramePermissions": [
    "microphone",
    "camera",
    "geolocation"
  ]
}

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { VoiceParticipant } from '../types';

interface MeetingSessionProps {
  onClose: () => void;
  onMinimize?: () => void;
  isMinimized?: boolean;
  groupName: string;
  mode: 'voice' | 'video';
}

const MeetingSession: React.FC<MeetingSessionProps> = ({ onClose, onMinimize, isMinimized = false, groupName, mode }) => {
  const [hasJoined, setHasJoined] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(mode === 'voice');
  const [participants, setParticipants] = useState<VoiceParticipant[]>([
    { id: '1', name: 'You', avatar: 'https://picsum.photos/80/80?u=1', isSpeaking: false },
    { id: 'ai', name: 'Nexus AI', avatar: 'https://picsum.photos/80/80?u=ai', isSpeaking: false },
    { id: '2', name: 'Sarah', avatar: 'https://picsum.photos/80/80?u=2', isSpeaking: false },
    { id: '3', name: 'Marcus', avatar: 'https://picsum.photos/80/80?u=3', isSpeaking: false },
  ]);
  const [isConnecting, setIsConnecting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const localStreamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    const setupPreview = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: true, 
          video: mode === 'video' ? { width: 640, height: 480 } : false 
        });
        localStreamRef.current = stream;
        if (mode === 'video' && lobbyVideoRef.current) {
          lobbyVideoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Preview failed:", err);
        setError("Microphone permission required.");
      }
    };
    setupPreview();
    return () => {
      localStreamRef.current?.getTracks().forEach(track => track.stop());
    };
  }, [mode]);

  const joinSession = async () => {
    if (!localStreamRef.current) return;
    setIsConnecting(true);
    setHasJoined(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = localStreamRef.current;
      setTimeout(() => {
        if (mode === 'video' && videoRef.current) videoRef.current.srcObject = stream;
      }, 100);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsConnecting(false);
            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              if (isMuted) return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: true } : p));
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: false } : p));
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: `Interactive learning facilitator for ${groupName}.`
        }
      });
    } catch (err) {
      setError("Connection Failure");
      setIsConnecting(false);
    }
  };

  const decode = (b64: string) => {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, rate: number, ch: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const buffer = ctx.createBuffer(ch, dataInt16.length / ch, rate);
    for (let c = 0; c < ch; c++) {
      const chData = buffer.getChannelData(c);
      for (let i = 0; i < chData.length; i++) chData[i] = dataInt16[i * ch + c] / 32768.0;
    }
    return buffer;
  };

  const createBlob = (data: Float32Array) => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
    return { data: btoa(String.fromCharCode(...new Uint8Array(int16.buffer))), mimeType: 'audio/pcm;rate=16000' };
  };

  // --- MINIMIZED VIEW ---
  if (isMinimized && hasJoined) {
    return (
      <div className="glass-effect rounded-[2rem] p-4 shadow-2xl border border-indigo-500/20 flex flex-col gap-3 animate-in slide-in-from-bottom duration-300">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 min-w-0">
             <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-xs shadow-lg">
               {mode === 'video' ? '📹' : '🔊'}
             </div>
             <div className="min-w-0">
                <div className="text-[10px] font-black text-white uppercase truncate">{groupName}</div>
                <div className="text-[8px] text-indigo-400 font-bold uppercase tracking-widest leading-none">Min-Mode Active</div>
             </div>
          </div>
          <button onClick={onMinimize} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
          </button>
        </div>
        <div className="flex gap-2 items-center justify-center">
           <button onClick={() => setIsMuted(!isMuted)} className={`p-2.5 rounded-xl ${isMuted ? 'bg-red-600' : 'bg-slate-800'} text-white`}>{isMuted ? '🔇' : '🎤'}</button>
           <button onClick={onClose} className="p-2.5 bg-red-600 rounded-xl text-white">🚪</button>
        </div>
      </div>
    );
  }

  // --- LOBBY VIEW ---
  if (!hasJoined) {
    return (
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300 mx-auto max-h-[90vh]">
        <div className="p-8 sm:p-12 flex flex-col items-center justify-center text-center">
          <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-3xl shadow-2xl mb-6">
            {mode === 'video' ? '📹' : '🔊'}
          </div>
          <h2 className="text-3xl font-black text-white italic uppercase mb-2">Nexus Lobby</h2>
          <p className="text-indigo-400 text-[10px] font-bold tracking-[0.3em] uppercase mb-10">{groupName}</p>

          {mode === 'video' ? (
            <div className="w-full aspect-video bg-slate-950 rounded-[2rem] overflow-hidden border border-slate-800 relative group shadow-2xl mb-10">
              {!isVideoOff ? (
                <video ref={lobbyVideoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center bg-slate-900">
                  <div className="text-5xl mb-4">👤</div>
                  <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Camera Standby</span>
                </div>
              )}
            </div>
          ) : (
            <div className="w-full py-12 bg-slate-950/50 rounded-[2rem] border border-slate-800/50 shadow-inner mb-10 flex flex-col items-center gap-4">
               <div className="w-24 h-24 rounded-full bg-slate-900 flex items-center justify-center border-4 border-slate-800 relative">
                  <span className="text-4xl">🎙️</span>
                  <div className="absolute inset-0 rounded-full border-4 border-indigo-500/20 animate-pulse"></div>
               </div>
               <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Voice Presence Initialised</span>
            </div>
          )}

          <div className="w-full max-w-xs space-y-4">
             <div className="flex justify-center gap-4 mb-4">
               <button onClick={() => setIsMuted(!isMuted)} className={`flex-1 py-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-3 font-bold uppercase text-[10px] tracking-widest ${isMuted ? 'bg-red-600 border-red-400 text-white' : 'bg-slate-900 border-indigo-500/50 text-indigo-400'}`}>
                 <span>{isMuted ? '🔇' : '🎤'}</span>
                 <span>{isMuted ? 'Muted' : 'Unmuted'}</span>
               </button>
               {mode === 'video' && (
                 <button onClick={() => setIsVideoOff(!isVideoOff)} className={`flex-1 py-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-3 font-bold uppercase text-[10px] tracking-widest ${isVideoOff ? 'bg-red-600 border-red-400 text-white' : 'bg-slate-900 border-indigo-500/50 text-indigo-400'}`}>
                   <span>{isVideoOff ? '🚫' : '📹'}</span>
                   <span>{isVideoOff ? 'No Video' : 'Video On'}</span>
                 </button>
               )}
             </div>
             <button onClick={joinSession} className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[1.5rem] font-black uppercase text-xs tracking-[0.2em] shadow-2xl transition-all">Connect Now</button>
             <button onClick={onClose} className="w-full text-slate-500 hover:text-white text-[10px] font-black uppercase tracking-widest pt-2">Cancel Link</button>
          </div>
        </div>
      </div>
    );
  }

  // --- FULL SESSION VIEW ---
  return (
    <div className="w-full max-w-6xl bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden max-h-[95vh] animate-in zoom-in-95 duration-300">
      <header className="p-5 sm:p-6 bg-slate-950/60 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-4 min-w-0">
           <div className="p-3 bg-indigo-600/20 rounded-2xl text-indigo-400 shrink-0">
             {mode === 'video' ? '📹' : '🔊'}
           </div>
           <div className="min-w-0">
             <h2 className="text-lg font-black text-white italic uppercase tracking-tight leading-none mb-1 truncate">{groupName}</h2>
             <p className="text-slate-500 text-[9px] font-bold tracking-widest uppercase">Live {mode} Session</p>
           </div>
        </div>
        <button onClick={onMinimize} className="p-2 hover:bg-slate-800 rounded-xl transition-all text-slate-400 shrink-0">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
        </button>
      </header>

      <div className="flex-1 p-4 sm:p-8 overflow-y-auto bg-slate-950 custom-scrollbar">
        {isConnecting ? (
          <div className="h-full flex flex-col items-center justify-center min-h-[300px]">
            <div className="w-16 h-16 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-6"></div>
            <p className="text-indigo-400 font-bold uppercase tracking-widest text-[10px]">Syncing Core...</p>
          </div>
        ) : (
          <div className={`grid gap-6 h-full ${mode === 'video' ? 'grid-cols-1 md:grid-cols-3' : 'grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5'}`}>

            {/* Main Stage for Video mode */}
            {mode === 'video' && (
              <div className="md:col-span-2 aspect-video bg-slate-900 rounded-[2rem] overflow-hidden border border-slate-800 shadow-2xl relative">
                {!isVideoOff ? (
                  <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <img src={participants[0].avatar} className="w-24 h-24 rounded-[2rem] border-4 border-indigo-500 shadow-2xl" alt="" />
                  </div>
                )}
                <div className="absolute bottom-4 left-4 px-3 py-1.5 bg-black/60 backdrop-blur-md rounded-xl text-[10px] font-bold text-white border border-white/10 uppercase tracking-widest">You (Lecturer)</div>
              </div>
            )}

            {/* Participants Grid */}
            {mode === 'video' ? (
              <div className="flex flex-col gap-4 overflow-y-auto max-h-full custom-scrollbar pr-2">
                 {participants.map(p => (
                   <div key={p.id} className={`p-4 rounded-[1.5rem] border transition-all ${p.isSpeaking ? 'bg-indigo-600/10 border-indigo-500 shadow-lg' : 'bg-slate-900 border-slate-800'} flex items-center gap-4`}>
                      <img src={p.avatar} className={`w-12 h-12 rounded-xl border-2 ${p.isSpeaking ? 'border-indigo-400' : 'border-slate-800'} shrink-0`} alt="" />
                      <div className="min-w-0">
                         <div className="text-xs font-black text-white truncate uppercase">{p.name}</div>
                         <div className="text-[9px] text-slate-500 font-bold uppercase mt-1">{p.isSpeaking ? 'Speaking...' : 'Standby'}</div>
                      </div>
                   </div>
                 ))}
              </div>
            ) : (
              /* Exclusive Voice Grid: All participants get equal visual priority */
              participants.map(p => (
                <div key={p.id} className={`flex flex-col items-center justify-center p-6 rounded-[2.5rem] border transition-all duration-300 gap-4 ${p.isSpeaking ? 'bg-indigo-600/10 border-indigo-500 shadow-xl' : 'bg-slate-900 border-slate-800'}`}>
                   <div className="relative">
                      <img src={p.avatar} className={`w-20 h-20 rounded-[2rem] border-4 transition-all duration-500 ${p.isSpeaking ? 'border-indigo-400 scale-110' : 'border-slate-800'}`} alt="" />
                      {p.isSpeaking && (
                         <div className="absolute -inset-2 border-2 border-indigo-500 rounded-[2.2rem] animate-ping opacity-20"></div>
                      )}
                      {p.id === 'ai' && <div className="absolute -top-2 -right-2 bg-indigo-600 text-[8px] font-black px-2 py-0.5 rounded-full border border-indigo-400 shadow-lg text-white uppercase">AI</div>}
                   </div>
                   <div className="text-center min-w-0 w-full">
                      <div className={`text-xs font-black uppercase tracking-tight truncate ${p.isSpeaking ? 'text-indigo-400' : 'text-white'}`}>{p.name}</div>
                      <div className="text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{p.isSpeaking ? 'Uplink active' : 'Connected'}</div>
                   </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      <footer className="p-6 sm:p-8 bg-slate-950/80 border-t border-slate-800 flex justify-center items-center gap-6">
        <button 
          onClick={() => setIsMuted(!isMuted)} 
          className={`p-5 rounded-2xl transition-all shadow-xl active:scale-95 ${isMuted ? 'bg-red-600 text-white' : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white'}`}
          title={isMuted ? "Unmute" : "Mute"}
        >
          {isMuted ? '🔇' : '🎤'}
        </button>

        {mode === 'video' && (
          <button 
            onClick={() => setIsVideoOff(!isVideoOff)} 
            className={`p-5 rounded-2xl transition-all shadow-xl active:scale-95 ${isVideoOff ? 'bg-red-600 text-white' : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white'}`}
            title={isVideoOff ? "Start Video" : "Stop Video"}
          >
            {isVideoOff ? '🚫' : '📹'}
          </button>
        )}

        <button onClick={onClose} className="px-10 sm:px-14 py-4 bg-red-600 hover:bg-red-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-[0_15px_40px_-5px_rgba(220,38,38,0.4)] active:scale-95 transition-all">
          End Session
        </button>

        <button className="hidden sm:block p-5 bg-slate-800 text-slate-400 hover:bg-indigo-600 hover:text-white rounded-2xl transition-all shadow-xl active:scale-95">
           <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
        </button>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default MeetingSession;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality } from '@google/genai';
import { VoiceParticipant } from '../types';

interface MeetingSessionProps {
  onClose: () => void;
  onMinimize?: () => void;
  isMinimized?: boolean;
  groupName: string;
  mode: 'voice' | 'video';
}

type ConnectionStatus = 'connecting' | 'stable' | 'unstable' | 'reconnecting' | 'failed';

const MeetingSession: React.FC<MeetingSessionProps> = ({ onClose, onMinimize, isMinimized = false, groupName, mode }) => {
  const [hasJoined, setHasJoined] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(mode === 'voice');
  const [participants, setParticipants] = useState<VoiceParticipant[]>([
    { id: '1', name: 'You', avatar: 'https://picsum.photos/80/80?u=1', isSpeaking: false },
    { id: 'ai', name: 'Nexus AI', avatar: 'https://picsum.photos/80/80?u=ai', isSpeaking: false },
    { id: '2', name: 'Sarah', avatar: 'https://picsum.photos/80/80?u=2', isSpeaking: false },
    { id: '3', name: 'Marcus', avatar: 'https://picsum.photos/80/80?u=3', isSpeaking: false },
  ]);

  const [connStatus, setConnStatus] = useState<ConnectionStatus>('connecting');
  const [error, setError] = useState<string | null>(null);

  // Adaptive Bitrate / Quality States
  const [streamQuality, setStreamQuality] = useState({ fps: 3, quality: 0.7 });
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 3;

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const localStreamRef = useRef<MediaStream | null>(null);
  const sessionPromiseRef = useRef<any>(null);
  const frameIntervalRef = useRef<number | null>(null);

  // Local device setup
  useEffect(() => {
    const setupPreview = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: true, 
          video: mode === 'video' ? { width: 640, height: 480 } : false 
        });
        localStreamRef.current = stream;
        if (mode === 'video' && lobbyVideoRef.current) {
          lobbyVideoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Preview failed:", err);
        setError("Microphone/Camera access denied.");
      }
    };
    setupPreview();
    return () => {
      localStreamRef.current?.getTracks().forEach(track => track.stop());
      if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    };
  }, [mode]);

  const joinSession = useCallback(async () => {
    if (!localStreamRef.current) return;
    setConnStatus(retryCountRef.current > 0 ? 'reconnecting' : 'connecting');
    setHasJoined(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

      // Cleanup previous context if reconnecting
      if (audioContextRef.current) audioContextRef.current.close();
      if (outputAudioContextRef.current) outputAudioContextRef.current.close();

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = localStreamRef.current;
      setTimeout(() => {
        if (mode === 'video' && videoRef.current) videoRef.current.srcObject = stream;
      }, 150);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setConnStatus('stable');
            retryCountRef.current = 0; // Reset retries on success

            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              if (isMuted || connStatus === 'reconnecting') return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }))
                .catch(() => setConnStatus('unstable'));
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);

            // Adaptive Video Stream Logic
            if (mode === 'video') {
              if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);

              frameIntervalRef.current = window.setInterval(() => {
                if (isVideoOff || !videoRef.current || !canvasRef.current || connStatus === 'reconnecting') return;

                const canvas = canvasRef.current;
                const video = videoRef.current;
                const ctx = canvas.getContext('2d', { alpha: false });
                if (!ctx) return;

                // Adaptive resolution based on quality
                const scale = streamQuality.quality;
                canvas.width = video.videoWidth * scale;
                canvas.height = video.videoHeight * scale;
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);

                const base64Data = canvas.toDataURL('image/jpeg', streamQuality.quality).split(',')[1];

                const startTime = performance.now();
                sessionPromise.then((session) => {
                  session.sendRealtimeInput({
                    media: { data: base64Data, mimeType: 'image/jpeg' }
                  });

                  // Adaptive logic: monitor "processing" speed
                  const elapsed = performance.now() - startTime;
                  if (elapsed > 200 && streamQuality.fps > 1) {
                    setStreamQuality(prev => ({ fps: Math.max(1, prev.fps - 1), quality: Math.max(0.4, prev.quality - 0.1) }));
                    setConnStatus('unstable');
                  } else if (elapsed < 50 && streamQuality.fps < 5) {
                    setStreamQuality(prev => ({ fps: Math.min(5, prev.fps + 1), quality: Math.min(0.8, prev.quality + 0.1) }));
                    setConnStatus('stable');
                  }
                }).catch(() => setConnStatus('unstable'));
              }, 1000 / streamQuality.fps);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: true } : p));
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: false } : p));
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }
          },
          onerror: (e) => {
            console.error("Session error:", e);
            setConnStatus('unstable');
          },
          onclose: () => {
            if (retryCountRef.current < MAX_RETRIES) {
              retryCountRef.current++;
              setTimeout(joinSession, 1000 * retryCountRef.current);
            } else {
              setConnStatus('failed');
              setError("Uplink severed. Multiple retries failed.");
            }
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: `Interactive facilitator for ${groupName}. Prioritize clear, low-latency audio response.`
        }
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      setConnStatus('failed');
      setError("Critical Linkage Error");
    }
  }, [groupName, mode, isMuted, isVideoOff, connStatus, streamQuality]);

  const decode = (b64: string) => {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, rate: number, ch: number) => {
    const dataInt16 = new Int16Array(data.buffer);
    const buffer = ctx.createBuffer(ch, dataInt16.length / ch, rate);
    for (let c = 0; c < ch; c++) {
      const chData = buffer.getChannelData(c);
      for (let i = 0; i < chData.length; i++) chData[i] = dataInt16[i * ch + c] / 32768.0;
    }
    return buffer;
  };

  const createBlob = (data: Float32Array) => {
    const int16 = new Int16Array(data.length);
    for (let i = 0; i < data.length; i++) int16[i] = data[i] * 32768;
    return { data: btoa(String.fromCharCode(...new Uint8Array(int16.buffer))), mimeType: 'audio/pcm;rate=16000' };
  };

  const getStatusBadge = () => {
    switch(connStatus) {
      case 'stable': return { color: 'bg-emerald-500', label: 'Strong' };
      case 'unstable': return { color: 'bg-amber-500', label: 'Weak Uplink' };
      case 'reconnecting': return { color: 'bg-indigo-500 animate-pulse', label: 'Re-syncing...' };
      case 'failed': return { color: 'bg-red-500', label: 'Severed' };
      default: return { color: 'bg-slate-500', label: 'Offline' };
    }
  };

  // --- MINIMIZED VIEW ---
  if (isMinimized && hasJoined) {
    const badge = getStatusBadge();
    return (
      <div className="glass-effect rounded-[2rem] p-4 shadow-2xl border border-indigo-500/20 flex flex-col gap-3 animate-in slide-in-from-bottom duration-300">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 min-w-0">
             <div className="w-8 h-8 rounded-xl bg-indigo-600 flex items-center justify-center text-xs shadow-lg">
               {mode === 'video' ? '📹' : '🔊'}
             </div>
             <div className="min-w-0">
                <div className="text-[10px] font-black text-white uppercase truncate">{groupName}</div>
                <div className="flex items-center gap-1.5 mt-0.5">
                   <div className={`w-1.5 h-1.5 rounded-full ${badge.color}`}></div>
                   <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest">{badge.label}</span>
                </div>
             </div>
          </div>
          <button onClick={onMinimize} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
          </button>
        </div>
        <div className="flex gap-2 items-center justify-center">
           <button onClick={() => setIsMuted(!isMuted)} className={`p-2.5 rounded-xl ${isMuted ? 'bg-red-600' : 'bg-slate-800'} text-white`}>{isMuted ? '🔇' : '🎤'}</button>
           <button onClick={onClose} className="p-2.5 bg-red-600 rounded-xl text-white">🚪</button>
        </div>
      </div>
    );
  }

  // --- LOBBY VIEW ---
  if (!hasJoined) {
    return (
      <div className="w-full max-w-xl bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300 mx-auto max-h-[90vh]">
        <div className="p-8 sm:p-12 flex flex-col items-center justify-center text-center">
          <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center text-3xl shadow-2xl mb-6">
            {mode === 'video' ? '📹' : '🔊'}
          </div>
          <h2 className="text-3xl font-black text-white italic uppercase mb-2">Nexus Lobby</h2>
          <p className="text-indigo-400 text-[10px] font-bold tracking-[0.3em] uppercase mb-10">{groupName}</p>

          {mode === 'video' ? (
            <div className="w-full aspect-video bg-slate-950 rounded-[2rem] overflow-hidden border border-slate-800 relative group shadow-2xl mb-10">
              {!isVideoOff ? (
                <video ref={lobbyVideoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center bg-slate-900">
                  <div className="text-5xl mb-4">👤</div>
                  <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Camera Standby</span>
                </div>
              )}
            </div>
          ) : (
            <div className="w-full py-12 bg-slate-950/50 rounded-[2rem] border border-slate-800/50 shadow-inner mb-10 flex flex-col items-center gap-4">
               <div className="w-24 h-24 rounded-full bg-slate-900 flex items-center justify-center border-4 border-slate-800 relative">
                  <span className="text-4xl">🎙️</span>
                  <div className="absolute inset-0 rounded-full border-4 border-indigo-500/20 animate-pulse"></div>
               </div>
               <span className="text-slate-500 font-bold uppercase tracking-widest text-[10px]">Voice Interface Initialised</span>
            </div>
          )}

          <div className="w-full max-w-xs space-y-4">
             <div className="flex justify-center gap-4 mb-4">
               <button onClick={() => setIsMuted(!isMuted)} className={`flex-1 py-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-3 font-bold uppercase text-[10px] tracking-widest ${isMuted ? 'bg-red-600 border-red-400 text-white' : 'bg-slate-900 border-indigo-500/50 text-indigo-400'}`}>
                 <span>{isMuted ? '🔇' : '🎤'}</span>
                 <span>{isMuted ? 'Muted' : 'Unmuted'}</span>
               </button>
               {mode === 'video' && (
                 <button onClick={() => setIsVideoOff(!isVideoOff)} className={`flex-1 py-4 rounded-2xl border-2 transition-all flex items-center justify-center gap-3 font-bold uppercase text-[10px] tracking-widest ${isVideoOff ? 'bg-red-600 border-red-400 text-white' : 'bg-slate-900 border-indigo-500/50 text-indigo-400'}`}>
                   <span>{isVideoOff ? '🚫' : '📹'}</span>
                   <span>{isVideoOff ? 'No Video' : 'Video On'}</span>
                 </button>
               )}
             </div>
             <button onClick={joinSession} className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[1.5rem] font-black uppercase text-xs tracking-[0.2em] shadow-2xl transition-all active:scale-95">Connect Now</button>
             <button onClick={onClose} className="w-full text-slate-500 hover:text-white text-[10px] font-black uppercase tracking-widest pt-2">Cancel Link</button>
          </div>
        </div>
      </div>
    );
  }

  // --- FULL SESSION VIEW ---
  const badge = getStatusBadge();
  return (
    <div className="w-full max-w-6xl bg-slate-900 border border-slate-800 rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden max-h-[95vh] animate-in zoom-in-95 duration-300">
      <header className="p-5 sm:p-6 bg-slate-950/60 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-4 min-w-0">
           <div className="p-3 bg-indigo-600/20 rounded-2xl text-indigo-400 shrink-0">
             {mode === 'video' ? '📹' : '🔊'}
           </div>
           <div className="min-w-0">
             <div className="flex items-center gap-3 mb-0.5">
                <h2 className="text-lg font-black text-white italic uppercase tracking-tight truncate">{groupName}</h2>
                <div className={`px-2 py-0.5 rounded-full ${badge.color} text-[8px] font-black text-white uppercase tracking-widest flex items-center gap-1.5`}>
                   {connStatus === 'stable' && <svg className="w-2 h-2" fill="currentColor" viewBox="0 0 20 20"><path d="M17.707 9.293a1 1 0 010 1.414l-7 7a1 1 0 01-1.414 0l-7-7a1 1 0 011.414-1.414L10 14.586l6.293-6.293a1 1 0 011.414 0z"/></svg>}
                   {badge.label}
                </div>
             </div>
             <p className="text-slate-500 text-[9px] font-bold tracking-widest uppercase">Live Interactive Uplink</p>
           </div>
        </div>
        <button onClick={onMinimize} className="p-2 hover:bg-slate-800 rounded-xl transition-all text-slate-400 shrink-0">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
        </button>
      </header>

      <div className="flex-1 p-4 sm:p-8 overflow-y-auto bg-slate-950 custom-scrollbar">
        {connStatus === 'connecting' || connStatus === 'reconnecting' ? (
          <div className="h-full flex flex-col items-center justify-center min-h-[300px]">
            <div className="relative w-16 h-16 mb-6">
              <div className="absolute inset-0 border-4 border-indigo-500/20 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
            <p className="text-indigo-400 font-bold uppercase tracking-widest text-[10px] animate-pulse">Syncing Nexus Feed...</p>
          </div>
        ) : error && connStatus === 'failed' ? (
          <div className="flex flex-col h-full items-center justify-center py-20 text-center">
            <div className="text-6xl mb-6">🛰️</div>
            <p className="text-slate-200 font-black text-xl mb-2 italic uppercase">{error}</p>
            <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest mb-10 max-w-xs">Connection attempts failed. Manual re-sync required.</p>
            <button onClick={joinSession} className="px-10 py-4 bg-indigo-600 text-white font-black uppercase tracking-widest text-[10px] rounded-2xl hover:bg-indigo-500 transition-all shadow-xl">Manual Reconnect</button>
          </div>
        ) : (
          <div className={`grid gap-6 h-full ${mode === 'video' ? 'grid-cols-1 lg:grid-cols-3' : 'grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5'}`}>

            {/* Main Stage for Video mode */}
            {mode === 'video' && (
              <div className="lg:col-span-2 aspect-video bg-slate-900 rounded-[2.5rem] overflow-hidden border border-slate-800 shadow-2xl relative">
                {!isVideoOff ? (
                  <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-slate-900">
                    <img src={participants[0].avatar} className="w-24 h-24 rounded-[2rem] border-4 border-indigo-500 shadow-2xl" alt="" />
                  </div>
                )}
                <div className="absolute bottom-6 left-6 px-4 py-2 bg-black/60 backdrop-blur-md rounded-2xl text-[10px] font-black text-white border border-white/10 uppercase tracking-widest flex items-center gap-2">
                   <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div> You (Lecturer)
                </div>
              </div>
            )}

            {/* Participants Grid */}
            {mode === 'video' ? (
              <div className="flex flex-col gap-4 overflow-y-auto max-h-[500px] lg:max-h-full custom-scrollbar pr-2">
                 {participants.map(p => (
                   <div key={p.id} className={`p-4 rounded-[1.8rem] border transition-all duration-300 ${p.isSpeaking ? 'bg-indigo-600/10 border-indigo-500 shadow-lg' : 'bg-slate-900 border-slate-800'} flex items-center gap-4`}>
                      <img src={p.avatar} className={`w-12 h-12 rounded-2xl border-2 ${p.isSpeaking ? 'border-indigo-400' : 'border-slate-800'} shrink-0`} alt="" />
                      <div className="min-w-0">
                         <div className="text-[11px] font-black text-white truncate uppercase tracking-tight">{p.name}</div>
                         <div className="text-[9px] text-slate-500 font-bold uppercase mt-1 tracking-widest">{p.isSpeaking ? 'Transmitting' : 'Monitoring'}</div>
                      </div>
                   </div>
                 ))}
              </div>
            ) : (
              /* Voice Grid */
              participants.map(p => (
                <div key={p.id} className={`flex flex-col items-center justify-center p-6 rounded-[3rem] border transition-all duration-500 gap-4 min-h-[160px] ${p.isSpeaking ? 'bg-indigo-600/10 border-indigo-500 shadow-xl' : 'bg-slate-900 border-slate-800'}`}>
                   <div className="relative">
                      <img src={p.avatar} className={`w-16 h-16 sm:w-20 sm:h-20 rounded-[2.2rem] border-4 transition-all duration-500 ${p.isSpeaking ? 'border-indigo-400 scale-110' : 'border-slate-800'}`} alt="" />
                      {p.isSpeaking && (
                         <div className="absolute -inset-2 border-2 border-indigo-500 rounded-[2.5rem] animate-ping opacity-20"></div>
                      )}
                   </div>
                   <div className="text-center min-w-0 w-full">
                      <div className={`text-[10px] sm:text-xs font-black uppercase tracking-tight truncate ${p.isSpeaking ? 'text-indigo-400' : 'text-white'}`}>{p.name}</div>
                      <div className="text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{p.isSpeaking ? 'Active' : 'Standby'}</div>
                   </div>
                </div>
              ))
            )}
          </div>
        )}
      </div>

      <footer className="p-6 sm:p-8 bg-slate-950/80 border-t border-slate-800 flex justify-center items-center gap-4 sm:gap-6">
        <button 
          onClick={() => setIsMuted(!isMuted)} 
          className={`p-5 rounded-[1.5rem] transition-all shadow-xl active:scale-95 ${isMuted ? 'bg-red-600 text-white' : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white'}`}
          title={isMuted ? "Unmute" : "Mute"}
        >
          {isMuted ? '🔇' : '🎤'}
        </button>

        {mode === 'video' && (
          <button 
            onClick={() => setIsVideoOff(!isVideoOff)} 
            className={`p-5 rounded-[1.5rem] transition-all shadow-xl active:scale-95 ${isVideoOff ? 'bg-red-600 text-white' : 'bg-slate-800 text-slate-400 hover:bg-slate-700 hover:text-white'}`}
            title={isVideoOff ? "Start Video" : "Stop Video"}
          >
            {isVideoOff ? '🚫' : '📹'}
          </button>
        )}

        <button onClick={onClose} className="px-10 sm:px-14 py-4 bg-red-600 hover:bg-red-500 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-[0_15px_40px_-5px_rgba(220,38,38,0.4)] active:scale-95 transition-all">
          End Session
        </button>

        <button className="hidden sm:block p-5 bg-slate-800 text-slate-400 hover:bg-indigo-600 hover:text-white rounded-[1.5rem] transition-all shadow-xl active:scale-95">
           <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
        </button>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

