import React, { useState, useRef, useEffect } from 'react';
import { Group, Message, Attachment, GroupMember } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  onSendMessage: (text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
}

const ChatArea: React.FC<ChatAreaProps> = ({ groupName, messages, members, onSendMessage, onAddMember, headerContent, onToggleMenu }) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);

  const [newMemberName, setNewMemberName] = useState('');
  const [newMemberRole, setNewMemberRole] = useState<GroupMember['role']>('Member');

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
  };

  const handleInviteSubmit = () => {
    if (newMemberName.trim()) {
      onAddMember(newMemberName, newMemberRole);
      setNewMemberName('');
      setIsInviteModalOpen(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared a file: ${file.name}`, attachment);
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-950 relative overflow-hidden">
      <header className="px-5 py-3 border-b border-slate-900 bg-slate-950/80 backdrop-blur-xl flex items-center justify-between z-10">
        <div className="flex items-center min-w-0">
          <button 
            onClick={onToggleMenu}
            className="p-2 mr-3 bg-slate-900 rounded-xl md:hidden text-slate-400 hover:text-white transition-all border border-slate-800"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
          </button>
          <div className="text-base font-extrabold text-white truncate tracking-tight uppercase italic flex items-center gap-2">
             <span className="text-indigo-500 opacity-60">#</span> {groupName}
          </div>
        </div>

        <div className="flex items-center gap-3">
          {headerContent}
          <button 
            onClick={() => setShowMembers(!showMembers)}
            className={`p-2.5 rounded-xl border transition-all duration-300 ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-500'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-5 custom-scrollbar">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-20">
              <div className="w-16 h-16 bg-slate-900 rounded-2xl flex items-center justify-center text-3xl mb-4 border border-slate-800">💬</div>
              <p className="text-[9px] font-bold uppercase tracking-[0.4em] text-white">Hub Initialized</p>
            </div>
          )}
          {messages.map((m) => {
            const isMe = m.sender === 'You';
            return (
              <div key={m.id} className={`flex items-start gap-3 ${isMe ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-1 duration-200`}>
                <img src={m.avatar} className="w-8 h-8 rounded-xl border border-slate-900 shadow-md shrink-0 object-cover" alt="" />
                <div className={`flex flex-col gap-1 max-w-[85%] md:max-w-[75%] ${isMe ? 'items-end' : ''}`}>
                  <div className="flex items-center gap-2 px-1">
                    <span className="text-[9px] font-extrabold text-indigo-400 uppercase tracking-tight italic">{m.sender}</span>
                    <span className="text-[8px] text-slate-600 font-bold">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                  <div className={`rounded-2xl px-4 py-3 shadow-lg border transition-all ${
                    isMe 
                      ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                      : 'bg-slate-900 border-slate-800 text-slate-200 rounded-tl-none'
                  }`}>
                    {m.attachment && (
                      <div className="mb-2 p-3 bg-black/20 rounded-xl flex items-center gap-3 border border-white/5">
                        <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="text-[12px] font-bold truncate tracking-tight">{m.attachment.name}</div>
                          <div className="text-[8px] opacity-60 font-black uppercase tracking-widest">{m.attachment.size}</div>
                        </div>
                      </div>
                    )}
                    <p className="text-[14px] leading-relaxed whitespace-pre-wrap font-medium">{m.text}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {showMembers && (
          <div className="absolute inset-y-0 right-0 w-64 bg-slate-950 border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
             <div className="p-4 border-b border-slate-900 flex items-center justify-between">
                <span className="text-[9px] font-extrabold uppercase text-indigo-400 tracking-widest italic">Directory</span>
                <button onClick={() => setIsInviteModalOpen(true)} className="p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 transition-all">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-4 custom-scrollbar">
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[8px] font-black text-slate-600 uppercase mb-2 ml-1 tracking-widest">{status} • {filtered.length}</div>
                      <div className="space-y-1">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-3 p-2 rounded-xl hover:bg-slate-900 transition-all cursor-pointer border border-transparent hover:border-slate-800">
                            <div className="relative">
                              <img src={member.avatar} className="w-8 h-8 rounded-lg object-cover border border-slate-800" alt="" />
                              {status === 'online' && <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full bg-emerald-500 border-2 border-slate-950"></div>}
                            </div>
                            <div className="min-w-0">
                               <div className="text-[12px] font-bold text-white truncate tracking-tight">{member.name}</div>
                               <div className="text-[8px] text-slate-500 font-extrabold uppercase tracking-widest">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-slate-950/80 backdrop-blur-xl border-t border-slate-900">
        <div className="max-w-3xl mx-auto flex items-end gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-slate-900 text-slate-500 hover:text-indigo-400 rounded-xl border border-slate-800 transition-all active:scale-95">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
          <div className="flex-1 relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              className="w-full bg-slate-900 border border-slate-800 rounded-2xl px-5 py-3 pr-12 outline-none focus:ring-1 focus:ring-indigo-500 transition-all resize-none max-h-32 min-h-[44px] text-sm text-slate-200 font-medium placeholder:text-slate-600"
              rows={1}
            />
            <button 
              onClick={handleSend} 
              className="absolute right-2 bottom-2 bg-indigo-600 hover:bg-indigo-500 text-white p-2 rounded-xl disabled:opacity-20 transition-all active:scale-95" 
              disabled={!input.trim()}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

