import React, { useState, useRef, useEffect } from 'react';
import { Message, Attachment, GroupMember } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  onSendMessage: (text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
}

const ChatArea: React.FC<ChatAreaProps> = ({ groupName, messages, members, onSendMessage, onAddMember, headerContent, onToggleMenu }) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);

  const [newMemberName, setNewMemberName] = useState('');
  const [newMemberRole, setNewMemberRole] = useState<GroupMember['role']>('Member');

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared a file: ${file.name}`, attachment);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {/* Slimmed Mobile Header */}
      <header className="h-14 md:h-16 px-3 md:px-5 border-b border-slate-900 bg-slate-950/80 backdrop-blur-xl flex items-center justify-between z-10 shrink-0">
        <div className="flex items-center min-w-0">
          <button 
            onClick={onToggleMenu}
            className="p-1.5 mr-2 bg-slate-900 rounded-lg md:hidden text-slate-400 border border-slate-800"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
          </button>
          <div className="text-sm md:text-base font-extrabold text-white truncate tracking-tight uppercase italic flex items-center gap-1.5">
             <span className="text-indigo-500 opacity-60">#</span> {groupName}
          </div>
        </div>

        <div className="flex items-center gap-2">
          {headerContent}
          <button 
            onClick={() => setShowMembers(!showMembers)}
            className={`p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-500'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 md:p-4 space-y-3 md:space-y-4 custom-scrollbar overscroll-contain">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-10">
              <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-2xl mb-3 border border-slate-800">💬</div>
              <p className="text-[8px] font-bold uppercase tracking-[0.4em] text-white">Encrypted Signal Channel</p>
            </div>
          )}
          {messages.map((m) => {
            const isMe = m.sender === 'You';
            return (
              <div key={m.id} className={`flex items-start gap-2 md:gap-3 ${isMe ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-1 duration-200`}>
                <img src={m.avatar} className="w-7 h-7 md:w-8 md:h-8 rounded-lg border border-slate-900 shadow-sm shrink-0 object-cover" alt="" />
                <div className={`flex flex-col gap-0.5 max-w-[85%] md:max-w-[75%] ${isMe ? 'items-end' : ''}`}>
                  <div className="flex items-center gap-2 px-1">
                    <span className="text-[8px] md:text-[9px] font-black text-indigo-400 uppercase tracking-tight italic">{m.sender}</span>
                    <span className="text-[7px] md:text-[8px] text-slate-600 font-bold">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                  <div className={`rounded-xl md:rounded-2xl px-3 py-2 md:px-4 md:py-3 shadow-md border transition-all ${
                    isMe 
                      ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                      : 'bg-slate-900 border-slate-800 text-slate-200 rounded-tl-none'
                  }`}>
                    {m.attachment && (
                      <div className="mb-2 p-2 bg-black/20 rounded-lg flex items-center gap-2 border border-white/5">
                        <div className="p-1.5 bg-indigo-500/20 rounded-md text-indigo-400">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="text-[10px] font-bold truncate">{m.attachment.name}</div>
                          <div className="text-[7px] opacity-60 font-black uppercase">{m.attachment.size}</div>
                        </div>
                      </div>
                    )}
                    <p className="text-[13px] md:text-[14px] leading-snug whitespace-pre-wrap font-medium">{m.text}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Members Sidebar - Overlay on mobile */}
        {showMembers && (
          <div className="absolute inset-y-0 right-0 w-64 bg-slate-950 border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
             <div className="h-14 px-4 border-b border-slate-900 flex items-center justify-between">
                <span className="text-[8px] font-black uppercase text-indigo-400 tracking-widest">Directory</span>
                <button onClick={() => setShowMembers(false)} className="p-1 text-slate-500 md:hidden">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-2 space-y-3 custom-scrollbar">
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[7px] font-black text-slate-700 uppercase mb-1.5 ml-1 tracking-[0.2em]">{status} • {filtered.length}</div>
                      <div className="space-y-0.5">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-2 p-1.5 rounded-lg hover:bg-slate-900 transition-all border border-transparent">
                            <div className="relative">
                              <img src={member.avatar} className="w-7 h-7 rounded-md object-cover" alt="" />
                              {status === 'online' && <div className="absolute -bottom-0.5 -right-0.5 w-2 h-2 rounded-full bg-emerald-500 border-2 border-slate-950"></div>}
                            </div>
                            <div className="min-w-0">
                               <div className="text-[11px] font-bold text-white truncate tracking-tight">{member.name}</div>
                               <div className="text-[7px] text-slate-600 font-extrabold uppercase">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      {/* Optimized Compact Input Bar */}
      <div className="px-2 py-2 md:p-4 bg-slate-950/95 border-t border-slate-900 shrink-0">
        <div className="max-w-3xl mx-auto flex items-end gap-2">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="p-2.5 bg-slate-900 text-slate-500 rounded-xl border border-slate-800 active:scale-95 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
          </button>
          <div className="flex-1 relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Message..."
              className="w-full bg-slate-900 border border-slate-800 rounded-xl px-4 py-2 pr-10 outline-none focus:border-indigo-500/50 transition-all resize-none max-h-24 min-h-[38px] text-[14px] text-slate-200 font-medium placeholder:text-slate-700"
              rows={1}
            />
            <button 
              onClick={handleSend} 
              className="absolute right-1 bottom-1 bg-indigo-600 text-white p-1.5 rounded-lg disabled:opacity-10 transition-all active:scale-90" 
              disabled={!input.trim()}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

