import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onCreateTopic: (name: string, icon: string, description: string) => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onAddMember,
  onUploadResource,
  onCreateTopic,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);

  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicIcon, setNewTopicIcon] = useState('📚');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel') || type.includes('spreadsheet') || type.includes('csv')) return '📊';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-500 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-[#020617] relative overflow-hidden">
      {/* Hidden Explorer on Mobile */}
      <div className="w-56 bg-slate-950 border-r border-slate-900 hidden xl:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-4 border-b border-slate-900">
          <div className="font-extrabold uppercase tracking-widest text-[9px] text-slate-600">Modules</div>
        </div>
        <div className="px-3 py-4 space-y-1">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-3 rounded-xl flex items-center gap-3 transition-all duration-200 ${
                activeTopicId === topic.id ? 'bg-indigo-600/10 text-indigo-400 border border-indigo-500/20 shadow-md' : 'text-slate-500 hover:bg-slate-900/50 hover:text-slate-300'
              }`}
            >
              <span className="text-lg">{topic.icon}</span>
              <span className="truncate flex-1 font-bold text-xs tracking-tight">{topic.name}</span>
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-8 text-center animate-in fade-in duration-700">
             <div className="w-16 h-16 bg-slate-900 rounded-2xl flex items-center justify-center text-3xl mb-4 border border-slate-800">📡</div>
             <h2 className="text-xl font-extrabold text-white mb-2 italic tracking-tight uppercase">Offline</h2>
             <button onClick={onToggleMenu} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-extrabold uppercase text-[10px] tracking-widest lg:hidden">Open Hub List</button>
          </div>
        ) : (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            {/* Highly Compressed Mobile Context Switcher */}
            <div className="bg-slate-950/80 backdrop-blur-xl border-b border-slate-900 p-2 md:p-3 flex flex-col md:flex-row items-center justify-between gap-2 z-10 shrink-0">
