                             </div>
                             <button className="p-2 bg-indigo-600/10 text-indigo-400 rounded-lg text-[9px] font-bold uppercase">Get</button>
                          </div>
                        ))}
                      </div>
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-4 custom-scrollbar">
                   <div className="max-w-4xl mx-auto grid grid-cols-1 sm:grid-cols-2 gap-3">
                      {group.members.map(member => (
                        <div key={member.id} className="bg-slate-900/40 border border-slate-900 p-3 rounded-xl flex items-center gap-3">
                           <div className="relative">
                             <img src={member.avatar} className="w-8 h-8 rounded-lg object-cover" alt="" />
                             <div className={`absolute -bottom-0.5 -right-0.5 w-2 h-2 rounded-full border border-slate-950 ${member.status === 'online' ? 'bg-emerald-500' : 'bg-slate-600'}`}></div>
