                             <img src={member.avatar} className="w-9 h-9 rounded-lg object-cover border border-slate-800/50 group-hover:rotate-3 transition-transform" alt="" />
                             <div className={`absolute -bottom-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-slate-950 ${member.status === 'online' ? 'bg-emerald-500' : 'bg-slate-700'}`}></div>
                           </div>
                           <div className="flex-1 min-w-0">
                             <div className="font-black text-white text-[12px] truncate uppercase italic tracking-tighter leading-none mb-1.5">{member.name}</div>
                             <div className={`inline-flex px-1.5 py-0.5 rounded text-[7px] font-black uppercase tracking-[0.2em] border ${getRoleColor(member.role)}`}>{member.role}</div>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Module Registration Modal */}
      {isTopicModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/90 backdrop-blur-md" onClick={() => setIsTopicModalOpen(false)} />
          <div className="relative w-full max-w-sm bg-slate-950 border border-slate-900 rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <h2 className="text-xl font-black mb-6 text-white text-center italic uppercase tracking-tighter">Register Module</h2>
            <div className="space-y-6">
              <input 
                type="text" 
                value={newTopicName} 
                onChange={(e) => setNewTopicName(e.target.value)} 
                className="w-full bg-slate-900/50 border border-slate-800 rounded-xl p-4 text-[13px] text-white font-black uppercase tracking-tighter outline-none focus:border-indigo-500 transition-all" 
                placeholder="Designation Code..." 
                autoFocus
              />
              <div className="flex gap-3">
                <button onClick={() => setIsTopicModalOpen(false)} className="flex-1 py-4 bg-slate-900 text-slate-600 rounded-2xl font-black uppercase text-[10px] tracking-widest">Abort</button>
                <button onClick={() => { if(newTopicName) { onCreateTopic(newTopicName, '📂', ''); setIsTopicModalOpen(false); setNewTopicName(''); } }} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Authorize</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

