                    disabled={!newName.trim()}
                    className="flex-1 py-5 bg-indigo-600 hover:bg-indigo-500 disabled:opacity-10 disabled:grayscale text-white rounded-3xl font-black uppercase text-[11px] tracking-[0.4em] shadow-[0_20px_40px_rgba(99,102,241,0.3)] transition-all active:scale-95"
                  >
                    Authorize Link
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </aside>
  );
};

