interface HubCreationScreenProps {
  onCreate: (name: string, type: GroupType, avatar: string) => void;
  onCancel: () => void;
}

const AVATAR_PRESETS = [
  'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=200&h=200&fit=crop',
  'https://images.unsplash.com/photo-1552664730-d307ca884978?w=200&h=200&fit=crop',
  'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=200&h=200&fit=crop',
  'https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?w=200&h=200&fit=crop',
  'https://images.unsplash.com/photo-1579546929518-9e396f3cc809?w=200&h=200&fit=crop',
  'https://images.unsplash.com/photo-1614850523296-d8c1af93d400?w=200&h=200&fit=crop',
];

const HubCreationScreen: React.FC<HubCreationScreenProps> = ({ onCreate, onCancel }) => {
  const [name, setName] = useState('');
  const [type, setType] = useState<GroupType>(GroupType.TOPICS);
  const [selectedAvatar, setSelectedAvatar] = useState(AVATAR_PRESETS[0]);

  const handleCreate = () => {
    if (name.trim()) {
      onCreate(name, type, selectedAvatar);
    }
  };

  return (
    <div className="flex-1 flex flex-col h-full bg-[#020617] overflow-y-auto custom-scrollbar animate-in fade-in duration-500">
      <div className="max-w-4xl mx-auto w-full px-6 py-12 md:py-20 flex flex-col items-center">

        {/* Core Identity Preview */}
        <div className="flex flex-col items-center text-center mb-16 relative">
          <div className="relative mb-8">
             <div className="absolute -inset-8 rounded-full bg-indigo-600/10 blur-3xl animate-pulse" />
             <div className="absolute -inset-2 rounded-full border border-indigo-500/30 animate-[spin_10s_linear_infinite]" />
             <img 
               src={selectedAvatar} 
               className="w-32 h-32 md:w-40 md:h-40 rounded-[2.5rem] border-4 border-indigo-600 shadow-[0_0_50px_rgba(79,70,229,0.4)] relative z-10 object-cover transform hover:rotate-2 transition-transform duration-500" 
               alt="" 
             />
             <div className="absolute -bottom-2 -right-2 bg-indigo-600 p-2 rounded-xl shadow-xl z-20 border border-indigo-400">
                <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
             </div>
          </div>
          <h1 className="text-3xl md:text-5xl font-black text-white italic uppercase tracking-tighter mb-2">
            {name || 'Nexus Hub 00'}
          </h1>
          <p className="text-[10px] md:text-xs font-black text-indigo-500 uppercase tracking-[0.6em] animate-pulse">Initializing System Node</p>
        </div>

        {/* Configuration Matrix */}
        <div className="w-full grid grid-cols-1 lg:grid-cols-2 gap-10 md:gap-16">

          {/* Left Column: Designation */}
          <div className="space-y-10">
            <div className="space-y-4">
               <label className="flex items-center gap-3 text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] ml-1">
                 <span className="w-4 h-[1px] bg-indigo-400"></span> Channel Designation
               </label>
               <input 
                 type="text" 
                 value={name}
                 autoFocus
                 onChange={(e) => setName(e.target.value)}
                 className="w-full bg-slate-900/50 border-2 border-slate-800 rounded-3xl px-8 py-5 text-xl md:text-2xl text-white font-bold outline-none focus:border-indigo-600 focus:ring-8 focus:ring-indigo-600/5 transition-all placeholder:text-slate-800 shadow-inner"
                 placeholder="Enter Hub Name..."
               />
            </div>

            <div className="space-y-4">
               <label className="flex items-center gap-3 text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] ml-1">
                 <span className="w-4 h-[1px] bg-indigo-400"></span> Uplink Protocol
               </label>
               <div className="grid grid-cols-2 gap-4 p-2 bg-slate-900/50 border-2 border-slate-800 rounded-[2rem]">
                  <button 
                    onClick={() => setType(GroupType.STANDARD)}
                    className={`flex flex-col items-center justify-center py-6 px-4 rounded-3xl transition-all duration-300 gap-3 border ${type === GroupType.STANDARD ? 'bg-indigo-600 border-indigo-400 text-white shadow-2xl scale-[1.02]' : 'border-transparent text-slate-600 hover:text-slate-400 hover:bg-slate-800/40'}`}
                  >
                    <span className="text-3xl">💬</span>
                    <div className="text-center">
                       <div className="font-black text-[11px] uppercase tracking-widest">Standard</div>
                       <div className="text-[8px] opacity-40 font-bold uppercase mt-1">Direct Stream</div>
                    </div>
                  </button>
                  <button 
                    onClick={() => setType(GroupType.TOPICS)}
                    className={`flex flex-col items-center justify-center py-6 px-4 rounded-3xl transition-all duration-300 gap-3 border ${type === GroupType.TOPICS ? 'bg-indigo-600 border-indigo-400 text-white shadow-2xl scale-[1.02]' : 'border-transparent text-slate-600 hover:text-slate-400 hover:bg-slate-800/40'}`}
                  >
                    <span className="text-3xl">🏗️</span>
                    <div className="text-center">
                       <div className="font-black text-[11px] uppercase tracking-widest">Workspace</div>
                       <div className="text-[8px] opacity-40 font-bold uppercase mt-1">Multi-Threaded</div>
                    </div>
                  </button>
               </div>
            </div>
          </div>

          {/* Right Column: Identity Signature */}
          <div className="space-y-6">
             <label className="flex items-center gap-3 text-[10px] font-black text-indigo-400 uppercase tracking-[0.4em] ml-1">
               <span className="w-4 h-[1px] bg-indigo-400"></span> Identity Signature
             </label>
             <div className="grid grid-cols-3 gap-4">
               {AVATAR_PRESETS.map((url) => (
                 <button
                   key={url}
                   onClick={() => setSelectedAvatar(url)}
                   className={`aspect-square rounded-[2rem] border-4 transition-all duration-300 overflow-hidden relative group ${selectedAvatar === url ? 'border-indigo-600 scale-105 shadow-2xl' : 'border-slate-900 opacity-40 grayscale hover:grayscale-0 hover:opacity-100'}`}
                 >
                   <img src={url} className="w-full h-full object-cover" alt="" />
                   {selectedAvatar === url && (
                     <div className="absolute inset-0 bg-indigo-600/20 backdrop-blur-[2px] flex items-center justify-center">
                        <div className="w-4 h-4 rounded-full bg-white shadow-[0_0_20px_white] animate-pulse" />
                     </div>
                   )}
                 </button>
               ))}
             </div>
             <p className="text-[9px] text-slate-600 font-bold uppercase tracking-widest leading-relaxed mt-4 p-4 bg-slate-900/20 rounded-2xl border border-slate-900/50 italic">
               * Note: Identity signature will be broadcasted to all nodes connected to this Hub. Security protocol Alpha-9 active.
             </p>
          </div>
        </div>

        {/* Finalize Action */}
        <div className="w-full max-w-2xl mt-16 md:mt-24 flex flex-col gap-6">
          <button 
            onClick={handleCreate}
            disabled={!name.trim()}
            className="w-full py-6 md:py-8 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-800 disabled:text-slate-600 disabled:opacity-50 text-white rounded-[2.5rem] font-black uppercase text-xs md:text-sm tracking-[0.5em] shadow-[0_20px_60px_-10px_rgba(79,70,229,0.5)] transition-all active:scale-[0.98] relative overflow-hidden group"
          >
            <span className="relative z-10">Authorize System Link</span>
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
          </button>

          <button 
            onClick={onCancel}
            className="w-full py-4 text-[10px] font-black text-slate-600 hover:text-white uppercase tracking-[0.4em] transition-colors"
          >
            Abort Protocol
          </button>
        </div>
      </div>
