export default HubCreationScreen;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatArea from './components/ChatArea';
import DashboardArea from './components/DashboardArea';
import MeetingSession from './components/MeetingSession';
import HubCreationScreen from './components/HubCreationScreen';
import { Group, GroupType, Message, Attachment, Resource, Topic, GroupMember } from './types';

const MOCK_MEMBERS: GroupMember[] = [
  { id: '1', name: 'You (Lecturer)', avatar: 'https://picsum.photos/80/80?u=1', role: 'Owner', status: 'online' },
  { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', role: 'AI Assistant', status: 'online' },
  { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', role: 'Admin', status: 'online' },
  { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', role: 'Member', status: 'offline' },
  { id: '4', name: 'Elena Rodriguez', avatar: 'https://picsum.photos/80/80?u=4', role: 'Member', status: 'online' },
];

const INITIAL_GROUPS: Group[] = [
  {
    id: 'edu-1',
    name: 'Advanced Mathematics',
    type: GroupType.TOPICS,
    category: 'Education',
    members: MOCK_MEMBERS,
    topics: [
      { 
        id: 't1', 
        name: 'Calculus III', 
        description: 'Multivariable calculus resources and lecture notes.', 
        icon: '📐',
        messages: [],
        resources: [
          { id: 'r1', name: 'Lecture_Notes_Week1.pdf', type: 'application/pdf', size: '2.4 MB', uploadedBy: 'Prof. Smith', date: new Date() }
        ]
      },
      { 
        id: 't2', 
        name: 'Linear Algebra', 
        description: 'Matrices, vectors, and linear transformations.', 
        icon: '📊',
        messages: [],
        resources: []
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=100&h=100&fit=crop'
  },
  {
    id: 'corp-1',
    name: 'Strategic Planning',
    type: GroupType.TOPICS,
    category: 'Corporate',
    members: MOCK_MEMBERS.slice(0, 3),
    topics: [
      { 
        id: 't3', 
        name: 'Q4 Roadmap', 
        description: 'Resource management and project milestones.', 
        icon: '🎯',
        messages: [],
        resources: [
          { id: 'r2', name: 'Budget_Draft.xlsx', type: 'application/vnd.ms-excel', size: '1.1 MB', uploadedBy: 'Jane Doe', date: new Date() }
        ]
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=100&h=100&fit=crop'
  }
];

const App: React.FC = () => {
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string | null>('edu-1');
  const [activeTopicId, setActiveTopicId] = useState<string | null>('t1');
  const [isAddingHub, setIsAddingHub] = useState(false);

  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [sessionGroupName, setSessionGroupName] = useState<string | null>(null);
  const [isSessionMinimized, setIsSessionMinimized] = useState(false);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  const handleSelectGroup = (id: string) => {
    setIsAddingHub(false);
    setActiveGroupId(id);
    const selectedGroup = groups.find(g => g.id === id);

    // Auto-select first topic if it's a Workspace hub
    if (selectedGroup && selectedGroup.type === GroupType.TOPICS && selectedGroup.topics.length > 0) {
      setActiveTopicId(selectedGroup.topics[0].id);
    } else {
      setActiveTopicId(null);
    }

    setIsMobileMenuOpen(false);
  };

  const handleOpenVoice = (mode: 'voice' | 'video') => {
    const groupName = activeTopicId 
      ? activeGroup?.topics.find(t => t.id === activeTopicId)?.name || activeGroup?.name
      : activeGroup?.name;

    setSessionGroupName(groupName || 'Nexus Hub Session');
    setSessionMode(mode);
    setIsSessionMinimized(false);
  };

  const handleCreateGroup = (name: string, type: GroupType, avatar: string) => {
    const defaultTopic: Topic = { id: `t-intro-${Date.now()}`, name: 'Welcome', description: 'Quick start guide.', icon: '✨', messages: [], resources: [] };
    const newGroup: Group = {
      id: `hub-${Date.now()}`,
      name,
      type,
      topics: type === GroupType.TOPICS ? [defaultTopic] : [],
      messages: [],
      members: [MOCK_MEMBERS[0]],
      avatar,
      category: 'Community'
    };
    setGroups(prev => [...prev, newGroup]);
    setActiveGroupId(newGroup.id);
    setActiveTopicId(type === GroupType.TOPICS ? defaultTopic.id : null);
    setIsAddingHub(false);
  };

  const handleAddMember = (groupId: string, name: string, role: GroupMember['role']) => {
    const newMember: GroupMember = {
      id: `mem-${Date.now()}`,
      name,
      role,
      avatar: `https://picsum.photos/80/80?u=${Date.now()}`,
      status: 'online'
    };
    setGroups(prev => prev.map(g => g.id === groupId ? { ...g, members: [...g.members, newMember] } : g));
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    const newMessage: Message = {
      id: `msg-${Date.now()}`,
      sender: 'You',
      text,
      timestamp: new Date(),
      avatar: MOCK_MEMBERS[0].avatar,
      attachment
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: [...t.messages, newMessage] } : t)
        };
      }
    }));
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#020617] text-slate-200 selection:bg-indigo-500/30">
      {/* Sidebar - Mobile Responsive Handling */}
      <div className={`fixed inset-y-0 left-0 z-50 transform lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <Sidebar 
          groups={groups} 
          activeGroupId={activeGroupId || ''} 
          activeTopicId={activeTopicId}
          onSelectGroup={handleSelectGroup}
          onSelectTopic={(id) => { setIsAddingHub(false); setActiveTopicId(id); setIsMobileMenuOpen(false); }}
          onStartAddingHub={() => { setIsAddingHub(true); setIsMobileMenuOpen(false); }}
          onJoinVoice={handleOpenVoice}
          isOpen={isMobileMenuOpen}
          onClose={() => setIsMobileMenuOpen(false)}
        />
      </div>

      {/* Backdrop for mobile menu */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 h-full relative">
        {isAddingHub ? (
          <HubCreationScreen 
            onCreate={handleCreateGroup} 
            onCancel={() => setIsAddingHub(false)} 
          />
        ) : activeGroup ? (
          activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              onSendMessage={(text, att) => handleSendMessage(null, text, att)}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              activeTopicId={activeTopicId}
              onSelectTopic={setActiveTopicId}
              onOpenVoice={handleOpenVoice}
              onSendMessage={handleSendMessage}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onUploadResource={(topicId, res) => {
                 setGroups(prev => prev.map(g => g.id === activeGroupId ? {
                   ...g,
                   topics: g.topics.map(t => t.id === topicId ? { ...t, resources: [...t.resources, { ...res, id: Date.now().toString(), uploadedBy: 'You', date: new Date() }] } : t)
                 } : g));
              }}
              onCreateTopic={(name, icon, desc) => {
                const newTopic: Topic = { id: `t-${Date.now()}`, name, icon, description: desc, messages: [], resources: [] };
                setGroups(prev => prev.map(g => g.id === activeGroupId ? { ...g, topics: [...g.topics, newTopic] } : g));
                setActiveTopicId(newTopic.id);
              }}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          )
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-8 text-center bg-slate-950">
            <div className="w-20 h-20 bg-slate-900 rounded-[2rem] flex items-center justify-center text-4xl mb-6 shadow-2xl border border-slate-800">🌌</div>
            <h2 className="text-2xl font-black text-white italic tracking-tight uppercase">Select a Link Hub</h2>
            <button onClick={() => setIsMobileMenuOpen(true)} className="mt-8 px-10 py-4 bg-indigo-600 text-white rounded-3xl font-black uppercase text-[10px] tracking-widest shadow-xl lg:hidden">Browse Hubs</button>
            <button onClick={() => setIsAddingHub(true)} className="mt-4 text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest transition-colors">Or Initialize New Hub</button>
          </div>
        )}

        {/* Persistent Call Layer */}
        {sessionMode && (
          <div className={`fixed z-[100] transition-all duration-500 ease-in-out ${
            isSessionMinimized 
              ? 'bottom-6 right-6 w-[320px] max-w-[90vw] h-auto pointer-events-auto' 
              : 'inset-0 flex items-center justify-center p-2 sm:p-4 bg-[#020617]/80 backdrop-blur-xl pointer-events-auto'
          }`}>
            <MeetingSession 
              mode={sessionMode}
              isMinimized={isSessionMinimized}
              onMinimize={() => setIsSessionMinimized(!isSessionMinimized)}
              onClose={() => { setSessionMode(null); setSessionGroupName(null); }} 
              groupName={sessionGroupName || 'Active Session'} 
            />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

