export enum GroupType {
  STANDARD = 'STANDARD',
  TOPICS = 'TOPICS'
}

export interface Attachment {
  name: string;
  type: string;
  size: string;
  url?: string;
}

export interface Resource extends Attachment {
  id: string;
  uploadedBy: string;
  date: Date;
}

export interface Message {
  id: string;
  sender: string;
  text: string;
  timestamp: Date;
  avatar: string;
  attachment?: Attachment;
}

export interface Topic {
  id: string;
  name: string;
  description: string;
  icon: string;
  messages: Message[];
  resources: Resource[];
  activeCall?: boolean;
}

export interface GroupMember {
  id: string;
  name: string;
  avatar: string;
  role: 'Owner' | 'Admin' | 'Member' | 'AI Assistant';
  status: 'online' | 'offline';
}

