        {/* Directory Sidebar transformed into Hub Intel */}
        {showMembers && (
          <div className="absolute inset-y-0 right-0 w-72 bg-slate-950/95 backdrop-blur-3xl border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
             <div className="h-14 px-4 border-b border-slate-900 flex items-center justify-between shrink-0">
                <span className="text-[8px] font-black uppercase text-indigo-500 tracking-[0.3em] italic">Hub Intelligence</span>
                <button onClick={() => setShowMembers(false)} className="p-1.5 text-slate-700">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>

             <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
               {/* Manifesto Section */}
               {(groupDescription || groupRules) && (
                 <div className="space-y-4">
                   {groupDescription && (
                     <div>
                       <div className="text-[7px] font-black text-indigo-500 uppercase tracking-widest mb-1.5 italic">Operational Briefing</div>
                       <div className="bg-slate-900/40 border border-slate-900 rounded-xl p-3 text-[10px] text-slate-400 font-medium leading-relaxed italic">
