import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onStartAddingTopic: () => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onAddMember,
  onUploadResource,
  onStartAddingTopic,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel')) return '📊';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-600 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-[#020617] relative overflow-hidden">
      {/* High-Density Module Explorer for Desktop */}
      <div className="w-52 bg-slate-950/40 border-r border-slate-900/50 hidden xl:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-3.5 border-b border-slate-900/50">
          <div className="font-black uppercase tracking-[0.3em] text-[8px] text-slate-600 italic">Core Modules</div>
        </div>
        <div className="px-2 py-3 space-y-0.5">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-2.5 rounded-xl flex items-center gap-2.5 transition-all duration-200 border ${
                activeTopicId === topic.id ? 'bg-indigo-600/5 text-indigo-400 border-indigo-500/20 shadow-md' : 'border-transparent text-slate-500 hover:text-slate-400'
              }`}
            >
              <span className="text-base">{topic.icon}</span>
              <span className="truncate flex-1 font-black text-[10px] tracking-tighter uppercase italic">{topic.name}</span>
            </button>
          ))}
          <button 
            onClick={onStartAddingTopic}
            className="w-full text-left p-2.5 rounded-xl flex items-center gap-2.5 text-slate-700 hover:text-slate-500 border border-dashed border-slate-900 mt-3 group transition-all"
          >
            <span className="text-base">➕</span>
            <span className="truncate flex-1 text-[9px] font-black uppercase tracking-widest">Register Module</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0 h-full">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-8 text-center animate-in fade-in duration-700 bg-slate-950/50">
             <div className="w-14 h-14 bg-slate-900/50 rounded-2xl flex items-center justify-center text-2xl mb-4 border border-slate-800 shadow-xl">📡</div>
             <h2 className="text-lg font-black text-white mb-2 italic tracking-tight uppercase">System Awaiting Input</h2>
             <button onClick={onToggleMenu} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest lg:hidden shadow-lg active:scale-95 transition-all">Browse Modules</button>
          </div>
        ) : (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            {/* Highly Compressed Context Switcher */}
            <div className="bg-slate-950/80 backdrop-blur-3xl border-b border-slate-900 p-2 md:p-3 flex flex-col md:flex-row items-center justify-between gap-3 z-10 shrink-0">
               <div className="flex items-center gap-2.5 w-full md:w-auto min-w-0">
                  <button onClick={onToggleMenu} className="p-2 bg-slate-900 rounded-lg lg:hidden text-slate-500 border border-slate-800/50 shrink-0">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" /></svg>
                  </button>
                  <div className="p-2 bg-slate-900 rounded-lg border border-slate-800 text-lg shadow-inner shrink-0">{activeTopic.icon}</div>
                  <div className="min-w-0 flex-1">
                    <h2 className="text-[13px] font-black text-white leading-tight truncate uppercase italic tracking-tighter">{activeTopic.name}</h2>
                    <div className="flex items-center gap-2 overflow-hidden">
                       <span className="text-[7px] text-indigo-500 font-black uppercase tracking-[0.3em] leading-none shrink-0">{group.name}</span>
                       {activeTopic.description && (
                         <>
                           <span className="w-0.5 h-0.5 rounded-full bg-slate-700 shrink-0"></span>
                           <span className="text-[7px] text-slate-500 font-bold uppercase tracking-widest truncate">{activeTopic.description}</span>
                         </>
                       )}
                    </div>
                  </div>
               </div>

               {/* Segment Switcher */}
               <div className="flex items-center gap-1 bg-slate-900/40 p-1 rounded-xl border border-slate-900/80 w-full md:w-auto shrink-0">
                  <button onClick={() => setViewMode('discussion')} className={`flex-1 md:flex-none px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Uplink</button>
                  <button onClick={() => setViewMode('resources')} className={`flex-1 md:flex-none px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Library</button>
                  <button onClick={() => setViewMode('members')} className={`flex-1 md:flex-none px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Nodes</button>
               </div>

               <div className="hidden md:flex items-center gap-2 shrink-0">
                 <button onClick={() => onOpenVoice('voice')} className="px-3.5 py-1.5 bg-slate-900/50 text-indigo-400 rounded-lg font-black text-[9px] uppercase tracking-widest border border-slate-800 transition-all hover:bg-slate-800">🔊 Voice</button>
                 <button onClick={() => onOpenVoice('video')} className="px-3.5 py-1.5 bg-indigo-600 text-white rounded-lg font-black text-[9px] uppercase tracking-widest border border-indigo-400 transition-all hover:bg-indigo-500 shadow-md">🎥 Video</button>
               </div>
            </div>

            <div className="flex-1 overflow-hidden">
              {viewMode === 'discussion' && (
                <ChatArea 
                  groupName={activeTopic.name} 
                  messages={activeTopic.messages} 
                  members={group.members} 
                  groupDescription={group.description}
                  groupRules={group.rules}
                  onSendMessage={(text, attachment) => onSendMessage(activeTopic.id, text, attachment)} 
                  onAddMember={onAddMember} 
                  onToggleMenu={onToggleMenu}
                  headerContent={
                    <div className="flex md:hidden gap-1.5">
                      <button onClick={() => onOpenVoice('voice')} className="p-1.5 bg-slate-900 text-indigo-500 rounded-lg border border-slate-800/50"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"/></svg></button>
                      <button onClick={() => onOpenVoice('video')} className="p-1.5 bg-indigo-600 text-white rounded-lg border border-indigo-500/50"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg></button>
                    </div>
                  }
                />
              )}
              {viewMode === 'resources' && (
                <div className="h-full overflow-y-auto p-4 md:p-8 bg-slate-950 custom-scrollbar overscroll-contain">
                   <div className="max-w-5xl mx-auto space-y-5">
                     <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" />
                        <button onClick={() => fileInputRef.current?.click()} className="bg-indigo-600/5 border border-dashed border-indigo-500/20 rounded-xl p-4 flex items-center justify-center gap-3 active:scale-95 transition-all">
                           <span className="text-xl">➕</span>
                           <span className="text-[10px] font-black text-white uppercase italic tracking-tighter">Inject Archive Node</span>
                        </button>
                        {activeTopic.resources.map(res => (
                          <div key={res.id} className="bg-slate-900/30 border border-slate-900/80 p-3.5 rounded-xl flex items-center gap-3.5 hover:bg-slate-900 transition-all shadow-lg group">
                             <div className="w-10 h-10 bg-slate-950 rounded-lg flex items-center justify-center text-xl border border-slate-800/40 shadow-inner group-hover:scale-110 transition-transform">{getFileIcon(res.type)}</div>
                             <div className="flex-1 min-w-0">
                                <h5 className="font-black text-white truncate text-[11px] tracking-tighter uppercase italic mb-0.5">{res.name}</h5>
                                <div className="flex items-center gap-1.5">
                                  <span className="text-[8px] text-slate-600 font-black uppercase tracking-widest">{res.size}</span>
                                  <span className="text-[7px] text-indigo-500/40 font-black uppercase">Archive</span>
                                </div>
                             </div>
                             <button className="p-2 bg-indigo-600/10 text-indigo-400 hover:bg-indigo-600 hover:text-white rounded-lg text-[9px] font-black uppercase tracking-widest transition-all">Get</button>
                          </div>
                        ))}
                      </div>
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-4 md:p-8 bg-slate-950 custom-scrollbar overscroll-contain">
                   <div className="max-w-4xl mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                      {group.members.map(member => (
                        <div key={member.id} className="bg-slate-900/30 border border-slate-900/80 p-3.5 rounded-xl flex items-center gap-3.5 hover:bg-slate-900 transition-all shadow-lg group">
                           <div className="relative">
                             <img src={member.avatar} className="w-9 h-9 rounded-lg object-cover border border-slate-800/50 group-hover:rotate-3 transition-transform" alt="" />
                             <div className={`absolute -bottom-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-slate-950 ${member.status === 'online' ? 'bg-emerald-500' : 'bg-slate-700'}`}></div>
                           </div>
                           <div className="flex-1 min-w-0">
                             <div className="font-black text-white text-[12px] truncate uppercase italic tracking-tighter leading-none mb-1.5">{member.name}</div>
                             <div className={`inline-flex px-1.5 py-0.5 rounded text-[7px] font-black uppercase tracking-[0.2em] border ${getRoleColor(member.role)}`}>{member.role}</div>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DashboardArea;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatArea from './components/ChatArea';
import DashboardArea from './components/DashboardArea';
import MeetingSession from './components/MeetingSession';
import HubCreationScreen from './components/HubCreationScreen';
import StartupScreen from './components/StartupScreen';
import { Group, GroupType, Message, Attachment, Resource, Topic, GroupMember } from './types';

const MOCK_MEMBERS: GroupMember[] = [
  { id: '1', name: 'You (Lecturer)', avatar: 'https://picsum.photos/80/80?u=1', role: 'Owner', status: 'online' },
  { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', role: 'AI Assistant', status: 'online' },
  { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', role: 'Admin', status: 'online' },
  { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', role: 'Member', status: 'offline' },
  { id: '4', name: 'Elena Rodriguez', avatar: 'https://picsum.photos/80/80?u=4', role: 'Member', status: 'online' },
];

const INITIAL_GROUPS: Group[] = [
  {
    id: 'edu-1',
    name: 'Advanced Mathematics',
    description: 'High-level synthesis of multivariable calculus and abstract algebra for research students.',
    rules: '1. Academic integrity is mandatory. 2. Support peers. 3. AI use permitted for clarification only.',
    type: GroupType.TOPICS,
    category: 'Education',
    members: MOCK_MEMBERS,
    topics: [
      { 
        id: 't1', 
        name: 'Calculus III', 
        description: 'Multivariable calculus resources and lecture notes.', 
        icon: '📐',
        messages: [],
        resources: [
          { id: 'r1', name: 'Lecture_Notes_Week1.pdf', type: 'application/pdf', size: '2.4 MB', uploadedBy: 'Prof. Smith', date: new Date() }
        ]
      },
      { 
        id: 't2', 
        name: 'Linear Algebra', 
        description: 'Matrices, vectors, and linear transformations.', 
        icon: '📊',
        messages: [],
        resources: []
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=100&h=100&fit=crop'
  },
  {
    id: 'corp-1',
    name: 'Strategic Planning',
    description: 'Central nerve center for corporate roadmap development and resource allocation.',
    rules: 'Strict confidentiality applies. Share weekly milestones by EOD Friday.',
    type: GroupType.TOPICS,
    category: 'Corporate',
    members: MOCK_MEMBERS.slice(0, 3),
    topics: [
      { 
        id: 't3', 
        name: 'Q4 Roadmap', 
        description: 'Resource management and project milestones.', 
        icon: '🎯',
        messages: [],
        resources: [
          { id: 'r2', name: 'Budget_Draft.xlsx', type: 'application/vnd.ms-excel', size: '1.1 MB', uploadedBy: 'Jane Doe', date: new Date() }
        ]
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1552664730-d307ca884978?w=100&h=100&fit=crop'
  }
];

const App: React.FC = () => {
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [isAddingHub, setIsAddingHub] = useState(false);
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);

  const [topicModalMode, setTopicModalMode] = useState<'create' | 'edit'>('create');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [topicModalGroupId, setTopicModalGroupId] = useState<string | null>(null);
  const [editingTopicId, setEditingTopicId] = useState<string | null>(null);
  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicDescription, setNewTopicDescription] = useState('');

  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [sessionGroupName, setSessionGroupName] = useState<string | null>(null);
  const [isSessionMinimized, setIsSessionMinimized] = useState(false);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  const handleSelectGroup = (id: string) => {
    setIsAddingHub(false);
    setEditingGroup(null);
    setActiveGroupId(id);
    const selectedGroup = groups.find(g => g.id === id);

    if (selectedGroup && selectedGroup.type === GroupType.TOPICS && selectedGroup.topics.length > 0) {
      setActiveTopicId(selectedGroup.topics[0].id);
    } else {
      setActiveTopicId(null);
    }

    setIsMobileMenuOpen(false);
  };

  const handleOpenTopicModal = (groupId: string, topic?: Topic) => {
    setTopicModalGroupId(groupId);
    if (topic) {
      setTopicModalMode('edit');
      setEditingTopicId(topic.id);
      setNewTopicName(topic.name);
      setNewTopicDescription(topic.description);
    } else {
      setTopicModalMode('create');
      setEditingTopicId(null);
      setNewTopicName('');
      setNewTopicDescription('');
    }
    setIsTopicModalOpen(true);
  };

  const handleCreateOrUpdateTopic = () => {
    if (!newTopicName.trim() || !topicModalGroupId) return;

    if (topicModalMode === 'create') {
      const newTopic: Topic = { 
        id: `t-${Date.now()}`, 
        name: newTopicName, 
        icon: '📂', 
        description: newTopicDescription, 
        messages: [], 
        resources: [] 
      };
      setGroups(prev => prev.map(g => g.id === topicModalGroupId ? { ...g, topics: [...g.topics, newTopic] } : g));
      if (activeGroupId === topicModalGroupId) {
        setActiveTopicId(newTopic.id);
      }
    } else if (editingTopicId) {
      setGroups(prev => prev.map(g => g.id === topicModalGroupId ? {
        ...g,
        topics: g.topics.map(t => t.id === editingTopicId ? { ...t, name: newTopicName, description: newTopicDescription } : t)
      } : g));
    }

    setIsTopicModalOpen(false);
    setNewTopicName('');
    setNewTopicDescription('');
    setTopicModalGroupId(null);
    setEditingTopicId(null);
  };

  const handleOpenVoice = (mode: 'voice' | 'video') => {
    const groupName = activeTopicId 
      ? activeGroup?.topics.find(t => t.id === activeTopicId)?.name || activeGroup?.name
      : activeGroup?.name;

    setSessionGroupName(groupName || 'Nexus Hub Session');
    setSessionMode(mode);
    setIsSessionMinimized(false);
  };

  const handleCreateGroup = (name: string, type: GroupType, avatar: string, description?: string, rules?: string) => {
    const defaultTopic: Topic = { id: `t-intro-${Date.now()}`, name: 'Welcome', description: 'Quick start guide.', icon: '✨', messages: [], resources: [] };
    const newGroup: Group = {
      id: `hub-${Date.now()}`,
      name,
      description,
      rules,
      type,
      topics: type === GroupType.TOPICS ? [defaultTopic] : [],
      messages: [],
      members: [MOCK_MEMBERS[0]],
      avatar,
      category: 'Community'
    };
    setGroups(prev => [...prev, newGroup]);
    setActiveGroupId(newGroup.id);
    setActiveTopicId(type === GroupType.TOPICS ? defaultTopic.id : null);
    setIsAddingHub(false);
  };

  const handleUpdateGroup = (name: string, type: GroupType, avatar: string, description?: string, rules?: string) => {
    if (!editingGroup) return;
    setGroups(prev => prev.map(g => g.id === editingGroup.id ? { ...g, name, type, avatar, description, rules } : g));
    setEditingGroup(null);
  };

  const handleAddMember = (groupId: string, name: string, role: GroupMember['role']) => {
    const newMember: GroupMember = {
      id: `mem-${Date.now()}`,
      name,
      role,
      avatar: `https://picsum.photos/80/80?u=${Date.now()}`,
      status: 'online'
    };
    setGroups(prev => prev.map(g => g.id === groupId ? { ...g, members: [...g.members, newMember] } : g));
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    const newMessage: Message = {
      id: `msg-${Date.now()}`,
      sender: 'You',
      text,
      timestamp: new Date(),
      avatar: MOCK_MEMBERS[0].avatar,
      attachment
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: [...t.messages, newMessage] } : t)
        };
      }
    }));
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#020617] text-slate-200 selection:bg-indigo-500/30">
      <div className={`fixed inset-y-0 left-0 z-50 transform lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <Sidebar 
          groups={groups} 
          activeGroupId={activeGroupId || ''} 
          activeTopicId={activeTopicId}
          onSelectGroup={handleSelectGroup}
          onSelectTopic={(id) => { setIsAddingHub(false); setEditingGroup(null); setActiveTopicId(id); setIsMobileMenuOpen(false); }}
          onStartAddingHub={() => { setIsAddingHub(true); setEditingGroup(null); setIsMobileMenuOpen(false); }}
          onResetPortal={() => { setActiveGroupId(null); setActiveTopicId(null); setIsAddingHub(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
          onAddTopic={handleOpenTopicModal}
          onJoinVoice={handleOpenVoice}
          isOpen={isMobileMenuOpen}
          onClose={() => setIsMobileMenuOpen(false)}
        />
      </div>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <main className="flex-1 flex flex-col min-w-0 h-full relative">
        {isAddingHub ? (
          <HubCreationScreen 
            onCreate={handleCreateGroup} 
            onCancel={() => setIsAddingHub(false)} 
          />
        ) : editingGroup ? (
          <HubCreationScreen 
            initialData={editingGroup}
            onCreate={handleUpdateGroup} 
            onCancel={() => setEditingGroup(null)} 
          />
        ) : activeGroup ? (
          activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              groupDescription={activeGroup.description}
              groupRules={activeGroup.rules}
              onSendMessage={(text, att) => handleSendMessage(null, text, att)}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
              onEditHub={() => setEditingGroup(activeGroup)}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              activeTopicId={activeTopicId}
              onSelectTopic={setActiveTopicId}
              onOpenVoice={handleOpenVoice}
              onSendMessage={handleSendMessage}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onUploadResource={(topicId, res) => {
                 setGroups(prev => prev.map(g => g.id === activeGroupId ? {
                   ...g,
                   topics: g.topics.map(t => t.id === topicId ? { ...t, resources: [...t.resources, { ...res, id: Date.now().toString(), uploadedBy: 'You', date: new Date() }] } : t)
                 } : g));
              }}
              onStartAddingTopic={() => handleOpenTopicModal(activeGroup.id)}
              onEditTopic={(topic) => handleOpenTopicModal(activeGroup.id, topic)}
              onEditHub={() => setEditingGroup(activeGroup)}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          )
        ) : (
          <StartupScreen 
            groups={groups} 
            onSelectHub={handleSelectGroup} 
            onInitializeHub={() => setIsAddingHub(true)} 
          />
        )}

        {isTopicModalOpen && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/90 backdrop-blur-md" onClick={() => setIsTopicModalOpen(false)} />
            <div className="relative w-full max-w-sm bg-slate-950 border border-slate-900 rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
              <h2 className="text-xl font-black mb-6 text-white text-center italic uppercase tracking-tighter">
                {topicModalMode === 'create' ? 'Register Module' : 'Configure Module'}
              </h2>
              <div className="space-y-4">
                <input 
                  type="text" 
                  value={newTopicName} 
                  onChange={(e) => setNewTopicName(e.target.value)} 
                  className="w-full bg-slate-900/50 border border-slate-800 rounded-xl p-4 text-[13px] text-white font-black uppercase tracking-tighter outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700" 
                  placeholder="Designation Code..." 
                  autoFocus
                />
                <textarea
                  value={newTopicDescription}
                  onChange={(e) => setNewTopicDescription(e.target.value)}
                  className="w-full bg-slate-900/50 border border-slate-800 rounded-xl p-4 text-[13px] text-white font-black uppercase tracking-tighter outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700 resize-none h-24"
                  placeholder="Mission Objectives / Description..."
                />
                <div className="flex gap-3">
                  <button onClick={() => setIsTopicModalOpen(false)} className="flex-1 py-4 bg-slate-900 text-slate-600 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-colors hover:text-white">Abort</button>
                  <button onClick={handleCreateOrUpdateTopic} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Authorize</button>
                </div>
              </div>
            </div>
          </div>
        )}

        {sessionMode && (
          <div className={`fixed z-[100] transition-all duration-500 ease-in-out ${
            isSessionMinimized 
              ? 'bottom-6 right-6 w-[320px] max-w-[90vw] h-auto pointer-events-auto' 
              : 'inset-0 flex items-center justify-center p-2 sm:p-4 bg-[#020617]/80 backdrop-blur-xl pointer-events-auto'
          }`}>
            <MeetingSession 
              mode={sessionMode}
              isMinimized={isSessionMinimized}
              onMinimize={() => setIsSessionMinimized(!isSessionMinimized)}
              onClose={() => { setSessionMode(null); setSessionGroupName(null); }} 
              groupName={sessionGroupName || 'Active Session'} 
            />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

