import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onStartAddingTopic: () => void;
  onEditTopic: (topic: Topic) => void;
  onEditHub: () => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onAddMember,
  onUploadResource,
  onStartAddingTopic,
  onEditTopic,
  onEditHub,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel')) return '📊';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-600 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-[#020617] relative overflow-hidden">
      {/* High-Density Module Explorer for Desktop */}
      <div className="w-52 bg-slate-950/40 border-r border-slate-900/50 hidden xl:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-3.5 border-b border-slate-900/50">
          <div className="font-black uppercase tracking-[0.3em] text-[8px] text-slate-600 italic">Core Modules</div>
        </div>
        <div className="px-2 py-3 space-y-0.5">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-2.5 rounded-xl flex items-center gap-2.5 transition-all duration-200 border ${
                activeTopicId === topic.id ? 'bg-indigo-600/5 text-indigo-400 border-indigo-500/20 shadow-md' : 'border-transparent text-slate-500 hover:text-slate-400'
              }`}
            >
              <span className="text-base">{topic.icon}</span>
              <span className="truncate flex-1 font-black text-[10px] tracking-tighter uppercase italic">{topic.name}</span>
            </button>
          ))}
          <button 
            onClick={onStartAddingTopic}
            className="w-full text-left p-2.5 rounded-xl flex items-center gap-2.5 text-slate-700 hover:text-slate-500 border border-dashed border-slate-900 mt-3 group transition-all"
          >
            <span className="text-base">➕</span>
            <span className="truncate flex-1 text-[9px] font-black uppercase tracking-widest">Register Module</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0 h-full">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-8 text-center animate-in fade-in duration-700 bg-slate-950/50">
             <div className="w-14 h-14 bg-slate-900/50 rounded-2xl flex items-center justify-center text-2xl mb-4 border border-slate-800 shadow-xl">📡</div>
             <h2 className="text-lg font-black text-white mb-2 italic tracking-tight uppercase">System Awaiting Input</h2>
             <button onClick={onToggleMenu} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest lg:hidden shadow-lg active:scale-95 transition-all">Browse Modules</button>
          </div>
        ) : (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            {/* Highly Compressed Context Switcher */}
            <div className="bg-slate-950/80 backdrop-blur-3xl border-b border-slate-900 p-2 md:p-3 flex flex-col md:flex-row items-center justify-between gap-3 z-10 shrink-0">
               <div className="flex items-center gap-2.5 w-full md:w-auto min-w-0">
                  <button onClick={onToggleMenu} className="p-2 bg-slate-900 rounded-lg lg:hidden text-slate-500 border border-slate-800/50 shrink-0">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" /></svg>
                  </button>
                  <div className="p-2 bg-slate-900 rounded-lg border border-slate-800 text-lg shadow-inner shrink-0">{activeTopic.icon}</div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-2">
                       <h2 className="text-[13px] font-black text-white leading-tight truncate uppercase italic tracking-tighter">{activeTopic.name}</h2>
                       <button onClick={() => onEditTopic(activeTopic)} className="p-1 text-slate-700 hover:text-indigo-400 transition-colors">
                         <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                       </button>
                    </div>
                    <div className="flex items-center gap-2 overflow-hidden">
                       <span className="text-[7px] text-indigo-500 font-black uppercase tracking-[0.3em] leading-none shrink-0">{group.name}</span>
                       {activeTopic.description && (
                         <>
                           <span className="w-0.5 h-0.5 rounded-full bg-slate-700 shrink-0"></span>
                           <span className="text-[7px] text-slate-500 font-bold uppercase tracking-widest truncate">{activeTopic.description}</span>
                         </>
                       )}
                    </div>
                  </div>
               </div>

               {/* Segment Switcher */}
               <div className="flex items-center gap-1 bg-slate-900/40 p-1 rounded-xl border border-slate-900/80 w-full md:w-auto shrink-0">
                  <button onClick={() => setViewMode('discussion')} className={`flex-1 md:flex-none px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Uplink</button>
                  <button onClick={() => setViewMode('resources')} className={`flex-1 md:flex-none px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Library</button>
                  <button onClick={() => setViewMode('members')} className={`flex-1 md:flex-none px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Nodes</button>
               </div>

               <div className="hidden md:flex items-center gap-2 shrink-0">
                 <button onClick={() => onOpenVoice('voice')} className="px-3.5 py-1.5 bg-slate-900/50 text-indigo-400 rounded-lg font-black text-[9px] uppercase tracking-widest border border-slate-800 transition-all hover:bg-slate-800">🔊 Voice</button>
                 <button onClick={() => onOpenVoice('video')} className="px-3.5 py-1.5 bg-indigo-600 text-white rounded-lg font-black text-[9px] uppercase tracking-widest border border-indigo-400 transition-all hover:bg-indigo-500 shadow-md">🎥 Video</button>
               </div>
            </div>

            <div className="flex-1 overflow-hidden">
              {viewMode === 'discussion' && (
                <ChatArea 
                  groupName={activeTopic.name} 
                  messages={activeTopic.messages} 
                  members={group.members} 
                  groupDescription={group.description}
                  groupRules={group.rules}
                  onSendMessage={(text, attachment) => onSendMessage(activeTopic.id, text, attachment)} 
                  onAddMember={onAddMember} 
                  onToggleMenu={onToggleMenu}
                  onEditHub={onEditHub}
                  headerContent={
                    <div className="flex md:hidden gap-1.5">
                      <button onClick={() => onOpenVoice('voice')} className="p-1.5 bg-slate-900 text-indigo-500 rounded-lg border border-slate-800/50"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z"/></svg></button>
                      <button onClick={() => onOpenVoice('video')} className="p-1.5 bg-indigo-600 text-white rounded-lg border border-indigo-500/50"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"/></svg></button>
                    </div>
                  }
                />
              )}
              {viewMode === 'resources' && (
                <div className="h-full overflow-y-auto p-4 md:p-8 bg-slate-950 custom-scrollbar overscroll-contain">
                   <div className="max-w-5xl mx-auto space-y-5">
                     <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" />
                        <button onClick={() => fileInputRef.current?.click()} className="bg-indigo-600/5 border border-dashed border-indigo-500/20 rounded-xl p-4 flex items-center justify-center gap-3 active:scale-95 transition-all">
                           <span className="text-xl">➕</span>
                           <span className="text-[10px] font-black text-white uppercase italic tracking-tighter">Inject Archive Node</span>
                        </button>
                        {activeTopic.resources.map(res => (
                          <div key={res.id} className="bg-slate-900/30 border border-slate-900/80 p-3.5 rounded-xl flex items-center gap-3.5 hover:bg-slate-900 transition-all shadow-lg group">
                             <div className="w-10 h-10 bg-slate-950 rounded-lg flex items-center justify-center text-xl border border-slate-800/40 shadow-inner group-hover:scale-110 transition-transform">{getFileIcon(res.type)}</div>
                             <div className="flex-1 min-w-0">
                                <h5 className="font-black text-white truncate text-[11px] tracking-tighter uppercase italic mb-0.5">{res.name}</h5>
                                <div className="flex items-center gap-1.5">
                                  <span className="text-[8px] text-slate-600 font-black uppercase tracking-widest">{res.size}</span>
                                  <span className="text-[7px] text-indigo-500/40 font-black uppercase">Archive</span>
                                </div>
                             </div>
                             <button className="p-2 bg-indigo-600/10 text-indigo-400 hover:bg-indigo-600 hover:text-white rounded-lg text-[9px] font-black uppercase tracking-widest transition-all">Get</button>
                          </div>
                        ))}
                      </div>
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-4 md:p-8 bg-slate-950 custom-scrollbar overscroll-contain">
                   <div className="max-w-4xl mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                      {group.members.map(member => (
                        <div key={member.id} className="bg-slate-900/30 border border-slate-900/80 p-3.5 rounded-xl flex items-center gap-3.5 hover:bg-slate-900 transition-all shadow-lg group">
                           <div className="relative">
                             <img src={member.avatar} className="w-9 h-9 rounded-lg object-cover border border-slate-800/50 group-hover:rotate-3 transition-transform" alt="" />
                             <div className={`absolute -bottom-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-slate-950 ${member.status === 'online' ? 'bg-emerald-500' : 'bg-slate-700'}`}></div>
                           </div>
                           <div className="flex-1 min-w-0">
                             <div className="font-black text-white text-[12px] truncate uppercase italic tracking-tighter leading-none mb-1.5">{member.name}</div>
                             <div className={`inline-flex px-1.5 py-0.5 rounded text-[7px] font-black uppercase tracking-[0.2em] border ${getRoleColor(member.role)}`}>{member.role}</div>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DashboardArea;

import React, { useState, useRef, useEffect } from 'react';
import { Message, Attachment, GroupMember } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
}

const ChatArea: React.FC<ChatAreaProps> = ({ groupName, messages, members, groupDescription, groupRules, onSendMessage, onAddMember, headerContent, onToggleMenu, onEditHub }) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Encrypted data packet: ${file.name}`, attachment);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {/* High-Density Header */}
      <header className="h-14 md:h-16 px-3.5 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
        <div className="flex items-center min-w-0">
          <button 
            onClick={onToggleMenu}
            className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M12.707 5.293a1 1 0 010 1.414L9.414 10l3.293 3.293a1 1 0 01-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" /></svg>
          </button>
          <div className="text-sm md:text-base font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
             <span className="text-indigo-600 opacity-60 font-black">#</span> {groupName}
          </div>
        </div>

        <div className="flex items-center gap-2">
          {headerContent}
          <button 
            onClick={() => setShowMembers(!showMembers)}
            className={`p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-hidden relative flex">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-3 md:p-6 space-y-2.5 md:space-y-4 custom-scrollbar overscroll-contain">
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-10">
              <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-xl mb-3 border border-slate-800">📡</div>
              <p className="text-[7px] font-black uppercase tracking-[0.5em] text-white">Signal Sync Active</p>
            </div>
          )}
          {messages.map((m) => {
            const isMe = m.sender === 'You';
            return (
              <div key={m.id} className={`flex items-start gap-2.5 ${isMe ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-1 duration-200`}>
                <img src={m.avatar} className="w-7 h-7 md:w-8 md:h-8 rounded-lg border border-slate-900 shadow-md shrink-0 object-cover" alt="" />
                <div className={`flex flex-col gap-0.5 max-w-[88%] md:max-w-[75%] ${isMe ? 'items-end' : ''}`}>
                  <div className="flex items-center gap-2 px-1 mb-0.5">
                    <span className="text-[8px] font-black text-indigo-500 uppercase tracking-tighter italic">{m.sender}</span>
                    <span className="text-[7px] text-slate-700 font-black">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>
                  <div className={`rounded-xl md:rounded-2xl px-3 py-2 md:px-4 md:py-3 shadow-xl border transition-all ${
                    isMe 
                      ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                      : 'bg-slate-900/80 border-slate-800 text-slate-200 rounded-tl-none'
                  }`}>
                    {m.attachment && (
                      <div className="mb-2 p-2 bg-black/30 rounded-lg flex items-center gap-2.5 border border-white/5">
                        <div className="p-1.5 bg-indigo-500/20 rounded-md text-indigo-400">
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="text-[10px] font-black truncate tracking-tighter">{m.attachment.name}</div>
                          <div className="text-[7px] opacity-40 font-black uppercase tracking-widest">{m.attachment.size}</div>
                        </div>
                      </div>
                    )}
                    <p className="text-[13px] md:text-[14px] leading-[1.35] whitespace-pre-wrap font-medium tracking-tight">{m.text}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Directory Sidebar transformed into Hub Intel */}
        {showMembers && (
          <div className="absolute inset-y-0 right-0 w-72 bg-slate-950/95 backdrop-blur-3xl border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
             <div className="h-14 px-4 border-b border-slate-900 flex items-center justify-between shrink-0">
                <span className="text-[8px] font-black uppercase text-indigo-500 tracking-[0.3em] italic">Hub Intelligence</span>
                <button onClick={() => setShowMembers(false)} className="p-1.5 text-slate-700">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>

             <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
               {/* Manifesto Section */}
               {(groupDescription || groupRules) && (
                 <div className="space-y-4">
                   {groupDescription && (
                     <div>
                       <div className="flex items-center justify-between mb-1.5">
                          <div className="text-[7px] font-black text-indigo-500 uppercase tracking-widest italic">Operational Briefing</div>
                          <button onClick={onEditHub} className="text-[7px] font-black text-slate-600 hover:text-white uppercase tracking-widest underline decoration-indigo-500/30">Manage Hub</button>
                       </div>
                       <div className="bg-slate-900/40 border border-slate-900 rounded-xl p-3 text-[10px] text-slate-400 font-medium leading-relaxed italic">
                         {groupDescription}
                       </div>
                     </div>
                   )}
                   {groupRules && (
                     <div>
                       <div className="text-[7px] font-black text-rose-500 uppercase tracking-widest mb-1.5 italic">Engagement Protocols</div>
                       <div className="bg-slate-900/40 border border-rose-500/10 rounded-xl p-3 text-[10px] text-slate-400 font-medium leading-relaxed">
                         {groupRules}
                       </div>
                     </div>
                   )}
                   <div className="h-[1px] bg-slate-900 w-full" />
                 </div>
               )}

               {/* Personnel Section */}
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[7px] font-black text-slate-700 uppercase mb-1.5 ml-1 tracking-[0.2em]">{status} • {filtered.length}</div>
                      <div className="space-y-0.5">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-2.5 p-1.5 rounded-lg hover:bg-slate-900 transition-all border border-transparent">
                            <div className="relative">
                              <img src={member.avatar} className="w-7 h-7 rounded-md object-cover border border-slate-800/50" alt="" />
                              {status === 'online' && <div className="absolute -bottom-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-emerald-500 border border-slate-950"></div>}
                            </div>
                            <div className="min-w-0">
                               <div className="text-[11px] font-black text-white truncate tracking-tighter uppercase italic">{member.name}</div>
                               <div className="text-[7px] text-slate-600 font-black uppercase tracking-widest leading-none">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      {/* Slim Input Area */}
      <div className="px-2 pb-2 md:px-6 md:pb-6 pt-1 bg-slate-950/95 border-t border-slate-900/50 shrink-0">
        <div className="max-w-4xl mx-auto flex items-end gap-2 md:gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="p-2.5 md:p-3 bg-slate-900/50 text-slate-600 rounded-xl border border-slate-800/50 active:scale-95 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </button>
          <div className="flex-1 relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              className="w-full bg-slate-900/40 border border-slate-800/80 rounded-xl md:rounded-2xl px-4 py-2.5 md:px-5 md:py-3.5 pr-10 md:pr-12 outline-none focus:border-indigo-500/50 transition-all resize-none max-h-24 min-h-[42px] md:min-h-[52px] text-[14px] text-slate-200 font-medium placeholder:text-slate-700 shadow-inner"
              rows={1}
            />
            <button 
              onClick={handleSend} 
              className="absolute right-1.5 bottom-1.5 md:right-2 md:bottom-2 bg-indigo-600 text-white p-1.5 md:p-2 rounded-lg md:rounded-xl disabled:opacity-5 transition-all active:scale-90 shadow-lg" 
              disabled={!input.trim()}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 md:h-4 md:w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

