                activeTopicId === topic.id 
                  ? 'bg-indigo-600/10 text-indigo-400 border-indigo-500/30 shadow-[0_0_20px_rgba(79,70,229,0.1)]' 
                  : 'border-transparent text-slate-500 hover:text-slate-400 hover:bg-slate-900/40'
              }`}
            >
              <span className={`text-lg transition-transform group-hover:scale-110 ${activeTopicId === topic.id ? 'opacity-100' : 'opacity-40'}`}>{topic.icon}</span>
              <div className="min-w-0 flex-1">
                <span className="block truncate font-black text-[10px] tracking-tight uppercase italic leading-none mb-0.5">{topic.name}</span>
                <span className="block text-[7px] text-slate-700 font-bold uppercase tracking-widest truncate">{topic.description || 'No objectives'}</span>
              </div>
            </button>
          ))}
          <button 
