            className="w-full text-left p-3 rounded-xl flex items-center gap-3 text-slate-700 hover:text-slate-500 border border-dashed border-slate-900 mt-4 group transition-all"
          >
            <span className="text-lg opacity-40">➕</span>
            <span className="truncate flex-1 text-[9px] font-black uppercase tracking-widest">Register Module</span>
          </button>
