import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onStartAddingTopic: () => void;
  onEditTopic: (topic: Topic) => void;
  onEditHub: () => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onAddMember,
  onUploadResource,
  onStartAddingTopic,
  onEditTopic,
  onEditHub,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel')) return '📊';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-600 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-slate-950 relative overflow-hidden">
      {/* High-Density Module Matrix - The Second View Column */}
      <div className="w-64 bg-slate-950/40 border-r border-slate-900/50 hidden lg:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-6 border-b border-slate-900/30 flex items-center justify-between">
          <div className="font-black uppercase tracking-[0.2em] text-[9px] text-slate-600 italic">Core Modules</div>
          <button 
            onClick={onStartAddingTopic}
            className="text-indigo-500 hover:text-white transition-colors p-1"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
          </button>
        </div>

        <div className="px-3 py-6 space-y-1.5">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-4 rounded-2xl flex items-center gap-4 transition-all duration-300 border group ${
                activeTopicId === topic.id 
                  ? 'bg-indigo-600/15 text-indigo-400 border-indigo-500/40 shadow-xl' 
                  : 'border-transparent text-slate-600 hover:text-slate-400 hover:bg-slate-900/60'
              }`}
            >
              <span className={`text-xl transition-transform group-hover:scale-110 ${activeTopicId === topic.id ? 'opacity-100' : 'opacity-40 grayscale'}`}>{topic.icon}</span>
              <div className="min-w-0 flex-1">
                <span className="block truncate font-black text-[12px] tracking-tight uppercase italic leading-none mb-1">{topic.name}</span>
                <span className="block text-[8px] text-slate-700 font-bold uppercase tracking-widest truncate">{topic.description || 'System Objectives'}</span>
              </div>
            </button>
          ))}

          <button 
            onClick={onStartAddingTopic}
            className="w-full text-left p-4 rounded-2xl flex items-center gap-4 text-slate-700 hover:text-slate-400 border border-dashed border-slate-900 mt-6 group transition-all hover:bg-slate-900/30"
          >
            <span className="text-xl opacity-40">➕</span>
            <span className="truncate flex-1 text-[10px] font-black uppercase tracking-widest">Register Module</span>
          </button>
        </div>

        <div className="mt-auto p-5 border-t border-slate-900/30 bg-slate-950/20">
           <div className="space-y-4">
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Active Nodes</span>
                 <span className="text-indigo-500">{group.members.length}</span>
              </div>
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Sync Status</span>
                 <span className="text-emerald-500 text-glow">STABLE</span>
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0 h-full relative">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-12 text-center animate-in fade-in duration-700">
             <div className="w-24 h-24 bg-slate-900/40 rounded-3xl flex items-center justify-center text-4xl mb-8 border border-slate-800 shadow-2xl">📡</div>
             <h2 className="text-3xl font-black text-white mb-4 italic tracking-tighter uppercase text-glow">System Idle</h2>
             <p className="text-slate-600 text-[10px] font-bold uppercase tracking-[0.5em] mb-12">Initialize module for uplink sequence</p>
             <button onClick={onToggleMenu} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-[0.4em] lg:hidden shadow-2xl active:scale-95 transition-all">Select Node</button>
          </div>
        ) : (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            {/* Header with Navigation Controls */}
            <div className="bg-slate-950/60 backdrop-blur-3xl border-b border-slate-900 px-6 py-4 flex flex-col md:flex-row items-center justify-between gap-6 z-10 shrink-0">
               <div className="flex items-center gap-5 w-full md:w-auto min-w-0">
                  <button onClick={onToggleMenu} className="p-3 bg-slate-900 rounded-2xl lg:hidden text-slate-500 border border-slate-800/50 shrink-0 shadow-lg">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
                  </button>
                  <div className="p-3.5 bg-slate-900 rounded-2xl border border-slate-800 text-2xl shadow-inner shrink-0">{activeTopic.icon}</div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-3 mb-1">
                       <h2 className="text-xl font-black text-white leading-tight truncate uppercase italic tracking-tighter">{activeTopic.name}</h2>
                       <button onClick={() => onEditTopic(activeTopic)} className="p-1.5 text-slate-700 hover:text-indigo-400 transition-colors bg-slate-900/40 rounded-xl border border-slate-800/40" title="Modify Module">
                         <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                       </button>
                    </div>
                    <div className="flex items-center gap-2 overflow-hidden">
                       <span className="text-[9px] text-indigo-500 font-black uppercase tracking-[0.3em] leading-none shrink-0">{group.name}</span>
                       {activeTopic.description && (
                         <>
                           <span className="w-1 h-1 rounded-full bg-slate-800 shrink-0"></span>
                           <span className="text-[8px] text-slate-600 font-bold uppercase tracking-widest truncate max-w-xs">{activeTopic.description}</span>
                         </>
                       )}
                    </div>
                  </div>
               </div>

               {/* Segment Hardware Switcher */}
               <div className="flex items-center gap-1.5 bg-slate-900/40 p-1.5 rounded-2xl border border-slate-800/50 w-full md:w-auto shrink-0 shadow-inner">
                  <button onClick={() => setViewMode('discussion')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-[10px] font-black tracking-[0.2em] uppercase transition-all duration-300 ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-600 hover:text-slate-400'}`}>Uplink</button>
                  <button onClick={() => setViewMode('resources')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-[10px] font-black tracking-[0.2em] uppercase transition-all duration-300 ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-600 hover:text-slate-400'}`}>Library</button>
                  <button onClick={() => setViewMode('members')} className={`flex-1 md:flex-none px-6 py-2.5 rounded-xl text-[10px] font-black tracking-[0.2em] uppercase transition-all duration-300 ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-600 hover:text-slate-400'}`}>Nodes</button>
               </div>

               {/* Action Buttons */}
               <div className="hidden md:flex items-center gap-3 shrink-0">
                 <button onClick={() => onOpenVoice('voice')} className="px-6 py-3 bg-slate-900 text-indigo-400 rounded-xl font-black text-[10px] uppercase tracking-widest border border-slate-800 transition-all hover:bg-indigo-600/10">🔊 Voice</button>
                 <button onClick={() => onOpenVoice('video')} className="px-6 py-3 bg-indigo-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest border border-indigo-400 shadow-2xl transition-all hover:bg-indigo-500">🎥 Video</button>
               </div>
            </div>

            <div className="flex-1 overflow-hidden">
              {viewMode === 'discussion' && (
                <ChatArea 
                  groupName={activeTopic.name} 
                  messages={activeTopic.messages} 
                  members={group.members} 
                  groupDescription={group.description}
                  groupRules={group.rules}
                  onSendMessage={(text, attachment) => onSendMessage(activeTopic.id, text, attachment)} 
                  onAddMember={onAddMember} 
                  onToggleMenu={onToggleMenu}
                  onEditHub={onEditHub}
                />
              )}
              {viewMode === 'resources' && (
                <div className="h-full overflow-y-auto p-10 bg-slate-950/40 custom-scrollbar">
                   <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                        <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" />
                        <button onClick={() => fileInputRef.current?.click()} className="aspect-square bg-indigo-600/5 border-2 border-dashed border-indigo-500/20 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 hover:bg-indigo-600/10 transition-all group">
                           <span className="text-4xl group-hover:scale-125 transition-transform duration-500">➕</span>
