                               <div className="text-[11px] font-black text-white truncate tracking-tighter uppercase italic">{member.name}</div>
                               <div className="text-[7px] text-slate-600 font-black uppercase tracking-widest leading-none">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
