import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  currentUser: GroupMember;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onReactToMessage: (topicId: string, messageId: string, emoji: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onStartAddingTopic: () => void;
  onEditTopic: (topic: Topic) => void;
  onEditHub: () => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  currentUser,
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onReactToMessage,
  onAddMember,
  onUploadResource,
  onStartAddingTopic,
  onEditTopic,
  onEditHub,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel')) return '📊';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-600 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-slate-950 relative overflow-hidden">
      {/* High-Density Module Matrix - Tablet and Desktop Sidebar */}
      <div className="w-64 bg-slate-950/40 border-r border-slate-900/50 hidden lg:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-6 border-b border-slate-900/30 flex items-center justify-between">
          <div className="font-black uppercase tracking-[0.2em] text-[9px] text-slate-600 italic">Core Modules</div>
          <button 
            onClick={onStartAddingTopic}
            className="text-indigo-500 hover:text-white transition-colors p-1"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
          </button>
        </div>

        <div className="px-3 py-6 space-y-1.5">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-4 rounded-2xl flex items-center transition-all duration-300 border group ${
                activeTopicId === topic.id 
                  ? 'bg-indigo-600/15 text-indigo-400 border-indigo-500/40 shadow-xl' 
                  : 'border-transparent text-slate-600 hover:text-slate-400 hover:bg-slate-900/60'
              }`}
            >
              <div className="min-w-0 flex-1">
                <span className="block truncate font-black text-[11px] tracking-tight uppercase italic leading-none mb-1.5 group-hover:tracking-wider transition-all duration-500">{topic.name}</span>
                <span className="block text-[8px] text-slate-700 font-bold uppercase tracking-widest truncate">{topic.description || 'Primary Objective'}</span>
              </div>
            </button>
          ))}

          <button 
            onClick={onStartAddingTopic}
            className="w-full text-left p-4 rounded-2xl flex items-center gap-4 text-slate-700 hover:text-slate-400 border border-dashed border-slate-900 mt-6 group transition-all hover:bg-slate-900/30"
          >
            <span className="text-xl opacity-40">➕</span>
            <span className="truncate flex-1 text-[10px] font-black uppercase tracking-widest">Register Module</span>
          </button>
        </div>

        <div className="mt-auto p-5 border-t border-slate-900/30 bg-slate-950/20">
           <div className="space-y-4">
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Active Nodes</span>
                 <span className="text-indigo-500">{group.members.length}</span>
              </div>
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Sync Status</span>
                 <span className="text-emerald-500 text-glow">STABLE</span>
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0 h-full relative">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-12 text-center animate-in fade-in duration-700">
