                  <button onClick={() => setViewMode('members')} className={`flex-1 px-4 py-2 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all duration-300 ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Nodes</button>
