                  groupName={activeTopic.name} 
                  messages={activeTopic.messages} 
                  members={group.members} 
                  currentUser={currentUser.name}
                  groupDescription={group.description}
                  groupRules={group.rules}
                  onSendMessage={(text, attachment) => onSendMessage(activeTopic.id, text, attachment)} 
                  onReactToMessage={(messageId, emoji) => onReactToMessage(activeTopic.id, messageId, emoji)}
                  onAddMember={onAddMember} 
                  onToggleMenu={onToggleMenu}
                  onEditHub={onEditHub}
                  hideHeader={true}
                />
              )}
              {viewMode === 'resources' && (
                <div className="h-full overflow-y-auto p-6 md:p-10 bg-slate-950/40 custom-scrollbar">
                   <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                        <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" />
                        <button onClick={() => fileInputRef.current?.click()} className="aspect-square bg-indigo-600/5 border-2 border-dashed border-indigo-500/20 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 hover:bg-indigo-600/10 transition-all group">
                           <span className="text-4xl group-hover:scale-125 transition-transform duration-500">➕</span>
                           <div className="text-center">
                              <span className="block text-[12px] font-black text-white uppercase italic tracking-tighter">Inject Archive</span>
                              <span className="block text-[8px] text-slate-700 font-bold uppercase tracking-widest mt-1">Maximum Linkage</span>
                           </div>
                        </button>
                        {activeTopic.resources.map(res => (
                          <div key={res.id} className="bg-slate-900/50 border border-slate-800/80 p-6 rounded-[2.5rem] flex flex-col justify-between hover:bg-slate-900 transition-all shadow-2xl group relative overflow-hidden">
                             <div className="flex items-center gap-5 mb-8">
                               <div className="w-14 h-14 bg-slate-950 rounded-2xl flex items-center justify-center text-3xl border border-slate-800/50 shadow-inner">{getFileIcon(res.type)}</div>
                               <div className="min-w-0 flex-1">
                                  <h5 className="font-black text-white truncate text-sm tracking-tighter uppercase italic mb-1">{res.name}</h5>
                                  <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest">{res.size} • Secured</span>
                               </div>
                             </div>
                             <div className="flex items-center justify-between pt-6 border-t border-slate-800/40">
                                <button className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-xl active:scale-95">Download</button>
                             </div>
                          </div>
                        ))}
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-6 md:p-10 bg-slate-950/40 custom-scrollbar">
                   <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                      {group.members.map(member => (
                        <div key={member.id} className="bg-slate-900/50 border border-slate-800/80 p-6 rounded-[2.5rem] flex items-center gap-5 hover:bg-slate-900 transition-all shadow-2xl group">
                           <div className="relative shrink-0">
                             <img src={member.avatar} className="w-14 h-14 rounded-2xl object-cover border-2 border-slate-800 shadow-xl" alt="" />
                             <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-4 border-slate-950 ${member.status === 'online' ? 'bg-emerald-500 pulse-indicator' : 'bg-slate-800'}`}></div>
                           </div>
                           <div className="flex-1 min-w-0">
                             <div className="font-black text-white text-sm truncate uppercase italic tracking-tighter leading-none mb-2">{member.name}</div>
                             <div className={`inline-flex px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest border ${getRoleColor(member.role)}`}>{member.role}</div>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

