  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {!hideHeader && (
        <header className="h-14 md:h-16 px-3.5 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button 
              onClick={onToggleMenu}
              className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
            </button>
            <div className="text-sm md:text-base font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60 font-black">#</span> {groupName}
            </div>
          </div>

          <div className="flex items-center gap-1.5 md:gap-3">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🔊</span>
                </button>
                <button onClick={() => onOpenVoice('video')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🎥</span>
                </button>
              </div>
