                          >
                            {emoji}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Reactions List */}
                  {hasReactions && (
                    <div className={`flex flex-wrap gap-1.5 mt-1.5 ${isMe ? 'justify-end' : 'justify-start'}`}>
                      {Object.entries(m.reactions!).map(([emoji, users]) => {
                        // Cast 'users' to 'string[]' to fix 'unknown' type error for 'includes' and 'length'
                        const usersList = users as string[];
                        const hasUserReacted = usersList.includes(currentUser);
                        return (
                          <button 
                            key={emoji}
                            onClick={(e) => {
                              e.stopPropagation();
                              onReactToMessage(m.id, emoji);
                            }}
                            className={`flex items-center gap-1.5 px-2 py-0.5 rounded-full border text-[10px] font-black transition-all ${
                              hasUserReacted 
                                ? 'bg-indigo-600/20 border-indigo-500/50 text-indigo-400' 
                                : 'bg-slate-900/50 border-slate-800 text-slate-500 hover:border-slate-700'
                            }`}
                          >
                            <span>{emoji}</span>
                            <span>{usersList.length}</span>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {!hideHeader && showMembers && (
          <div className="absolute inset-y-0 right-0 w-72 bg-slate-950/95 backdrop-blur-3xl border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
             <div className="h-14 px-4 border-b border-slate-900 flex items-center justify-between shrink-0">
                <span className="text-[8px] font-black uppercase text-indigo-500 tracking-[0.3em] italic">Hub Intelligence</span>
                <button onClick={() => setShowMembers(false)} className="p-1.5 text-slate-700">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[7px] font-black text-slate-700 uppercase mb-1.5 ml-1 tracking-[0.2em]">{status} • {filtered.length}</div>
                      <div className="space-y-0.5">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-2.5 p-1.5 rounded-lg hover:bg-slate-900 transition-all border border-transparent">
                            <div className="relative">
                              <img src={member.avatar} className="w-7 h-7 rounded-md object-cover border border-slate-800/50" alt="" />
                              {status === 'online' && <div className="absolute -bottom-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-emerald-500 border border-slate-950"></div>}
                            </div>
                            <div className="min-w-0">
                               <div className="text-[11px] font-black text-white truncate tracking-tighter uppercase italic">{member.name}</div>
                               <div className="text-[7px] text-slate-600 font-black uppercase tracking-widest leading-none">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      <div className="px-2 pb-2 md:px-6 md:pb-6 pt-1 bg-slate-950/95 border-t border-slate-900/50 shrink-0">
        <div className="max-w-4xl mx-auto flex items-end gap-2 md:gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />
          <button onClick={() => fileInputRef.current?.click()} className="p-2.5 md:p-3 bg-slate-900/50 text-slate-600 rounded-xl border border-slate-800/50 active:scale-95 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </button>
          <div className="flex-1 relative">
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              className="w-full bg-slate-900/40 border border-slate-800/80 rounded-xl md:rounded-2xl px-4 py-2.5 md:px-5 md:py-3.5 pr-10 md:pr-12 outline-none focus:border-indigo-500/50 transition-all resize-none max-h-24 min-h-[42px] md:min-h-[52px] text-[14px] text-slate-200 font-medium placeholder:text-slate-700 shadow-inner"
              rows={1}
            />
            <button 
              onClick={handleSend} 
              className="absolute right-1.5 bottom-1.5 md:right-2 md:bottom-2 bg-indigo-600 text-white p-1.5 md:p-2 rounded-lg md:rounded-xl disabled:opacity-5 transition-all active:scale-90 shadow-lg" 
              disabled={!input.trim()}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 md:h-4 md:w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect } from 'react';
import { Message, Attachment, GroupMember } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '🙌', '🎉', '💡', '🤔', '👀', '✅'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  groupDescription, 
  groupRules, 
  onSendMessage, 
  onReactToMessage,
  onAddMember, 
  headerContent, 
  onToggleMenu, 
  onEditHub,
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Encrypted data packet: ${file.name}`, attachment);
    }
  };

  const addEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
  };

  const startCamera = async () => {
    setIsCameraLoading(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' }, audio: false });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
    } catch (err) {
      console.error("Camera access denied:", err);
      alert("Please grant camera permissions to capture data.");
    } finally {
      setIsCameraLoading(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');

        const attachment: Attachment = {
          name: `captured_frame_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Data',
          url: dataUrl
        };

        onSendMessage("Captured visual signature.", attachment);
        stopCamera();
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {!hideHeader && (
        <header className="h-14 md:h-16 px-3.5 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button 
              onClick={onToggleMenu}
              className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
            </button>
            <div className="text-sm md:text-base font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60 font-black">#</span> {groupName}
            </div>
          </div>

          <div className="flex items-center gap-1.5 md:gap-3">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🔊</span>
                </button>
                <button onClick={() => onOpenVoice('video')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🎥</span>
                </button>
              </div>
            )}
            {headerContent}
            <button 
              onClick={() => setShowMembers(!showMembers)}
              className={`p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      <div className="flex-1 overflow-hidden relative flex">
        <div 
          ref={scrollRef} 
          className="flex-1 overflow-y-auto p-3 md:p-6 space-y-4 md:space-y-6 custom-scrollbar overscroll-contain"
          onClick={() => {
            setActiveReactionPicker(null);
            setShowEmojiPicker(false);
          }}
        >
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-10">
              <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-xl mb-3 border border-slate-800">📡</div>
              <p className="text-[7px] font-black uppercase tracking-[0.5em] text-white">Signal Sync Active</p>
            </div>
          )}
          {messages.map((m) => {
            const isMe = m.sender === currentUser;
            const hasReactions = m.reactions && Object.keys(m.reactions).length > 0;

            return (
              <div key={m.id} className={`flex items-start gap-2.5 ${isMe ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-1 duration-200 group`}>
                <img src={m.avatar} className="w-7 h-7 md:w-8 md:h-8 rounded-lg border border-slate-900 shadow-md shrink-0 object-cover" alt="" />

                <div className={`flex flex-col gap-1 max-w-[88%] md:max-w-[75%] ${isMe ? 'items-end' : ''} relative`}>
                  <div className="flex items-center gap-2 px-1 mb-0.5">
                    <span className="text-[8px] font-black text-indigo-500 uppercase tracking-tighter italic">{m.sender}</span>
                    <span className="text-[7px] text-slate-700 font-black">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>

                  <div className="relative group/msg">
                    <div className={`rounded-xl md:rounded-2xl px-3 py-2 md:px-4 md:py-3 shadow-xl border transition-all ${
                      isMe 
                        ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                        : 'bg-slate-900/80 border-slate-800 text-slate-200 rounded-tl-none'
                    }`}>
                      {m.attachment && (
                        <div className="mb-2 bg-black/30 rounded-lg overflow-hidden border border-white/5">
                          {m.attachment.url && m.attachment.type.startsWith('image/') ? (
                            <img src={m.attachment.url} className="w-full h-auto max-h-64 object-cover" alt="attachment" />
                          ) : (
                            <div className="p-2 flex items-center gap-2.5">
                              <div className="p-1.5 bg-indigo-500/20 rounded-md text-indigo-400">
                                 <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                              </div>
                              <div className="flex-1 min-w-0">
                                <div className="text-[10px] font-black truncate tracking-tighter">{m.attachment.name}</div>
                                <div className="text-[7px] opacity-40 font-black uppercase tracking-widest">{m.attachment.size}</div>
                              </div>
                            </div>
                          )}
                        </div>
                      )}
                      <p className="text-[13px] md:text-[14px] leading-[1.35] whitespace-pre-wrap font-medium tracking-tight">{m.text}</p>
                    </div>

                    {/* Quick Reaction Button */}
                    <button 
                      onClick={(e) => {
                        e.stopPropagation();
                        setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id);
                      }}
                      className={`absolute top-0 ${isMe ? '-left-8' : '-right-8'} p-1.5 bg-slate-900/90 border border-slate-800 rounded-lg text-slate-500 opacity-0 group-hover/msg:opacity-100 transition-all hover:text-white z-10`}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </button>

                    {/* Reaction Picker Popover */}
                    {activeReactionPicker === m.id && (
                      <div 
                        className={`absolute -top-12 ${isMe ? 'right-0' : 'left-0'} bg-slate-950 border border-slate-800 p-1.5 rounded-2xl shadow-2xl flex items-center gap-1 z-30 animate-in fade-in zoom-in-90 duration-150`}
                        onClick={e => e.stopPropagation()}
                      >
                        {COMMON_EMOJIS.slice(0, 8).map(emoji => (
                          <button 
                            key={emoji} 
                            onClick={() => {
                              onReactToMessage(m.id, emoji);
                              setActiveReactionPicker(null);
                            }}
                            className="w-8 h-8 flex items-center justify-center hover:bg-slate-800 rounded-xl transition-all hover:scale-125 text-lg"
                          >
                            {emoji}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Reactions List */}
                  {hasReactions && (
                    <div className={`flex flex-wrap gap-1.5 mt-1.5 ${isMe ? 'justify-end' : 'justify-start'}`}>
                      {Object.entries(m.reactions!).map(([emoji, users]) => {
                        const usersList = users as string[];
                        const hasUserReacted = usersList.includes(currentUser);
                        return (
                          <button 
                            key={emoji}
                            onClick={(e) => {
                              e.stopPropagation();
                              onReactToMessage(m.id, emoji);
                            }}
                            className={`flex items-center gap-1.5 px-2 py-0.5 rounded-full border text-[10px] font-black transition-all ${
                              hasUserReacted 
                                ? 'bg-indigo-600/20 border-indigo-500/50 text-indigo-400' 
                                : 'bg-slate-900/50 border-slate-800 text-slate-500 hover:border-slate-700'
                            }`}
                          >
                            <span>{emoji}</span>
                            <span>{usersList.length}</span>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {!hideHeader && showMembers && (
          <div className="absolute inset-y-0 right-0 w-72 bg-slate-950/95 backdrop-blur-3xl border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
             <div className="h-14 px-4 border-b border-slate-900 flex items-center justify-between shrink-0">
                <span className="text-[8px] font-black uppercase text-indigo-500 tracking-[0.3em] italic">Hub Intelligence</span>
                <button onClick={() => setShowMembers(false)} className="p-1.5 text-slate-700">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[7px] font-black text-slate-700 uppercase mb-1.5 ml-1 tracking-[0.2em]">{status} • {filtered.length}</div>
                      <div className="space-y-0.5">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-2.5 p-1.5 rounded-lg hover:bg-slate-900 transition-all border border-transparent">
                            <div className="relative">
                              <img src={member.avatar} className="w-7 h-7 rounded-md object-cover border border-slate-800/50" alt="" />
                              {status === 'online' && <div className="absolute -bottom-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-emerald-500 border border-slate-950"></div>}
                            </div>
                            <div className="min-w-0">
                               <div className="text-[11px] font-black text-white truncate tracking-tighter uppercase italic">{member.name}</div>
                               <div className="text-[7px] text-slate-600 font-black uppercase tracking-widest leading-none">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      {/* Camera Capture Modal */}
      {showCamera && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
          <div className="relative w-full max-w-lg bg-slate-900 rounded-[2rem] border border-slate-800 overflow-hidden shadow-2xl flex flex-col">
            <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-950/50">
               <span className="text-[10px] font-black text-white uppercase tracking-widest italic">Visual Capture Hub</span>
               <button onClick={stopCamera} className="p-2 text-slate-500 hover:text-white transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
               </button>
            </div>
            <div className="relative aspect-video bg-black flex items-center justify-center">
              <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover mirror" />
              <div className="absolute inset-0 pointer-events-none border-2 border-indigo-500/20 m-6 rounded-2xl"></div>
            </div>
            <div className="p-6 flex justify-center gap-4">
               <button 
                 onClick={capturePhoto}
                 className="w-16 h-16 rounded-full bg-white border-4 border-slate-300 shadow-2xl active:scale-90 transition-transform flex items-center justify-center"
               >
                 <div className="w-10 h-10 rounded-full bg-indigo-600"></div>
               </button>
            </div>
            <canvas ref={canvasRef} className="hidden" />
          </div>
        </div>
      )}

      <div className="px-2 pb-2 md:px-6 md:pb-6 pt-1 bg-slate-950/95 border-t border-slate-900/50 shrink-0">
        <div className="max-w-4xl mx-auto flex items-end gap-2 md:gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

          <div className="flex gap-1.5 md:gap-2">
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="p-2.5 md:p-3 bg-slate-900/50 text-slate-600 hover:text-indigo-400 rounded-xl border border-slate-800/50 active:scale-95 transition-all"
              title="Add Attachment"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
            </button>
            <button 
              onClick={startCamera}
              disabled={isCameraLoading}
              className={`p-2.5 md:p-3 bg-slate-900/50 text-slate-600 hover:text-indigo-400 rounded-xl border border-slate-800/50 active:scale-95 transition-all ${isCameraLoading ? 'animate-pulse' : ''}`}
              title="Capture Image"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </button>
          </div>

          <div className="flex-1 relative">
            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[300px] bg-slate-950 border border-slate-800 rounded-2xl p-3 shadow-2xl grid grid-cols-6 gap-1 animate-in slide-in-from-bottom-2 duration-200">
                {COMMON_EMOJIS.map(emoji => (
                  <button 
                    key={emoji} 
                    onClick={() => addEmoji(emoji)}
                    className="w-10 h-10 flex items-center justify-center hover:bg-slate-800 rounded-xl transition-all text-xl"
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            )}

            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              className="w-full bg-slate-900/40 border border-slate-800/80 rounded-xl md:rounded-2xl px-4 py-2.5 md:px-5 md:py-3.5 pr-10 md:pr-20 outline-none focus:border-indigo-500/50 transition-all resize-none max-h-24 min-h-[42px] md:min-h-[52px] text-[14px] text-slate-200 font-medium placeholder:text-slate-700 shadow-inner"
              rows={1}
            />

            <div className="absolute right-1.5 bottom-1.5 md:right-2 md:bottom-2 flex items-center gap-1.5 md:gap-2">
              <button 
                onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                className={`p-1.5 md:p-2 rounded-lg md:rounded-xl transition-all ${showEmojiPicker ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:text-slate-400'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </button>
              <button 
                onClick={handleSend} 
                className="bg-indigo-600 text-white p-1.5 md:p-2 rounded-lg md:rounded-xl disabled:opacity-5 transition-all active:scale-90 shadow-lg" 
                disabled={!input.trim()}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 md:h-4 md:w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect } from 'react';
import { Message, Attachment, GroupMember } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '🙌', '🎉', '💡', '🤔', '👀', '✅'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  groupDescription, 
  groupRules, 
  onSendMessage, 
  onReactToMessage,
  onAddMember, 
  headerContent, 
  onToggleMenu, 
  onEditHub,
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Encrypted data packet: ${file.name}`, attachment);
    }
  };

  const addEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    // If there's an existing stream, stop it first
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
      alert("Please grant camera permissions to capture data.");
    } finally {
      setIsCameraLoading(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        // Handle mirroring in canvas if needed
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }

        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');

        const attachment: Attachment = {
          name: `captured_frame_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Data',
          url: dataUrl
        };

        onSendMessage("Captured visual signature.", attachment);
        stopCamera();
      }
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {!hideHeader && (
        <header className="h-14 md:h-16 px-3.5 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button 
              onClick={onToggleMenu}
              className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
            </button>
            <div className="text-sm md:text-base font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60 font-black">#</span> {groupName}
            </div>
          </div>

          <div className="flex items-center gap-1.5 md:gap-3">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🔊</span>
                </button>
                <button onClick={() => onOpenVoice('video')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🎥</span>
                </button>
              </div>
            )}
            {headerContent}
            <button 
              onClick={() => setShowMembers(!showMembers)}
              className={`p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      <div className="flex-1 overflow-hidden relative flex">
        <div 
          ref={scrollRef} 
          className="flex-1 overflow-y-auto p-3 md:p-6 space-y-4 md:space-y-6 custom-scrollbar overscroll-contain"
          onClick={() => {
            setActiveReactionPicker(null);
            setShowEmojiPicker(false);
          }}
        >
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-10">
              <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-xl mb-3 border border-slate-800">📡</div>
              <p className="text-[7px] font-black uppercase tracking-[0.5em] text-white">Signal Sync Active</p>
            </div>
          )}
          {messages.map((m) => {
            const isMe = m.sender === currentUser;
            const hasReactions = m.reactions && Object.keys(m.reactions).length > 0;

            return (
              <div key={m.id} className={`flex items-start gap-2.5 ${isMe ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-1 duration-200 group`}>
                <img src={m.avatar} className="w-7 h-7 md:w-8 md:h-8 rounded-lg border border-slate-900 shadow-md shrink-0 object-cover" alt="" />

                <div className={`flex flex-col gap-1 max-w-[88%] md:max-w-[75%] ${isMe ? 'items-end' : ''} relative`}>
                  <div className="flex items-center gap-2 px-1 mb-0.5">
                    <span className="text-[8px] font-black text-indigo-500 uppercase tracking-tighter italic">{m.sender}</span>
                    <span className="text-[7px] text-slate-700 font-black">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>

                  <div className="relative group/msg">
                    <div className={`rounded-xl md:rounded-2xl px-3 py-2 md:px-4 md:py-3 shadow-xl border transition-all ${
                      isMe 
                        ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                        : 'bg-slate-900/80 border-slate-800 text-slate-200 rounded-tl-none'
                    }`}>
                      {m.attachment && (
                        <div className="mb-2 bg-black/30 rounded-lg overflow-hidden border border-white/5">
                          {m.attachment.url && m.attachment.type.startsWith('image/') ? (
                            <img src={m.attachment.url} className="w-full h-auto max-h-64 object-cover" alt="attachment" />
                          ) : (
                            <div className="p-2 flex items-center gap-2.5">
                              <div className="p-1.5 bg-indigo-500/20 rounded-md text-indigo-400">
                                 <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                              </div>
                              <div className="flex-1 min-w-0">
                                <div className="text-[10px] font-black truncate tracking-tighter">{m.attachment.name}</div>
                                <div className="text-[7px] opacity-40 font-black uppercase tracking-widest">{m.attachment.size}</div>
                              </div>
                            </div>
                          )}
                        </div>
                      )}
                      <p className="text-[13px] md:text-[14px] leading-[1.35] whitespace-pre-wrap font-medium tracking-tight">{m.text}</p>
                    </div>

                    {/* Quick Reaction Button */}
                    <button 
                      onClick={(e) => {
                        e.stopPropagation();
                        setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id);
                      }}
                      className={`absolute top-0 ${isMe ? '-left-8' : '-right-8'} p-1.5 bg-slate-900/90 border border-slate-800 rounded-lg text-slate-500 opacity-0 group-hover/msg:opacity-100 transition-all hover:text-white z-10`}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                    </button>

                    {/* Reaction Picker Popover */}
                    {activeReactionPicker === m.id && (
                      <div 
                        className={`absolute -top-12 ${isMe ? 'right-0' : 'left-0'} bg-slate-950 border border-slate-800 p-1.5 rounded-2xl shadow-2xl flex items-center gap-1 z-30 animate-in fade-in zoom-in-90 duration-150`}
                        onClick={e => e.stopPropagation()}
                      >
                        {COMMON_EMOJIS.slice(0, 8).map(emoji => (
                          <button 
                            key={emoji} 
                            onClick={() => {
                              onReactToMessage(m.id, emoji);
                              setActiveReactionPicker(null);
                            }}
                            className="w-8 h-8 flex items-center justify-center hover:bg-slate-800 rounded-xl transition-all hover:scale-125 text-lg"
                          >
                            {emoji}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Reactions List */}
                  {hasReactions && (
                    <div className={`flex flex-wrap gap-1.5 mt-1.5 ${isMe ? 'justify-end' : 'justify-start'}`}>
                      {Object.entries(m.reactions!).map(([emoji, users]) => {
                        const usersList = users as string[];
                        const hasUserReacted = usersList.includes(currentUser);
                        return (
                          <button 
                            key={emoji}
                            onClick={(e) => {
                              e.stopPropagation();
                              onReactToMessage(m.id, emoji);
                            }}
                            className={`flex items-center gap-1.5 px-2 py-0.5 rounded-full border text-[10px] font-black transition-all ${
                              hasUserReacted 
                                ? 'bg-indigo-600/20 border-indigo-500/50 text-indigo-400' 
                                : 'bg-slate-900/50 border-slate-800 text-slate-500 hover:border-slate-700'
                            }`}
                          >
                            <span>{emoji}</span>
                            <span>{usersList.length}</span>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {!hideHeader && showMembers && (
          <div className="absolute inset-y-0 right-0 w-72 bg-slate-950/95 backdrop-blur-3xl border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
             <div className="h-14 px-4 border-b border-slate-900 flex items-center justify-between shrink-0">
                <span className="text-[8px] font-black uppercase text-indigo-500 tracking-[0.3em] italic">Hub Intelligence</span>
                <button onClick={() => setShowMembers(false)} className="p-1.5 text-slate-700">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[7px] font-black text-slate-700 uppercase mb-1.5 ml-1 tracking-[0.2em]">{status} • {filtered.length}</div>
                      <div className="space-y-0.5">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-2.5 p-1.5 rounded-lg hover:bg-slate-900 transition-all border border-transparent">
                            <div className="relative">
                              <img src={member.avatar} className="w-7 h-7 rounded-md object-cover border border-slate-800/50" alt="" />
                              {status === 'online' && <div className="absolute -bottom-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-emerald-500 border border-slate-950"></div>}
                            </div>
                            <div className="min-w-0">
                               <div className="text-[11px] font-black text-white truncate tracking-tighter uppercase italic">{member.name}</div>
                               <div className="text-[7px] text-slate-600 font-black uppercase tracking-widest leading-none">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      {/* Camera Capture Modal */}
      {showCamera && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
          <div className="relative w-full max-w-lg bg-slate-900 rounded-[2rem] border border-slate-800 overflow-hidden shadow-2xl flex flex-col">
            <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-950/50">
               <span className="text-[10px] font-black text-white uppercase tracking-widest italic">Visual Capture Hub</span>
               <div className="flex items-center gap-2">
                 <button onClick={flipCamera} className="p-2 text-indigo-400 hover:text-white transition-colors" title="Flip Camera">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                 </button>
                 <button onClick={stopCamera} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
               </div>
            </div>
            <div className="relative aspect-video bg-black flex items-center justify-center">
              <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
              <div className="absolute inset-0 pointer-events-none border-2 border-indigo-500/20 m-6 rounded-2xl"></div>
            </div>
            <div className="p-6 flex justify-center gap-4">
               <button 
                 onClick={capturePhoto}
                 className="w-16 h-16 rounded-full bg-white border-4 border-slate-300 shadow-2xl active:scale-90 transition-transform flex items-center justify-center"
               >
                 <div className="w-10 h-10 rounded-full bg-indigo-600"></div>
               </button>
            </div>
            <canvas ref={canvasRef} className="hidden" />
          </div>
        </div>
      )}

      <div className="px-2 pb-2 md:px-6 md:pb-6 pt-1 bg-slate-950/95 border-t border-slate-900/50 shrink-0">
        <div className="max-w-4xl mx-auto flex items-end gap-2 md:gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

          <div className="flex gap-1.5 md:gap-2">
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="p-2.5 md:p-3 bg-slate-900/50 text-slate-600 hover:text-indigo-400 rounded-xl border border-slate-800/50 active:scale-95 transition-all"
              title="Add Attachment"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
            </button>
            <button 
              onClick={() => startCamera(facingMode)}
              disabled={isCameraLoading}
              className={`p-2.5 md:p-3 bg-slate-900/50 text-slate-600 hover:text-indigo-400 rounded-xl border border-slate-800/50 active:scale-95 transition-all ${isCameraLoading ? 'animate-pulse' : ''}`}
              title="Capture Image"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </button>
          </div>

          <div className="flex-1 relative">
            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[300px] bg-slate-950 border border-slate-800 rounded-2xl p-3 shadow-2xl grid grid-cols-6 gap-1 animate-in slide-in-from-bottom-2 duration-200">
                {COMMON_EMOJIS.map(emoji => (
                  <button 
                    key={emoji} 
                    onClick={() => addEmoji(emoji)}
                    className="w-10 h-10 flex items-center justify-center hover:bg-slate-800 rounded-xl transition-all text-xl"
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            )}

            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              className="w-full bg-slate-900/40 border border-slate-800/80 rounded-xl md:rounded-2xl px-4 py-2.5 md:px-5 md:py-3.5 pr-10 md:pr-20 outline-none focus:border-indigo-500/50 transition-all resize-none max-h-24 min-h-[42px] md:min-h-[52px] text-[14px] text-slate-200 font-medium placeholder:text-slate-700 shadow-inner"
              rows={1}
            />

            <div className="absolute right-1.5 bottom-1.5 md:right-2 md:bottom-2 flex items-center gap-1.5 md:gap-2">
              <button 
                onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                className={`p-1.5 md:p-2 rounded-lg md:rounded-xl transition-all ${showEmojiPicker ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:text-slate-400'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </button>
              <button 
                onClick={handleSend} 
                className="bg-indigo-600 text-white p-1.5 md:p-2 rounded-lg md:rounded-xl disabled:opacity-5 transition-all active:scale-90 shadow-lg" 
                disabled={!input.trim()}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 md:h-4 md:w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatArea;

export enum GroupType {
  STANDARD = 'STANDARD',
  TOPICS = 'TOPICS'
}

export interface Attachment {
  name: string;
  type: string;
  size: string;
  url?: string;
}

export interface Resource extends Attachment {
  id: string;
  uploadedBy: string;
  date: Date;
}

export interface Message {
  id: string;
  sender: string;
  text: string;
  timestamp: Date;
  avatar: string;
  attachment?: Attachment;
  reactions?: { [emoji: string]: string[] }; // Map of emoji to list of usernames
  isPinned?: boolean;
}

export interface Topic {
  id: string;
  name: string;
  description: string;
  icon: string;
  messages: Message[];
  resources: Resource[];
  activeCall?: boolean;
}

export interface GroupMember {
  id: string;
  name: string;
  avatar: string;
  role: 'Owner' | 'Admin' | 'Member' | 'AI Assistant';
  status: 'online' | 'offline';
}

export interface Group {
  id: string;
  name: string;
  description?: string;
  rules?: string;
  type: GroupType;
  topics: Topic[];
  messages: Message[]; // For standard groups
  members: GroupMember[];
  lastMessage?: string;
  avatar: string;
  activeVoiceChannel?: boolean;
  category?: 'Education' | 'Corporate' | 'Community';
}

export interface VoiceParticipant {
  id: string;
  name: string;
  avatar: string;
  isSpeaking: boolean;
}

