const App: React.FC = () => {
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [currentUser, setCurrentUser] = useState<GroupMember>(MOCK_MEMBERS[0]);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [isAddingHub, setIsAddingHub] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);

  const [topicModalMode, setTopicModalMode] = useState<'create' | 'edit'>('create');
  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [topicModalGroupId, setTopicModalGroupId] = useState<string | null>(null);
  const [editingTopicId, setEditingTopicId] = useState<string | null>(null);
  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicDescription, setNewTopicDescription] = useState('');

  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [sessionGroupName, setSessionGroupName] = useState<string | null>(null);
  const [isSessionMinimized, setIsSessionMinimized] = useState(false);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [windowWidth, setWindowWidth] = useState(window.innerWidth);

  useEffect(() => {
    const handleResize = () => setWindowWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  const handleSelectGroup = (id: string) => {
    setIsAddingHub(false);
    setIsEditingProfile(false);
    setEditingGroup(null);
    setActiveGroupId(id);
    const selectedGroup = groups.find(g => g.id === id);

    if (selectedGroup && selectedGroup.type === GroupType.TOPICS && selectedGroup.topics.length > 0) {
      setActiveTopicId(selectedGroup.topics[0].id);
    } else {
      setActiveTopicId(null);
    }

    setIsMobileMenuOpen(false);
  };

  const handleOpenTopicModal = (groupId: string, topic?: Topic) => {
    setTopicModalGroupId(groupId);
    if (topic) {
      setTopicModalMode('edit');
      setEditingTopicId(topic.id);
      setNewTopicName(topic.name);
      setNewTopicDescription(topic.description);
    } else {
      setTopicModalMode('create');
      setEditingTopicId(null);
      setNewTopicName('');
      setNewTopicDescription('');
    }
    setIsTopicModalOpen(true);
  };

  const handleCreateOrUpdateTopic = () => {
    if (!newTopicName.trim() || !topicModalGroupId) return;

    if (topicModalMode === 'create') {
      const newTopic: Topic = { 
        id: `t-${Date.now()}`, 
        name: newTopicName, 
        icon: '📂', 
        description: newTopicDescription, 
        messages: [], 
        resources: [] 
      };
      setGroups(prev => prev.map(g => g.id === topicModalGroupId ? { ...g, topics: [...g.topics, newTopic] } : g));
      if (activeGroupId === topicModalGroupId) {
        setActiveTopicId(newTopic.id);
      }
    } else if (editingTopicId) {
      setGroups(prev => prev.map(g => g.id === topicModalGroupId ? {
        ...g,
        topics: g.topics.map(t => t.id === editingTopicId ? { ...t, name: newTopicName, description: newTopicDescription } : t)
      } : g));
    }

    setIsTopicModalOpen(false);
    setNewTopicName('');
    setNewTopicDescription('');
    setTopicModalGroupId(null);
    setEditingTopicId(null);
  };

  const handleOpenVoice = (mode: 'voice' | 'video') => {
    const groupName = activeTopicId 
      ? activeGroup?.topics.find(t => t.id === activeTopicId)?.name || activeGroup?.name
      : activeGroup?.name;

    setSessionGroupName(groupName || 'Nexus Hub Session');
    setSessionMode(mode);
    setIsSessionMinimized(false);
  };

  const handleCreateGroup = (name: string, type: GroupType, avatar: string, description?: string, rules?: string) => {
    const defaultTopic: Topic = { id: `t-intro-${Date.now()}`, name: 'Welcome', description: 'Quick start guide.', icon: '✨', messages: [], resources: [] };
    const newGroup: Group = {
      id: `hub-${Date.now()}`,
      name,
      description,
      rules,
      type,
      topics: type === GroupType.TOPICS ? [defaultTopic] : [],
      messages: [],
      members: [currentUser],
      avatar,
      category: 'Community'
    };
    setGroups(prev => [...prev, newGroup]);
    setActiveGroupId(newGroup.id);
    setActiveTopicId(type === GroupType.TOPICS ? defaultTopic.id : null);
    setIsAddingHub(false);
  };

  const handleUpdateGroup = (name: string, type: GroupType, avatar: string, description?: string, rules?: string) => {
    if (!editingGroup) return;
    setGroups(prev => prev.map(g => g.id === editingGroup.id ? { ...g, name, type, avatar, description, rules } : g));
    setEditingGroup(null);
  };

  const handleAddMember = (groupId: string, name: string, role: GroupMember['role']) => {
    const newMember: GroupMember = {
      id: `mem-${Date.now()}`,
      name,
      role,
      avatar: `https://picsum.photos/80/80?u=${Date.now()}`,
      status: 'online'
    };
    setGroups(prev => prev.map(g => g.id === groupId ? { ...g, members: [...g.members, newMember] } : g));
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    const newMessage: Message = {
      id: `msg-${Date.now()}`,
      sender: currentUser.name,
      text,
      timestamp: new Date(),
      avatar: currentUser.avatar,
      attachment,
      reactions: {},
      isPinned: false
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: [...t.messages, newMessage] } : t)
        };
      }
    }));
  };

  const handleReactToMessage = (topicIdOrNull: string | null, messageId: string, emoji: string) => {
    const userName = currentUser.name;

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;

      const updateMessage = (messages: Message[]) => {
        return messages.map(m => {
          if (m.id !== messageId) return m;
          const reactions = { ...(m.reactions || {}) };
          const users = [...(reactions[emoji] || [])];

          if (users.includes(userName)) {
            // Remove reaction
            const newUsers = users.filter(u => u !== userName);
            if (newUsers.length === 0) {
              delete reactions[emoji];
            } else {
              reactions[emoji] = newUsers;
            }
          } else {
            // Add reaction
            reactions[emoji] = [...users, userName];
          }

          return { ...m, reactions };
        });
      };

      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: updateMessage(g.messages) };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessage(t.messages) } : t)
        };
      }
    }));
  };

  const handlePinMessage = (topicIdOrNull: string | null, messageId: string) => {
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      const updateMessage = (messages: Message[]) => {
        return messages.map(m => m.id === messageId ? { ...m, isPinned: !m.isPinned } : m);
      };

      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: updateMessage(g.messages) };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessage(t.messages) } : t)
        };
      }
    }));
  };

  const handleUpdateProfile = (updatedUser: Partial<GroupMember>) => {
    const newUser = { ...currentUser, ...updatedUser };
    setCurrentUser(newUser);
    // Sync update with all groups that the user is a member of
    setGroups(prev => prev.map(g => ({
      ...g,
      members: g.members.map(m => m.id === currentUser.id ? { ...m, ...updatedUser } : m)
    })));
    setIsEditingProfile(false);
  };

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#020617] text-slate-200 selection:bg-indigo-500/30">
      <div className={`fixed inset-y-0 left-0 z-50 transform md:relative md:translate-x-0 transition-transform duration-300 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <Sidebar 
          groups={groups} 
          activeGroupId={activeGroupId || ''} 
          activeTopicId={activeTopicId}
          currentUser={currentUser}
          onSelectGroup={handleSelectGroup}
          onSelectTopic={(id) => { setIsAddingHub(false); setIsEditingProfile(false); setEditingGroup(null); setActiveTopicId(id); setIsMobileMenuOpen(false); }}
          onStartAddingHub={() => { setIsAddingHub(true); setIsEditingProfile(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
          onResetPortal={() => { setActiveGroupId(null); setActiveTopicId(null); setIsAddingHub(false); setIsEditingProfile(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
          onAddTopic={handleOpenTopicModal}
          onJoinVoice={handleOpenVoice}
          onEditProfile={() => { setIsEditingProfile(true); setIsAddingHub(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
          isOpen={isMobileMenuOpen}
          onClose={() => setIsMobileMenuOpen(false)}
        />
      </div>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <main className="flex-1 flex flex-col min-w-0 h-full relative">
        {isEditingProfile ? (
          <UserProfileScreen 
            user={currentUser} 
            onUpdate={handleUpdateProfile} 
            onCancel={() => setIsEditingProfile(false)} 
          />
        ) : isAddingHub ? (
          <HubCreationScreen 
            onCreate={handleCreateGroup} 
            onCancel={() => setIsAddingHub(false)} 
          />
        ) : editingGroup ? (
          <HubCreationScreen 
            initialData={editingGroup}
            onCreate={handleUpdateGroup} 
            onCancel={() => setEditingGroup(null)} 
          />
        ) : activeGroup ? (
          activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              currentUser={currentUser.name}
              groupDescription={activeGroup.description}
              groupRules={activeGroup.rules}
              onSendMessage={(text, att) => handleSendMessage(null, text, att)}
              onReactToMessage={(msgId, emoji) => handleReactToMessage(null, msgId, emoji)}
              onPinMessage={(msgId) => handlePinMessage(null, msgId)}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
              onEditHub={() => setEditingGroup(activeGroup)}
              onOpenVoice={handleOpenVoice}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              currentUser={currentUser}
              activeTopicId={activeTopicId}
              onSelectTopic={setActiveTopicId}
              onOpenVoice={handleOpenVoice}
              onSendMessage={handleSendMessage}
              onReactToMessage={handleReactToMessage}
              onPinMessage={handlePinMessage}
              onAddMember={(name, role) => handleAddMember(activeGroup.id, name, role)}
              onUploadResource={(topicId, res) => {
                 setGroups(prev => prev.map(g => g.id === activeGroupId ? {
                   ...g,
                   topics: g.topics.map(t => t.id === topicId ? { ...t, resources: [...t.resources, { ...res, id: Date.now().toString(), uploadedBy: 'You', date: new Date() }] } : t)
                 } : g));
              }}
              onStartAddingTopic={() => handleOpenTopicModal(activeGroup.id)}
              onEditTopic={(topic) => handleOpenTopicModal(activeGroup.id, topic)}
              onEditHub={() => setEditingGroup(activeGroup)}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          )
        ) : (
          <StartupScreen 
            groups={groups} 
            onSelectHub={handleSelectGroup} 
            onInitializeHub={() => setIsAddingHub(true)} 
          />
        )}

        {isTopicModalOpen && (
          <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/90 backdrop-blur-md" onClick={() => setIsTopicModalOpen(false)} />
            <div className="relative w-full max-w-sm bg-slate-950 border border-slate-900 rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
              <h2 className="text-xl font-black mb-6 text-white text-center italic uppercase tracking-tighter">
                {topicModalMode === 'create' ? 'Register Module' : 'Configure Module'}
              </h2>
              <div className="space-y-4">
                <input 
                  type="text" 
                  value={newTopicName} 
                  onChange={(e) => setNewTopicName(e.target.value)} 
                  className="w-full bg-slate-900/50 border border-slate-800 rounded-xl p-4 text-[13px] text-white font-black uppercase tracking-tighter outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700" 
                  placeholder="Designation Code..." 
                  autoFocus
                />
                <textarea
                  value={newTopicDescription}
                  onChange={(e) => setNewTopicDescription(e.target.value)}
                  className="w-full bg-slate-900/50 border border-slate-800 rounded-xl p-4 text-[13px] text-white font-black uppercase tracking-tighter outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700 resize-none h-24"
                  placeholder="Mission Objectives / Description..."
                />
                <div className="flex gap-3">
                  <button onClick={() => setIsTopicModalOpen(false)} className="flex-1 py-4 bg-slate-900 text-slate-600 rounded-2xl font-black uppercase text-[10px] tracking-widest transition-colors hover:text-white">Abort</button>
                  <button onClick={handleCreateOrUpdateTopic} className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Authorize</button>
                </div>
              </div>
            </div>
          </div>
        )}

        {sessionMode && (
          <div className={`fixed z-[100] transition-all duration-500 ease-in-out ${
            isSessionMinimized 
              ? 'bottom-6 right-6 w-[320px] max-w-[90vw] h-auto pointer-events-auto' 
              : 'inset-0 flex items-center justify-center p-2 sm:p-4 bg-[#020617]/80 backdrop-blur-xl pointer-events-auto'
          }`}>
            <MeetingSession 
              mode={sessionMode}
              isMinimized={isSessionMinimized}
              onMinimize={() => setIsSessionMinimized(!isSessionMinimized)}
              onClose={() => { setSessionMode(null); setSessionGroupName(null); }} 
              groupName={sessionGroupName || 'Active Session'} 
            />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '🙌', '🎉', '💡', '🤔', '👀', '✅'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  groupDescription, 
  groupRules, 
  onSendMessage, 
  onReactToMessage,
  onPinMessage,
  onAddMember, 
  headerContent, 
  onToggleMenu, 
  onEditHub,
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const [showPinnedList, setShowPinnedList] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Encrypted data packet: ${file.name}`, attachment);
    }
  };

  const addEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
      alert("Please grant camera permissions to capture data.");
    } finally {
      setIsCameraLoading(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `captured_frame_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Data',
          url: dataUrl
        };
        onSendMessage("Captured visual signature.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      el.classList.add('ring-2', 'ring-indigo-500', 'ring-offset-4', 'ring-offset-[#020617]');
      setTimeout(() => el.classList.remove('ring-2', 'ring-indigo-500', 'ring-offset-4', 'ring-offset-[#020617]'), 2000);
    }
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {!hideHeader && (
        <header className="h-14 md:h-16 px-3.5 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button 
              onClick={onToggleMenu}
              className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
            </button>
            <div className="text-sm md:text-base font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60 font-black">#</span> {groupName}
            </div>
          </div>

          <div className="flex items-center gap-1.5 md:gap-3">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🔊</span>
                </button>
                <button onClick={() => onOpenVoice('video')} className="p-2 text-indigo-400 hover:text-white transition-colors">
                  <span className="text-sm md:text-lg">🎥</span>
                </button>
              </div>
            )}
            {headerContent}
            <button 
              onClick={() => setShowMembers(!showMembers)}
              className={`p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button 
            onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)}
            className="flex-1 flex items-center gap-3 overflow-hidden text-left"
          >
            <span className="text-indigo-500 shrink-0">📌</span>
            <div className="min-w-0">
               <div className="text-[8px] font-black uppercase text-slate-500 tracking-widest leading-none mb-0.5">Pinned Directive</div>
               <div className="text-[11px] font-medium text-slate-300 truncate">{pinnedMessages[pinnedMessages.length - 1].text}</div>
            </div>
          </button>
          <div className="flex items-center gap-1">
            <span className="text-[8px] font-black bg-slate-800 text-slate-500 px-1.5 py-0.5 rounded uppercase tracking-widest">{pinnedMessages.length} total</span>
            <button 
              onClick={() => setShowPinnedList(!showPinnedList)}
              className="p-1 text-slate-600 hover:text-white transition-colors"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className={`h-4 w-4 transition-transform ${showPinnedList ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
            </button>
          </div>

          {showPinnedList && (
            <div className="absolute top-full left-0 right-0 bg-slate-950/95 border-b border-slate-900 shadow-2xl z-20 max-h-60 overflow-y-auto animate-in slide-in-from-top-2 duration-200">
               {pinnedMessages.map(m => (
                 <div key={m.id} className="p-3 border-b border-slate-900/50 flex items-center justify-between hover:bg-slate-900 transition-colors">
                    <button 
                      onClick={() => { scrollToMessage(m.id); setShowPinnedList(false); }}
                      className="flex-1 min-w-0 text-left"
                    >
                      <div className="text-[9px] font-black text-indigo-400 uppercase tracking-tighter italic mb-1">{m.sender}</div>
                      <div className="text-[11px] text-slate-400 truncate">{m.text}</div>
                    </button>
                    <button onClick={() => onPinMessage(m.id)} className="p-2 text-slate-700 hover:text-red-500 transition-colors">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                 </div>
               ))}
            </div>
          )}
        </div>
      )}

      <div className="flex-1 overflow-hidden relative flex">
        <div 
          ref={scrollRef} 
          className="flex-1 overflow-y-auto p-3 md:p-6 space-y-4 md:space-y-6 custom-scrollbar overscroll-contain"
          onClick={() => {
            setActiveReactionPicker(null);
            setShowEmojiPicker(false);
          }}
        >
          {messages.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-10">
              <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-xl mb-3 border border-slate-800">📡</div>
              <p className="text-[7px] font-black uppercase tracking-[0.5em] text-white">Signal Sync Active</p>
            </div>
          )}
          {messages.map((m) => {
            const isMe = m.sender === currentUser;
            const hasReactions = m.reactions && Object.keys(m.reactions).length > 0;

            return (
              <div id={`msg-${m.id}`} key={m.id} className={`flex items-start gap-2.5 ${isMe ? 'flex-row-reverse' : ''} animate-in fade-in slide-in-from-bottom-1 duration-200 group transition-all`}>
                <img src={m.avatar} className="w-7 h-7 md:w-8 md:h-8 rounded-lg border border-slate-900 shadow-md shrink-0 object-cover" alt="" />

                <div className={`flex flex-col gap-1 max-w-[88%] md:max-w-[75%] ${isMe ? 'items-end' : ''} relative`}>
                  <div className="flex items-center gap-2 px-1 mb-0.5">
                    {m.isPinned && <span className="text-indigo-500 text-[10px]">📌</span>}
                    <span className="text-[8px] font-black text-indigo-500 uppercase tracking-tighter italic">{m.sender}</span>
                    <span className="text-[7px] text-slate-700 font-black">{m.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                  </div>

                  <div className="relative group/msg">
                    <div className={`rounded-xl md:rounded-2xl px-3 py-2 md:px-4 md:py-3 shadow-xl border transition-all ${
                      isMe 
                        ? 'bg-indigo-600 border-indigo-500 text-white rounded-tr-none' 
                        : 'bg-slate-900/80 border-slate-800 text-slate-200 rounded-tl-none'
                    } ${m.isPinned ? 'ring-1 ring-indigo-500/30' : ''}`}>
                      {m.attachment && (
                        <div className="mb-2 bg-black/30 rounded-lg overflow-hidden border border-white/5">
                          {m.attachment.url && m.attachment.type.startsWith('image/') ? (
                            <img src={m.attachment.url} className="w-full h-auto max-h-64 object-cover" alt="attachment" />
                          ) : (
                            <div className="p-2 flex items-center gap-2.5">
                              <div className="p-1.5 bg-indigo-500/20 rounded-md text-indigo-400">
                                 <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" /></svg>
                              </div>
                              <div className="flex-1 min-w-0">
                                <div className="text-[10px] font-black truncate tracking-tighter">{m.attachment.name}</div>
                                <div className="text-[7px] opacity-40 font-black uppercase tracking-widest">{m.attachment.size}</div>
                              </div>
                            </div>
                          )}
                        </div>
                      )}
                      <p className="text-[13px] md:text-[14px] leading-[1.35] whitespace-pre-wrap font-medium tracking-tight">{m.text}</p>
                    </div>

                    {/* Action Bar */}
                    <div className={`absolute top-0 ${isMe ? '-left-16' : '-right-16'} flex items-center gap-1 opacity-0 group-hover/msg:opacity-100 transition-all z-10`}>
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          onPinMessage(m.id);
                        }}
                        className={`p-1.5 bg-slate-900/90 border border-slate-800 rounded-lg transition-all ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white'}`}
                        title={m.isPinned ? "Unpin Message" : "Pin Message"}
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                      </button>
                      <button 
                        onClick={(e) => {
                          e.stopPropagation();
                          setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id);
                        }}
                        className={`p-1.5 bg-slate-900/90 border border-slate-800 rounded-lg text-slate-500 transition-all hover:text-white ${activeReactionPicker === m.id ? 'bg-indigo-500/10 text-indigo-400' : ''}`}
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                      </button>
                    </div>

                    {/* Reaction Picker Popover */}
                    {activeReactionPicker === m.id && (
                      <div 
                        className={`absolute -top-12 ${isMe ? 'right-0' : 'left-0'} bg-slate-950 border border-slate-800 p-1.5 rounded-2xl shadow-2xl flex items-center gap-1 z-30 animate-in fade-in zoom-in-90 duration-150`}
                        onClick={e => e.stopPropagation()}
                      >
                        {COMMON_EMOJIS.slice(0, 8).map(emoji => (
                          <button 
                            key={emoji} 
                            onClick={() => {
                              onReactToMessage(m.id, emoji);
                              setActiveReactionPicker(null);
                            }}
                            className="w-8 h-8 flex items-center justify-center hover:bg-slate-800 rounded-xl transition-all hover:scale-125 text-lg"
                          >
                            {emoji}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>

                  {/* Reactions List */}
                  {hasReactions && (
                    <div className={`flex flex-wrap gap-1.5 mt-1.5 ${isMe ? 'justify-end' : 'justify-start'}`}>
                      {Object.entries(m.reactions!).map(([emoji, users]) => {
                        const usersList = users as string[];
                        const hasUserReacted = usersList.includes(currentUser);
                        return (
                          <button 
                            key={emoji}
                            onClick={(e) => {
                              e.stopPropagation();
                              onReactToMessage(m.id, emoji);
                            }}
                            className={`flex items-center gap-1.5 px-2 py-0.5 rounded-full border text-[10px] font-black transition-all ${
                              hasUserReacted 
                                ? 'bg-indigo-600/20 border-indigo-500/50 text-indigo-400' 
                                : 'bg-slate-900/50 border-slate-800 text-slate-500 hover:border-slate-700'
                            }`}
                          >
                            <span>{emoji}</span>
                            <span>{usersList.length}</span>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        {!hideHeader && showMembers && (
          <div className="absolute inset-y-0 right-0 w-72 bg-slate-950/95 backdrop-blur-3xl border-l border-slate-900 z-20 shadow-2xl flex flex-col animate-in slide-in-from-right duration-200">
             <div className="h-14 px-4 border-b border-slate-900 flex items-center justify-between shrink-0">
                <span className="text-[8px] font-black uppercase text-indigo-500 tracking-[0.3em] italic">Hub Intelligence</span>
                <button onClick={() => setShowMembers(false)} className="p-1.5 text-slate-700">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar">
               {['online', 'offline'].map(status => {
                 const filtered = members.filter(m => m.status === status);
                 if (filtered.length === 0) return null;
                 return (
                   <div key={status}>
                      <div className="text-[7px] font-black text-slate-700 uppercase mb-1.5 ml-1 tracking-[0.2em]">{status} • {filtered.length}</div>
                      <div className="space-y-0.5">
                        {filtered.map(member => (
                          <div key={member.id} className="flex items-center gap-2.5 p-1.5 rounded-lg hover:bg-slate-900 transition-all border border-transparent">
                            <div className="relative">
                              <img src={member.avatar} className="w-7 h-7 rounded-md object-cover border border-slate-800/50" alt="" />
                              {status === 'online' && <div className="absolute -bottom-0.5 -right-0.5 w-1.5 h-1.5 rounded-full bg-emerald-500 border border-slate-950"></div>}
                            </div>
                            <div className="min-w-0">
                               <div className="text-[11px] font-black text-white truncate tracking-tighter uppercase italic">{member.name}</div>
                               <div className="text-[7px] text-slate-600 font-black uppercase tracking-widest leading-none">{member.role}</div>
                            </div>
                          </div>
                        ))}
                      </div>
                   </div>
                 );
               })}
             </div>
          </div>
        )}
      </div>

      {/* Camera Capture Modal */}
      {showCamera && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
          <div className="relative w-full max-w-lg bg-slate-900 rounded-[2rem] border border-slate-800 overflow-hidden shadow-2xl flex flex-col">
            <div className="p-4 border-b border-slate-800 flex justify-between items-center bg-slate-950/50">
               <span className="text-[10px] font-black text-white uppercase tracking-widest italic">Visual Capture Hub</span>
               <div className="flex items-center gap-2">
                 <button onClick={flipCamera} className="p-2 text-indigo-400 hover:text-white transition-colors" title="Flip Camera">
                   <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                 </button>
                 <button onClick={stopCamera} className="p-2 text-slate-500 hover:text-white transition-colors">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
               </div>
            </div>
            <div className="relative aspect-video bg-black flex items-center justify-center">
              <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
              <div className="absolute inset-0 pointer-events-none border-2 border-indigo-500/20 m-6 rounded-2xl"></div>
            </div>
            <div className="p-6 flex justify-center gap-4">
               <button 
                 onClick={capturePhoto}
                 className="w-16 h-16 rounded-full bg-white border-4 border-slate-300 shadow-2xl active:scale-90 transition-transform flex items-center justify-center"
               >
                 <div className="w-10 h-10 rounded-full bg-indigo-600"></div>
               </button>
            </div>
            <canvas ref={canvasRef} className="hidden" />
          </div>
        </div>
      )}

      <div className="px-2 pb-2 md:px-6 md:pb-6 pt-1 bg-slate-950/95 border-t border-slate-900/50 shrink-0">
        <div className="max-w-4xl mx-auto flex items-end gap-2 md:gap-3">
          <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

          <div className="flex gap-1.5 md:gap-2">
            <button 
              onClick={() => fileInputRef.current?.click()} 
              className="p-2.5 md:p-3 bg-slate-900/50 text-slate-600 hover:text-indigo-400 rounded-xl border border-slate-800/50 active:scale-95 transition-all"
              title="Add Attachment"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
            </button>
            <button 
              onClick={() => startCamera(facingMode)}
              disabled={isCameraLoading}
              className={`p-2.5 md:p-3 bg-slate-900/50 text-slate-600 hover:text-indigo-400 rounded-xl border border-slate-800/50 active:scale-95 transition-all ${isCameraLoading ? 'animate-pulse' : ''}`}
              title="Capture Image"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </button>
          </div>

          <div className="flex-1 relative">
            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[300px] bg-slate-950 border border-slate-800 rounded-2xl p-3 shadow-2xl grid grid-cols-6 gap-1 animate-in slide-in-from-bottom-2 duration-200">
                {COMMON_EMOJIS.map(emoji => (
                  <button 
                    key={emoji} 
                    onClick={() => addEmoji(emoji)}
                    className="w-10 h-10 flex items-center justify-center hover:bg-slate-800 rounded-xl transition-all text-xl"
                  >
                    {emoji}
                  </button>
                ))}
              </div>
            )}

            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              className="w-full bg-slate-900/40 border border-slate-800/80 rounded-xl md:rounded-2xl px-4 py-2.5 md:px-5 md:py-3.5 pr-10 md:pr-20 outline-none focus:border-indigo-500/50 transition-all resize-none max-h-24 min-h-[42px] md:min-h-[52px] text-[14px] text-slate-200 font-medium placeholder:text-slate-700 shadow-inner"
              rows={1}
            />

            <div className="absolute right-1.5 bottom-1.5 md:right-2 md:bottom-2 flex items-center gap-1.5 md:gap-2">
              <button 
                onClick={() => setShowEmojiPicker(!showEmojiPicker)}
                className={`p-1.5 md:p-2 rounded-lg md:rounded-xl transition-all ${showEmojiPicker ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:text-slate-400'}`}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.828 14.828a4 4 0 01-5.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </button>
              <button 
                onClick={handleSend} 
                className="bg-indigo-600 text-white p-1.5 md:p-2 rounded-lg md:rounded-xl disabled:opacity-5 transition-all active:scale-90 shadow-lg" 
                disabled={!input.trim()}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5 md:h-4 md:w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  currentUser: GroupMember;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment) => void;
  onReactToMessage: (topicId: string, messageId: string, emoji: string) => void;
  onPinMessage: (topicId: string, messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onStartAddingTopic: () => void;
  onEditTopic: (topic: Topic) => void;
  onEditHub: () => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  currentUser,
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onReactToMessage,
  onPinMessage,
  onAddMember,
  onUploadResource,
  onStartAddingTopic,
  onEditTopic,
  onEditHub,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel')) return '📊';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-600 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-slate-950 relative overflow-hidden">
      {/* High-Density Module Matrix - Tablet and Desktop Sidebar */}
      <div className="w-64 bg-slate-950/40 border-r border-slate-900/50 hidden lg:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-6 border-b border-slate-900/30 flex items-center justify-between">
          <div className="font-black uppercase tracking-[0.2em] text-[9px] text-slate-600 italic">Core Modules</div>
          <button 
            onClick={onStartAddingTopic}
            className="text-indigo-500 hover:text-white transition-colors p-1"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 4v16m8-8H4"/></svg>
          </button>
        </div>

        <div className="px-3 py-6 space-y-1.5">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-4 rounded-2xl flex items-center transition-all duration-300 border group ${
                activeTopicId === topic.id 
                  ? 'bg-indigo-600/15 text-indigo-400 border-indigo-500/40 shadow-xl' 
                  : 'border-transparent text-slate-600 hover:text-slate-400 hover:bg-slate-900/60'
              }`}
            >
              <div className="min-w-0 flex-1">
                <span className="block truncate font-black text-[11px] tracking-tight uppercase italic leading-none mb-1.5 group-hover:tracking-wider transition-all duration-500">{topic.name}</span>
                <span className="block text-[8px] text-slate-700 font-bold uppercase tracking-widest truncate">{topic.description || 'Primary Objective'}</span>
              </div>
            </button>
          ))}

          <button 
            onClick={onStartAddingTopic}
            className="w-full text-left p-4 rounded-2xl flex items-center gap-4 text-slate-700 hover:text-slate-400 border border-dashed border-slate-900 mt-6 group transition-all hover:bg-slate-900/30"
          >
            <span className="text-xl opacity-40">➕</span>
            <span className="truncate flex-1 text-[10px] font-black uppercase tracking-widest">Register Module</span>
          </button>
        </div>

        <div className="mt-auto p-5 border-t border-slate-900/30 bg-slate-950/20">
           <div className="space-y-4">
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Active Nodes</span>
                 <span className="text-indigo-500">{group.members.length}</span>
              </div>
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Sync Status</span>
                 <span className="text-emerald-500 text-glow">STABLE</span>
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0 h-full relative">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-12 text-center animate-in fade-in duration-700">
             <div className="w-24 h-24 bg-slate-900/40 rounded-3xl flex items-center justify-center text-4xl mb-8 border border-slate-800 shadow-2xl text-slate-700">📡</div>
             <h2 className="text-3xl font-black text-white mb-4 italic tracking-tighter uppercase text-glow">System Idle</h2>
             <p className="text-slate-600 text-[10px] font-bold uppercase tracking-[0.5em] mb-12">Initialize module for uplink sequence</p>
             <button onClick={onToggleMenu} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-[0.4em] lg:hidden shadow-2xl active:scale-95 transition-all">Select Node</button>
          </div>
        ) : (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            {/* Master Header with Adaptive Segment Switcher */}
            <header className="bg-slate-950/60 backdrop-blur-3xl border-b border-slate-900 px-4 md:px-6 py-4 flex flex-col gap-4 z-10 shrink-0">
               <div className="flex items-center justify-between gap-4">
                  <div className="flex items-center gap-3 md:gap-5 min-w-0 flex-1">
                    <button onClick={onToggleMenu} className="p-2.5 bg-slate-900 rounded-xl md:hidden text-slate-500 border border-slate-800/50 shrink-0 shadow-lg">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
                    </button>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2 md:gap-3 mb-1">
                         <div className="flex items-center gap-1 md:gap-2 min-w-0">
                            <span className="text-indigo-500/50 font-black text-sm md:text-base">#</span>
                            <h2 className="text-lg md:text-xl font-black text-white leading-tight truncate uppercase italic tracking-tighter">{activeTopic.name}</h2>
                         </div>
                         <button onClick={() => onEditTopic(activeTopic)} className="p-1.5 text-slate-700 hover:text-indigo-400 transition-colors bg-slate-900/40 rounded-xl border border-slate-800/40 shrink-0" title="Modify Module">
                           <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                         </button>
                      </div>
                      {/* Topic Description & Context - Visible on all sizes with truncation */}
                      <div className="flex items-center gap-2 overflow-hidden">
                         <span className="text-[9px] text-indigo-500 font-black uppercase tracking-[0.2em] leading-none shrink-0 hidden sm:inline">{group.name}</span>
                         {activeTopic.description && (
                           <>
                             <span className="w-1 h-1 rounded-full bg-slate-800 shrink-0 hidden sm:inline"></span>
                             <span className="text-[8px] md:text-[9px] text-slate-500 font-bold uppercase tracking-widest truncate max-w-xs">{activeTopic.description}</span>
                           </>
                         )}
                      </div>
                    </div>
                  </div>

                  {/* Right Actions Group (Tablet and Desktop switcher integrated here) */}
                  <div className="flex items-center gap-2 md:gap-4 shrink-0">
                    {/* View Switcher: Beside Intel/Voice on md+ screens */}
                    <div className="hidden md:flex items-center gap-1 bg-slate-900/50 p-1 rounded-xl border border-slate-800/50 shadow-inner mr-2">
                       <button onClick={() => setViewMode('discussion')} className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.1em] uppercase transition-all ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Uplink</button>
                       <button onClick={() => setViewMode('resources')} className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.1em] uppercase transition-all ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Library</button>
                       <button onClick={() => setViewMode('members')} className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.1em] uppercase transition-all ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Nodes</button>
                    </div>

                    <div className="flex items-center gap-2">
                      <button onClick={() => onOpenVoice('voice')} className="p-2 md:p-2.5 text-indigo-400 hover:text-white transition-colors bg-slate-900/40 rounded-xl border border-slate-800/40">
                        <span className="text-base">🔊</span>
                      </button>
                      <button onClick={() => onOpenVoice('video')} className="p-2 md:p-2.5 text-indigo-400 hover:text-white transition-colors bg-slate-900/40 rounded-xl border border-slate-800/40">
                        <span className="text-base">🎥</span>
                      </button>
                    </div>
                  </div>
               </div>

               {/* Segment Hardware Switcher - Mobile only (below title) */}
