import React, { useState, useRef } from 'react';
import { GroupMember } from '../types';

interface AuthScreenProps {
  onRegister: (user: GroupMember) => void;
}

const AVATAR_PRESETS = [
  'https://picsum.photos/150/150?u=101',
  'https://picsum.photos/150/150?u=102',
  'https://picsum.photos/150/150?u=103',
  'https://picsum.photos/150/150?u=104',
  'https://picsum.photos/150/150?u=105',
  'https://picsum.photos/150/150?u=106',
];

const AuthScreen: React.FC<AuthScreenProps> = ({ onRegister }) => {
  const [name, setName] = useState('');
  const [selectedAvatar, setSelectedAvatar] = useState(AVATAR_PRESETS[0]);
  const [customAvatarUrl, setCustomAvatarUrl] = useState('');
  const [step, setStep] = useState(1);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const finalAvatar = customAvatarUrl.trim() || selectedAvatar;

  const handleComplete = () => {
    if (name.trim()) {
      const newUser: GroupMember = {
        id: `user-${Date.now()}`,
        name: name.trim(),
        avatar: finalAvatar,
        role: 'Owner',
        status: 'online',
      };
      onRegister(newUser);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedAvatar(reader.result as string);
        setCustomAvatarUrl('');
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-[#020617] flex items-center justify-center p-6 overflow-hidden">
      {/* Background Decor */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[80%] h-[80%] bg-indigo-600/5 blur-[120px] rounded-full animate-pulse" />
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 brightness-50 contrast-150" />
      </div>

      <div className="relative w-full max-w-lg bg-slate-950/40 backdrop-blur-3xl border border-slate-900 rounded-[3rem] p-8 md:p-12 shadow-2xl animate-in fade-in zoom-in-95 duration-700">
        {/* Step Indicator */}
        <div className="flex justify-center gap-2 mb-12">
          {[1, 2].map((s) => (
            <div 
              key={s} 
              className={`h-1 rounded-full transition-all duration-500 ${step === s ? 'w-12 bg-indigo-500 shadow-[0_0_10px_rgba(79,70,229,0.8)]' : 'w-4 bg-slate-900'}`} 
            />
          ))}
        </div>

        {step === 1 ? (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="text-center space-y-3">
              <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter text-glow">Identity Uplink</h1>
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.4em]">Initialize Alias Registry</p>
            </div>

            <div className="space-y-4">
              <div className="relative group">
                <input 
                  type="text" 
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && name.trim() && setStep(2)}
                  className="w-full bg-slate-900/30 border-2 border-slate-800 rounded-2xl px-6 py-5 text-xl text-white font-black italic tracking-tighter outline-none focus:border-indigo-600 transition-all placeholder:text-slate-800 shadow-inner uppercase"
                  placeholder="Designate Alias..."
                  autoFocus
                />
                <div className="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none opacity-20 group-focus-within:opacity-100 transition-opacity">
                   <span className="text-[8px] font-black text-indigo-400 uppercase tracking-widest">Input_Required</span>
                </div>
              </div>

              <button 
                onClick={() => setStep(2)}
                disabled={!name.trim()}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-700 disabled:opacity-50 text-white rounded-2xl font-black uppercase text-[11px] tracking-[0.4em] italic shadow-xl transition-all active:scale-[0.98]"
              >
                Proceed to Signature
              </button>
            </div>
          </div>
        ) : (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="text-center space-y-3">
              <h2 className="text-3xl font-black text-white italic uppercase tracking-tighter">Visual Signature</h2>
              <p className="text-[9px] font-black text-indigo-500 uppercase tracking-[0.4em]">Confirm Biological Representation</p>
            </div>

            <div className="flex flex-col items-center gap-8">
              <div className="relative group">
                <div className="absolute inset-0 rounded-[2.5rem] bg-indigo-600/10 blur-2xl animate-pulse" />
                <img 
                  src={finalAvatar} 
                  className="w-32 h-32 rounded-[2.5rem] border-2 border-indigo-500/50 relative z-10 object-cover shadow-2xl bg-slate-950 transition-all duration-500" 
                  alt="Identity Preview" 
                />
              </div>

              <div className="grid grid-cols-4 gap-3 w-full">
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="aspect-square rounded-xl border-2 border-dashed border-slate-800 bg-slate-900/40 flex flex-col items-center justify-center gap-1 hover:border-indigo-500 hover:bg-indigo-600/10 transition-all group"
                >
                  <span className="text-lg">📤</span>
                  <span className="text-[6px] font-black uppercase text-slate-600 group-hover:text-indigo-400">Upload</span>
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />

                {AVATAR_PRESETS.map((url) => (
                  <button
                    key={url}
                    onClick={() => { setSelectedAvatar(url); setCustomAvatarUrl(''); }}
                    className={`aspect-square rounded-xl border-2 overflow-hidden transition-all ${selectedAvatar === url && !customAvatarUrl ? 'border-indigo-500 ring-4 ring-indigo-500/10 scale-105' : 'border-slate-800 opacity-40 hover:opacity-100 hover:scale-105'}`}
                  >
                    <img src={url} className="w-full h-full object-cover" alt="" />
                  </button>
                ))}
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => setStep(1)}
                className="px-8 py-5 text-[10px] font-black text-slate-600 hover:text-white uppercase tracking-[0.2em] transition-colors"
              >
                Back
              </button>
              <button 
                onClick={handleComplete}
                className="flex-1 py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase text-[11px] tracking-[0.4em] italic shadow-[0_15px_40px_-10px_rgba(79,70,229,0.5)] transition-all active:scale-[0.98]"
              >
                Authorize Identity
              </button>
            </div>
          </div>
        )}

        <div className="mt-12 pt-8 border-t border-slate-900/50 flex items-center justify-center gap-6 opacity-30">
          <div className="flex flex-col items-center">
            <span className="text-[6px] font-black text-slate-600 uppercase tracking-widest mb-1">Security Protocol</span>
            <span className="text-[8px] font-black text-white uppercase tracking-tighter italic">AES_256_ACTIVE</span>
          </div>
          <div className="w-[1px] h-6 bg-slate-900" />
          <div className="flex flex-col items-center">
            <span className="text-[6px] font-black text-slate-600 uppercase tracking-widest mb-1">Latency</span>
            <span className="text-[8px] font-black text-emerald-500 uppercase tracking-tighter italic">0.01MS_SYNC</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthScreen;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatArea from './components/ChatArea';
import DashboardArea from './components/DashboardArea';
import MeetingSession from './components/MeetingSession';
import HubCreationScreen from './components/HubCreationScreen';
import StartupScreen from './components/StartupScreen';
import UserProfileScreen from './components/UserProfileScreen';
import AuthScreen from './components/AuthScreen';
import { Group, GroupType, Message, Attachment, Resource, Topic, GroupMember } from './types';

const MOCK_MEMBERS: GroupMember[] = [
  { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', role: 'AI Assistant', status: 'online' },
  { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', role: 'Admin', status: 'online' },
  { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', role: 'Member', status: 'offline' },
  { id: '4', name: 'Elena Rodriguez', avatar: 'https://picsum.photos/80/80?u=4', role: 'Member', status: 'online' },
];

const INITIAL_GROUPS: Group[] = [
  {
    id: 'edu-1',
    name: 'Advanced Mathematics',
    description: 'High-level synthesis of multivariable calculus and abstract algebra for research students.',
    rules: '1. Academic integrity is mandatory. 2. Support peers. 3. AI use permitted for clarification only.',
    type: GroupType.TOPICS,
    category: 'Education',
    members: MOCK_MEMBERS,
    topics: [
      { 
        id: 't1', 
        name: 'Calculus III', 
        description: 'Multivariable calculus resources and lecture notes.', 
        icon: '📐',
        messages: [],
        resources: [
          { id: 'r1', name: 'Lecture_Notes_Week1.pdf', type: 'application/pdf', size: '2.4 MB', uploadedBy: 'Prof. Smith', date: new Date() }
        ]
      },
      { 
        id: 't2', 
        name: 'Linear Algebra', 
        description: 'Matrices, vectors, and linear transformations.', 
        icon: '📊',
        messages: [],
        resources: []
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=100&h=100&fit=crop'
  }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<GroupMember | null>(null);
  const [isRegistered, setIsRegistered] = useState(false);
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [isAddingHub, setIsAddingHub] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);

  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [topicModalGroupId, setTopicModalGroupId] = useState<string | null>(null);
  const [topicModalMode, setTopicModalMode] = useState<'create' | 'edit'>('create');
  const [editingTopicId, setEditingTopicId] = useState<string | null>(null);
  const [newTopicName, setNewTopicName] = useState('');
  const [newTopicDescription, setNewTopicDescription] = useState('');

  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [sessionGroupName, setSessionGroupName] = useState<string | null>(null);
  const [isSessionMinimized, setIsSessionMinimized] = useState(false);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Load user data from local storage on mount
  useEffect(() => {
    const savedUser = localStorage.getItem('nexus_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      setCurrentUser(user);
      setIsRegistered(true);
    }
  }, []);

  const handleRegister = (user: GroupMember) => {
    localStorage.setItem('nexus_user', JSON.stringify(user));
    setCurrentUser(user);
    setIsRegistered(true);

    // Inject the new user into initial groups
    setGroups(prev => prev.map(g => ({
      ...g,
      members: [user, ...g.members]
    })));
  };

  const handleSelectGroup = (id: string) => {
    setIsAddingHub(false);
    setIsEditingProfile(false);
    setEditingGroup(null);
    setActiveGroupId(id);
    const selectedGroup = groups.find(g => g.id === id);
    if (selectedGroup && selectedGroup.type === GroupType.TOPICS && selectedGroup.topics.length > 0) {
      setActiveTopicId(selectedGroup.topics[0].id);
    } else {
      setActiveTopicId(null);
    }
    setIsMobileMenuOpen(false);
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: `msg-${Date.now()}`,
      sender: currentUser.name,
      text,
      timestamp: new Date(),
      avatar: currentUser.avatar,
      attachment,
      reactions: {},
      isPinned: false
    };
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: [...t.messages, newMessage] } : t)
        };
      }
    }));
  };

  const handleReactToMessage = (topicIdOrNull: string | null, messageId: string, emoji: string) => {
    if (!currentUser) return;
    const userName = currentUser.name;
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      const updateMessage = (messages: Message[]) => {
        return messages.map(m => {
          if (m.id !== messageId) return m;
          const reactions = { ...(m.reactions || {}) };
          const users = [...(reactions[emoji] || [])];
          if (users.includes(userName)) {
            const newUsers = users.filter(u => u !== userName);
            if (newUsers.length === 0) delete reactions[emoji];
            else reactions[emoji] = newUsers;
          } else {
            reactions[emoji] = [...users, userName];
          }
          return { ...m, reactions };
        });
      };
      if (g.type === GroupType.STANDARD) return { ...g, messages: updateMessage(g.messages) };
      else return { ...g, topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessage(t.messages) } : t) };
    }));
  };

  const handlePinMessage = (topicIdOrNull: string | null, messageId: string) => {
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      const updateMessage = (messages: Message[]) => messages.map(m => m.id === messageId ? { ...m, isPinned: !m.isPinned } : m);
      if (g.type === GroupType.STANDARD) return { ...g, messages: updateMessage(g.messages) };
      else return { ...g, topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessage(t.messages) } : t) };
    }));
  };

  const handleUpdateProfile = (updatedUser: Partial<GroupMember>) => {
    if (!currentUser) return;
    const newUser = { ...currentUser, ...updatedUser };
    localStorage.setItem('nexus_user', JSON.stringify(newUser));
    setCurrentUser(newUser);
    setGroups(prev => prev.map(g => ({
      ...g,
      members: g.members.map(m => m.id === currentUser.id ? { ...m, ...updatedUser } : m)
    })));
    setIsEditingProfile(false);
  };

  if (!isRegistered) {
    return <AuthScreen onRegister={handleRegister} />;
  }

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#020617] text-slate-200 selection:bg-indigo-500/30">
      <div className={`fixed inset-y-0 left-0 z-50 transform md:relative md:translate-x-0 transition-transform duration-300 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        {currentUser && (
          <Sidebar 
            groups={groups} 
            activeGroupId={activeGroupId || ''} 
            activeTopicId={activeTopicId}
            currentUser={currentUser}
            onSelectGroup={handleSelectGroup}
            onSelectTopic={(id) => { setIsAddingHub(false); setIsEditingProfile(false); setEditingGroup(null); setActiveTopicId(id); setIsMobileMenuOpen(false); }}
            onStartAddingHub={() => { setIsAddingHub(true); setIsEditingProfile(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
            onResetPortal={() => { setActiveGroupId(null); setActiveTopicId(null); setIsAddingHub(false); setIsEditingProfile(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
            onAddTopic={(groupId) => { setTopicModalGroupId(groupId); setIsTopicModalOpen(true); }}
            onJoinVoice={(mode) => { setSessionMode(mode); setSessionGroupName(activeGroup?.name || 'Session'); }}
            onEditProfile={() => { setIsEditingProfile(true); setIsAddingHub(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
            isOpen={isMobileMenuOpen}
            onClose={() => setIsMobileMenuOpen(false)}
          />
        )}
      </div>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <main className="flex-1 flex flex-col min-w-0 h-full relative">
        {isEditingProfile && currentUser ? (
          <UserProfileScreen 
            user={currentUser} 
            onUpdate={handleUpdateProfile} 
            onCancel={() => setIsEditingProfile(false)} 
          />
        ) : isAddingHub ? (
          <HubCreationScreen 
            onCreate={(name, type, avatar, desc, rules) => {
              const newGroup: Group = {
                id: `hub-${Date.now()}`,
                name, type, avatar, description: desc, rules,
                topics: type === GroupType.TOPICS ? [{ id: 't1', name: 'General', description: 'Main chat', icon: '🌐', messages: [], resources: [] }] : [],
                messages: [],
                members: [currentUser!, ...MOCK_MEMBERS],
                category: 'Community'
              };
              setGroups(prev => [...prev, newGroup]);
              setActiveGroupId(newGroup.id);
              setIsAddingHub(false);
            }} 
            onCancel={() => setIsAddingHub(false)} 
          />
        ) : activeGroup && currentUser ? (
          activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              currentUser={currentUser.name}
              onSendMessage={(text, att) => handleSendMessage(null, text, att)}
              onReactToMessage={(msgId, emoji) => handleReactToMessage(null, msgId, emoji)}
              onPinMessage={(msgId) => handlePinMessage(null, msgId)}
              onAddMember={() => {}}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
              onOpenVoice={(mode) => setSessionMode(mode)}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              currentUser={currentUser}
              activeTopicId={activeTopicId}
              onSelectTopic={setActiveTopicId}
              onOpenVoice={(mode) => setSessionMode(mode)}
              onSendMessage={handleSendMessage}
              onReactToMessage={handleReactToMessage}
              onPinMessage={handlePinMessage}
              onAddMember={() => {}}
              onUploadResource={() => {}}
              onStartAddingTopic={() => setIsTopicModalOpen(true)}
              onEditTopic={() => {}}
              onEditHub={() => setEditingGroup(activeGroup)}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          )
        ) : (
          <StartupScreen 
            groups={groups} 
            onSelectHub={handleSelectGroup} 
            onInitializeHub={() => setIsAddingHub(true)} 
          />
        )}
      </main>

      {sessionMode && (
        <div className={`fixed z-[100] transition-all duration-500 ease-in-out ${isSessionMinimized ? 'bottom-6 right-6 w-[320px] max-w-[90vw] h-auto pointer-events-auto' : 'inset-0 flex items-center justify-center p-2 sm:p-4 bg-[#020617]/80 backdrop-blur-xl pointer-events-auto'}`}>
          <MeetingSession 
            mode={sessionMode}
            isMinimized={isSessionMinimized}
            onMinimize={() => setIsSessionMinimized(!isSessionMinimized)}
            onClose={() => { setSessionMode(null); setSessionGroupName(null); }} 
            groupName={sessionGroupName || 'Active Session'} 
          />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GroupMember } from '../types';

interface AuthScreenProps {
  onRegister: (user: GroupMember & { phoneNumber: string }) => void;
}

const AVATAR_PRESETS = [
  'https://picsum.photos/150/150?u=101',
  'https://picsum.photos/150/150?u=102',
  'https://picsum.photos/150/150?u=103',
  'https://picsum.photos/150/150?u=104',
  'https://picsum.photos/150/150?u=105',
  'https://picsum.photos/150/150?u=106',
];

const AuthScreen: React.FC<AuthScreenProps> = ({ onRegister }) => {
  const [step, setStep] = useState(1); // 1: Phone, 2: OTP, 3: Name, 4: Avatar
  const [phoneNumber, setPhoneNumber] = useState('');
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [name, setName] = useState('');
  const [selectedAvatar, setSelectedAvatar] = useState(AVATAR_PRESETS[0]);
  const [customAvatarUrl, setCustomAvatarUrl] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const finalAvatar = customAvatarUrl.trim() || selectedAvatar;

  // Simulate sending OTP
  const handleSendCode = () => {
    if (phoneNumber.length > 8) {
      setIsLoading(true);
      setTimeout(() => {
        setIsLoading(false);
        setStep(2);
      }, 1500);
    }
  };

  // Check OTP (Hardcoded to 123456 for demo)
  useEffect(() => {
    if (step === 2 && otp.every(v => v !== '')) {
      const fullCode = otp.join('');
      if (fullCode === '123456') {
        setIsLoading(true);
        setTimeout(() => {
          setIsLoading(false);
          setStep(3);
        }, 1000);
      } else {
        // Reset OTP if wrong
        setTimeout(() => {
          setOtp(['', '', '', '', '', '']);
          otpRefs.current[0]?.focus();
        }, 500);
      }
    }
  }, [otp, step]);

  const handleOtpChange = (index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;
    const newOtp = [...otp];
    newOtp[index] = value.slice(-1);
    setOtp(newOtp);

    if (value && index < 5) {
      otpRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  };

  const handleComplete = () => {
    if (name.trim()) {
      const newUser: any = {
        id: `user-${Date.now()}`,
        name: name.trim(),
        avatar: finalAvatar,
        role: 'Owner',
        status: 'online',
        phoneNumber: phoneNumber
      };
      onRegister(newUser);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedAvatar(reader.result as string);
        setCustomAvatarUrl('');
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] bg-[#020617] flex items-center justify-center p-4 overflow-hidden">
      {/* Background Decor */}
      <div className="absolute inset-0 pointer-events-none">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[80%] h-[80%] bg-indigo-600/5 blur-[120px] rounded-full animate-pulse" />
        <div className="absolute inset-0 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] opacity-20 brightness-50 contrast-150" />
      </div>

      <div className="relative w-full max-w-lg bg-slate-950/40 backdrop-blur-3xl border border-slate-900 rounded-[3rem] p-8 md:p-12 shadow-2xl animate-in fade-in zoom-in-95 duration-700">
        {/* Step Indicator */}
        <div className="flex justify-center gap-2 mb-10">
          {[1, 2, 3, 4].map((s) => (
            <div 
              key={s} 
              className={`h-1 rounded-full transition-all duration-500 ${step === s ? 'w-10 bg-indigo-500 shadow-[0_0_10px_rgba(79,70,229,0.8)]' : step > s ? 'w-4 bg-indigo-900' : 'w-4 bg-slate-900'}`} 
            />
          ))}
        </div>

        {/* Phase 1: Phone Entry */}
        {step === 1 && (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="text-center space-y-3">
              <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter text-glow">Secure Uplink</h1>
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.4em]">Register Mobile Matrix</p>
            </div>

            <div className="space-y-4">
              <div className="flex gap-2">
                 <div className="bg-slate-900/50 border-2 border-slate-800 rounded-2xl px-4 py-5 text-indigo-400 font-black flex items-center gap-2 shrink-0">
                    <span className="text-sm">🌐</span>
                    <span>+</span>
                 </div>
                 <input 
                  type="tel" 
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value.replace(/\D/g, ''))}
                  className="w-full bg-slate-900/30 border-2 border-slate-800 rounded-2xl px-6 py-5 text-xl text-white font-black italic tracking-tighter outline-none focus:border-indigo-600 transition-all placeholder:text-slate-800 shadow-inner"
                  placeholder="Mobile Number..."
                  autoFocus
                />
              </div>

              <button 
                onClick={handleSendCode}
                disabled={phoneNumber.length < 8 || isLoading}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-700 disabled:opacity-50 text-white rounded-2xl font-black uppercase text-[11px] tracking-[0.4em] italic shadow-xl transition-all active:scale-[0.98] flex items-center justify-center gap-2"
              >
                {isLoading ? (
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                ) : 'Request Signal Code'}
              </button>
            </div>
            <p className="text-center text-[8px] text-slate-600 uppercase font-black tracking-widest">
              Encrypted transmission protocols active
            </p>
          </div>
        )}

        {/* Phase 2: OTP Verification */}
        {step === 2 && (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="text-center space-y-3">
              <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter text-glow">Signal Auth</h1>
              <p className="text-[9px] font-black text-indigo-500 uppercase tracking-[0.4em]">Enter Decryption Sequence (123456)</p>
            </div>

            <div className="flex justify-between gap-2">
              {otp.map((digit, idx) => (
                <input
                  key={idx}
                  ref={(el) => (otpRefs.current[idx] = el)}
                  type="text"
                  inputMode="numeric"
                  value={digit}
                  onChange={(e) => handleOtpChange(idx, e.target.value)}
                  onKeyDown={(e) => handleOtpKeyDown(idx, e)}
                  className="w-full aspect-square bg-slate-900/30 border-2 border-slate-800 rounded-xl text-center text-2xl text-white font-black outline-none focus:border-indigo-500 focus:bg-indigo-500/10 transition-all"
                  maxLength={1}
                />
              ))}
            </div>

            <button 
              onClick={() => setStep(1)}
              className="w-full text-[9px] font-black text-slate-600 hover:text-indigo-400 uppercase tracking-[0.3em] transition-colors"
            >
              Request New Signal
            </button>
          </div>
        )}

        {/* Phase 3: Name Entry */}
        {step === 3 && (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="text-center space-y-3">
              <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter text-glow">Identity Uplink</h1>
              <p className="text-[9px] font-black text-slate-500 uppercase tracking-[0.4em]">Initialize Alias Registry</p>
            </div>

            <div className="space-y-4">
              <input 
                type="text" 
                value={name}
                onChange={(e) => setName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && name.trim() && setStep(4)}
                className="w-full bg-slate-900/30 border-2 border-slate-800 rounded-2xl px-6 py-5 text-xl text-white font-black italic tracking-tighter outline-none focus:border-indigo-600 transition-all placeholder:text-slate-800 shadow-inner uppercase"
                placeholder="Designate Alias..."
                autoFocus
              />

              <button 
                onClick={() => setStep(4)}
                disabled={!name.trim()}
                className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 text-white rounded-2xl font-black uppercase text-[11px] tracking-[0.4em] italic shadow-xl transition-all active:scale-[0.98]"
              >
                Proceed to Signature
              </button>
            </div>
          </div>
        )}

        {/* Phase 4: Avatar Selection */}
        {step === 4 && (
          <div className="space-y-8 animate-in slide-in-from-right-4 duration-500">
            <div className="text-center space-y-3">
              <h2 className="text-3xl font-black text-white italic uppercase tracking-tighter">Visual Signature</h2>
              <p className="text-[9px] font-black text-indigo-500 uppercase tracking-[0.4em]">Confirm Biological Representation</p>
            </div>

            <div className="flex flex-col items-center gap-8">
              <div className="relative group">
                <div className="absolute inset-0 rounded-[2.5rem] bg-indigo-600/10 blur-2xl animate-pulse" />
                <img 
                  src={finalAvatar} 
                  className="w-32 h-32 rounded-[2.5rem] border-2 border-indigo-500/50 relative z-10 object-cover shadow-2xl bg-slate-950 transition-all duration-500" 
                  alt="Identity Preview" 
                />
              </div>

              <div className="grid grid-cols-4 gap-3 w-full">
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="aspect-square rounded-xl border-2 border-dashed border-slate-800 bg-slate-900/40 flex flex-col items-center justify-center gap-1 hover:border-indigo-500 hover:bg-indigo-600/10 transition-all group"
                >
                  <span className="text-lg">📤</span>
                  <span className="text-[6px] font-black uppercase text-slate-600 group-hover:text-indigo-400">Upload</span>
                </button>
                <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" accept="image/*" />

                {AVATAR_PRESETS.map((url) => (
                  <button
                    key={url}
                    onClick={() => { setSelectedAvatar(url); setCustomAvatarUrl(''); }}
                    className={`aspect-square rounded-xl border-2 overflow-hidden transition-all ${selectedAvatar === url && !customAvatarUrl ? 'border-indigo-500 ring-4 ring-indigo-500/10 scale-105' : 'border-slate-800 opacity-40 hover:opacity-100 hover:scale-105'}`}
                  >
                    <img src={url} className="w-full h-full object-cover" alt="" />
                  </button>
                ))}
              </div>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => setStep(3)}
                className="px-8 py-5 text-[10px] font-black text-slate-600 hover:text-white uppercase tracking-[0.2em] transition-colors"
              >
                Back
              </button>
              <button 
                onClick={handleComplete}
                className="flex-1 py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase text-[11px] tracking-[0.4em] italic shadow-[0_15px_40px_-10px_rgba(79,70,229,0.5)] transition-all active:scale-[0.98]"
              >
                Authorize Identity
              </button>
            </div>
          </div>
        )}

        {/* Footer Metrics */}
        <div className="mt-12 pt-8 border-t border-slate-900/50 flex items-center justify-center gap-6 opacity-30">
          <div className="flex flex-col items-center">
            <span className="text-[6px] font-black text-slate-600 uppercase tracking-widest mb-1">Security</span>
            <span className="text-[8px] font-black text-white uppercase tracking-tighter italic">SHA_512</span>
          </div>
          <div className="w-[1px] h-6 bg-slate-900" />
          <div className="flex flex-col items-center">
            <span className="text-[6px] font-black text-slate-600 uppercase tracking-widest mb-1">Status</span>
            <span className="text-[8px] font-black text-emerald-500 uppercase tracking-tighter italic">SYNCED</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AuthScreen;

