  );
};

export default VoiceChannel;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { VoiceParticipant } from '../types';

interface MeetingSessionProps {
  onClose: () => void;
  onMinimize?: () => void;
  isMinimized?: boolean;
  groupName: string;
  mode: 'voice' | 'video';
}

type ConnectionStatus = 'connecting' | 'stable' | 'unstable' | 'reconnecting' | 'failed';

const MeetingSession: React.FC<MeetingSessionProps> = ({ onClose, onMinimize, isMinimized = false, groupName, mode }) => {
  const [hasJoined, setHasJoined] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(mode === 'voice');
  const [participants, setParticipants] = useState<VoiceParticipant[]>([
    { id: '1', name: 'You', avatar: 'https://picsum.photos/80/80?u=1', isSpeaking: false },
    { id: 'ai', name: 'Nexus AI', avatar: 'https://picsum.photos/80/80?u=ai', isSpeaking: false },
    { id: '2', name: 'Sarah', avatar: 'https://picsum.photos/80/80?u=2', isSpeaking: false },
    { id: '3', name: 'Marcus', avatar: 'https://picsum.photos/80/80?u=3', isSpeaking: false },
  ]);

  const [connStatus, setConnStatus] = useState<ConnectionStatus>('connecting');
  const [error, setError] = useState<string | null>(null);
  const [streamQuality, setStreamQuality] = useState({ fps: 3, quality: 0.6 });
  const retryCountRef = useRef(0);
  const MAX_RETRIES = 3;

  const videoRef = useRef<HTMLVideoElement>(null);
  const lobbyVideoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const localStreamRef = useRef<MediaStream | null>(null);
  const sessionPromiseRef = useRef<any>(null);
  const frameIntervalRef = useRef<number | null>(null);

  useEffect(() => {
    const setupPreview = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ 
          audio: true, 
          video: mode === 'video' ? { width: 640, height: 480 } : false 
        });
        localStreamRef.current = stream;
        if (mode === 'video' && lobbyVideoRef.current) {
          lobbyVideoRef.current.srcObject = stream;
        }
      } catch (err) {
        console.error("Preview failed:", err);
        setError("Permissions denied.");
      }
    };
    setupPreview();
    return () => {
      localStreamRef.current?.getTracks().forEach(track => track.stop());
      if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
    };
  }, [mode]);

  const joinSession = useCallback(async () => {
    if (!localStreamRef.current) return;
    setConnStatus(retryCountRef.current > 0 ? 'reconnecting' : 'connecting');
    setHasJoined(true);

    try {
      // Fix: Direct API key usage and correct initialization
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      if (audioContextRef.current) audioContextRef.current.close();
      if (outputAudioContextRef.current) outputAudioContextRef.current.close();

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = localStreamRef.current;
      setTimeout(() => {
        if (mode === 'video' && videoRef.current) videoRef.current.srcObject = stream;
      }, 150);

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setConnStatus('stable');
            retryCountRef.current = 0;
            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              if (isMuted || connStatus === 'reconnecting') return;
              const inputData = e.inputBuffer.getChannelData(0);
              sessionPromise.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }))
                .catch(() => setConnStatus('unstable'));
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);

            if (mode === 'video') {
              if (frameIntervalRef.current) clearInterval(frameIntervalRef.current);
              frameIntervalRef.current = window.setInterval(() => {
                if (isVideoOff || !videoRef.current || !canvasRef.current || connStatus === 'reconnecting') return;
                const canvas = canvasRef.current;
                const video = videoRef.current;
                const ctx = canvas.getContext('2d', { alpha: false });
                if (!ctx) return;
                const scale = streamQuality.quality;
                canvas.width = video.videoWidth * scale;
                canvas.height = video.videoHeight * scale;
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const base64Data = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                sessionPromise.then(s => s.sendRealtimeInput({ media: { data: base64Data, mimeType: 'image/jpeg' } }));
              }, 1000 / streamQuality.fps);
            }
          },
          onmessage: async (message: LiveServerMessage) => {
            const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (audioData) {
              setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: true } : p));
              const ctx = outputAudioContextRef.current!;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
                setParticipants(prev => prev.map(p => p.id === 'ai' ? { ...p, isSpeaking: false } : p));
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }
          },
          onclose: () => {
            if (retryCountRef.current < MAX_RETRIES) {
              retryCountRef.current++;
              setTimeout(joinSession, 1000 * retryCountRef.current);
            } else {
              setConnStatus('failed');
            }
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          systemInstruction: `Interactive facilitator for ${groupName}.`
        }
      });
      sessionPromiseRef.current = sessionPromise;
    } catch (err) {
      setConnStatus('failed');
    }
  }, [groupName, mode, isMuted, isVideoOff, connStatus, streamQuality]);

  // Fix: Manual implementation of audio encoding/decoding as required by SDK guidelines
  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  };

  const getStatusBadge = () => {
    switch(connStatus) {
      case 'stable': return { color: 'bg-emerald-500', label: 'Strong' };
      case 'unstable': return { color: 'bg-amber-500', label: 'Weak' };
      case 'reconnecting': return { color: 'bg-indigo-500 animate-pulse', label: 'Syncing' };
      default: return { color: 'bg-red-500', label: 'Offline' };
    }
  };

  if (isMinimized && hasJoined) {
    return (
      <div className="glass-effect rounded-[1.5rem] p-3 shadow-xl border border-indigo-500/20 flex flex-col gap-2 animate-in duration-300">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-2 min-w-0">
             <div className="w-7 h-7 rounded-lg bg-indigo-600 flex items-center justify-center text-[10px]">
               {mode === 'video' ? '📹' : '🔊'}
             </div>
             <div className="min-w-0">
                <div className="text-[9px] font-black text-white uppercase truncate">{groupName}</div>
                <div className="flex items-center gap-1">
                   <div className={`w-1 h-1 rounded-full ${getStatusBadge().color}`}></div>
                   <span className="text-[7px] text-slate-400 font-bold uppercase">{getStatusBadge().label}</span>
                </div>
             </div>
          </div>
          <button onClick={onMinimize} className="p-1.5 hover:bg-slate-800 rounded-lg text-slate-400">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
          </button>
        </div>
        <div className="flex gap-2 items-center justify-center pt-1 border-t border-white/5">
           <button onClick={() => setIsMuted(!isMuted)} className={`p-2 rounded-lg text-xs ${isMuted ? 'bg-red-600' : 'bg-slate-800'}`}>{isMuted ? '🔇' : '🎤'}</button>
           <button onClick={onClose} className="p-2 bg-red-600 rounded-lg text-xs">🚪</button>
        </div>
      </div>
    );
  }

  if (!hasJoined) {
    return (
      <div className="w-full max-w-lg bg-slate-900 border border-slate-800 rounded-[2rem] shadow-2xl flex flex-col overflow-hidden animate-in fade-in duration-300 mx-auto">
        <div className="p-8 sm:p-10 flex flex-col items-center justify-center text-center">
          <div className="w-16 h-16 bg-indigo-600 rounded-2xl flex items-center justify-center text-2xl shadow-xl mb-5">
            {mode === 'video' ? '📹' : '🔊'}
          </div>
          <h2 className="text-2xl font-black text-white italic uppercase mb-1">Nexus Lobby</h2>
          <p className="text-indigo-400 text-[9px] font-bold tracking-widest uppercase mb-8">{groupName}</p>

          {mode === 'video' ? (
            <div className="w-full aspect-video bg-slate-950 rounded-2xl overflow-hidden border border-slate-800 relative shadow-xl mb-8">
              {!isVideoOff ? (
                <video ref={lobbyVideoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
              ) : (
                <div className="w-full h-full flex items-center justify-center bg-slate-900 text-3xl opacity-30">👤</div>
              )}
            </div>
          ) : (
            <div className="w-full py-10 bg-slate-950/50 rounded-2xl border border-slate-800/50 shadow-inner mb-8 flex flex-col items-center gap-3">
               <div className="w-16 h-16 rounded-full bg-slate-900 flex items-center justify-center border-2 border-slate-800 relative">
                  <span className="text-2xl">🎙️</span>
               </div>
               <span className="text-slate-600 font-bold uppercase tracking-widest text-[9px]">Interface Ready</span>
            </div>
          )}

          <div className="w-full max-w-xs space-y-3">
             <div className="flex justify-center gap-3">
               <button onClick={() => setIsMuted(!isMuted)} className={`flex-1 py-3 rounded-xl border transition-all text-[9px] font-bold uppercase tracking-widest ${isMuted ? 'bg-red-600 border-red-400 text-white' : 'bg-slate-900 border-slate-800 text-indigo-400'}`}>
                 {isMuted ? 'Muted' : 'Unmuted'}
               </button>
               {mode === 'video' && (
                 <button onClick={() => setIsVideoOff(!isVideoOff)} className={`flex-1 py-3 rounded-xl border transition-all text-[9px] font-bold uppercase tracking-widest ${isVideoOff ? 'bg-red-600 border-red-400 text-white' : 'bg-slate-900 border-slate-800 text-indigo-400'}`}>
                   {isVideoOff ? 'Cam Off' : 'Cam On'}
                 </button>
               )}
             </div>
             <button onClick={joinSession} className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Link Start</button>
             <button onClick={onClose} className="w-full text-slate-500 hover:text-white text-[9px] font-black uppercase tracking-widest">Cancel</button>
          </div>
        </div>
      </div>
    );
  }

  const badge = getStatusBadge();
  return (
    <div className="w-full max-w-5xl bg-slate-900 border border-slate-800 rounded-[2rem] shadow-2xl flex flex-col overflow-hidden max-h-[90vh] animate-in zoom-in-95 duration-200">
      <header className="p-4 sm:p-5 bg-slate-950/60 border-b border-slate-900 flex items-center justify-between">
        <div className="flex items-center gap-3 min-w-0">
           <div className="p-2.5 bg-indigo-600/20 rounded-xl text-indigo-400 shrink-0 text-sm">
             {mode === 'video' ? '📹' : '🔊'}
           </div>
           <div className="min-w-0">
             <div className="flex items-center gap-2 mb-0.5">
                <h2 className="text-base font-black text-white italic uppercase tracking-tight truncate">{groupName}</h2>
                <div className={`px-1.5 py-0.5 rounded-md ${badge.color} text-[7px] font-black text-white uppercase tracking-widest`}>
                   {badge.label}
                </div>
             </div>
             <p className="text-slate-600 text-[8px] font-bold tracking-widest uppercase">Live Interactive Uplink</p>
           </div>
        </div>
        <button onClick={onMinimize} className="p-2 hover:bg-slate-800 rounded-lg transition-all text-slate-400 shrink-0">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5" /></svg>
        </button>
      </header>

      <div className="flex-1 p-4 sm:p-6 overflow-y-auto bg-slate-950 custom-scrollbar">
        {(connStatus === 'connecting' || connStatus === 'reconnecting') ? (
          <div className="h-full flex flex-col items-center justify-center min-h-[250px]">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4"></div>
            <p className="text-indigo-400 font-bold uppercase tracking-widest text-[8px]">Syncing Feed...</p>
          </div>
        ) : (
          <div className={`grid gap-4 h-full ${mode === 'video' ? 'grid-cols-1 lg:grid-cols-4' : 'grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5'}`}>

            {mode === 'video' && (
              <div className="lg:col-span-3 aspect-video bg-slate-900 rounded-2xl overflow-hidden border border-slate-800 shadow-xl relative">
                {!isVideoOff ? (
                  <video ref={videoRef} autoPlay playsInline muted className="w-full h-full object-cover mirror" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-4xl opacity-20">👤</div>
                )}
                <div className="absolute bottom-4 left-4 px-3 py-1.5 bg-black/60 backdrop-blur-md rounded-xl text-[9px] font-black text-white border border-white/10 uppercase tracking-widest">You (Lecturer)</div>
              </div>
            )}

            <div className={`${mode === 'video' ? 'flex lg:flex-col gap-3 overflow-x-auto lg:overflow-y-auto' : 'contents'} custom-scrollbar`}>
               {participants.map(p => (
                 <div key={p.id} className={`p-3 rounded-2xl border transition-all shrink-0 ${mode === 'video' ? 'w-40 lg:w-full' : 'w-full'} ${p.isSpeaking ? 'bg-indigo-600/10 border-indigo-500' : 'bg-slate-900 border-slate-800'} flex items-center gap-3`}>
                    <img src={p.avatar} className={`w-10 h-10 rounded-xl border ${p.isSpeaking ? 'border-indigo-400' : 'border-slate-800'} shrink-0`} alt="" />
                    <div className="min-w-0">
                       <div className="text-[10px] font-black text-white truncate uppercase tracking-tight">{p.name}</div>
                       <div className="text-[8px] text-slate-600 font-bold uppercase tracking-widest mt-0.5">{p.isSpeaking ? 'Talking' : 'Idle'}</div>
                    </div>
                 </div>
               ))}
            </div>
          </div>
        )}
      </div>

      <footer className="p-4 sm:p-5 bg-slate-950/80 border-t border-slate-900 flex justify-center items-center gap-4">
        <button onClick={() => setIsMuted(!isMuted)} className={`p-4 rounded-xl transition-all ${isMuted ? 'bg-red-600 text-white shadow-lg' : 'bg-slate-800 text-slate-500 hover:text-white'}`}>
          {isMuted ? '🔇' : '🎤'}
        </button>

        {mode === 'video' && (
          <button onClick={() => setIsVideoOff(!isVideoOff)} className={`p-4 rounded-xl transition-all ${isVideoOff ? 'bg-red-600 text-white shadow-lg' : 'bg-slate-800 text-slate-500 hover:text-white'}`}>
            {isVideoOff ? '🚫' : '📹'}
          </button>
        )}

        <button onClick={onClose} className="px-8 sm:px-10 py-3 bg-red-600 hover:bg-red-500 text-white rounded-xl font-black uppercase text-[9px] tracking-widest transition-all active:scale-95 shadow-lg">
          End Session
        </button>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default MeetingSession;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  onSendMessage, 
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onToggleMenu, 
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setIsCameraLoading(false);
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        };
        onSendMessage("Visual signature captured.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {!hideHeader && (
        <header className="h-16 px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-2 text-indigo-400 hover:text-white transition-colors text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-2 text-indigo-400 hover:text-white transition-colors text-lg">🎥</button>
              </div>
            )}
            <button onClick={() => setShowMembers(!showMembers)} className={`p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
          <span className="text-[7px] font-black text-slate-600 uppercase tracking-widest ml-4">System Anchor</span>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
        {messages.map((m) => (
          <div key={m.id} id={`msg-${m.id}`} className={`flex gap-4 group animate-in slide-in-from-bottom-2 duration-300 ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-9 h-9 md:w-11 md:h-11 rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end" alt="" />
            <div className={`flex flex-col gap-1.5 max-w-[85%] md:max-w-[70%] ${m.sender === currentUser ? 'items-end' : ''}`}>
               <div className="flex items-center gap-2 px-1">
                 <span className="text-[10px] font-black text-white uppercase italic tracking-tighter">{m.sender === currentUser ? 'YOU' : m.sender}</span>
                 <span className="text-[8px] text-slate-700 font-bold uppercase tracking-widest">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               </div>

               <div className="relative group/bubble">
                 {/* Message Bubble */}
                 <div className={`relative px-5 py-3.5 rounded-[1.8rem] shadow-2xl border transition-all ${
                   m.sender === currentUser 
                     ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                     : 'bg-slate-900 text-slate-200 border-slate-800/80 rounded-tl-none'
                 } ${m.isPinned ? 'ring-2 ring-indigo-500/50 ring-offset-2 ring-offset-[#020617]' : ''}`}>

                   {m.isPinned && (
                     <div className="absolute -top-3 -left-3 bg-indigo-600 w-6 h-6 rounded-full flex items-center justify-center text-[10px] shadow-lg border border-indigo-400 z-10 animate-bounce">📌</div>
                   )}

                   <p className="text-sm md:text-base font-medium leading-relaxed whitespace-pre-wrap">{m.text}</p>

                   {m.attachment && (
                     <div className="mt-4 p-4 bg-black/30 rounded-2xl border border-white/5 flex items-center gap-4 group/att">
                        {m.attachment.type.startsWith('image/') && m.attachment.url ? (
                          <img src={m.attachment.url} className="w-full rounded-xl" alt="attached" />
                        ) : (
                          <>
                            <div className="w-12 h-12 bg-slate-950 rounded-xl flex items-center justify-center text-2xl shadow-inner">📄</div>
                            <div className="min-w-0">
                              <div className="text-[10px] font-black uppercase truncate text-white italic">{m.attachment.name}</div>
                              <div className="text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{m.attachment.size}</div>
                            </div>
                          </>
                        )}
                     </div>
                   )}

                   {m.poll && (
                     <div className="mt-4 space-y-3 bg-black/20 p-5 rounded-2xl border border-white/5 w-full md:min-w-[300px]">
                       <div className="text-xs font-black text-white uppercase tracking-widest italic mb-2">Tactical Inquiry: {m.poll.question}</div>
                       {m.poll.options.map((opt, idx) => {
                         const totalVotes = m.poll!.options.reduce((acc, o) => acc + o.votes.length, 0);
                         const percentage = totalVotes === 0 ? 0 : Math.round((opt.votes.length / totalVotes) * 100);
                         const hasVoted = opt.votes.includes(currentUser);
                         return (
                           <button 
                             key={idx}
                             onClick={() => onVotePoll(m.id, idx)}
                             className={`w-full relative h-10 rounded-xl overflow-hidden border transition-all group/opt ${hasVoted ? 'border-indigo-400/50' : 'border-slate-800/50 hover:border-slate-700'}`}
                           >
                             <div className={`absolute inset-0 h-full transition-all duration-1000 ${hasVoted ? 'bg-indigo-500/20' : 'bg-slate-800/10'}`} style={{ width: `${percentage}%` }} />
                             <div className="absolute inset-0 flex items-center justify-between px-4 z-10">
                                <span className={`text-[10px] font-black uppercase tracking-widest ${hasVoted ? 'text-indigo-300' : 'text-slate-400'}`}>{opt.text}</span>
                                <span className="text-[9px] font-black text-slate-500">{percentage}% ({opt.votes.length})</span>
                             </div>
                           </button>
                         );
                       })}
                     </div>
                   )}
                 </div>

                 {/* Message Actions Tray */}
                 <div className={`absolute top-0 flex items-center gap-1 bg-slate-900 border border-slate-800 rounded-full px-2 py-1 shadow-2xl transition-all duration-200 opacity-0 group-hover/bubble:opacity-100 ${m.sender === currentUser ? 'right-full mr-3' : 'left-full ml-3'}`}>
                    <button 
                      onClick={() => onPinMessage(m.id)}
                      className={`p-1.5 rounded-full transition-colors ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                    >
                      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z"/></svg>
                    </button>
                    <div className="relative">
                      <button 
                        onClick={() => setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id)}
                        className={`p-1.5 rounded-full hover:bg-slate-800 transition-colors ${activeReactionPicker === m.id ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white'}`}
                      >
                        <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
                      </button>

                      {activeReactionPicker === m.id && (
                        <div className="absolute bottom-full mb-2 left-1/2 -translate-x-1/2 bg-slate-900 border border-slate-800 p-2 rounded-2xl shadow-2xl flex gap-1 z-50 animate-in slide-in-from-bottom-2">
                           {COMMON_EMOJIS.slice(0, 8).map(emoji => (
                             <button key={emoji} onClick={() => { onReactToMessage(m.id, emoji); setActiveReactionPicker(null); }} className="hover:scale-125 transition-transform p-1.5 text-lg">{emoji}</button>
                           ))}
                        </div>
                      )}
                    </div>
                 </div>

                 {/* Reactions Display */}
                 {m.reactions && Object.keys(m.reactions).length > 0 && (
                   <div className={`flex flex-wrap gap-1 mt-2 ${m.sender === currentUser ? 'justify-end' : 'justify-start'}`}>
                      {Object.entries(m.reactions).map(([emoji, users]) => (
                        <button 
                          key={emoji} 
                          onClick={() => onReactToMessage(m.id, emoji)}
                          className={`px-2 py-0.5 rounded-full border text-[10px] font-black transition-all flex items-center gap-1.5 ${users.includes(currentUser) ? 'bg-indigo-600/20 border-indigo-500 text-indigo-400' : 'bg-slate-900/60 border-slate-800 text-slate-500 hover:text-slate-300'}`}
                        >
                          <span>{emoji}</span>
                          <span className="opacity-60">{users.length}</span>
                        </button>
                      ))}
                   </div>
                 )}
               </div>
            </div>
          </div>
        ))}
      </div>

      {/* Chat Input Area */}
      <footer className="p-4 md:p-8 bg-slate-950/80 backdrop-blur-3xl border-t border-slate-900/50 shrink-0 relative">
        <div className="max-w-6xl mx-auto flex items-end gap-3 md:gap-4">
          <div className="relative">
            <button 
              onClick={() => setShowActionMenu(!showActionMenu)}
              className={`w-12 h-12 md:w-14 md:h-14 rounded-2xl flex items-center justify-center text-xl transition-all shadow-xl active:scale-95 ${showActionMenu ? 'bg-indigo-600 text-white rotate-45' : 'bg-slate-900 text-slate-500 hover:text-white border border-slate-800'}`}
            >
              ➕
            </button>

            {showActionMenu && (
              <div className="absolute bottom-16 left-0 w-48 bg-slate-900 border border-slate-800 rounded-2xl shadow-2xl p-2 animate-in slide-in-from-bottom-2 duration-200 z-50">
                 <button onClick={() => startCamera()} className="w-full flex items-center gap-3 p-3 hover:bg-indigo-600/10 rounded-xl transition-colors text-left group">
                    <span className="text-lg">📸</span>
                    <span className="text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Visual Matrix</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 p-3 hover:bg-indigo-600/10 rounded-xl transition-colors text-left group">
                    <span className="text-lg">📄</span>
                    <span className="text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Data Packet</span>
                 </button>
                 <button onClick={() => setShowPollModal(true)} className="w-full flex items-center gap-3 p-3 hover:bg-indigo-600/10 rounded-xl transition-colors text-left group">
                    <span className="text-lg">📊</span>
                    <span className="text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Strategic Poll</span>
                 </button>
              </div>
            )}
          </div>

          <div className="flex-1 relative group flex items-end bg-slate-900/40 border border-slate-800 rounded-2xl overflow-hidden focus-within:border-indigo-600 transition-all">
            <button 
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className={`p-4 transition-colors ${showEmojiPicker ? 'text-indigo-400' : 'text-slate-600 hover:text-indigo-400'}`}
            >
               <svg className="w-6 h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
            </button>

            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit signal..."
              rows={1}
              className="w-full bg-transparent px-2 py-4 text-white text-sm md:text-base font-medium outline-none placeholder:text-slate-800 resize-none shadow-inner"
            />

            {showEmojiPicker && (
              <div className="absolute bottom-full mb-4 left-0 w-full max-w-sm bg-slate-950 border border-slate-800 rounded-3xl p-4 shadow-2xl z-50 animate-in slide-in-from-bottom-2">
                 <div className="grid grid-cols-8 gap-2">
                    {COMMON_EMOJIS.map(emoji => (
                      <button key={emoji} onClick={() => injectEmoji(emoji)} className="text-xl hover:scale-125 transition-transform p-1.5">{emoji}</button>
                    ))}
                 </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleSend}
            disabled={!input.trim()}
            className="w-12 h-12 md:w-14 md:h-14 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-800 text-white rounded-2xl flex items-center justify-center shadow-xl active:scale-95 transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
          </button>
        </div>
      </footer>

      {/* File Input */}
      <input type="file" hideHeader={true} ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

      {/* Poll Modal */}
      {showPollModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-[2.5rem] shadow-2xl p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-8">
               <h3 className="text-xl font-black text-white italic uppercase tracking-tighter">Strategic Query</h3>
               <button onClick={() => setShowPollModal(false)} className="text-slate-500 hover:text-white">✕</button>
            </div>

            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Inquiry Objective</label>
                <input 
                  type="text" 
                  value={pollQuestion}
                  onChange={(e) => setPollQuestion(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white font-bold outline-none focus:border-indigo-500"
                  placeholder="The query target..."
                />
              </div>

              <div className="space-y-3">
                <label className="text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Outcome Variables</label>
                {pollOptions.map((opt, idx) => (
                  <input 
                    key={idx}
                    type="text"
                    value={opt}
                    onChange={(e) => {
                      const newOpts = [...pollOptions];
                      newOpts[idx] = e.target.value;
                      setPollOptions(newOpts);
                    }}
                    className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-xs text-white outline-none focus:border-indigo-500"
                    placeholder={`Option ${idx + 1}`}
                  />
                ))}
                <button 
                  onClick={() => setPollOptions([...pollOptions, ''])}
                  className="w-full py-2.5 text-[8px] font-black text-indigo-500 uppercase tracking-[0.3em] hover:text-white transition-colors"
                >
                  ➕ Add Variable
                </button>
              </div>

              <div className="flex gap-4 pt-4">
                 <button onClick={() => setShowPollModal(false)} className="flex-1 py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Abort</button>
                 <button onClick={handleCreatePoll} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl font-black uppercase text-[9px] tracking-widest shadow-xl">Deploy Poll</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Camera UI Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[110] bg-black flex flex-col animate-in fade-in duration-300">
           <div className="relative flex-1 bg-slate-950 flex items-center justify-center">
             <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
             <div className="absolute inset-0 pointer-events-none border-[40px] border-black/40" />
             <div className="absolute top-10 left-1/2 -translate-x-1/2 flex flex-col items-center">
               <div className="text-white font-black italic tracking-tighter uppercase text-xl text-glow">Visual Scanner</div>
               <div className="text-[8px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-1">Matrix Uplink Active</div>
             </div>
           </div>

           <div className="h-40 bg-slate-950 border-t border-slate-900 flex items-center justify-around px-10">
              <button onClick={stopCamera} className="p-4 bg-slate-900 rounded-full text-slate-400 hover:text-white transition-colors">✕</button>
              <button onClick={capturePhoto} className="w-20 h-20 rounded-full border-4 border-indigo-500 p-1 group active:scale-95 transition-all">
                 <div className="w-full h-full rounded-full bg-white/10 group-hover:bg-indigo-500 transition-colors" />
              </button>
              <button onClick={flipCamera} className="p-4 bg-slate-900 rounded-full text-indigo-400 hover:text-white transition-colors">🔄</button>
           </div>
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  onSendMessage, 
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onToggleMenu, 
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setIsCameraLoading(false);
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        };
        onSendMessage("Visual signature captured.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden">
      {!hideHeader && (
        <header className="h-16 px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-2 text-indigo-400 hover:text-white transition-colors text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-2 text-indigo-400 hover:text-white transition-colors text-lg">🎥</button>
              </div>
            )}
            <button onClick={() => setShowMembers(!showMembers)} className={`p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
          <span className="text-[7px] font-black text-slate-600 uppercase tracking-widest ml-4">System Anchor</span>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
        {messages.map((m) => (
          <div key={m.id} id={`msg-${m.id}`} className={`flex gap-4 group animate-in slide-in-from-bottom-2 duration-300 ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-9 h-9 md:w-11 md:h-11 rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end" alt="" />
            <div className={`flex flex-col gap-1.5 max-w-[85%] md:max-w-[70%] ${m.sender === currentUser ? 'items-end' : ''}`}>
               <div className="flex items-center gap-2 px-1">
                 <span className="text-[10px] font-black text-white uppercase italic tracking-tighter">{m.sender === currentUser ? 'YOU' : m.sender}</span>
                 <span className="text-[8px] text-slate-700 font-bold uppercase tracking-widest">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               </div>

               <div className="relative group/bubble">
                 {/* Message Bubble */}
                 <div className={`relative px-5 py-3.5 rounded-[1.8rem] shadow-2xl border transition-all ${
                   m.sender === currentUser 
                     ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                     : 'bg-slate-900 text-slate-200 border-slate-800/80 rounded-tl-none'
                 } ${m.isPinned ? 'ring-2 ring-indigo-500/50 ring-offset-2 ring-offset-[#020617]' : ''}`}>

                   {m.isPinned && (
                     <div className="absolute -top-3 -left-3 bg-indigo-600 w-6 h-6 rounded-full flex items-center justify-center text-[10px] shadow-lg border border-indigo-400 z-10 animate-bounce">📌</div>
                   )}

                   <p className="text-sm md:text-base font-medium leading-relaxed whitespace-pre-wrap">{m.text}</p>

                   {m.attachment && (
                     <div className="mt-4 p-4 bg-black/30 rounded-2xl border border-white/5 flex items-center gap-4 group/att">
                        {m.attachment.type.startsWith('image/') && m.attachment.url ? (
                          <img src={m.attachment.url} className="w-full rounded-xl" alt="attached" />
                        ) : (
                          <>
                            <div className="w-12 h-12 bg-slate-950 rounded-xl flex items-center justify-center text-2xl shadow-inner">📄</div>
                            <div className="min-w-0">
                              <div className="text-[10px] font-black uppercase truncate text-white italic">{m.attachment.name}</div>
                              <div className="text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{m.attachment.size}</div>
                            </div>
                          </>
                        )}
                     </div>
                   )}

                   {m.poll && (
                     <div className="mt-4 space-y-3 bg-black/20 p-5 rounded-2xl border border-white/5 w-full md:min-w-[300px]">
                       <div className="text-xs font-black text-white uppercase tracking-widest italic mb-2">Tactical Inquiry: {m.poll.question}</div>
                       {m.poll.options.map((opt, idx) => {
                         const totalVotes = m.poll!.options.reduce((acc, o) => acc + o.votes.length, 0);
                         const percentage = totalVotes === 0 ? 0 : Math.round((opt.votes.length / totalVotes) * 100);
                         const hasVoted = opt.votes.includes(currentUser);
                         return (
                           <button 
                             key={idx}
                             onClick={() => onVotePoll(m.id, idx)}
                             className={`w-full relative h-10 rounded-xl overflow-hidden border transition-all group/opt ${hasVoted ? 'border-indigo-400/50' : 'border-slate-800/50 hover:border-slate-700'}`}
                           >
                             <div className={`absolute inset-0 h-full transition-all duration-1000 ${hasVoted ? 'bg-indigo-500/20' : 'bg-slate-800/10'}`} style={{ width: `${percentage}%` }} />
                             <div className="absolute inset-0 flex items-center justify-between px-4 z-10">
                                <span className={`text-[10px] font-black uppercase tracking-widest ${hasVoted ? 'text-indigo-300' : 'text-slate-400'}`}>{opt.text}</span>
                                <span className="text-[9px] font-black text-slate-500">{percentage}% ({opt.votes.length})</span>
                             </div>
                           </button>
                         );
                       })}
                     </div>
                   )}
                 </div>

                 {/* Message Actions Tray */}
                 <div className={`absolute top-0 flex items-center gap-1 bg-slate-900 border border-slate-800 rounded-full px-2 py-1 shadow-2xl transition-all duration-200 opacity-0 group-hover/bubble:opacity-100 ${m.sender === currentUser ? 'right-full mr-3' : 'left-full ml-3'}`}>
                    <button 
                      onClick={() => onPinMessage(m.id)}
                      className={`p-1.5 rounded-full transition-colors ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                    >
                      <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z"/></svg>
                    </button>
                    <div className="relative">
                      <button 
