             <div className="w-24 h-24 bg-slate-900/40 rounded-3xl flex items-center justify-center text-4xl mb-8 border border-slate-800 shadow-2xl text-slate-700">📡</div>
             <h2 className="text-3xl font-black text-white mb-4 italic tracking-tighter uppercase text-glow">System Idle</h2>
             <p className="text-slate-600 text-[10px] font-bold uppercase tracking-[0.5em] mb-12">Initialize module for uplink sequence</p>
             <button onClick={onToggleMenu} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-[0.4em] lg:hidden shadow-2xl active:scale-95 transition-all">Select Node</button>
          </div>
        ) : (
          <div className="flex flex-col h-full animate-in fade-in duration-300">
            {/* Master Header with Adaptive Segment Switcher */}
            <header className="bg-slate-950/60 backdrop-blur-3xl border-b border-slate-900 px-4 md:px-6 py-4 flex flex-col gap-4 z-10 shrink-0">
               <div className="flex items-center justify-between gap-4">
                  <div className="flex items-center gap-3 md:gap-5 min-w-0 flex-1">
                    <button onClick={onToggleMenu} className="p-2.5 bg-slate-900 rounded-xl md:hidden text-slate-500 border border-slate-800/50 shrink-0 shadow-lg">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
                    </button>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2 md:gap-3 mb-1">
                         <div className="flex items-center gap-1 md:gap-2 min-w-0">
                            <span className="text-indigo-500/50 font-black text-sm md:text-base">#</span>
                            <h2 className="text-lg md:text-xl font-black text-white leading-tight truncate uppercase italic tracking-tighter">{activeTopic.name}</h2>
