                           <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"/></svg>
                         </button>
                      </div>
                      <div className="flex items-center gap-2 overflow-hidden">
                         <span className="text-[9px] text-indigo-500 font-black uppercase tracking-[0.2em] leading-none shrink-0 hidden sm:inline">{group.name}</span>
                         {activeTopic.description && (
                           <>
                             <span className="w-1 h-1 rounded-full bg-slate-800 shrink-0 hidden sm:inline"></span>
                             <span className="text-[8px] md:text-[9px] text-slate-500 font-bold uppercase tracking-widest truncate max-w-xs">{activeTopic.description}</span>
