                      </div>
                    </div>
                  </div>

                  <div className="flex items-center gap-2 md:gap-4 shrink-0">
                    <div className="hidden md:flex items-center gap-1 bg-slate-900/50 p-1 rounded-xl border border-slate-800/50 shadow-inner mr-2">
                       <button onClick={() => setViewMode('discussion')} className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.1em] uppercase transition-all ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Uplink</button>
                       <button onClick={() => setViewMode('resources')} className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.1em] uppercase transition-all ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Library</button>
                       <button onClick={() => setViewMode('members')} className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-[0.1em] uppercase transition-all ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}>Nodes</button>
                    </div>

                    <div className="flex items-center gap-2">
                      <button onClick={() => onOpenVoice('voice')} className="p-2 md:p-2.5 text-indigo-400 hover:text-white transition-colors bg-slate-900/40 rounded-xl border border-slate-800/40">
                        <span className="text-base">🔊</span>
                      </button>
                      <button onClick={() => onOpenVoice('video')} className="p-2 md:p-2.5 text-indigo-400 hover:text-white transition-colors bg-slate-900/40 rounded-xl border border-slate-800/40">
                        <span className="text-base">🎥</span>
                      </button>
                    </div>
                  </div>
               </div>

               <div className="flex md:hidden items-center gap-1.5 bg-slate-900/40 p-1 rounded-xl border border-slate-800/50 w-full shadow-inner">
                  <button onClick={() => setViewMode('discussion')} className={`flex-1 px-4 py-2 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all duration-300 ${viewMode === 'discussion' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Uplink</button>
                  <button onClick={() => setViewMode('resources')} className={`flex-1 px-4 py-2 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all duration-300 ${viewMode === 'resources' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Library</button>
                  <button onClick={() => setViewMode('members')} className={`flex-1 px-4 py-2 rounded-lg text-[9px] font-black tracking-[0.2em] uppercase transition-all duration-300 ${viewMode === 'members' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-600 hover:text-slate-400'}`}>Nodes</button>
               </div>
            </header>

            <div className="flex-1 overflow-hidden">
              {viewMode === 'discussion' && (
                <ChatArea 
                  groupName={activeTopic.name} 
                  messages={activeTopic.messages} 
                  members={group.members} 
                  currentUser={currentUser.name}
                  groupDescription={group.description}
                  groupRules={group.rules}
                  onSendMessage={(text, attachment, poll) => onSendMessage(activeTopic.id, text, attachment, poll)} 
                  onVotePoll={(messageId, optIdx) => onVotePoll(activeTopic.id, messageId, optIdx)}
                  onReactToMessage={(messageId, emoji) => onReactToMessage(activeTopic.id, messageId, emoji)}
                  onPinMessage={(messageId) => onPinMessage(activeTopic.id, messageId)}
                  onAddMember={onAddMember} 
                  onToggleMenu={onToggleMenu}
                  onEditHub={onEditHub}
                  hideHeader={true}
                />
              )}
              {viewMode === 'resources' && (
                <div className="h-full overflow-y-auto p-6 md:p-10 bg-slate-950/40 custom-scrollbar">
                   <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                        <input type="file" ref={fileInputRef} onChange={handleFileSelect} className="hidden" />
                        <button onClick={() => fileInputRef.current?.click()} className="aspect-square bg-indigo-600/5 border-2 border-dashed border-indigo-500/20 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 hover:bg-indigo-600/10 transition-all group">
                           <span className="text-4xl group-hover:scale-125 transition-transform duration-500">➕</span>
                           <div className="text-center">
                              <span className="block text-[12px] font-black text-white uppercase italic tracking-tighter">Inject Archive</span>
                              <span className="block text-[8px] text-slate-700 font-bold uppercase tracking-widest mt-1">Maximum Linkage</span>
                           </div>
                        </button>
                        {activeTopic.resources.map((res, index) => (
                          <div key={res.id} className="bg-slate-900/50 border border-slate-800/80 p-6 rounded-[2.5rem] flex flex-col justify-between hover:bg-slate-900 transition-all shadow-2xl group relative overflow-hidden">
                             {/* Reordering Controls Overlay */}
                             <div className="absolute top-4 right-4 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-opacity z-20">
                                <button 
                                  onClick={() => onRearrangeResources(activeTopic.id, 'up', res.id)}
                                  disabled={index === 0}
                                  className="w-8 h-8 rounded-lg bg-indigo-600/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400 hover:bg-indigo-600 hover:text-white disabled:opacity-30 disabled:pointer-events-none transition-all"
                                >
                                   ▲
                                </button>
                                <button 
                                  onClick={() => onRearrangeResources(activeTopic.id, 'down', res.id)}
                                  disabled={index === activeTopic.resources.length - 1}
                                  className="w-8 h-8 rounded-lg bg-indigo-600/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400 hover:bg-indigo-600 hover:text-white disabled:opacity-30 disabled:pointer-events-none transition-all"
                                >
                                   ▼
                                </button>
                             </div>

                             <div className="flex items-center gap-5 mb-8">
                               <div className="w-14 h-14 bg-slate-950 rounded-2xl flex items-center justify-center text-3xl border border-slate-800/50 shadow-inner">{getFileIcon(res.type)}</div>
                               <div className="min-w-0 flex-1">
                                  <h5 className="font-black text-white truncate text-sm tracking-tighter uppercase italic mb-1">{res.name}</h5>
                                  <div className="flex items-center gap-2">
                                     <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest">{res.size}</span>
                                     <span className="w-1 h-1 rounded-full bg-slate-800"></span>
                                     <span className="text-[7px] text-indigo-500/80 font-black uppercase tracking-tighter">Chat_Synced</span>
                                  </div>
                               </div>
                             </div>
                             <div className="flex items-center justify-between pt-6 border-t border-slate-800/40">
                                <button className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-xl active:scale-95">Download</button>
                             </div>
                          </div>
                        ))}
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-6 md:p-10 bg-slate-950/40 custom-scrollbar">
                   <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                      {group.members.map(member => (
                        <div key={member.id} className="bg-slate-900/50 border border-slate-800/80 p-6 rounded-[2.5rem] flex items-center gap-5 hover:bg-slate-900 transition-all shadow-2xl group">
                           <div className="relative shrink-0">
                             <img src={member.avatar} className="w-14 h-14 rounded-2xl object-cover border-2 border-slate-800 shadow-xl" alt="" />
                             <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-4 border-slate-950 ${member.status === 'online' ? 'bg-emerald-500 pulse-indicator' : 'bg-slate-800'}`}></div>
                           </div>
                           <div className="flex-1 min-w-0">
                             <div className="font-black text-white text-sm truncate uppercase italic tracking-tighter leading-none mb-2">{member.name}</div>
                             <div className={`inline-flex px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest border ${getRoleColor(member.role)}`}>{member.role}</div>
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DashboardArea;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatArea from './components/ChatArea';
import DashboardArea from './components/DashboardArea';
import MeetingSession from './components/MeetingSession';
import HubCreationScreen from './components/HubCreationScreen';
import StartupScreen from './components/StartupScreen';
import UserProfileScreen from './components/UserProfileScreen';
import AuthScreen from './components/AuthScreen';
import { Group, GroupType, Message, Attachment, Resource, Topic, GroupMember, Poll } from './types';

const MOCK_MEMBERS: GroupMember[] = [
  { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', role: 'AI Assistant', status: 'online' },
  { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', role: 'Admin', status: 'online' },
  { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', role: 'Member', status: 'offline' },
  { id: '4', name: 'Elena Rodriguez', avatar: 'https://picsum.photos/80/80?u=4', role: 'Member', status: 'online' },
];

const INITIAL_GROUPS: Group[] = [
  {
    id: 'edu-1',
    name: 'Advanced Mathematics',
    description: 'High-level synthesis of multivariable calculus and abstract algebra for research students.',
    rules: '1. Academic integrity is mandatory. 2. Support peers. 3. AI use permitted for clarification only.',
    type: GroupType.TOPICS,
    category: 'Education',
    members: MOCK_MEMBERS,
    topics: [
      { 
        id: 't1', 
        name: 'Calculus III', 
        description: 'Multivariable calculus resources and lecture notes.', 
        icon: '📐',
        messages: [],
        resources: [
          { id: 'r1', name: 'Lecture_Notes_Week1.pdf', type: 'application/pdf', size: '2.4 MB', uploadedBy: 'Prof. Smith', date: new Date() }
        ]
      },
      { 
        id: 't2', 
        name: 'Linear Algebra', 
        description: 'Matrices, vectors, and linear transformations.', 
        icon: '📊',
        messages: [],
        resources: []
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=100&h=100&fit=crop'
  }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<GroupMember | null>(null);
  const [isRegistered, setIsRegistered] = useState(false);
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [isAddingHub, setIsAddingHub] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);

  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [sessionGroupName, setSessionGroupName] = useState<string | null>(null);
  const [isSessionMinimized, setIsSessionMinimized] = useState(false);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('nexus_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      setCurrentUser(user);
      setIsRegistered(true);
    }
  }, []);

  const handleRegister = (user: GroupMember) => {
    localStorage.setItem('nexus_user', JSON.stringify(user));
    setCurrentUser(user);
    setIsRegistered(true);
    setGroups(prev => prev.map(g => ({
      ...g,
      members: [user, ...g.members]
    })));
  };

  const handleSelectGroup = (id: string) => {
    setIsAddingHub(false);
    setIsEditingProfile(false);
    setEditingGroup(null);
    setActiveGroupId(id);
    const selectedGroup = groups.find(g => g.id === id);
    if (selectedGroup && selectedGroup.type === GroupType.TOPICS && selectedGroup.topics.length > 0) {
      setActiveTopicId(selectedGroup.topics[0].id);
    } else {
      setActiveTopicId(null);
    }
    setIsMobileMenuOpen(false);
  };

  const handleDeleteGroup = (groupId: string) => {
    if (window.confirm("Confirm deletion of this Hub? All synchronization and data packets will be lost.")) {
      setGroups(prev => prev.filter(g => g.id !== groupId));
      setActiveGroupId(null);
      setActiveTopicId(null);
      setEditingGroup(null);
    }
  };

  const handleUpdateGroup = (groupId: string, name: string, type: GroupType, avatar: string, description?: string, rules?: string) => {
    setGroups(prev => prev.map(g => {
      if (g.id !== groupId) return g;
      return { ...g, name, type, avatar, description, rules };
    }));
    setEditingGroup(null);
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment, poll?: Poll) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: `msg-${Date.now()}`,
      sender: currentUser.name,
      text,
      timestamp: new Date(),
      avatar: currentUser.avatar,
      attachment,
      poll,
      reactions: {},
      isPinned: false
    };

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;

      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => {
            if (t.id !== topicIdOrNull) return t;

            let updatedResources = [...t.resources];
            if (attachment) {
              updatedResources.push({
                id: `res-${Date.now()}`,
                name: attachment.name,
                type: attachment.type,
                size: attachment.size,
                url: attachment.url,
                uploadedBy: currentUser.name,
                date: new Date()
              });
            }

            return { 
              ...t, 
              messages: [...t.messages, newMessage],
              resources: updatedResources
            };
          })
        };
      }
    }));
  };

  const handleRearrangeResources = (topicId: string, direction: 'up' | 'down', resourceId: string) => {
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      return {
        ...g,
        topics: g.topics.map(t => {
          if (t.id !== topicId) return t;
          const newResources = [...t.resources];
          const index = newResources.findIndex(r => r.id === resourceId);
          if (index === -1) return t;

          const targetIndex = direction === 'up' ? index - 1 : index + 1;
          if (targetIndex < 0 || targetIndex >= newResources.length) return t;

          [newResources[index], newResources[targetIndex]] = [newResources[targetIndex], newResources[index]];
          return { ...t, resources: newResources };
        })
      };
    }));
  };

  const handleVotePoll = (topicIdOrNull: string | null, messageId: string, optionIndex: number) => {
    if (!currentUser) return;
    const userName = currentUser.name;

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;

      const updateMessage = (messages: Message[]) => {
        return messages.map(m => {
          if (m.id !== messageId || !m.poll) return m;

          const newOptions = m.poll.options.map((opt, idx) => {
            const hasVoted = opt.votes.includes(userName);
            let newVotes = [...opt.votes];

            if (idx === optionIndex) {
              if (hasVoted) {
                newVotes = newVotes.filter(v => v !== userName);
              } else {
                newVotes.push(userName);
              }
            } else {
              newVotes = newVotes.filter(v => v !== userName);
            }

            return { ...opt, votes: newVotes };
          });

          return { ...m, poll: { ...m.poll, options: newOptions } };
        });
      };

      if (g.type === GroupType.STANDARD) {
        return { ...g, messages: updateMessage(g.messages) };
      } else {
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessage(t.messages) } : t)
        };
      }
    }));
  };

  const handleReactToMessage = (topicIdOrNull: string | null, messageId: string, emoji: string) => {
    if (!currentUser) return;
    const userName = currentUser.name;
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      const updateMessage = (messages: Message[]) => {
        return messages.map(m => {
          if (m.id !== messageId) return m;
          const reactions = { ...(m.reactions || {}) };
          const users = [...(reactions[emoji] || [])];
          if (users.includes(userName)) {
            const newUsers = users.filter(u => u !== userName);
            if (newUsers.length === 0) delete reactions[emoji];
            else reactions[emoji] = newUsers;
          } else {
            reactions[emoji] = [...users, userName];
          }
          return { ...m, reactions };
        });
      };
      if (g.type === GroupType.STANDARD) return { ...g, messages: updateMessage(g.messages) };
      else return { ...g, topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessage(t.messages) } : t) };
    }));
  };

  const handlePinMessage = (topicIdOrNull: string | null, messageId: string) => {
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      const updateMessage = (messages: Message[]) => messages.map(m => m.id === messageId ? { ...m, isPinned: !m.isPinned } : m);
      if (g.type === GroupType.STANDARD) return { ...g, messages: updateMessage(g.messages) };
      else return { ...g, topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessage(t.messages) } : t) };
    }));
  };

  const handleUpdateProfile = (updatedUser: Partial<GroupMember>) => {
    if (!currentUser) return;
    const newUser = { ...currentUser, ...updatedUser };
    localStorage.setItem('nexus_user', JSON.stringify(newUser));
    setCurrentUser(newUser);
    setGroups(prev => prev.map(g => ({
      ...g,
      members: g.members.map(m => m.id === currentUser.id ? { ...m, ...updatedUser } : m)
    })));
    setIsEditingProfile(false);
  };

  if (!isRegistered) {
    return <AuthScreen onRegister={handleRegister} />;
  }

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#020617] text-slate-200 selection:bg-indigo-500/30">
      <div className={`fixed inset-y-0 left-0 z-50 transform md:relative md:translate-x-0 transition-transform duration-300 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        {currentUser && (
          <Sidebar 
            groups={groups} 
            activeGroupId={activeGroupId || ''} 
            activeTopicId={activeTopicId}
            currentUser={currentUser}
            onSelectGroup={handleSelectGroup}
            onSelectTopic={(id) => { setIsAddingHub(false); setIsEditingProfile(false); setEditingGroup(null); setActiveTopicId(id); setIsMobileMenuOpen(false); }}
            onStartAddingHub={() => { setIsAddingHub(true); setIsEditingProfile(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
            onResetPortal={() => { setActiveGroupId(null); setActiveTopicId(null); setIsAddingHub(false); setIsEditingProfile(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
            onAddTopic={(groupId) => { setIsTopicModalOpen(true); }}
            onJoinVoice={(mode) => { setSessionMode(mode); setSessionGroupName(activeGroup?.name || 'Session'); }}
            onEditProfile={() => { setIsEditingProfile(true); setIsAddingHub(false); setEditingGroup(null); setIsMobileMenuOpen(false); }}
            isOpen={isMobileMenuOpen}
            onClose={() => setIsMobileMenuOpen(false)}
          />
        )}
      </div>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 md:hidden" onClick={() => setIsMobileMenuOpen(false)} />
      )}

      <main className="flex-1 flex flex-col min-w-0 h-full relative">
        {isEditingProfile && currentUser ? (
          <UserProfileScreen 
            user={currentUser} 
            onUpdate={handleUpdateProfile} 
            onCancel={() => setIsEditingProfile(false)} 
          />
        ) : isAddingHub ? (
          <HubCreationScreen 
            onCreate={(name, type, avatar, desc, rules) => {
              const newGroup: Group = {
                id: `hub-${Date.now()}`,
                name, type, avatar, description: desc, rules,
                topics: type === GroupType.TOPICS ? [{ id: 't1', name: 'General', description: 'Main chat', icon: '🌐', messages: [], resources: [] }] : [],
                messages: [],
                members: [currentUser!, ...MOCK_MEMBERS],
                category: 'Community'
              };
              setGroups(prev => [...prev, newGroup]);
              setActiveGroupId(newGroup.id);
              setIsAddingHub(false);
            }} 
            onCancel={() => setIsAddingHub(false)} 
          />
        ) : editingGroup ? (
          <HubCreationScreen 
            initialData={editingGroup}
            onCreate={(name, type, avatar, desc, rules) => handleUpdateGroup(editingGroup.id, name, type, avatar, desc, rules)}
            onCancel={() => setEditingGroup(null)}
          />
        ) : activeGroup && currentUser ? (
          activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              currentUser={currentUser.name}
              onSendMessage={(text, att, poll) => handleSendMessage(null, text, att, poll)}
              onVotePoll={(msgId, optIdx) => handleVotePoll(null, msgId, optIdx)}
              onReactToMessage={(msgId, emoji) => handleReactToMessage(null, msgId, emoji)}
              onPinMessage={(msgId) => handlePinMessage(null, msgId)}
              onAddMember={() => {}}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
              onOpenVoice={(mode) => setSessionMode(mode)}
              onEditHub={() => setEditingGroup(activeGroup)}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              currentUser={currentUser}
              activeTopicId={activeTopicId}
              onSelectTopic={setActiveTopicId}
              onOpenVoice={(mode) => setSessionMode(mode)}
              onSendMessage={handleSendMessage}
              onVotePoll={handleVotePoll}
              onReactToMessage={handleReactToMessage}
              onPinMessage={handlePinMessage}
              onRearrangeResources={handleRearrangeResources}
              onAddMember={() => {}}
              onUploadResource={(topicId, res) => {
                setGroups(prev => prev.map(g => {
                   if (g.id !== activeGroupId) return g;
                   return {
                     ...g,
                     topics: g.topics.map(t => t.id === topicId ? { ...t, resources: [...t.resources, { ...res, id: `res-${Date.now()}`, uploadedBy: currentUser.name, date: new Date() }] } : t)
                   };
                }));
              }}
              onStartAddingTopic={() => setIsTopicModalOpen(true)}
              onEditTopic={() => {}}
              onEditHub={() => setEditingGroup(activeGroup)}
              onDeleteHub={() => handleDeleteGroup(activeGroup.id)}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          )
        ) : (
          <StartupScreen 
            groups={groups} 
            onSelectHub={handleSelectGroup} 
            onInitializeHub={() => setIsAddingHub(true)} 
          />
        )}
      </main>

      {/* Topic Addition Modal */}
      {isTopicModalOpen && activeGroupId && (
        <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-md flex items-center justify-center p-6">
           <div className="bg-slate-900 border border-slate-800 rounded-[2rem] w-full max-w-md p-8 animate-in zoom-in-95">
              <h3 className="text-xl font-black text-white italic uppercase tracking-tighter mb-6">Inject New Module</h3>
              <input 
                id="topic-name-input"
                type="text" 
                placeholder="Module Designation..."
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-5 py-4 text-white font-bold mb-6 outline-none focus:border-indigo-600"
              />
              <div className="flex gap-4">
                 <button onClick={() => setIsTopicModalOpen(false)} className="flex-1 py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Abort</button>
                 <button 
                  onClick={() => {
                    const name = (document.getElementById('topic-name-input') as HTMLInputElement).value;
                    if (name.trim()) {
                      setGroups(prev => prev.map(g => {
                        if (g.id !== activeGroupId) return g;
                        const newTopic: Topic = { id: `t-${Date.now()}`, name, description: '', icon: '🛰️', messages: [], resources: [] };
                        return { ...g, topics: [...g.topics, newTopic] };
                      }));
                      setIsTopicModalOpen(false);
                    }
                  }}
                  className="flex-1 py-4 bg-indigo-600 text-white rounded-xl font-black uppercase text-[9px] tracking-widest"
                 >
                   Deploy Module
                 </button>
              </div>
           </div>
        </div>
      )}

      {sessionMode && (
        <div className={`fixed z-[100] transition-all duration-500 ease-in-out ${isSessionMinimized ? 'bottom-6 right-6 w-[320px] max-w-[90vw] h-auto pointer-events-auto' : 'inset-0 flex items-center justify-center p-2 sm:p-4 bg-[#020617]/80 backdrop-blur-xl pointer-events-auto'}`}>
          <MeetingSession 
            mode={sessionMode}
            isMinimized={isSessionMinimized}
            onMinimize={() => setIsSessionMinimized(!isSessionMinimized)}
            onClose={() => { setSessionMode(null); setSessionGroupName(null); }} 
            groupName={sessionGroupName || 'Active Session'} 
          />
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Group, Topic, Attachment, Resource, GroupMember, Poll } from '../types';
import ChatArea from './ChatArea';

interface DashboardAreaProps {
  group: Group;
  currentUser: GroupMember;
  activeTopicId: string | null;
  onSelectTopic: (id: string) => void;
  onOpenVoice: (mode: 'voice' | 'video') => void;
  onSendMessage: (topicId: string, text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (topicId: string, messageId: string, optionIndex: number) => void;
  onReactToMessage: (topicId: string, messageId: string, emoji: string) => void;
  onPinMessage: (topicId: string, messageId: string) => void;
  onRearrangeResources: (topicId: string, direction: 'up' | 'down', resourceId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onUploadResource: (topicId: string, resource: Omit<Resource, 'id' | 'uploadedBy' | 'date'>) => void;
  onStartAddingTopic: () => void;
  onEditTopic: (topic: Topic) => void;
  onEditHub: () => void;
  onDeleteHub: () => void;
  onToggleMenu: () => void;
}

const DashboardArea: React.FC<DashboardAreaProps> = ({ 
  group, 
  currentUser,
  activeTopicId, 
  onSelectTopic, 
  onOpenVoice, 
  onSendMessage,
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onRearrangeResources,
  onAddMember,
  onUploadResource,
  onStartAddingTopic,
  onEditTopic,
  onEditHub,
  onDeleteHub,
  onToggleMenu
}) => {
  const [viewMode, setViewMode] = useState<'discussion' | 'resources' | 'members'>('discussion');
  const [showHubSettings, setShowHubSettings] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const activeTopic = group.topics.find(t => t.id === activeTopicId);

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return '📕';
    if (type.includes('excel')) return '📊';
    if (type.includes('image')) return '🖼️';
    return '📁';
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && activeTopic) {
      const sizeStr = file.size > 1024 * 1024 
        ? `${(file.size / (1024 * 1024)).toFixed(1)} MB` 
        : `${(file.size / 1024).toFixed(1)} KB`;

      onUploadResource(activeTopic.id, {
        name: file.name,
        type: file.type || 'application/octet-stream',
        size: sizeStr
      });
      e.target.value = '';
    }
  };

  const getRoleColor = (role: string) => {
    switch(role) {
      case 'Owner': return 'bg-rose-500/10 text-rose-500 border-rose-500/20';
      case 'Admin': return 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
      case 'AI Assistant': return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      default: return 'bg-slate-900 text-slate-600 border-slate-800';
    }
  };

  return (
    <div className="flex h-full bg-slate-950 relative overflow-hidden">
      {/* High-Density Module Matrix - Tablet and Desktop Sidebar */}
      <div className="w-64 bg-slate-950/40 border-r border-slate-900/50 hidden lg:flex flex-col shrink-0 custom-scrollbar overflow-y-auto">
        <div className="p-6 border-b border-slate-900/30 flex items-center justify-between">
          <div className="font-black uppercase tracking-[0.2em] text-[9px] text-slate-600 italic">Core Modules</div>
          <button 
            onClick={() => setShowHubSettings(true)}
            className="text-indigo-500 hover:text-white transition-colors p-1.5 bg-slate-900/40 rounded-lg border border-slate-800/40"
            title="Hub Intelligence & Management"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z"/><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/></svg>
          </button>
        </div>

        <div className="px-3 py-6 space-y-1.5">
          {group.topics.map((topic) => (
            <button
              key={topic.id}
              onClick={() => onSelectTopic(topic.id)}
              className={`w-full text-left p-4 rounded-2xl flex items-center transition-all duration-300 border group ${
                activeTopicId === topic.id 
                  ? 'bg-indigo-600/15 text-indigo-400 border-indigo-500/40 shadow-xl' 
                  : 'border-transparent text-slate-600 hover:text-slate-400 hover:bg-slate-900/60'
              }`}
            >
              <div className="min-w-0 flex-1">
                <span className="block truncate font-black text-[11px] tracking-tight uppercase italic leading-none mb-1.5 group-hover:tracking-wider transition-all duration-500">{topic.name}</span>
                <span className="block text-[8px] text-slate-700 font-bold uppercase tracking-widest truncate">{topic.description || 'Primary Objective'}</span>
              </div>
            </button>
          ))}

          <button 
            onClick={() => setShowHubSettings(true)}
            className="w-full text-left p-4 rounded-2xl flex items-center gap-4 text-slate-700 hover:text-slate-400 border border-dashed border-slate-900 mt-6 group transition-all hover:bg-slate-900/30"
          >
            <span className="text-xl opacity-40">⚙️</span>
            <span className="truncate flex-1 text-[10px] font-black uppercase tracking-widest">Hub Controls</span>
          </button>
        </div>

        <div className="mt-auto p-5 border-t border-slate-900/30 bg-slate-950/20">
           <div className="space-y-4">
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Active Nodes</span>
                 <span className="text-indigo-500">{group.members.length}</span>
              </div>
              <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-widest">
                 <span className="text-slate-700">Sync Status</span>
                 <span className="text-emerald-500 text-glow">STABLE</span>
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col min-w-0 h-full relative">
        {!activeTopic ? (
          <div className="flex flex-col h-full items-center justify-center p-12 text-center animate-in fade-in duration-700">
             <div className="w-24 h-24 bg-slate-900/40 rounded-3xl flex items-center justify-center text-4xl mb-8 border border-slate-800 shadow-2xl text-slate-700">📡</div>
             <h2 className="text-3xl font-black text-white mb-4 italic tracking-tighter uppercase text-glow">System Idle</h2>
