                                <button 
                                  onClick={() => onRearrangeResources(activeTopic.id, 'up', res.id)}
                                  disabled={index === 0}
                                  className="w-8 h-8 rounded-lg bg-indigo-600/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400 hover:bg-indigo-600 hover:text-white disabled:opacity-30 disabled:pointer-events-none transition-all"
                                >
                                   ▲
                                </button>
                                <button 
                                  onClick={() => onRearrangeResources(activeTopic.id, 'down', res.id)}
                                  disabled={index === activeTopic.resources.length - 1}
                                  className="w-8 h-8 rounded-lg bg-indigo-600/20 border border-indigo-500/30 flex items-center justify-center text-indigo-400 hover:bg-indigo-600 hover:text-white disabled:opacity-30 disabled:pointer-events-none transition-all"
                                >
                                   ▼
