                                  </div>
                               </div>
                             </div>
                             <div className="flex items-center justify-between pt-6 border-t border-slate-800/40">
                                <button className="w-full py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all shadow-xl active:scale-95">Download</button>
                             </div>
                          </div>
                        ))}
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-6 md:p-10 bg-slate-950/40 custom-scrollbar">
                   <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                      {group.members.map(member => (
                        <div key={member.id} className="bg-slate-900/50 border border-slate-800/80 p-6 rounded-[2.5rem] flex items-center gap-5 hover:bg-slate-900 transition-all shadow-2xl group">
                           <div className="relative shrink-0">
                             <img src={member.avatar} className="w-14 h-14 rounded-2xl object-cover border-2 border-slate-800 shadow-xl" alt="" />
                             <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-4 border-slate-950 ${member.status === 'online' ? 'bg-emerald-500 pulse-indicator' : 'bg-slate-800'}`}></div>
