                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Hub Management Modal */}
      {showHubSettings && (
        <div className="fixed inset-0 z-[120] bg-black/80 backdrop-blur-xl flex items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="bg-slate-900 border border-slate-800 rounded-[3rem] w-full max-w-xl shadow-[0_30px_100px_-20px_rgba(0,0,0,0.8)] overflow-hidden animate-in zoom-in-95 duration-200">
