import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  onSendMessage, 
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onToggleMenu, 
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setIsCameraLoading(false);
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        };
        onSendMessage("Visual signature captured.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden w-full min-w-0">
      {!hideHeader && (
        <header className="h-16 px-4 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🎥</button>
              </div>
            )}
            <button onClick={() => setShowMembers(!showMembers)} className={`p-1.5 md:p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
          <span className="text-[7px] font-black text-slate-600 uppercase tracking-widest ml-4 hidden sm:inline">System Anchor</span>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar w-full overflow-x-hidden">
        {messages.map((m) => (
          <div key={m.id} id={`msg-${m.id}`} className={`flex gap-3 md:gap-4 group animate-in slide-in-from-bottom-2 duration-300 ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-8 h-8 md:w-11 md:h-11 rounded-xl md:rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end shrink-0" alt="" />
            <div className={`flex flex-col gap-1.5 max-w-[85%] md:max-w-[70%] min-w-0 ${m.sender === currentUser ? 'items-end' : ''}`}>
               <div className="flex items-center gap-2 px-1">
                 <span className="text-[9px] md:text-[10px] font-black text-white uppercase italic tracking-tighter truncate">{m.sender === currentUser ? 'YOU' : m.sender}</span>
                 <span className="text-[7px] md:text-[8px] text-slate-700 font-bold uppercase tracking-widest shrink-0">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               </div>

               <div className="relative group/bubble w-full min-w-0">
                 {/* Message Bubble */}
                 <div className={`relative px-4 py-3 md:px-5 md:py-3.5 rounded-[1.5rem] md:rounded-[1.8rem] shadow-2xl border transition-all w-fit max-w-full ${
                   m.sender === currentUser 
                     ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none ml-auto' 
                     : 'bg-slate-900 text-slate-200 border-slate-800/80 rounded-tl-none'
                 } ${m.isPinned ? 'ring-2 ring-indigo-500/50 ring-offset-2 ring-offset-[#020617]' : ''}`}>

                   {m.isPinned && (
                     <div className="absolute -top-3 -left-3 bg-indigo-600 w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[10px] shadow-lg border border-indigo-400 z-10 animate-bounce">📌</div>
                   )}

                   <p className="text-sm md:text-base font-medium leading-relaxed whitespace-pre-wrap break-words">{m.text}</p>

                   {m.attachment && (
                     <div className="mt-3 md:mt-4 p-3 md:p-4 bg-black/30 rounded-xl md:rounded-2xl border border-white/5 flex items-center gap-3 md:gap-4 group/att">
                        {m.attachment.type.startsWith('image/') && m.attachment.url ? (
                          <img src={m.attachment.url} className="w-full rounded-lg md:rounded-xl" alt="attached" />
                        ) : (
                          <>
                            <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-950 rounded-lg md:rounded-xl flex items-center justify-center text-xl md:text-2xl shadow-inner shrink-0">📄</div>
                            <div className="min-w-0">
                              <div className="text-[9px] md:text-[10px] font-black uppercase truncate text-white italic">{m.attachment.name}</div>
                              <div className="text-[7px] md:text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{m.attachment.size}</div>
                            </div>
                          </>
                        )}
                     </div>
                   )}

                   {m.poll && (
                     <div className="mt-3 md:mt-4 space-y-2 md:space-y-3 bg-black/20 p-4 md:p-5 rounded-xl md:rounded-2xl border border-white/5 w-full md:min-w-[300px]">
                       <div className="text-[10px] md:text-xs font-black text-white uppercase tracking-widest italic mb-2 break-words">Tactical Inquiry: {m.poll.question}</div>
                       {m.poll.options.map((opt, idx) => {
                         const totalVotes = m.poll!.options.reduce((acc, o) => acc + o.votes.length, 0);
                         const percentage = totalVotes === 0 ? 0 : Math.round((opt.votes.length / totalVotes) * 100);
                         const hasVoted = opt.votes.includes(currentUser);
                         return (
                           <button 
                             key={idx}
                             onClick={() => onVotePoll(m.id, idx)}
                             className={`w-full relative h-9 md:h-10 rounded-lg md:rounded-xl overflow-hidden border transition-all group/opt ${hasVoted ? 'border-indigo-400/50' : 'border-slate-800/50 hover:border-slate-700'}`}
                           >
                             <div className={`absolute inset-0 h-full transition-all duration-1000 ${hasVoted ? 'bg-indigo-500/20' : 'bg-slate-800/10'}`} style={{ width: `${percentage}%` }} />
                             <div className="absolute inset-0 flex items-center justify-between px-3 md:px-4 z-10">
                                <span className={`text-[9px] md:text-[10px] font-black uppercase tracking-widest truncate mr-2 ${hasVoted ? 'text-indigo-300' : 'text-slate-400'}`}>{opt.text}</span>
                                <span className="text-[8px] md:text-[9px] font-black text-slate-500 shrink-0">{percentage}%</span>
                             </div>
                           </button>
                         );
                       })}
                     </div>
                   )}
                 </div>

                 {/* Message Actions Tray - Adjusted for mobile boundary safety */}
                 <div className={`absolute top-0 flex items-center gap-1 bg-slate-900 border border-slate-800 rounded-full px-2 py-1 shadow-2xl transition-all duration-200 opacity-0 group-hover/bubble:opacity-100 z-20 ${m.sender === currentUser ? 'right-full mr-2 md:mr-3' : 'left-full ml-2 md:ml-3'} ${m.sender === currentUser ? 'origin-right' : 'origin-left'}`}>
                    <button 
                      onClick={() => onPinMessage(m.id)}
                      className={`p-1.5 rounded-full transition-colors ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z"/></svg>
                    </button>
                    <div className="relative">
                      <button 
                        onClick={() => setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id)}
                        className={`p-1.5 rounded-full hover:bg-slate-800 transition-colors ${activeReactionPicker === m.id ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white'}`}
                      >
                        <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
                      </button>

                      {activeReactionPicker === m.id && (
                        <div className={`absolute bottom-full mb-2 bg-slate-900 border border-slate-800 p-2 rounded-2xl shadow-2xl flex gap-1 z-50 animate-in slide-in-from-bottom-2 ${m.sender === currentUser ? 'right-0' : 'left-0'}`}>
                           {COMMON_EMOJIS.slice(0, 8).map(emoji => (
                             <button key={emoji} onClick={() => { onReactToMessage(m.id, emoji); setActiveReactionPicker(null); }} className="hover:scale-125 transition-transform p-1 md:p-1.5 text-base md:text-lg">{emoji}</button>
                           ))}
                        </div>
                      )}
                    </div>
                 </div>

                 {/* Reactions Display */}
                 {m.reactions && Object.keys(m.reactions).length > 0 && (
                   <div className={`flex flex-wrap gap-1 mt-2 w-full ${m.sender === currentUser ? 'justify-end' : 'justify-start'}`}>
                      {Object.entries(m.reactions).map(([emoji, users]) => (
                        <button 
                          key={emoji} 
                          onClick={() => onReactToMessage(m.id, emoji)}
                          className={`px-2 py-0.5 rounded-full border text-[9px] md:text-[10px] font-black transition-all flex items-center gap-1 md:gap-1.5 ${(users as string[]).includes(currentUser) ? 'bg-indigo-600/20 border-indigo-500 text-indigo-400' : 'bg-slate-900/60 border-slate-800 text-slate-500 hover:text-slate-300'}`}
                        >
                          <span>{emoji}</span>
                          <span className="opacity-60">{(users as string[]).length}</span>
                        </button>
                      ))}
                   </div>
                 )}
               </div>
            </div>
          </div>
        ))}
      </div>

      {/* Chat Input Area */}
      <footer className="p-3 md:p-6 lg:p-8 bg-slate-950/80 backdrop-blur-3xl border-t border-slate-900/50 shrink-0 relative">
        <div className="max-w-6xl mx-auto flex items-end gap-2 md:gap-4">
          <div className="relative">
            <button 
              onClick={() => setShowActionMenu(!showActionMenu)}
              className={`w-10 h-10 md:w-14 md:h-14 rounded-xl md:rounded-2xl flex items-center justify-center text-lg md:text-xl transition-all shadow-xl active:scale-95 shrink-0 ${showActionMenu ? 'bg-indigo-600 text-white rotate-45' : 'bg-slate-900 text-slate-500 hover:text-white border border-slate-800'}`}
            >
              ➕
            </button>

            {showActionMenu && (
              <div className="absolute bottom-12 md:bottom-16 left-0 w-40 md:w-48 bg-slate-900 border border-slate-800 rounded-xl md:rounded-2xl shadow-2xl p-1.5 md:p-2 animate-in slide-in-from-bottom-2 duration-200 z-50">
                 <button onClick={() => startCamera()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📸</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Visual</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📄</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Packet</span>
                 </button>
                 <button onClick={() => setShowPollModal(true)} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📊</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Poll</span>
                 </button>
              </div>
            )}
          </div>

          <div className="flex-1 relative group flex items-end bg-slate-900/40 border border-slate-800 rounded-xl md:rounded-2xl overflow-hidden focus-within:border-indigo-600 transition-all min-w-0">
            <button 
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className={`p-2 md:p-4 transition-colors shrink-0 ${showEmojiPicker ? 'text-indigo-400' : 'text-slate-600 hover:text-indigo-400'}`}
            >
               <svg className="w-5 h-5 md:w-6 md:h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
            </button>

            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit..."
              rows={1}
              className="w-full bg-transparent px-1 py-3 md:py-4 text-white text-sm md:text-base font-medium outline-none placeholder:text-slate-800 resize-none shadow-inner min-w-0"
            />

            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[280px] md:max-w-sm bg-slate-950 border border-slate-800 rounded-2xl md:rounded-3xl p-3 md:p-4 shadow-2xl z-50 animate-in slide-in-from-bottom-2">
                 <div className="grid grid-cols-6 md:grid-cols-8 gap-1 md:gap-2">
                    {COMMON_EMOJIS.map(emoji => (
                      <button key={emoji} onClick={() => injectEmoji(emoji)} className="text-lg md:text-xl hover:scale-125 transition-transform p-1.5">{emoji}</button>
                    ))}
                 </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleSend}
            disabled={!input.trim()}
            className="w-10 h-10 md:w-14 md:h-14 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-800 text-white rounded-xl md:rounded-2xl flex items-center justify-center shadow-xl active:scale-95 transition-all shrink-0"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
          </button>
        </div>
      </footer>

      {/* File Input */}
      <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

      {/* Poll Modal */}
      {showPollModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm md:max-w-md rounded-[2rem] md:rounded-[2.5rem] shadow-2xl p-6 md:p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6 md:mb-8">
               <h3 className="text-lg md:text-xl font-black text-white italic uppercase tracking-tighter">Strategic Query</h3>
               <button onClick={() => setShowPollModal(false)} className="text-slate-500 hover:text-white">✕</button>
            </div>

            <div className="space-y-4 md:space-y-6">
              <div className="space-y-1.5 md:space-y-2">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Inquiry Objective</label>
                <input 
                  type="text" 
                  value={pollQuestion}
                  onChange={(e) => setPollQuestion(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 md:py-3 text-sm text-white font-bold outline-none focus:border-indigo-500"
                  placeholder="The query target..."
                />
              </div>

              <div className="space-y-2 md:space-y-3">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Outcome Variables</label>
                {pollOptions.map((opt, idx) => (
                  <input 
                    key={idx}
                    type="text"
                    value={opt}
                    onChange={(e) => {
                      const newOpts = [...pollOptions];
                      newOpts[idx] = e.target.value;
                      setPollOptions(newOpts);
                    }}
                    className="w-full bg-slate-950 border border-slate-800 rounded-lg md:rounded-xl px-4 py-2 md:py-3 text-xs text-white outline-none focus:border-indigo-500"
                    placeholder={`Option ${idx + 1}`}
                  />
                ))}
                <button 
                  onClick={() => setPollOptions([...pollOptions, ''])}
                  className="w-full py-2 text-[8px] font-black text-indigo-500 uppercase tracking-[0.3em] hover:text-white transition-colors"
                >
                  ➕ Add Variable
                </button>
              </div>

              <div className="flex gap-3 md:gap-4 pt-2 md:pt-4">
                 <button onClick={() => setShowPollModal(false)} className="flex-1 py-3 md:py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Abort</button>
                 <button onClick={handleCreatePoll} className="flex-1 py-3 md:py-4 bg-indigo-600 text-white rounded-lg md:rounded-xl font-black uppercase text-[9px] tracking-widest shadow-xl">Deploy</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Camera UI Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[110] bg-black flex flex-col animate-in fade-in duration-300">
           <div className="relative flex-1 bg-slate-950 flex items-center justify-center overflow-hidden">
             <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
             <div className="absolute inset-0 pointer-events-none border-[20px] md:border-[40px] border-black/40" />
             <div className="absolute top-6 md:top-10 left-1/2 -translate-x-1/2 flex flex-col items-center">
               <div className="text-white font-black italic tracking-tighter uppercase text-lg md:text-xl text-glow">Visual Scanner</div>
               <div className="text-[7px] md:text-[8px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-1">Active Uplink</div>
             </div>
           </div>

           <div className="h-32 md:h-40 bg-slate-950 border-t border-slate-900 flex items-center justify-around px-6 md:px-10 shrink-0">
              <button onClick={stopCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-slate-400 hover:text-white transition-colors">✕</button>
              <button onClick={capturePhoto} className="w-16 h-16 md:w-20 md:h-20 rounded-full border-4 border-indigo-500 p-1 group active:scale-95 transition-all">
                 <div className="w-full h-full rounded-full bg-white/10 group-hover:bg-indigo-500 transition-colors" />
              </button>
              <button onClick={flipCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-indigo-400 hover:text-white transition-colors">🔄</button>
           </div>
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  onSendMessage, 
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onToggleMenu, 
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setIsCameraLoading(false);
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        };
        onSendMessage("Visual signature captured.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden w-full min-w-0">
      {!hideHeader && (
        <header className="h-16 px-4 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🎥</button>
              </div>
            )}
            <button onClick={() => setShowMembers(!showMembers)} className={`p-1.5 md:p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
          <span className="text-[7px] font-black text-slate-600 uppercase tracking-widest ml-4 hidden sm:inline">System Anchor</span>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar w-full overflow-x-hidden">
        {messages.map((m) => (
          <div key={m.id} id={`msg-${m.id}`} className={`flex gap-3 md:gap-4 group animate-in slide-in-from-bottom-2 duration-300 overflow-x-hidden ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-8 h-8 md:w-11 md:h-11 rounded-xl md:rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end shrink-0" alt="" />
            <div className={`flex flex-col gap-1.5 max-w-[85%] md:max-w-[70%] min-w-0 ${m.sender === currentUser ? 'items-end' : ''}`}>
               <div className="flex items-center gap-2 px-1">
                 <span className="text-[9px] md:text-[10px] font-black text-white uppercase italic tracking-tighter truncate">{m.sender === currentUser ? 'YOU' : m.sender}</span>
                 <span className="text-[7px] md:text-[8px] text-slate-700 font-bold uppercase tracking-widest shrink-0">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               </div>

               <div className="relative group/bubble w-full min-w-0">
                 {/* Message Actions Tray - Repositioned for Mobile Safety */}
                 <div className={`absolute flex items-center gap-1 bg-slate-900 border border-slate-800 rounded-full px-2 py-1 shadow-2xl transition-all duration-200 opacity-0 group-hover/bubble:opacity-100 z-20 
                   ${/* Mobile: centered above. Desktop: side-car */ ''}
                   bottom-full mb-2 left-1/2 -translate-x-1/2 md:bottom-auto md:top-0 md:translate-x-0
                   ${m.sender === currentUser ? 'md:left-auto md:right-full md:mr-3' : 'md:right-auto md:left-full md:ml-3'}
                 `}>
                    <button 
                      onClick={() => onPinMessage(m.id)}
                      className={`p-1.5 rounded-full transition-colors ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z"/></svg>
                    </button>
                    <div className="relative">
                      <button 
                        onClick={() => setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id)}
                        className={`p-1.5 rounded-full hover:bg-slate-800 transition-colors ${activeReactionPicker === m.id ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white'}`}
                      >
                        <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
                      </button>

                      {activeReactionPicker === m.id && (
                        <div className={`fixed md:absolute bottom-20 md:bottom-full left-4 right-4 md:left-auto md:right-auto mb-2 bg-slate-900 border border-slate-800 p-2 rounded-2xl shadow-2xl flex gap-1 z-[100] animate-in slide-in-from-bottom-2 ${m.sender === currentUser ? 'md:right-0' : 'md:left-0'} justify-center`}>
                           {COMMON_EMOJIS.slice(0, 8).map(emoji => (
                             <button key={emoji} onClick={() => { onReactToMessage(m.id, emoji); setActiveReactionPicker(null); }} className="hover:scale-125 transition-transform p-1.5 md:p-1.5 text-base md:text-lg">{emoji}</button>
                           ))}
                        </div>
                      )}
                    </div>
                 </div>

                 {/* Message Bubble */}
                 <div className={`relative px-4 py-3 md:px-5 md:py-3.5 rounded-[1.5rem] md:rounded-[1.8rem] shadow-2xl border transition-all w-fit max-w-full min-w-0 ${
                   m.sender === currentUser 
                     ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none ml-auto' 
                     : 'bg-slate-900 text-slate-200 border-slate-800/80 rounded-tl-none'
                 } ${m.isPinned ? 'ring-2 ring-indigo-500/50 ring-offset-2 ring-offset-[#020617]' : ''}`}>

                   {m.isPinned && (
                     <div className="absolute -top-3 -left-3 bg-indigo-600 w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[10px] shadow-lg border border-indigo-400 z-10 animate-bounce">📌</div>
                   )}

                   <p className="text-sm md:text-base font-medium leading-relaxed whitespace-pre-wrap break-words">{m.text}</p>

                   {m.attachment && (
                     <div className="mt-3 md:mt-4 p-3 md:p-4 bg-black/30 rounded-xl md:rounded-2xl border border-white/5 flex flex-col sm:flex-row items-center gap-3 md:gap-4 group/att min-w-0">
                        {m.attachment.type.startsWith('image/') && m.attachment.url ? (
                          <img src={m.attachment.url} className="w-full rounded-lg md:rounded-xl" alt="attached" />
                        ) : (
                          <>
                            <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-950 rounded-lg md:rounded-xl flex items-center justify-center text-xl md:text-2xl shadow-inner shrink-0">📄</div>
                            <div className="min-w-0 flex-1">
                              <div className="text-[9px] md:text-[10px] font-black uppercase truncate text-white italic">{m.attachment.name}</div>
                              <div className="text-[7px] md:text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{m.attachment.size}</div>
                            </div>
                          </>
                        )}
                     </div>
                   )}

                   {m.poll && (
                     <div className="mt-3 md:mt-4 space-y-2 md:space-y-3 bg-black/20 p-4 md:p-5 rounded-xl md:rounded-2xl border border-white/5 w-full md:min-w-[300px]">
                       <div className="text-[10px] md:text-xs font-black text-white uppercase tracking-widest italic mb-2 break-words">Tactical Inquiry: {m.poll.question}</div>
                       {m.poll.options.map((opt, idx) => {
                         const totalVotes = m.poll!.options.reduce((acc, o) => acc + o.votes.length, 0);
                         const percentage = totalVotes === 0 ? 0 : Math.round((opt.votes.length / totalVotes) * 100);
                         const hasVoted = opt.votes.includes(currentUser);
                         return (
                           <button 
                             key={idx}
                             onClick={() => onVotePoll(m.id, idx)}
                             className={`w-full relative h-9 md:h-10 rounded-lg md:rounded-xl overflow-hidden border transition-all group/opt ${hasVoted ? 'border-indigo-400/50' : 'border-slate-800/50 hover:border-slate-700'}`}
                           >
                             <div className={`absolute inset-0 h-full transition-all duration-1000 ${hasVoted ? 'bg-indigo-500/20' : 'bg-slate-800/10'}`} style={{ width: `${percentage}%` }} />
                             <div className="absolute inset-0 flex items-center justify-between px-3 md:px-4 z-10">
                                <span className={`text-[9px] md:text-[10px] font-black uppercase tracking-widest truncate mr-2 ${hasVoted ? 'text-indigo-300' : 'text-slate-400'}`}>{opt.text}</span>
                                <span className="text-[8px] md:text-[9px] font-black text-slate-500 shrink-0">{percentage}%</span>
                             </div>
                           </button>
                         );
                       })}
                     </div>
                   )}
                 </div>

                 {/* Reactions Display - Constraints Added */}
                 {m.reactions && Object.keys(m.reactions).length > 0 && (
                   <div className={`flex flex-wrap gap-1 mt-2 w-full max-w-full ${m.sender === currentUser ? 'justify-end' : 'justify-start'}`}>
                      {Object.entries(m.reactions).map(([emoji, users]) => (
                        <button 
                          key={emoji} 
                          onClick={() => onReactToMessage(m.id, emoji)}
                          className={`px-2 py-0.5 rounded-full border text-[9px] md:text-[10px] font-black transition-all flex items-center gap-1 md:gap-1.5 shrink-0 ${(users as string[]).includes(currentUser) ? 'bg-indigo-600/20 border-indigo-500 text-indigo-400' : 'bg-slate-900/60 border-slate-800 text-slate-500 hover:text-slate-300'}`}
                        >
                          <span>{emoji}</span>
                          <span className="opacity-60">{(users as string[]).length}</span>
                        </button>
                      ))}
                   </div>
                 )}
               </div>
            </div>
          </div>
        ))}
      </div>

      {/* Chat Input Area */}
      <footer className="p-3 md:p-6 lg:p-8 bg-slate-950/80 backdrop-blur-3xl border-t border-slate-900/50 shrink-0 relative">
        <div className="max-w-6xl mx-auto flex items-end gap-2 md:gap-4">
          <div className="relative">
            <button 
              onClick={() => setShowActionMenu(!showActionMenu)}
              className={`w-10 h-10 md:w-14 md:h-14 rounded-xl md:rounded-2xl flex items-center justify-center text-lg md:text-xl transition-all shadow-xl active:scale-95 shrink-0 ${showActionMenu ? 'bg-indigo-600 text-white rotate-45' : 'bg-slate-900 text-slate-500 hover:text-white border border-slate-800'}`}
            >
              ➕
            </button>

            {showActionMenu && (
              <div className="absolute bottom-12 md:bottom-16 left-0 w-40 md:w-48 bg-slate-900 border border-slate-800 rounded-xl md:rounded-2xl shadow-2xl p-1.5 md:p-2 animate-in slide-in-from-bottom-2 duration-200 z-50">
                 <button onClick={() => startCamera()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📸</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Visual</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📄</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Packet</span>
                 </button>
                 <button onClick={() => setShowPollModal(true)} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📊</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Poll</span>
                 </button>
              </div>
            )}
          </div>

          <div className="flex-1 relative group flex items-end bg-slate-900/40 border border-slate-800 rounded-xl md:rounded-2xl overflow-hidden focus-within:border-indigo-600 transition-all min-w-0">
            <button 
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className={`p-2 md:p-4 transition-colors shrink-0 ${showEmojiPicker ? 'text-indigo-400' : 'text-slate-600 hover:text-indigo-400'}`}
            >
               <svg className="w-5 h-5 md:w-6 md:h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
            </button>

            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit..."
              rows={1}
              className="w-full bg-transparent px-1 py-3 md:py-4 text-white text-sm md:text-base font-medium outline-none placeholder:text-slate-800 resize-none shadow-inner min-w-0"
            />

            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[280px] md:max-w-sm bg-slate-950 border border-slate-800 rounded-2xl md:rounded-3xl p-3 md:p-4 shadow-2xl z-50 animate-in slide-in-from-bottom-2">
                 <div className="grid grid-cols-6 md:grid-cols-8 gap-1 md:gap-2">
                    {COMMON_EMOJIS.map(emoji => (
                      <button key={emoji} onClick={() => injectEmoji(emoji)} className="text-lg md:text-xl hover:scale-125 transition-transform p-1.5">{emoji}</button>
                    ))}
                 </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleSend}
            disabled={!input.trim()}
            className="w-10 h-10 md:w-14 md:h-14 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-800 text-white rounded-xl md:rounded-2xl flex items-center justify-center shadow-xl active:scale-95 transition-all shrink-0"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
          </button>
        </div>
      </footer>

      {/* File Input */}
      <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

      {/* Poll Modal */}
      {showPollModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm md:max-w-md rounded-[2rem] md:rounded-[2.5rem] shadow-2xl p-6 md:p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6 md:mb-8">
               <h3 className="text-lg md:text-xl font-black text-white italic uppercase tracking-tighter">Strategic Query</h3>
               <button onClick={() => setShowPollModal(false)} className="text-slate-500 hover:text-white">✕</button>
            </div>

            <div className="space-y-4 md:space-y-6">
              <div className="space-y-1.5 md:space-y-2">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Inquiry Objective</label>
                <input 
                  type="text" 
                  value={pollQuestion}
                  onChange={(e) => setPollQuestion(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 md:py-3 text-sm text-white font-bold outline-none focus:border-indigo-500"
                  placeholder="The query target..."
                />
              </div>

              <div className="space-y-2 md:space-y-3">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Outcome Variables</label>
                {pollOptions.map((opt, idx) => (
                  <input 
                    key={idx}
                    type="text"
                    value={opt}
                    onChange={(e) => {
                      const newOpts = [...pollOptions];
                      newOpts[idx] = e.target.value;
                      setPollOptions(newOpts);
                    }}
                    className="w-full bg-slate-950 border border-slate-800 rounded-lg md:rounded-xl px-4 py-2 md:py-3 text-xs text-white outline-none focus:border-indigo-500"
                    placeholder={`Option ${idx + 1}`}
                  />
                ))}
                <button 
                  onClick={() => setPollOptions([...pollOptions, ''])}
                  className="w-full py-2 text-[8px] font-black text-indigo-500 uppercase tracking-[0.3em] hover:text-white transition-colors"
                >
                  ➕ Add Variable
                </button>
              </div>

              <div className="flex gap-3 md:gap-4 pt-2 md:pt-4">
                 <button onClick={() => setShowPollModal(false)} className="flex-1 py-3 md:py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Abort</button>
                 <button onClick={handleCreatePoll} className="flex-1 py-3 md:py-4 bg-indigo-600 text-white rounded-lg md:rounded-xl font-black uppercase text-[9px] tracking-widest shadow-xl">Deploy</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Camera UI Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[110] bg-black flex flex-col animate-in fade-in duration-300">
           <div className="relative flex-1 bg-slate-950 flex items-center justify-center overflow-hidden">
             <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
             <div className="absolute inset-0 pointer-events-none border-[20px] md:border-[40px] border-black/40" />
             <div className="absolute top-6 md:top-10 left-1/2 -translate-x-1/2 flex flex-col items-center">
               <div className="text-white font-black italic tracking-tighter uppercase text-lg md:text-xl text-glow">Visual Scanner</div>
               <div className="text-[7px] md:text-[8px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-1">Active Uplink</div>
             </div>
           </div>

           <div className="h-32 md:h-40 bg-slate-950 border-t border-slate-900 flex items-center justify-around px-6 md:px-10 shrink-0">
              <button onClick={stopCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-slate-400 hover:text-white transition-colors">✕</button>
              <button onClick={capturePhoto} className="w-16 h-16 md:w-20 md:h-20 rounded-full border-4 border-indigo-500 p-1 group active:scale-95 transition-all">
                 <div className="w-full h-full rounded-full bg-white/10 group-hover:bg-indigo-500 transition-colors" />
              </button>
              <button onClick={flipCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-indigo-400 hover:text-white transition-colors">🔄</button>
           </div>
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, 
  currentUser,
  onSendMessage, 
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onToggleMenu, 
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setIsCameraLoading(false);
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        };
        onSendMessage("Visual signature captured.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden w-full min-w-0">
      {!hideHeader && (
        <header className="h-16 px-4 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🎥</button>
              </div>
            )}
            <button onClick={() => setShowMembers(!showMembers)} className={`p-1.5 md:p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
          <span className="text-[7px] font-black text-slate-600 uppercase tracking-widest ml-4 hidden sm:inline">System Anchor</span>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-10 custom-scrollbar w-full overflow-x-hidden">
        {messages.map((m) => (
          <div key={m.id} id={`msg-${m.id}`} className={`flex gap-3 md:gap-4 group animate-in slide-in-from-bottom-2 duration-300 overflow-x-hidden ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-8 h-8 md:w-11 md:h-11 rounded-xl md:rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end shrink-0" alt="" />
            <div className={`flex flex-col gap-1.5 max-w-[85%] md:max-w-[70%] min-w-0 ${m.sender === currentUser ? 'items-end' : ''}`}>
               <div className="flex items-center gap-2 px-1">
                 <span className="text-[9px] md:text-[10px] font-black text-white uppercase italic tracking-tighter truncate">{m.sender === currentUser ? 'YOU' : m.sender}</span>
                 <span className="text-[7px] md:text-[8px] text-slate-700 font-bold uppercase tracking-widest shrink-0">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               </div>

               <div className="relative group/bubble w-full min-w-0">
                 {/* Message Actions Tray - Repositioned for Total Mobile Boundary Safety */}
                 <div className={`absolute flex items-center gap-1 bg-slate-900 border border-slate-800 rounded-full px-2 py-1 shadow-2xl transition-all duration-200 opacity-0 group-hover/bubble:opacity-100 z-20 
                   ${/* On mobile, center it perfectly above. On desktop, side-car it. */ ''}
                   bottom-full mb-2 left-1/2 -translate-x-1/2 md:bottom-auto md:top-0 md:translate-x-0
                   ${m.sender === currentUser ? 'md:left-auto md:right-full md:mr-3' : 'md:right-auto md:left-full md:ml-3'}
                 `}>
                    <button 
                      onClick={() => onPinMessage(m.id)}
                      className={`p-1.5 rounded-full transition-colors ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z"/></svg>
                    </button>
                    <div className="relative">
                      <button 
                        onClick={() => setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id)}
                        className={`p-1.5 rounded-full hover:bg-slate-800 transition-colors ${activeReactionPicker === m.id ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white'}`}
                      >
                        <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
                      </button>
                    </div>
                 </div>

                 {/* Message Bubble */}
                 <div className={`relative px-4 py-3 md:px-5 md:py-3.5 rounded-[1.5rem] md:rounded-[1.8rem] shadow-2xl border transition-all w-fit max-w-full min-w-0 ${
                   m.sender === currentUser 
                     ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none ml-auto' 
                     : 'bg-slate-900 text-slate-200 border-slate-800/80 rounded-tl-none'
                 } ${m.isPinned ? 'ring-2 ring-indigo-500/50 ring-offset-2 ring-offset-[#020617]' : ''}`}>

                   {m.isPinned && (
                     <div className="absolute -top-3 -left-3 bg-indigo-600 w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[10px] shadow-lg border border-indigo-400 z-10 animate-bounce">📌</div>
                   )}

                   <p className="text-sm md:text-base font-medium leading-relaxed whitespace-pre-wrap break-words">{m.text}</p>

                   {m.attachment && (
                     <div className="mt-3 md:mt-4 p-3 md:p-4 bg-black/30 rounded-xl md:rounded-2xl border border-white/5 flex flex-col items-center gap-3 md:gap-4 min-w-0">
                        {m.attachment.type.startsWith('image/') && m.attachment.url ? (
                          <img src={m.attachment.url} className="w-full rounded-lg md:rounded-xl" alt="attached" />
                        ) : (
                          <div className="flex items-center gap-3 w-full">
                            <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-950 rounded-lg md:rounded-xl flex items-center justify-center text-xl md:text-2xl shadow-inner shrink-0">📄</div>
                            <div className="min-w-0 flex-1">
                              <div className="text-[9px] md:text-[10px] font-black uppercase truncate text-white italic">{m.attachment.name}</div>
                              <div className="text-[7px] md:text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{m.attachment.size}</div>
                            </div>
                          </div>
                        )}
                     </div>
                   )}

                   {m.poll && (
                     <div className="mt-3 md:mt-4 space-y-2 md:space-y-3 bg-black/20 p-4 md:p-5 rounded-xl md:rounded-2xl border border-white/5 w-full md:min-w-[300px]">
                       <div className="text-[10px] md:text-xs font-black text-white uppercase tracking-widest italic mb-2 break-words">Tactical Inquiry: {m.poll.question}</div>
                       {m.poll.options.map((opt, idx) => {
                         const totalVotes = m.poll!.options.reduce((acc, o) => acc + o.votes.length, 0);
                         const percentage = totalVotes === 0 ? 0 : Math.round((opt.votes.length / totalVotes) * 100);
                         const hasVoted = opt.votes.includes(currentUser);
                         return (
                           <button 
                             key={idx}
                             onClick={() => onVotePoll(m.id, idx)}
                             className={`w-full relative h-9 md:h-10 rounded-lg md:rounded-xl overflow-hidden border transition-all group/opt ${hasVoted ? 'border-indigo-400/50' : 'border-slate-800/50 hover:border-slate-700'}`}
                           >
                             <div className={`absolute inset-0 h-full transition-all duration-1000 ${hasVoted ? 'bg-indigo-500/20' : 'bg-slate-800/10'}`} style={{ width: `${percentage}%` }} />
                             <div className="absolute inset-0 flex items-center justify-between px-3 md:px-4 z-10">
                                <span className={`text-[9px] md:text-[10px] font-black uppercase tracking-widest truncate mr-2 ${hasVoted ? 'text-indigo-300' : 'text-slate-400'}`}>{opt.text}</span>
                                <span className="text-[8px] md:text-[9px] font-black text-slate-500 shrink-0">{percentage}%</span>
                             </div>
                           </button>
                         );
                       })}
                     </div>
                   )}
                 </div>
               </div>

               {/* Reactions Display - Moved BELOW the bubble logic to prevent width expansion */}
               {m.reactions && Object.keys(m.reactions).length > 0 && (
                 <div className={`flex flex-wrap gap-1 mt-1 w-full max-w-full overflow-hidden ${m.sender === currentUser ? 'justify-end' : 'justify-start'}`}>
                    {Object.entries(m.reactions).map(([emoji, users]) => (
                      <button 
                        key={emoji} 
                        onClick={() => onReactToMessage(m.id, emoji)}
                        className={`px-2 py-0.5 rounded-full border text-[9px] md:text-[10px] font-black transition-all flex items-center gap-1.5 shrink-0 break-all ${(users as string[]).includes(currentUser) ? 'bg-indigo-600/20 border-indigo-500 text-indigo-400' : 'bg-slate-900/60 border-slate-800 text-slate-500 hover:text-slate-300'}`}
                      >
                        <span>{emoji}</span>
                        <span className="opacity-60">{(users as string[]).length}</span>
                      </button>
                    ))}
                 </div>
               )}

               {/* Mobile Bottom-Bar Emoji Picker */}
               {activeReactionPicker === m.id && (
                 <div className={`fixed inset-x-0 bottom-0 md:absolute md:bottom-full md:inset-x-auto md:mb-2 md:left-auto md:right-auto bg-slate-900 md:border md:border-slate-800 p-4 md:p-2 md:rounded-2xl shadow-[0_-10px_40px_rgba(0,0,0,0.5)] md:shadow-2xl flex gap-2 z-[150] animate-in slide-in-from-bottom-full md:slide-in-from-bottom-2 ${m.sender === currentUser ? 'md:right-0' : 'md:left-0'} justify-center overflow-x-auto custom-scrollbar`}>
                    <div className="flex items-center gap-2">
                       {COMMON_EMOJIS.slice(0, 10).map(emoji => (
                         <button key={emoji} onClick={() => { onReactToMessage(m.id, emoji); setActiveReactionPicker(null); }} className="hover:scale-125 active:scale-90 transition-all p-2 text-xl md:text-lg shrink-0">{emoji}</button>
                       ))}
                       <div className="w-[1px] h-6 bg-slate-800 mx-2 hidden md:block"></div>
                       <button onClick={() => setActiveReactionPicker(null)} className="p-2 text-slate-500 hover:text-white md:hidden">✕</button>
                    </div>
                 </div>
               )}
            </div>
          </div>
        ))}
      </div>

      {/* Chat Input Area */}
      <footer className="p-3 md:p-6 lg:p-8 bg-slate-950/80 backdrop-blur-3xl border-t border-slate-900/50 shrink-0 relative">
        <div className="max-w-6xl mx-auto flex items-end gap-2 md:gap-4">
          <div className="relative">
            <button 
              onClick={() => setShowActionMenu(!showActionMenu)}
              className={`w-10 h-10 md:w-14 md:h-14 rounded-xl md:rounded-2xl flex items-center justify-center text-lg md:text-xl transition-all shadow-xl active:scale-95 shrink-0 ${showActionMenu ? 'bg-indigo-600 text-white rotate-45' : 'bg-slate-900 text-slate-500 hover:text-white border border-slate-800'}`}
            >
              ➕
            </button>

            {showActionMenu && (
              <div className="absolute bottom-12 md:bottom-16 left-0 w-40 md:w-48 bg-slate-900 border border-slate-800 rounded-xl md:rounded-2xl shadow-2xl p-1.5 md:p-2 animate-in slide-in-from-bottom-2 duration-200 z-50">
                 <button onClick={() => startCamera()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📸</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Visual</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📄</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Packet</span>
                 </button>
                 <button onClick={() => setShowPollModal(true)} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📊</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Poll</span>
                 </button>
              </div>
            )}
          </div>

          <div className="flex-1 relative group flex items-end bg-slate-900/40 border border-slate-800 rounded-xl md:rounded-2xl overflow-hidden focus-within:border-indigo-600 transition-all min-w-0">
            <button 
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className={`p-2 md:p-4 transition-colors shrink-0 ${showEmojiPicker ? 'text-indigo-400' : 'text-slate-600 hover:text-indigo-400'}`}
            >
               <svg className="w-5 h-5 md:w-6 md:h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
            </button>

            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit..."
              rows={1}
              className="w-full bg-transparent px-1 py-3 md:py-4 text-white text-sm md:text-base font-medium outline-none placeholder:text-slate-800 resize-none shadow-inner min-w-0"
            />

            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[280px] md:max-w-sm bg-slate-950 border border-slate-800 rounded-2xl md:rounded-3xl p-3 md:p-4 shadow-2xl z-50 animate-in slide-in-from-bottom-2">
                 <div className="grid grid-cols-6 md:grid-cols-8 gap-1 md:gap-2">
                    {COMMON_EMOJIS.map(emoji => (
                      <button key={emoji} onClick={() => injectEmoji(emoji)} className="text-lg md:text-xl hover:scale-125 transition-transform p-1.5">{emoji}</button>
                    ))}
                 </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleSend}
            disabled={!input.trim()}
            className="w-10 h-10 md:w-14 md:h-14 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-800 text-white rounded-xl md:rounded-2xl flex items-center justify-center shadow-xl active:scale-95 transition-all shrink-0"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
          </button>
        </div>
      </footer>

      {/* File Input */}
      <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

      {/* Poll Modal */}
      {showPollModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm md:max-w-md rounded-[2rem] md:rounded-[2.5rem] shadow-2xl p-6 md:p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6 md:mb-8">
               <h3 className="text-lg md:text-xl font-black text-white italic uppercase tracking-tighter">Strategic Query</h3>
               <button onClick={() => setShowPollModal(false)} className="text-slate-500 hover:text-white">✕</button>
            </div>

            <div className="space-y-4 md:space-y-6">
              <div className="space-y-1.5 md:space-y-2">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Inquiry Objective</label>
                <input 
                  type="text" 
                  value={pollQuestion}
                  onChange={(e) => setPollQuestion(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 md:py-3 text-sm text-white font-bold outline-none focus:border-indigo-500"
                  placeholder="The query target..."
                />
              </div>

              <div className="space-y-2 md:space-y-3">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Outcome Variables</label>
                {pollOptions.map((opt, idx) => (
                  <input 
                    key={idx}
                    type="text"
                    value={opt}
                    onChange={(e) => {
                      const newOpts = [...pollOptions];
                      newOpts[idx] = e.target.value;
                      setPollOptions(newOpts);
                    }}
                    className="w-full bg-slate-950 border border-slate-800 rounded-lg md:rounded-xl px-4 py-2 md:py-3 text-xs text-white outline-none focus:border-indigo-500"
                    placeholder={`Option ${idx + 1}`}
                  />
                ))}
                <button 
                  onClick={() => setPollOptions([...pollOptions, ''])}
                  className="w-full py-2 text-[8px] font-black text-indigo-500 uppercase tracking-[0.3em] hover:text-white transition-colors"
                >
                  ➕ Add Variable
                </button>
              </div>

              <div className="flex gap-3 md:gap-4 pt-2 md:pt-4">
                 <button onClick={() => setShowPollModal(false)} className="flex-1 py-3 md:py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Abort</button>
                 <button onClick={handleCreatePoll} className="flex-1 py-3 md:py-4 bg-indigo-600 text-white rounded-lg md:rounded-xl font-black uppercase text-[9px] tracking-widest shadow-xl">Deploy</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Camera UI Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[110] bg-black flex flex-col animate-in fade-in duration-300">
           <div className="relative flex-1 bg-slate-950 flex items-center justify-center overflow-hidden">
             <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
             <div className="absolute inset-0 pointer-events-none border-[20px] md:border-[40px] border-black/40" />
             <div className="absolute top-6 md:top-10 left-1/2 -translate-x-1/2 flex flex-col items-center">
               <div className="text-white font-black italic tracking-tighter uppercase text-lg md:text-xl text-glow">Visual Scanner</div>
               <div className="text-[7px] md:text-[8px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-1">Active Uplink</div>
             </div>
           </div>

           <div className="h-32 md:h-40 bg-slate-950 border-t border-slate-900 flex items-center justify-around px-6 md:px-10 shrink-0">
              <button onClick={stopCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-slate-400 hover:text-white transition-colors">✕</button>
              <button onClick={capturePhoto} className="w-16 h-16 md:w-20 md:h-20 rounded-full border-4 border-indigo-500 p-1 group active:scale-95 transition-all">
                 <div className="w-full h-full rounded-full bg-white/10 group-hover:bg-indigo-500 transition-colors" />
              </button>
              <button onClick={flipCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-indigo-400 hover:text-white transition-colors">🔄</button>
           </div>
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  currentUser,
  onSendMessage, 
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onToggleMenu, 
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setIsCameraLoading(false);
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        };
        onSendMessage("Visual signature captured.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden w-full min-w-0">
      {!hideHeader && (
        <header className="h-16 px-4 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🎥</button>
              </div>
            )}
            <button onClick={() => setShowMembers(!showMembers)} className={`p-1.5 md:p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
          <span className="text-[7px] font-black text-slate-600 uppercase tracking-widest ml-4 hidden sm:inline">System Anchor</span>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-10 custom-scrollbar w-full overflow-x-hidden">
        {messages.map((m) => (
          <div key={m.id} id={`msg-${m.id}`} className={`flex gap-2 md:gap-4 group animate-in slide-in-from-bottom-2 duration-300 overflow-x-hidden ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-8 h-8 md:w-11 md:h-11 rounded-xl md:rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end shrink-0" alt="" />

            <div className={`flex flex-col gap-1.5 max-w-[calc(100%-4rem)] md:max-w-[70%] min-w-0 ${m.sender === currentUser ? 'items-end' : 'items-start'}`}>
               {/* Sender Header */}
               <div className="flex items-center gap-2 px-1">
                 <span className="text-[9px] md:text-[10px] font-black text-white uppercase italic tracking-tighter truncate">{m.sender === currentUser ? 'YOU' : m.sender}</span>
                 <span className="text-[7px] md:text-[8px] text-slate-700 font-bold uppercase tracking-widest shrink-0">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               </div>

               <div className="relative group/bubble w-full">
                 {/* Action Tray - Positioned Left or Right of bubble */}
                 <div className={`absolute top-1/2 -translate-y-1/2 flex items-center gap-1 bg-slate-900/80 backdrop-blur-md border border-slate-800 rounded-full px-2 py-1 shadow-2xl transition-all duration-200 opacity-0 group-hover/bubble:opacity-100 z-20 
                   ${m.sender === currentUser ? 'right-full mr-2 md:mr-3' : 'left-full ml-2 md:ml-3'}
                 `}>
                    <button 
                      onClick={() => onPinMessage(m.id)}
                      className={`p-1.5 rounded-full transition-colors ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z"/></svg>
                    </button>
                    <button 
                      onClick={() => setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id)}
                      className={`p-1.5 rounded-full hover:bg-slate-800 transition-colors ${activeReactionPicker === m.id ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white'}`}
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
                    </button>
                 </div>

                 {/* Message Bubble Container */}
                 <div className={`relative w-fit max-w-full flex flex-col ${m.sender === currentUser ? 'items-end ml-auto' : 'items-start'}`}>
                   {/* Main Bubble */}
                   <div className={`relative px-4 py-3 md:px-5 md:py-3.5 rounded-[1.5rem] md:rounded-[1.8rem] shadow-2xl border transition-all w-fit max-w-full min-w-0 ${
                     m.sender === currentUser 
                       ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                       : 'bg-slate-900 text-slate-200 border-slate-800/80 rounded-tl-none'
                   } ${m.isPinned ? 'ring-2 ring-indigo-500/50 ring-offset-2 ring-offset-[#020617]' : ''}`}>

                     {m.isPinned && (
                       <div className="absolute -top-3 -left-3 bg-indigo-600 w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[10px] shadow-lg border border-indigo-400 z-10 animate-bounce">📌</div>
                     )}

                     <p className="text-sm md:text-base font-medium leading-relaxed whitespace-pre-wrap break-words">{m.text}</p>

                     {m.attachment && (
                       <div className="mt-3 md:mt-4 p-3 md:p-4 bg-black/30 rounded-xl md:rounded-2xl border border-white/5 flex flex-col items-center gap-3 md:gap-4 min-w-0">
                          {m.attachment.type.startsWith('image/') && m.attachment.url ? (
                            <img src={m.attachment.url} className="w-full rounded-lg md:rounded-xl" alt="attached" />
                          ) : (
                            <div className="flex items-center gap-3 w-full">
                              <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-950 rounded-lg md:rounded-xl flex items-center justify-center text-xl md:text-2xl shadow-inner shrink-0">📄</div>
                              <div className="min-w-0 flex-1">
                                <div className="text-[9px] md:text-[10px] font-black uppercase truncate text-white italic">{m.attachment.name}</div>
                                <div className="text-[7px] md:text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{m.attachment.size}</div>
                              </div>
                            </div>
                          )}
                       </div>
                     )}

                     {m.poll && (
                       <div className="mt-3 md:mt-4 space-y-2 md:space-y-3 bg-black/20 p-4 md:p-5 rounded-xl md:rounded-2xl border border-white/5 w-full md:min-w-[280px]">
                         <div className="text-[10px] md:text-xs font-black text-white uppercase tracking-widest italic mb-2 break-words">Tactical Inquiry: {m.poll.question}</div>
                         {m.poll.options.map((opt, idx) => {
                           const totalVotes = m.poll!.options.reduce((acc, o) => acc + o.votes.length, 0);
                           const percentage = totalVotes === 0 ? 0 : Math.round((opt.votes.length / totalVotes) * 100);
                           const hasVoted = opt.votes.includes(currentUser);
                           return (
                             <button 
                               key={idx}
                               onClick={() => onVotePoll(m.id, idx)}
                               className={`w-full relative h-9 md:h-10 rounded-lg md:rounded-xl overflow-hidden border transition-all group/opt ${hasVoted ? 'border-indigo-400/50' : 'border-slate-800/50 hover:border-slate-700'}`}
                             >
                               <div className={`absolute inset-0 h-full transition-all duration-1000 ${hasVoted ? 'bg-indigo-500/20' : 'bg-slate-800/10'}`} style={{ width: `${percentage}%` }} />
                               <div className="absolute inset-0 flex items-center justify-between px-3 md:px-4 z-10">
                                  <span className={`text-[9px] md:text-[10px] font-black uppercase tracking-widest truncate mr-2 ${hasVoted ? 'text-indigo-300' : 'text-slate-400'}`}>{opt.text}</span>
                                  <span className="text-[8px] md:text-[9px] font-black text-slate-500 shrink-0">{percentage}%</span>
                               </div>
                             </button>
                           );
                         })}
                       </div>
                     )}
                   </div>

                   {/* Reaction Picker - Positioned BELOW the bubble */}
                   {activeReactionPicker === m.id && (
                     <div className={`mt-2 flex items-center gap-1.5 p-2 bg-slate-900/90 backdrop-blur-xl border border-slate-800 rounded-2xl shadow-2xl z-30 animate-in slide-in-from-top-2 w-fit max-w-full overflow-x-auto custom-scrollbar ${m.sender === currentUser ? 'self-end' : 'self-start'}`}>
                        {COMMON_EMOJIS.slice(0, 8).map(emoji => (
                          <button 
                            key={emoji} 
                            onClick={() => { onReactToMessage(m.id, emoji); setActiveReactionPicker(null); }} 
                            className="hover:scale-125 active:scale-90 transition-all p-1.5 text-lg md:text-base shrink-0"
                          >
                            {emoji}
                          </button>
                        ))}
                        <button onClick={() => setActiveReactionPicker(null)} className="ml-1 p-1.5 text-slate-500 hover:text-white shrink-0 text-xs">✕</button>
                     </div>
                   )}

                   {/* Reactions List - Positioned BELOW bubble logic */}
                   {m.reactions && Object.keys(m.reactions).length > 0 && (
                     <div className={`flex flex-wrap gap-1 mt-1.5 w-full max-w-full overflow-hidden ${m.sender === currentUser ? 'justify-end' : 'justify-start'}`}>
                        {Object.entries(m.reactions).map(([emoji, users]) => (
                          <button 
                            key={emoji} 
                            onClick={() => onReactToMessage(m.id, emoji)}
                            className={`px-2 py-0.5 rounded-full border text-[9px] md:text-[10px] font-black transition-all flex items-center gap-1.5 shrink-0 break-all ${(users as string[]).includes(currentUser) ? 'bg-indigo-600/20 border-indigo-500 text-indigo-400' : 'bg-slate-900/60 border-slate-800 text-slate-500 hover:text-slate-300'}`}
                          >
                            <span>{emoji}</span>
                            <span className="opacity-60">{(users as string[]).length}</span>
                          </button>
                        ))}
                     </div>
                   )}
                 </div>
               </div>
            </div>
          </div>
        ))}
      </div>

      {/* Chat Input Area */}
      <footer className="p-3 md:p-6 lg:p-8 bg-slate-950/80 backdrop-blur-3xl border-t border-slate-900/50 shrink-0 relative">
        <div className="max-w-6xl mx-auto flex items-end gap-2 md:gap-4">
          <div className="relative">
            <button 
              onClick={() => setShowActionMenu(!showActionMenu)}
              className={`w-10 h-10 md:w-14 md:h-14 rounded-xl md:rounded-2xl flex items-center justify-center text-lg md:text-xl transition-all shadow-xl active:scale-95 shrink-0 ${showActionMenu ? 'bg-indigo-600 text-white rotate-45' : 'bg-slate-900 text-slate-500 hover:text-white border border-slate-800'}`}
            >
              ➕
            </button>

            {showActionMenu && (
              <div className="absolute bottom-12 md:bottom-16 left-0 w-40 md:w-48 bg-slate-900 border border-slate-800 rounded-xl md:rounded-2xl shadow-2xl p-1.5 md:p-2 animate-in slide-in-from-bottom-2 duration-200 z-50">
                 <button onClick={() => startCamera()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📸</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Visual</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📄</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Packet</span>
                 </button>
                 <button onClick={() => setShowPollModal(true)} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📊</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Poll</span>
                 </button>
              </div>
            )}
          </div>

          <div className="flex-1 relative group flex items-end bg-slate-900/40 border border-slate-800 rounded-xl md:rounded-2xl overflow-hidden focus-within:border-indigo-600 transition-all min-w-0">
            <button 
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className={`p-2 md:p-4 transition-colors shrink-0 ${showEmojiPicker ? 'text-indigo-400' : 'text-slate-600 hover:text-indigo-400'}`}
            >
               <svg className="w-5 h-5 md:w-6 md:h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
            </button>

            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit..."
              rows={1}
              className="w-full bg-transparent px-1 py-3 md:py-4 text-white text-sm md:text-base font-medium outline-none placeholder:text-slate-800 resize-none shadow-inner min-w-0"
            />

            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[280px] md:max-w-sm bg-slate-950 border border-slate-800 rounded-2xl md:rounded-3xl p-3 md:p-4 shadow-2xl z-50 animate-in slide-in-from-bottom-2">
                 <div className="grid grid-cols-6 md:grid-cols-8 gap-1 md:gap-2">
                    {COMMON_EMOJIS.map(emoji => (
                      <button key={emoji} onClick={() => injectEmoji(emoji)} className="text-lg md:text-xl hover:scale-125 transition-transform p-1.5">{emoji}</button>
                    ))}
                 </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleSend}
            disabled={!input.trim()}
            className="w-10 h-10 md:w-14 md:h-14 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-800 text-white rounded-xl md:rounded-2xl flex items-center justify-center shadow-xl active:scale-95 transition-all shrink-0"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
          </button>
        </div>
      </footer>

      {/* File Input */}
      <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

      {/* Poll Modal */}
      {showPollModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm md:max-w-md rounded-[2rem] md:rounded-[2.5rem] shadow-2xl p-6 md:p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6 md:mb-8">
               <h3 className="text-lg md:text-xl font-black text-white italic uppercase tracking-tighter">Strategic Query</h3>
               <button onClick={() => setShowPollModal(false)} className="text-slate-500 hover:text-white">✕</button>
            </div>

            <div className="space-y-4 md:space-y-6">
              <div className="space-y-1.5 md:space-y-2">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Inquiry Objective</label>
                <input 
                  type="text" 
                  value={pollQuestion}
                  onChange={(e) => setPollQuestion(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 md:py-3 text-sm text-white font-bold outline-none focus:border-indigo-500"
                  placeholder="The query target..."
                />
              </div>

              <div className="space-y-2 md:space-y-3">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Outcome Variables</label>
                {pollOptions.map((opt, idx) => (
                  <input 
                    key={idx}
                    type="text"
                    value={opt}
                    onChange={(e) => {
                      const newOpts = [...pollOptions];
                      newOpts[idx] = e.target.value;
                      setPollOptions(newOpts);
                    }}
                    className="w-full bg-slate-950 border border-slate-800 rounded-lg md:rounded-xl px-4 py-2 md:py-3 text-xs text-white outline-none focus:border-indigo-500"
                    placeholder={`Option ${idx + 1}`}
                  />
                ))}
                <button 
                  onClick={() => setPollOptions([...pollOptions, ''])}
                  className="w-full py-2 text-[8px] font-black text-indigo-500 uppercase tracking-[0.3em] hover:text-white transition-colors"
                >
                  ➕ Add Variable
                </button>
              </div>

              <div className="flex gap-3 md:gap-4 pt-2 md:pt-4">
                 <button onClick={() => setShowPollModal(false)} className="flex-1 py-3 md:py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Abort</button>
                 <button onClick={handleCreatePoll} className="flex-1 py-3 md:py-4 bg-indigo-600 text-white rounded-lg md:rounded-xl font-black uppercase text-[9px] tracking-widest shadow-xl">Deploy</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Camera UI Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[110] bg-black flex flex-col animate-in fade-in duration-300">
           <div className="relative flex-1 bg-slate-950 flex items-center justify-center overflow-hidden">
             <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
             <div className="absolute inset-0 pointer-events-none border-[20px] md:border-[40px] border-black/40" />
             <div className="absolute top-6 md:top-10 left-1/2 -translate-x-1/2 flex flex-col items-center">
               <div className="text-white font-black italic tracking-tighter uppercase text-lg md:text-xl text-glow">Visual Scanner</div>
               <div className="text-[7px] md:text-[8px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-1">Active Uplink</div>
             </div>
           </div>

           <div className="h-32 md:h-40 bg-slate-950 border-t border-slate-900 flex items-center justify-around px-6 md:px-10 shrink-0">
              <button onClick={stopCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-slate-400 hover:text-white transition-colors">✕</button>
              <button onClick={capturePhoto} className="w-16 h-16 md:w-20 md:h-20 rounded-full border-4 border-indigo-500 p-1 group active:scale-95 transition-all">
                 <div className="w-full h-full rounded-full bg-white/10 group-hover:bg-indigo-500 transition-colors" />
              </button>
              <button onClick={flipCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-indigo-400 hover:text-white transition-colors">🔄</button>
           </div>
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  groupDescription?: string;
  groupRules?: string;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  headerContent?: React.ReactNode;
  onToggleMenu?: () => void;
  onEditHub?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  members, // Destructured missing prop
  currentUser,
  onSendMessage, 
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onAddMember, // Destructured missing prop
  onToggleMenu, 
  onEditHub, // Destructured missing prop
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [showMembers, setShowMembers] = useState(false);
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    setIsCameraLoading(true);
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setIsCameraLoading(false);
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    startCamera(nextMode);
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        const attachment: Attachment = {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        };
        onSendMessage("Visual signature captured.", attachment);
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden w-full min-w-0">
      {!hideHeader && (
        <header className="h-16 px-4 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🎥</button>
              </div>
            )}
            <button onClick={() => setShowMembers(!showMembers)} className={`p-1.5 md:p-2 rounded-lg border transition-all ${showMembers ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900/50 border-slate-800 text-slate-500'}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
            </button>
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
          <span className="text-[7px] font-black text-slate-600 uppercase tracking-widest ml-4 hidden sm:inline">System Anchor</span>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-10 custom-scrollbar w-full overflow-x-hidden">
        {messages.map((m) => (
          <div key={m.id} id={`msg-${m.id}`} className={`flex gap-2 md:gap-4 group animate-in slide-in-from-bottom-2 duration-300 overflow-x-hidden ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
            <img src={m.avatar} className="w-8 h-8 md:w-11 md:h-11 rounded-xl md:rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end shrink-0" alt="" />

            <div className={`flex flex-col gap-1.5 max-w-[calc(100%-4rem)] md:max-w-[70%] min-w-0 ${m.sender === currentUser ? 'items-end' : 'items-start'}`}>
               <div className="flex items-center gap-2 px-1">
                 <span className="text-[9px] md:text-[10px] font-black text-white uppercase italic tracking-tighter truncate">{m.sender === currentUser ? 'YOU' : m.sender}</span>
                 <span className="text-[7px] md:text-[8px] text-slate-700 font-bold uppercase tracking-widest shrink-0">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               </div>

               <div className="relative group/bubble w-full">
                 {/* Action Tray - Positioned Left or Right of bubble */}
                 <div className={`absolute top-1/2 -translate-y-1/2 flex items-center gap-1 bg-slate-900/80 backdrop-blur-md border border-slate-800 rounded-full px-2 py-1 shadow-2xl transition-all duration-200 opacity-0 group-hover/bubble:opacity-100 z-20 
                   ${m.sender === currentUser ? 'right-full mr-2 md:mr-3' : 'left-full ml-2 md:ml-3'}
                 `}>
                    <button 
                      onClick={(e) => { e.stopPropagation(); onPinMessage(m.id); }}
                      className={`p-1.5 rounded-full transition-colors ${m.isPinned ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white hover:bg-slate-800'}`}
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 20 20"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z"/></svg>
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); setActiveReactionPicker(activeReactionPicker === m.id ? null : m.id); }}
                      className={`p-1.5 rounded-full hover:bg-slate-800 transition-colors ${activeReactionPicker === m.id ? 'text-indigo-500 bg-indigo-500/10' : 'text-slate-500 hover:text-white'}`}
                    >
                      <svg className="w-3.5 h-3.5" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
                    </button>
                 </div>

                 {/* Message Bubble Container */}
                 <div className={`relative w-fit max-w-full flex flex-col ${m.sender === currentUser ? 'items-end ml-auto' : 'items-start'}`}>
                   <div className={`relative px-4 py-3 md:px-5 md:py-3.5 rounded-[1.5rem] md:rounded-[1.8rem] shadow-2xl border transition-all w-fit max-w-full min-w-0 ${
                     m.sender === currentUser 
                       ? 'bg-indigo-600 text-white border-indigo-500 rounded-tr-none' 
                       : 'bg-slate-900 text-slate-200 border-slate-800/80 rounded-tl-none'
                   } ${m.isPinned ? 'ring-2 ring-indigo-500/50 ring-offset-2 ring-offset-[#020617]' : ''}`}>

                     {m.isPinned && (
                       <div className="absolute -top-3 -left-3 bg-indigo-600 w-5 h-5 md:w-6 md:h-6 rounded-full flex items-center justify-center text-[10px] shadow-lg border border-indigo-400 z-10 animate-bounce">📌</div>
                     )}

                     <p className="text-sm md:text-base font-medium leading-relaxed whitespace-pre-wrap break-words">{m.text}</p>

                     {m.attachment && (
                       <div className="mt-3 md:mt-4 p-3 md:p-4 bg-black/30 rounded-xl md:rounded-2xl border border-white/5 flex flex-col items-center gap-3 md:gap-4 min-w-0">
                          {m.attachment.type.startsWith('image/') && m.attachment.url ? (
                            <img src={m.attachment.url} className="w-full rounded-lg md:rounded-xl" alt="attached" />
                          ) : (
                            <div className="flex items-center gap-3 w-full">
                              <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-950 rounded-lg md:rounded-xl flex items-center justify-center text-xl md:text-2xl shadow-inner shrink-0">📄</div>
                              <div className="min-w-0 flex-1">
                                <div className="text-[9px] md:text-[10px] font-black uppercase truncate text-white italic">{m.attachment.name}</div>
                                <div className="text-[7px] md:text-[8px] text-slate-500 font-bold uppercase tracking-widest mt-1">{m.attachment.size}</div>
                              </div>
                            </div>
                          )}
                       </div>
                     )}

                     {m.poll && (
                       <div className="mt-3 md:mt-4 space-y-2 md:space-y-3 bg-black/20 p-4 md:p-5 rounded-xl md:rounded-2xl border border-white/5 w-full md:min-w-[280px]">
                         <div className="text-[10px] md:text-xs font-black text-white uppercase tracking-widest italic mb-2 break-words">Tactical Inquiry: {m.poll.question}</div>
                         {m.poll.options.map((opt, idx) => {
                           const totalVotes = m.poll!.options.reduce((acc, o) => acc + o.votes.length, 0);
                           const percentage = totalVotes === 0 ? 0 : Math.round((opt.votes.length / totalVotes) * 100);
                           const hasVoted = opt.votes.includes(currentUser);
                           return (
                             <button 
                               key={idx}
                               onClick={() => onVotePoll(m.id, idx)}
                               className={`w-full relative h-9 md:h-10 rounded-lg md:rounded-xl overflow-hidden border transition-all group/opt ${hasVoted ? 'border-indigo-400/50' : 'border-slate-800/50 hover:border-slate-700'}`}
                             >
                               <div className={`absolute inset-0 h-full transition-all duration-1000 ${hasVoted ? 'bg-indigo-500/20' : 'bg-slate-800/10'}`} style={{ width: `${percentage}%` }} />
                               <div className="absolute inset-0 flex items-center justify-between px-3 md:px-4 z-10">
                                  <span className={`text-[9px] md:text-[10px] font-black uppercase tracking-widest truncate mr-2 ${hasVoted ? 'text-indigo-300' : 'text-slate-400'}`}>{opt.text}</span>
                                  <span className="text-[8px] md:text-[9px] font-black text-slate-500 shrink-0">{percentage}%</span>
                               </div>
                             </button>
                           );
                         })}
                       </div>
                     )}
                   </div>

                   {/* Reaction Picker - Positioned BELOW the bubble as requested */}
                   {activeReactionPicker === m.id && (
                     <div 
                      onClick={(e) => e.stopPropagation()}
                      className={`mt-2 flex items-center gap-1 p-1 bg-slate-900/95 backdrop-blur-2xl border border-slate-700/50 rounded-2xl shadow-2xl z-[100] animate-in slide-in-from-top-2 w-fit max-w-[280px] sm:max-w-none overflow-x-auto custom-scrollbar ${m.sender === currentUser ? 'self-end' : 'self-start'}`}
                     >
                        {COMMON_EMOJIS.slice(0, 10).map(emoji => (
                          <button 
                            key={emoji} 
                            onClick={(e) => { e.stopPropagation(); onReactToMessage(m.id, emoji); setActiveReactionPicker(null); }} 
                            className="hover:scale-125 active:scale-90 transition-all p-2 text-xl md:text-lg shrink-0 rounded-lg hover:bg-white/5"
                          >
                            {emoji}
                          </button>
                        ))}
                        <button onClick={() => setActiveReactionPicker(null)} className="ml-1 p-2 text-slate-500 hover:text-white shrink-0">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M6 18L18 6M6 6l12 12"/></svg>
                        </button>
                     </div>
                   )}

                   {/* Active Reactions List */}
                   {m.reactions && Object.keys(m.reactions).length > 0 && (
                     <div className={`flex flex-wrap gap-1 mt-1.5 w-full max-w-full ${m.sender === currentUser ? 'justify-end' : 'justify-start'}`}>
                        {Object.entries(m.reactions).map(([emoji, users]) => (
                          <button 
                            key={emoji} 
                            onClick={(e) => { e.stopPropagation(); onReactToMessage(m.id, emoji); }}
                            className={`px-2 py-0.5 rounded-full border text-[9px] md:text-[10px] font-black transition-all flex items-center gap-1.5 shrink-0 break-all ${(users as string[]).includes(currentUser) ? 'bg-indigo-600/20 border-indigo-500 text-indigo-400' : 'bg-slate-900/60 border-slate-800 text-slate-500 hover:text-slate-300'}`}
                          >
                            <span>{emoji}</span>
                            <span className="opacity-60">{(users as string[]).length}</span>
                          </button>
                        ))}
                     </div>
                   )}
                 </div>
               </div>
            </div>
          </div>
        ))}
      </div>

      {/* Chat Input Area */}
      <footer className="p-3 md:p-6 lg:p-8 bg-slate-950/80 backdrop-blur-3xl border-t border-slate-900/50 shrink-0 relative">
        <div className="max-w-6xl mx-auto flex items-end gap-2 md:gap-4">
          <div className="relative">
            <button 
              onClick={() => setShowActionMenu(!showActionMenu)}
              className={`w-10 h-10 md:w-14 md:h-14 rounded-xl md:rounded-2xl flex items-center justify-center text-lg md:text-xl transition-all shadow-xl active:scale-95 shrink-0 ${showActionMenu ? 'bg-indigo-600 text-white rotate-45' : 'bg-slate-900 text-slate-500 hover:text-white border border-slate-800'}`}
            >
              ➕
            </button>

            {showActionMenu && (
              <div className="absolute bottom-12 md:bottom-16 left-0 w-40 md:w-48 bg-slate-900 border border-slate-800 rounded-xl md:rounded-2xl shadow-2xl p-1.5 md:p-2 animate-in slide-in-from-bottom-2 duration-200 z-50">
                 <button onClick={() => startCamera()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📸</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Visual</span>
                 </button>
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📄</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Packet</span>
                 </button>
                 <button onClick={() => setShowPollModal(true)} className="w-full flex items-center gap-2 md:gap-3 p-2 md:p-3 hover:bg-indigo-600/10 rounded-lg md:rounded-xl transition-colors text-left group">
                    <span className="text-base md:text-lg">📊</span>
                    <span className="text-[8px] md:text-[9px] font-black text-slate-400 group-hover:text-white uppercase tracking-widest">Poll</span>
                 </button>
              </div>
            )}
          </div>

          <div className="flex-1 relative group flex items-end bg-slate-900/40 border border-slate-800 rounded-xl md:rounded-2xl overflow-hidden focus-within:border-indigo-600 transition-all min-w-0">
            <button 
              onClick={() => setShowEmojiPicker(!showEmojiPicker)}
              className={`p-2 md:p-4 transition-colors shrink-0 ${showEmojiPicker ? 'text-indigo-400' : 'text-slate-600 hover:text-indigo-400'}`}
            >
               <svg className="w-5 h-5 md:w-6 md:h-6" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.41 0-8-3.59-8-8s3.59-8 8-8 8 3.59 8 8-3.59 8-8 8zm3.5-9c.83 0 1.5-.67 1.5-1.5S16.33 8 15.5 8 14 8.67 14 9.5s.67 1.5 1.5 1.5zm-7 0c.83 0 1.5-.67 1.5-1.5S9.33 8 8.5 8 7 8.67 7 9.5s.67 1.5 1.5 1.5zm3.5 6.5c2.33 0 4.31-1.46 5.11-3.5H6.89c.8 2.04 2.78 3.5 5.11 3.5z"/></svg>
            </button>

            <textarea 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); } }}
              placeholder="Transmit..."
              rows={1}
              className="w-full bg-transparent px-1 py-3 md:py-4 text-white text-sm md:text-base font-medium outline-none placeholder:text-slate-800 resize-none shadow-inner min-w-0"
            />

            {showEmojiPicker && (
              <div className="absolute bottom-full mb-3 left-0 w-full max-w-[280px] md:max-w-sm bg-slate-950 border border-slate-800 rounded-2xl md:rounded-3xl p-3 md:p-4 shadow-2xl z-50 animate-in slide-in-from-bottom-2">
                 <div className="grid grid-cols-6 md:grid-cols-8 gap-1 md:gap-2">
                    {COMMON_EMOJIS.map(emoji => (
                      <button key={emoji} onClick={() => injectEmoji(emoji)} className="text-lg md:text-xl hover:scale-125 transition-transform p-1.5">{emoji}</button>
                    ))}
                 </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleSend}
            disabled={!input.trim()}
            className="w-10 h-10 md:w-14 md:h-14 bg-indigo-600 hover:bg-indigo-500 disabled:bg-slate-900 disabled:text-slate-800 text-white rounded-xl md:rounded-2xl flex items-center justify-center shadow-xl active:scale-95 transition-all shrink-0"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 md:h-5 md:w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor"><path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" /></svg>
          </button>
        </div>
      </footer>

      {/* File Input */}
      <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" />

      {/* Poll Modal */}
      {showPollModal && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-sm">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-sm md:max-w-md rounded-[2rem] md:rounded-[2.5rem] shadow-2xl p-6 md:p-8 animate-in zoom-in-95 duration-200">
            <div className="flex items-center justify-between mb-6 md:mb-8">
               <h3 className="text-lg md:text-xl font-black text-white italic uppercase tracking-tighter">Strategic Query</h3>
               <button onClick={() => setShowPollModal(false)} className="text-slate-500 hover:text-white">✕</button>
            </div>

            <div className="space-y-4 md:space-y-6">
              <div className="space-y-1.5 md:space-y-2">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Inquiry Objective</label>
                <input 
                  type="text" 
                  value={pollQuestion}
                  onChange={(e) => setPollQuestion(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 md:py-3 text-sm text-white font-bold outline-none focus:border-indigo-500"
                  placeholder="The query target..."
                />
              </div>

              <div className="space-y-2 md:space-y-3">
                <label className="text-[7px] md:text-[8px] font-black text-slate-600 uppercase tracking-widest italic ml-2">Outcome Variables</label>
                {pollOptions.map((opt, idx) => (
                  <input 
                    key={idx}
                    type="text"
                    value={opt}
                    onChange={(e) => {
                      const newOpts = [...pollOptions];
                      newOpts[idx] = e.target.value;
                      setPollOptions(newOpts);
                    }}
                    className="w-full bg-slate-950 border border-slate-800 rounded-lg md:rounded-xl px-4 py-2 md:py-3 text-xs text-white outline-none focus:border-indigo-500"
                    placeholder={`Option ${idx + 1}`}
                  />
                ))}
                <button 
                  onClick={() => setPollOptions([...pollOptions, ''])}
                  className="w-full py-2 text-[8px] font-black text-indigo-500 uppercase tracking-[0.3em] hover:text-white transition-colors"
                >
                  ➕ Add Variable
                </button>
              </div>

              <div className="flex gap-3 md:gap-4 pt-2 md:pt-4">
                 <button onClick={() => setShowPollModal(false)} className="flex-1 py-3 md:py-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Abort</button>
                 <button onClick={handleCreatePoll} className="flex-1 py-3 md:py-4 bg-indigo-600 text-white rounded-lg md:rounded-xl font-black uppercase text-[9px] tracking-widest shadow-xl">Deploy</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Camera UI Overlay */}
      {showCamera && (
        <div className="fixed inset-0 z-[200] bg-black flex flex-col animate-in fade-in duration-300">
           <div className="relative flex-1 bg-slate-950 flex items-center justify-center overflow-hidden">
             <video ref={videoRef} autoPlay playsInline className={`w-full h-full object-cover ${facingMode === 'user' ? 'mirror' : ''}`} />
             <div className="absolute inset-0 pointer-events-none border-[20px] md:border-[40px] border-black/40" />
             <div className="absolute top-6 md:top-10 left-1/2 -translate-x-1/2 flex flex-col items-center">
               <div className="text-white font-black italic tracking-tighter uppercase text-lg md:text-xl text-glow">Visual Scanner</div>
               <div className="text-[7px] md:text-[8px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-1">Active Uplink</div>
             </div>
           </div>

           <div className="h-32 md:h-40 bg-slate-950 border-t border-slate-900 flex items-center justify-around px-6 md:px-10 shrink-0">
              <button onClick={stopCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-slate-400 hover:text-white transition-colors">✕</button>
              <button onClick={capturePhoto} className="w-16 h-16 md:w-20 md:h-20 rounded-full border-4 border-indigo-500 p-1 group active:scale-95 transition-all">
                 <div className="w-full h-full rounded-full bg-white/10 group-hover:bg-indigo-500 transition-colors" />
              </button>
              <button onClick={flipCamera} className="p-3 md:p-4 bg-slate-900 rounded-full text-indigo-400 hover:text-white transition-colors">🔄</button>
           </div>
        </div>
      )}

      <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default ChatArea;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Message, Attachment, GroupMember, Poll, PollOption } from '../types';

interface ChatAreaProps {
  groupName: string;
  messages: Message[];
  members: GroupMember[];
  currentUser: string;
  isAiLoading?: boolean;
  onSendMessage: (text: string, attachment?: Attachment, poll?: Poll) => void;
  onAskAI: (text: string) => void;
  onVotePoll: (messageId: string, optionIndex: number) => void;
  onReactToMessage: (messageId: string, emoji: string) => void;
  onPinMessage: (messageId: string) => void;
  onAddMember: (name: string, role: GroupMember['role']) => void;
  onToggleMenu?: () => void;
  onOpenVoice?: (mode: 'voice' | 'video') => void;
  hideHeader?: boolean;
}

const COMMON_EMOJIS = ['👍', '❤️', '😂', '😮', '😢', '🔥', '👏', '💯', '✨', '🚀', '✅', '👀', '💡', '🤔', '🎉', '🙌'];

const ChatArea: React.FC<ChatAreaProps> = ({ 
  groupName, 
  messages, 
  currentUser,
  isAiLoading = false,
  onSendMessage, 
  onAskAI,
  onVotePoll,
  onReactToMessage,
  onPinMessage,
  onToggleMenu, 
  onOpenVoice,
  hideHeader = false
}) => {
  const [input, setInput] = useState('');
  const [activeReactionPicker, setActiveReactionPicker] = useState<string | null>(null);
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showActionMenu, setShowActionMenu] = useState(false);
  const [showCamera, setShowCamera] = useState(false);
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');

  const [showPollModal, setShowPollModal] = useState(false);
  const [pollQuestion, setPollQuestion] = useState('');
  const [pollOptions, setPollOptions] = useState<string[]>(['', '']);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const pinnedMessages = useMemo(() => messages.filter(m => m.isPinned), [messages]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isAiLoading]);

  const handleSend = () => {
    if (!input.trim()) return;
    onSendMessage(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleAIRequest = () => {
    if (!input.trim()) return;
    onAskAI(input);
    setInput('');
    setShowEmojiPicker(false);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const attachment: Attachment = {
        name: file.name,
        type: file.type,
        size: `${(file.size / 1024).toFixed(1)} KB`
      };
      onSendMessage(`Shared an encrypted packet: ${file.name}`, attachment);
      setShowActionMenu(false);
    }
  };

  const handleCreatePoll = () => {
    const validOptions = pollOptions.filter(opt => opt.trim() !== '');
    if (pollQuestion.trim() && validOptions.length >= 2) {
      const poll: Poll = {
        question: pollQuestion.trim(),
        options: validOptions.map(opt => ({ text: opt.trim(), votes: [] }))
      };
      onSendMessage("A strategic query has been initiated.", undefined, poll);
      setPollQuestion('');
      setPollOptions(['', '']);
      setShowPollModal(false);
      setShowActionMenu(false);
    }
  };

  const startCamera = async (mode: 'user' | 'environment' = 'user') => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: mode }, 
        audio: false 
      });
      streamRef.current = stream;
      if (videoRef.current) videoRef.current.srcObject = stream;
      setShowCamera(true);
      setFacingMode(mode);
    } catch (err) {
      console.error("Camera access denied:", err);
    } finally {
      setShowActionMenu(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) streamRef.current.getTracks().forEach(track => track.stop());
    streamRef.current = null;
    setShowCamera(false);
  };

  const flipCamera = () => startCamera(facingMode === 'user' ? 'environment' : 'user');

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      const context = canvas.getContext('2d');
      if (context) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        if (facingMode === 'user') {
          context.translate(canvas.width, 0);
          context.scale(-1, 1);
        }
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg');
        onSendMessage("Visual signature captured.", {
          name: `capture_${Date.now()}.jpg`,
          type: 'image/jpeg',
          size: 'Captured Matrix',
          url: dataUrl
        });
        stopCamera();
      }
    }
  };

  const scrollToMessage = (id: string) => {
    const el = document.getElementById(`msg-${id}`);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const injectEmoji = (emoji: string) => {
    setInput(prev => prev + emoji);
    setShowEmojiPicker(false);
  };

  return (
    <div className="flex flex-col h-full bg-[#020617] relative overflow-hidden w-full min-w-0">
      {!hideHeader && (
        <header className="h-16 px-4 md:px-6 border-b border-slate-900 bg-slate-950/90 backdrop-blur-2xl flex items-center justify-between z-10 shrink-0">
          <div className="flex items-center min-w-0 flex-1">
            <button onClick={onToggleMenu} className="p-1.5 mr-2.5 bg-slate-900/50 rounded-lg md:hidden text-slate-500 border border-slate-800/50">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="text-sm font-black text-white truncate tracking-tighter uppercase italic flex items-center gap-2">
               <span className="text-indigo-600 opacity-60">#</span> {groupName}
            </div>
          </div>
          <div className="flex items-center gap-2">
            {onOpenVoice && (
              <div className="flex items-center gap-1.5 mr-1 md:mr-2">
                <button onClick={() => onOpenVoice('voice')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🔊</button>
                <button onClick={() => onOpenVoice('video')} className="p-1.5 md:p-2 text-indigo-400 hover:text-white transition-colors text-base md:text-lg">🎥</button>
              </div>
            )}
          </div>
        </header>
      )}

      {/* Pinned Messages Bar */}
      {pinnedMessages.length > 0 && (
        <div className="bg-slate-900/40 border-b border-slate-900 px-4 py-2 flex items-center justify-between z-10 shrink-0 relative">
          <button onClick={() => scrollToMessage(pinnedMessages[pinnedMessages.length - 1].id)} className="flex-1 flex items-center gap-3 overflow-hidden text-left">
            <span className="text-indigo-500 shrink-0 text-xs">📌</span>
            <span className="text-[10px] font-black uppercase text-indigo-400 truncate tracking-widest italic">{pinnedMessages[pinnedMessages.length - 1].text}</span>
          </button>
        </div>
      )}

      {/* Message Feed */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-10 custom-scrollbar w-full overflow-x-hidden">
        {messages.map((m) => {
          const isAI = m.sender.toLowerCase().includes('ai');
          return (
            <div key={m.id} id={`msg-${m.id}`} className={`flex gap-2 md:gap-4 group animate-in slide-in-from-bottom-2 duration-300 overflow-x-hidden ${m.sender === currentUser ? 'flex-row-reverse' : ''}`}>
              <img src={m.avatar} className="w-8 h-8 md:w-11 md:h-11 rounded-xl md:rounded-2xl object-cover border border-slate-800/50 shadow-xl self-end shrink-0" alt="" />

              <div className={`flex flex-col gap-1.5 max-w-[calc(100%-4rem)] md:max-w-[70%] min-w-0 ${m.sender === currentUser ? 'items-end' : 'items-start'}`}>
                 <div className="flex items-center gap-2 px-1">
                   <span className={`text-[9px] md:text-[10px] font-black uppercase italic tracking-tighter truncate ${isAI ? 'text-indigo-400' : 'text-white'}`}>
                     {m.sender === currentUser ? 'YOU' : m.sender}
                   </span>
                   <span className="text-[7px] md:text-[8px] text-slate-700 font-bold uppercase tracking-widest shrink-0">{new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
                 </div>

                 <div className="relative group/bubble w-full">
                   {/* Action Tray */}
