import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import ChatArea from './components/ChatArea';
import DashboardArea from './components/DashboardArea';
import MeetingSession from './components/MeetingSession';
import HubCreationScreen from './components/HubCreationScreen';
import StartupScreen from './components/StartupScreen';
import UserProfileScreen from './components/UserProfileScreen';
import AuthScreen from './components/AuthScreen';
import { Group, GroupType, Message, Attachment, Resource, Topic, GroupMember, Poll } from './types';
import { GoogleGenAI } from "@google/genai";

const MOCK_AI_MEMBER: GroupMember = { id: 'ai', name: 'Nexus AI Tutor', avatar: 'https://picsum.photos/80/80?u=ai', role: 'AI Assistant', status: 'online' };

const MOCK_MEMBERS: GroupMember[] = [
  MOCK_AI_MEMBER,
  { id: '2', name: 'Sarah Miller', avatar: 'https://picsum.photos/80/80?u=2', role: 'Admin', status: 'online' },
  { id: '3', name: 'Marcus Chen', avatar: 'https://picsum.photos/80/80?u=3', role: 'Member', status: 'offline' },
  { id: '4', name: 'Elena Rodriguez', avatar: 'https://picsum.photos/80/80?u=4', role: 'Member', status: 'online' },
];

const INITIAL_GROUPS: Group[] = [
  {
    id: 'edu-1',
    name: 'Advanced Mathematics',
    description: 'High-level synthesis of multivariable calculus and abstract algebra for research students.',
    rules: '1. Academic integrity is mandatory. 2. Support peers. 3. AI use permitted for clarification only.',
    type: GroupType.TOPICS,
    category: 'Education',
    members: MOCK_MEMBERS,
    topics: [
      { 
        id: 't1', 
        name: 'Calculus III', 
        description: 'Multivariable calculus resources and lecture notes.', 
        icon: '📐',
        messages: [],
        resources: [
          { id: 'r1', name: 'Lecture_Notes_Week1.pdf', type: 'application/pdf', size: '2.4 MB', uploadedBy: 'Prof. Smith', date: new Date() }
        ]
      },
      { 
        id: 't2', 
        name: 'Linear Algebra', 
        description: 'Matrices, vectors, and linear transformations.', 
        icon: '📊',
        messages: [],
        resources: []
      }
    ],
    messages: [],
    avatar: 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=100&h=100&fit=crop'
  }
];

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<GroupMember | null>(null);
  const [isRegistered, setIsRegistered] = useState(false);
  const [groups, setGroups] = useState<Group[]>(INITIAL_GROUPS);
  const [activeGroupId, setActiveGroupId] = useState<string | null>(null);
  const [activeTopicId, setActiveTopicId] = useState<string | null>(null);
  const [isAddingHub, setIsAddingHub] = useState(false);
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);

  const [isTopicModalOpen, setIsTopicModalOpen] = useState(false);
  const [sessionMode, setSessionMode] = useState<'voice' | 'video' | null>(null);
  const [sessionGroupName, setSessionGroupName] = useState<string | null>(null);
  const [isSessionMinimized, setIsSessionMinimized] = useState(false);
  const [isAiLoading, setIsAiLoading] = useState(false);

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const savedUser = localStorage.getItem('nexus_user');
    if (savedUser) {
      const user = JSON.parse(savedUser);
      setCurrentUser(user);
      setIsRegistered(true);
    }
  }, []);

  const handleRegister = (user: GroupMember) => {
    localStorage.setItem('nexus_user', JSON.stringify(user));
    setCurrentUser(user);
    setIsRegistered(true);
    setGroups(prev => prev.map(g => ({
      ...g,
      members: [user, ...g.members]
    })));
  };

  const handleSendMessage = (topicIdOrNull: string | null, text: string, attachment?: Attachment, poll?: Poll) => {
    if (!currentUser) return;
    const newMessage: Message = {
      id: `msg-${Date.now()}`,
      sender: currentUser.name,
      text,
      timestamp: new Date(),
      avatar: currentUser.avatar,
      attachment,
      poll,
      reactions: {},
      isPinned: false
    };

    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      if (g.type === GroupType.STANDARD) return { ...g, messages: [...g.messages, newMessage], lastMessage: text };
      return {
        ...g,
        topics: g.topics.map(t => {
          if (t.id !== topicIdOrNull) return t;
          let updatedResources = [...t.resources];
          if (attachment) {
            updatedResources.push({
              id: `res-${Date.now()}`,
              name: attachment.name,
              type: attachment.type,
              size: attachment.size,
              url: attachment.url,
              uploadedBy: currentUser.name,
              date: new Date()
            });
          }
          return { ...t, messages: [...t.messages, newMessage], resources: updatedResources };
        })
      };
    }));
  };

  const handleAskAI = async (topicIdOrNull: string | null, prompt: string) => {
    if (!currentUser || isAiLoading) return;

    // 1. Add User's prompt to message list first
    handleSendMessage(topicIdOrNull, prompt);
    setIsAiLoading(true);

    try {
      const activeGroup = groups.find(g => g.id === activeGroupId);
      if (!activeGroup) return;

      const historyMessages = activeGroup.type === GroupType.STANDARD 
        ? activeGroup.messages.slice(-10)
        : activeGroup.topics.find(t => t.id === topicIdOrNull)?.messages.slice(-10) || [];

      const context = historyMessages.map(m => `${m.sender}: ${m.text}`).join('\n');
      const systemPrompt = `You are Nexus AI Tutor, an advanced facilitator in the Nexus Hub workspace. 
      The current context is a group called "${activeGroup.name}". 
      Respond concisely and professionally. Focus on being a helpful assistant for high-level research and collaboration.
      Previous messages for context:\n${context}`;

      const aiClient = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await aiClient.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction: systemPrompt }
      });

      const aiResponseText = response.text || "I encountered a spectral interference in my neural processing. Please retry transmission.";

      const aiMessage: Message = {
        id: `ai-${Date.now()}`,
        sender: MOCK_AI_MEMBER.name,
        text: aiResponseText,
        timestamp: new Date(),
        avatar: MOCK_AI_MEMBER.avatar,
        reactions: {},
        isPinned: false
      };

      setGroups(prev => prev.map(g => {
        if (g.id !== activeGroupId) return g;
        if (g.type === GroupType.STANDARD) return { ...g, messages: [...g.messages, aiMessage], lastMessage: aiResponseText };
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: [...t.messages, aiMessage] } : t)
        };
      }));
    } catch (err) {
      console.error("AI Facilitation failed:", err);
    } finally {
      setIsAiLoading(false);
    }
  };

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#020617] text-slate-200 selection:bg-indigo-500/30">
      <div className={`fixed inset-y-0 left-0 z-50 transform md:relative md:translate-x-0 transition-transform duration-300 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        {currentUser && (
          <Sidebar 
            groups={groups} 
            activeGroupId={activeGroupId || ''} 
            activeTopicId={activeTopicId}
            currentUser={currentUser}
            onSelectGroup={(id) => { setActiveGroupId(id); setActiveTopicId(groups.find(g => g.id === id)?.topics[0]?.id || null); setIsMobileMenuOpen(false); }}
            onSelectTopic={(id) => { setActiveTopicId(id); setIsMobileMenuOpen(false); }}
            onStartAddingHub={() => { setIsAddingHub(true); setIsMobileMenuOpen(false); }}
            onResetPortal={() => { setActiveGroupId(null); setActiveTopicId(null); setIsAddingHub(false); }}
            onAddTopic={() => setIsTopicModalOpen(true)}
            onJoinVoice={(mode) => { setSessionMode(mode); setSessionGroupName(activeGroup?.name || 'Session'); }}
            onEditProfile={() => { setIsEditingProfile(true); setIsMobileMenuOpen(false); }}
            isOpen={isMobileMenuOpen}
            onClose={() => setIsMobileMenuOpen(false)}
          />
        )}
      </div>

      <main className="flex-1 flex flex-col min-w-0 h-full relative">
        {isEditingProfile && currentUser ? (
          <UserProfileScreen user={currentUser} onUpdate={(upd) => { setCurrentUser({...currentUser, ...upd}); setIsEditingProfile(false); }} onCancel={() => setIsEditingProfile(false)} />
        ) : isAddingHub ? (
          <HubCreationScreen onCreate={(name, type, avatar, desc, rules) => {
            const newG: Group = { id: `h-${Date.now()}`, name, type, avatar, description: desc, rules, topics: type === GroupType.TOPICS ? [{ id: 't1', name: 'General', description: 'Main chat', icon: '🌐', messages: [], resources: [] }] : [], messages: [], members: [currentUser!, ...MOCK_MEMBERS], avatar };
            setGroups([...groups, newG]); setActiveGroupId(newG.id); setIsAddingHub(false);
          }} onCancel={() => setIsAddingHub(false)} />
        ) : activeGroup && currentUser ? (
          activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              currentUser={currentUser.name}
              isAiLoading={isAiLoading}
              onSendMessage={(txt, att, poll) => handleSendMessage(null, txt, att, poll)}
              onAskAI={(txt) => handleAskAI(null, txt)}
              onVotePoll={(id, idx) => {}} 
              onReactToMessage={(id, emo) => {}}
              onPinMessage={(id) => {}}
              onAddMember={() => {}}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
              onOpenVoice={(mode) => setSessionMode(mode)}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              currentUser={currentUser}
              activeTopicId={activeTopicId}
              isAiLoading={isAiLoading}
              onSelectTopic={setActiveTopicId}
              onOpenVoice={(mode) => setSessionMode(mode)}
              onSendMessage={handleSendMessage}
              onAskAI={handleAskAI}
              onVotePoll={(tid, mid, idx) => {}}
              onReactToMessage={(tid, mid, emo) => {}}
              onPinMessage={(tid, mid) => {}}
              onRearrangeResources={() => {}}
              onAddMember={() => {}}
              onUploadResource={() => {}}
              onStartAddingTopic={() => setIsTopicModalOpen(true)}
              onEditTopic={() => {}}
              onEditHub={() => setEditingGroup(activeGroup)}
              onDeleteHub={() => {}}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          )
        ) : (
          <StartupScreen groups={groups} onSelectHub={(id) => { setActiveGroupId(id); setActiveTopicId(groups.find(g => g.id === id)?.topics[0]?.id || null); }} onInitializeHub={() => setIsAddingHub(true)} />
        )}
      </main>

      {/* Modals & Session */}
      {isTopicModalOpen && <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-6"><div className="bg-slate-900 p-8 rounded-[2rem] border border-slate-800"><h3 className="text-xl font-black text-white italic mb-6">Deploy Module</h3><input id="t-name" className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 mb-6 outline-none" placeholder="Module Name..."/><div className="flex gap-4"><button onClick={() => setIsTopicModalOpen(false)} className="flex-1 py-4 text-slate-500 font-black">Abort</button><button onClick={() => { const n = (document.getElementById('t-name') as HTMLInputElement).value; if(n){ setGroups(groups.map(g => g.id === activeGroupId ? {...g, topics: [...g.topics, {id: `t-${Date.now()}`, name: n, description: '', icon: '🛰️', messages: [], resources: []}]} : g)); setIsTopicModalOpen(false); } }} className="flex-1 py-4 bg-indigo-600 rounded-xl font-black text-white">Deploy</button></div></div></div>}
      {sessionMode && <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4"><MeetingSession mode={sessionMode} onClose={() => setSessionMode(null)} groupName={sessionGroupName || 'Session'} /></div>}
    </div>
  );
};

