          if (m.id !== messageId) return m;
          const currentReactions = { ...(m.reactions || {}) };
          const users = [...(currentReactions[emoji] || [])];

          if (users.includes(currentUser.name)) {
            currentReactions[emoji] = users.filter(u => u !== currentUser.name);
            if (currentReactions[emoji].length === 0) delete currentReactions[emoji];
          } else {
            currentReactions[emoji] = [...users, currentUser.name];
          }
          return { ...m, reactions: currentReactions };
        });

      if (g.type === GroupType.STANDARD) return { ...g, messages: updateMessageList(g.messages) };
      return {
        ...g,
        topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessageList(t.messages) } : t)
      };
    }));
  };

  const handlePinMessage = (topicIdOrNull: string | null, messageId: string) => {
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;
      const updateMessageList = (messages: Message[]) => 
        messages.map(m => m.id === messageId ? { ...m, isPinned: !m.isPinned } : m);

      if (g.type === GroupType.STANDARD) return { ...g, messages: updateMessageList(g.messages) };
      return {
        ...g,
        topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessageList(t.messages) } : t)
      };
    }));
  };

  const handleVotePoll = (topicIdOrNull: string | null, messageId: string, optionIndex: number) => {
    if (!currentUser) return;
    setGroups(prev => prev.map(g => {
      if (g.id !== activeGroupId) return g;

      const updateMessageList = (messages: Message[]) => 
        messages.map(m => {
          if (m.id !== messageId || !m.poll) return m;
          const newOptions = m.poll.options.map((opt, idx) => {
            let votes = [...opt.votes];
            if (idx === optionIndex) {
              if (votes.includes(currentUser.name)) {
                votes = votes.filter(v => v !== currentUser.name);
              } else {
                votes.push(currentUser.name);
              }
            } else {
              // Usually polls are single choice, so remove vote from other options
              votes = votes.filter(v => v !== currentUser.name);
            }
            return { ...opt, votes };
          });
          return { ...m, poll: { ...m.poll, options: newOptions } };
        });

      if (g.type === GroupType.STANDARD) return { ...g, messages: updateMessageList(g.messages) };
      return {
        ...g,
        topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: updateMessageList(t.messages) } : t)
      };
    }));
  };

  const handleAskAI = async (topicIdOrNull: string | null, prompt: string) => {
    if (!currentUser || isAiLoading) return;
    handleSendMessage(topicIdOrNull, prompt);
    setIsAiLoading(true);

    try {
      const activeGroup = groups.find(g => g.id === activeGroupId);
      if (!activeGroup) return;

      const historyMessages = activeGroup.type === GroupType.STANDARD 
        ? activeGroup.messages.slice(-10)
        : activeGroup.topics.find(t => t.id === topicIdOrNull)?.messages.slice(-10) || [];

      const context = historyMessages.map(m => `${m.sender}: ${m.text}`).join('\n');
      const systemPrompt = `You are Nexus AI Tutor. Previous context:\n${context}`;

      const aiClient = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await aiClient.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { systemInstruction: systemPrompt }
      });

      const aiResponseText = response.text || "Connection lost.";
      const aiMessage: Message = {
        id: `ai-${Date.now()}`,
        sender: MOCK_AI_MEMBER.name,
        text: aiResponseText,
        timestamp: new Date(),
        avatar: MOCK_AI_MEMBER.avatar,
        reactions: {},
        isPinned: false
      };

      setGroups(prev => prev.map(g => {
        if (g.id !== activeGroupId) return g;
        if (g.type === GroupType.STANDARD) return { ...g, messages: [...g.messages, aiMessage], lastMessage: aiResponseText };
        return {
          ...g,
          topics: g.topics.map(t => t.id === topicIdOrNull ? { ...t, messages: [...t.messages, aiMessage] } : t)
        };
      }));
    } catch (err) {
      console.error(err);
    } finally {
      setIsAiLoading(false);
    }
  };

  const activeGroup = groups.find(g => g.id === activeGroupId) || null;

  if (!isRegistered) {
    return <AuthScreen onRegister={handleRegister} />;
  }

  return (
    <div className="flex h-screen w-full overflow-hidden bg-[#020617] text-slate-200 selection:bg-indigo-500/30">
      <div className={`fixed inset-y-0 left-0 z-50 transform md:relative md:translate-x-0 transition-transform duration-300 ease-in-out ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        {currentUser && (
          <Sidebar 
            groups={groups} 
            activeGroupId={activeGroupId || ''} 
            activeTopicId={activeTopicId}
            currentUser={currentUser}
            onSelectGroup={(id) => { setActiveGroupId(id); setActiveTopicId(groups.find(g => g.id === id)?.topics[0]?.id || null); setIsMobileMenuOpen(false); }}
            onSelectTopic={(id) => { setActiveTopicId(id); setIsMobileMenuOpen(false); }}
            onStartAddingHub={() => { setIsAddingHub(true); setIsMobileMenuOpen(false); }}
            onResetPortal={() => { setActiveGroupId(null); setActiveTopicId(null); setIsAddingHub(false); }}
            onAddTopic={() => setIsTopicModalOpen(true)}
            onJoinVoice={(mode) => { setSessionMode(mode); setSessionGroupName(activeGroup?.name || 'Session'); }}
            onEditProfile={() => { setIsEditingProfile(true); setIsMobileMenuOpen(false); }}
            isOpen={isMobileMenuOpen}
            onClose={() => setIsMobileMenuOpen(false)}
          />
        )}
      </div>

      <main className="flex-1 flex flex-col min-w-0 h-full relative">
        {isEditingProfile && currentUser ? (
          <UserProfileScreen user={currentUser} onUpdate={(upd) => { setCurrentUser({...currentUser, ...upd}); setIsEditingProfile(false); }} onCancel={() => setIsEditingProfile(false)} />
        ) : isAddingHub ? (
          <HubCreationScreen onCreate={(name, type, avatar, desc, rules) => {
            const newG: Group = { id: `h-${Date.now()}`, name, type, avatar, description: desc, rules, topics: type === GroupType.TOPICS ? [{ id: 't1', name: 'General', description: 'Main chat', icon: '🌐', messages: [], resources: [] }] : [], messages: [], members: [currentUser!, ...MOCK_MEMBERS] };
            setGroups([...groups, newG]); setActiveGroupId(newG.id); setIsAddingHub(false);
          }} onCancel={() => setIsAddingHub(false)} />
        ) : activeGroup && currentUser ? (
          activeGroup.type === GroupType.STANDARD ? (
            <ChatArea 
              groupName={activeGroup.name} 
              messages={activeGroup.messages}
              members={activeGroup.members}
              currentUser={currentUser.name}
              isAiLoading={isAiLoading}
              onSendMessage={(txt, att, poll) => handleSendMessage(null, txt, att, poll)}
              onAskAI={(txt) => handleAskAI(null, txt)}
              onVotePoll={(mid, idx) => handleVotePoll(null, mid, idx)} 
              onReactToMessage={(mid, emo) => handleReactToMessage(null, mid, emo)}
              onPinMessage={(mid) => handlePinMessage(null, mid)}
              onAddMember={() => {}}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
              onOpenVoice={(mode) => setSessionMode(mode)}
            />
          ) : (
            <DashboardArea 
              group={activeGroup} 
              currentUser={currentUser}
              activeTopicId={activeTopicId}
              isAiLoading={isAiLoading}
              onSelectTopic={setActiveTopicId}
              onOpenVoice={(mode) => setSessionMode(mode)}
              onSendMessage={handleSendMessage}
              onAskAI={handleAskAI}
              onVotePoll={handleVotePoll}
              onReactToMessage={handleReactToMessage}
              onPinMessage={handlePinMessage}
              onRearrangeResources={() => {}}
              onAddMember={() => {}}
              onUploadResource={() => {}}
              onStartAddingTopic={() => setIsTopicModalOpen(true)}
              onEditTopic={() => {}}
              onEditHub={() => setEditingGroup(activeGroup)}
              onDeleteHub={() => {}}
              onToggleMenu={() => setIsMobileMenuOpen(true)}
            />
          )
        ) : (
          <StartupScreen groups={groups} onSelectHub={(id) => { setActiveGroupId(id); setActiveTopicId(groups.find(g => g.id === id)?.topics[0]?.id || null); }} onInitializeHub={() => setIsAddingHub(true)} />
        )}
      </main>

      {isTopicModalOpen && <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-6"><div className="bg-slate-900 p-8 rounded-[2rem] border border-slate-800"><h3 className="text-xl font-black text-white italic mb-6">Deploy Module</h3><input id="t-name" className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 mb-6 outline-none" placeholder="Module Name..."/><div className="flex gap-4"><button onClick={() => setIsTopicModalOpen(false)} className="flex-1 py-4 text-slate-500 font-black">Abort</button><button onClick={() => { const n = (document.getElementById('t-name') as HTMLInputElement).value; if(n){ setGroups(groups.map(g => g.id === activeGroupId ? {...g, topics: [...g.topics, {id: `t-${Date.now()}`, name: n, description: '', icon: '🛰️', messages: [], resources: []}]} : g)); setIsTopicModalOpen(false); } }} className="flex-1 py-4 bg-indigo-600 rounded-xl font-black text-white">Deploy</button></div></div></div>}
      {sessionMode && <div className="fixed inset-0 z-[100] bg-black/80 flex items-center justify-center p-4"><MeetingSession mode={sessionMode} onClose={() => setSessionMode(null)} groupName={sessionGroupName || 'Session'} /></div>}
    </div>
  );
};

