                             <button className="w-full mt-2 py-1.5 bg-indigo-600/10 border border-indigo-500/20 hover:bg-indigo-600 hover:text-white text-indigo-400 rounded-lg text-[8px] font-black uppercase tracking-widest transition-all shadow-lg">Download</button>
                          </div>
                        ))}
                    </div>
                </div>
              )}
              {viewMode === 'members' && (
                <div className="h-full overflow-y-auto p-4 md:p-8 bg-slate-950/40 custom-scrollbar">
                   <div className="max-w-7xl mx-auto grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-3">
                      {group.members.map(member => (
                        <div key={member.id} className="bg-slate-900/50 border border-slate-800/80 p-3 rounded-2xl flex items-center gap-3 hover:bg-slate-900 transition-all shadow-xl group">
                           <div className="relative shrink-0"><img src={member.avatar} className="w-8 h-8 rounded-lg object-cover border border-slate-800 shadow-md" alt="" /><div className={`absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 rounded-full border-2 border-slate-950 ${member.status === 'online' ? 'bg-emerald-500' : 'bg-slate-800'}`}></div></div>
                           <div className="flex-1 min-w-0"><div className="font-black text-white text-[9px] truncate uppercase italic tracking-tighter leading-none mb-1">{member.name}</div><div className={`inline-flex px-1.5 py-0.5 rounded text-[6px] font-black uppercase tracking-widest border ${getRoleColor(member.role)}`}>{member.role}</div></div>
                        </div>
                      ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>

      {showHubSettings && (
        <div className="fixed inset-0 z-[120] bg-black/80 backdrop-blur-xl flex items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="bg-slate-900 border border-slate-800 rounded-[3rem] w-full max-w-xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
              <header className="p-8 border-b border-slate-800 flex items-center justify-between bg-slate-950/40"><h3 className="text-2xl font-black text-white italic uppercase tracking-tighter">Hub Intelligence</h3><button onClick={() => setShowHubSettings(false)} className="text-slate-500 hover:text-white">✕</button></header>
              <div className="p-8 space-y-4">
                 <button onClick={() => { setShowHubSettings(false); onEditHub(); }} className="w-full flex items-center justify-between p-6 bg-slate-950/60 border border-slate-800 rounded-2xl hover:border-indigo-500 transition-all group"><div className="flex items-center gap-5"><span className="text-3xl">🧩</span><div className="text-left"><div className="text-sm font-black text-white uppercase italic tracking-tighter">Modify Matrix</div></div></div><span className="text-indigo-500">→</span></button>
                 <button onClick={() => { setShowHubSettings(false); onStartAddingTopic(); }} className="w-full flex items-center justify-between p-6 bg-slate-950/60 border border-slate-800 rounded-2xl hover:border-indigo-500 transition-all group"><div className="flex items-center gap-5"><span className="text-3xl">🛰️</span><div className="text-left"><div className="text-sm font-black text-white uppercase italic tracking-tighter">Inject Module</div></div></div><span className="text-indigo-500">→</span></button>
                 <div className="pt-8 mt-4 border-t border-slate-800/50"><button onClick={() => { if(window.confirm("Permanent Deletion?")) { setShowHubSettings(false); onDeleteHub(); } }} className="w-full flex items-center justify-between p-6 bg-rose-950/20 border border-rose-900/30 rounded-2xl hover:bg-rose-600 hover:text-white transition-all group"><div className="flex items-center gap-5 text-rose-500 group-hover:text-white"><span className="text-3xl opacity-60">☢️</span><div className="text-left"><div className="text-sm font-black uppercase tracking-tighter italic">Decommission Hub</div></div></div></button></div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

